}

import { differenceInDays, parseISO, isAfter } from 'date-fns';
import { Rental, RentalStatus } from '../types';

export const formatCurrency = (amount: number) => {
  return new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0,
  }).format(amount);
};

export const calculateRentalTotal = (startDate: string, endDate: string, dailyRate: number, quantity: number) => {
  const start = parseISO(startDate);
  const end = parseISO(endDate);
  const days = Math.max(1, differenceInDays(end, start));
  return days * dailyRate * quantity;
};

export const calculateLateFee = (expectedReturnDate: string, actualReturnDate: string | undefined, dailyRate: number, quantity: number) => {
  const expected = parseISO(expectedReturnDate);
  const actual = actualReturnDate ? parseISO(actualReturnDate) : new Date();

  if (isAfter(actual, expected)) {
    const overdueDays = differenceInDays(actual, expected);
    return overdueDays * dailyRate * quantity * 1.5; // 1.5x penalty for late return
  }
  return 0;
};

export const generateID = () => Math.random().toString(36).substr(2, 9).toUpperCase();

export const getStatusColor = (status: string) => {
  switch (status) {
    case 'ACTIVE': return 'bg-blue-100 text-blue-700';
    case 'RETURNED': return 'bg-green-100 text-green-700';
    case 'OVERDUE': return 'bg-red-100 text-red-700';
    case 'PAID': return 'bg-green-100 text-green-700';
    case 'PARTIAL': return 'bg-orange-100 text-orange-700';
    case 'UNPAID': return 'bg-red-100 text-red-700';
    default: return 'bg-gray-100 text-gray-700';
  }
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { AppState, Product, Customer, Supplier, Sale, Rental, StockLog, RentalStatus, PaymentStatus } from '../types';
import { generateID } from '../utils/helpers';

interface AppContextType extends AppState {
  addProduct: (product: Omit<Product, 'id' | 'createdAt'>) => void;
  updateProduct: (id: string, product: Partial<Product>) => void;
  deleteProduct: (id: string) => void;
  addCustomer: (customer: Omit<Customer, 'id' | 'createdAt'>) => void;
  addSupplier: (supplier: Omit<Supplier, 'id' | 'createdAt'>) => void;
  addSale: (sale: Omit<Sale, 'id' | 'invoiceNumber' | 'date'>) => void;
  addRental: (rental: Omit<Rental, 'id' | 'invoiceNumber' | 'date' | 'status' | 'lateFee' | 'actualReturnDate'>) => void;
  returnRental: (rentalId: string, lateFee: number) => void;
  updateStock: (productId: string, quantity: number, type: 'IN' | 'OUT', reason: string) => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

const INITIAL_DATA: AppState = {
  products: [
    { id: 'P1', name: 'Canon EOS R5', sku: 'CAM-001', barcode: '123456', category: 'Electronics', purchasePrice: 280000, sellingPrice: 320000, rentalPrice: 2500, taxPercent: 18, stockQuantity: 5, minStockAlert: 2, supplierId: 'S1', description: 'Mirrorless Camera', createdAt: new Date().toISOString() },
    { id: 'P2', name: 'DJI Ronin RS3', sku: 'GIM-002', barcode: '654321', category: 'Electronics', purchasePrice: 45000, sellingPrice: 55000, rentalPrice: 1200, taxPercent: 18, stockQuantity: 8, minStockAlert: 3, supplierId: 'S1', description: 'Camera Gimbal', createdAt: new Date().toISOString() }
  ],
  customers: [
    { id: 'C1', name: 'John Doe', phone: '9876543210', email: 'john@example.com', address: '123 Street, NY', createdAt: new Date().toISOString() }
  ],
  suppliers: [
    { id: 'S1', name: 'Tech Solutions Ltd', contactPerson: 'Alice Smith', phone: '1122334455', email: 'alice@techsol.com', address: 'Industrial Area', createdAt: new Date().toISOString() }
  ],
  sales: [],
  rentals: [],
  stockLogs: []
};

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('inventory_pro_data');
    return saved ? JSON.parse(saved) : INITIAL_DATA;
  });

  useEffect(() => {
    localStorage.setItem('inventory_pro_data', JSON.stringify(state));
  }, [state]);

  const addProduct = (p: Omit<Product, 'id' | 'createdAt'>) => {
    const newProduct: Product = { ...p, id: generateID(), createdAt: new Date().toISOString() };
    setState(prev => ({ ...prev, products: [...prev.products, newProduct] }));
  };

  const updateProduct = (id: string, updates: Partial<Product>) => {
    setState(prev => ({
      ...prev,
      products: prev.products.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const deleteProduct = (id: string) => {
    setState(prev => ({ ...prev, products: prev.products.filter(p => p.id !== id) }));
  };

  const addCustomer = (c: Omit<Customer, 'id' | 'createdAt'>) => {
    const newCustomer: Customer = { ...c, id: generateID(), createdAt: new Date().toISOString() };
    setState(prev => ({ ...prev, customers: [...prev.customers, newCustomer] }));
  };

  const addSupplier = (s: Omit<Supplier, 'id' | 'createdAt'>) => {
    const newSupplier: Supplier = { ...s, id: generateID(), createdAt: new Date().toISOString() };
    setState(prev => ({ ...prev, suppliers: [...prev.suppliers, newSupplier] }));
  };

  const addSale = (s: Omit<Sale, 'id' | 'invoiceNumber' | 'date'>) => {
    const newSale: Sale = {
      ...s,
      id: generateID(),
      invoiceNumber: `INV-${state.sales.length + 1001}`,
      date: new Date().toISOString()
    };

    // Update stock for all items
    s.items.forEach(item => {
      updateStock(item.productId, item.quantity, 'OUT', `Sale ${newSale.invoiceNumber}`);
    });

    setState(prev => ({ ...prev, sales: [...prev.sales, newSale] }));
  };

  const addRental = (r: Omit<Rental, 'id' | 'invoiceNumber' | 'date' | 'status' | 'lateFee' | 'actualReturnDate'>) => {
    const newRental: Rental = {
      ...r,
      id: generateID(),
      invoiceNumber: `RNT-${state.rentals.length + 1001}`,
      date: new Date().toISOString(),
      status: RentalStatus.ACTIVE,
      lateFee: 0
    };

    updateStock(r.productId, r.quantity, 'OUT', `Rental ${newRental.invoiceNumber}`);
    setState(prev => ({ ...prev, rentals: [...prev.rentals, newRental] }));
  };

  const returnRental = (id: string, lateFee: number) => {
    const rental = state.rentals.find(r => r.id === id);
    if (!rental) return;

    updateStock(rental.productId, rental.quantity, 'IN', `Return ${rental.invoiceNumber}`);

    setState(prev => ({
      ...prev,
      rentals: prev.rentals.map(r => r.id === id ? {
        ...r,
        status: RentalStatus.RETURNED,
        actualReturnDate: new Date().toISOString(),
        lateFee: lateFee,
        totalRentAmount: r.totalRentAmount + lateFee
      } : r)
    }));
  };

  const updateStock = (productId: string, quantity: number, type: 'IN' | 'OUT', reason: string) => {
    const log: StockLog = {
      id: generateID(),
      productId,
      type,
      quantity,
      reason,
      date: new Date().toISOString()
    };

    setState(prev => ({
      ...prev,
      products: prev.products.map(p => 
        p.id === productId 
          ? { ...p, stockQuantity: type === 'IN' ? p.stockQuantity + quantity : p.stockQuantity - quantity }
          : p
      ),
      stockLogs: [...prev.stockLogs, log]
    }));
  };

  return (
    <AppContext.Provider value={{ 
      ...state, 
      addProduct, 
      updateProduct, 
      deleteProduct, 
      addCustomer, 
      addSupplier, 
      addSale, 
      addRental, 
      returnRental,
      updateStock 
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useApp must be used within AppProvider');
  return context;
};

import React from 'react';
import { X } from 'lucide-react';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
}

export const Modal: React.FC<ModalProps> = ({ isOpen, onClose, title, children }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
        <div className="flex items-center justify-between p-6 border-b">
          <h2 className="text-xl font-bold text-gray-800">{title}</h2>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition-colors">
            <X size={20} />
          </button>
        </div>
        <div className="p-6 max-h-[80vh] overflow-y-auto">
          {children}
        </div>
      </div>
    </div>
  );
};

export const Card: React.FC<{ children: React.ReactNode; className?: string }> = ({ children, className = "" }) => (
  <div className={`bg-white rounded-xl shadow-sm border border-gray-100 ${className}`}>
    {children}
  </div>
);

export const Button: React.FC<{ 
  children: React.ReactNode; 
  onClick?: () => void; 
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost'; 
  className?: string;
  type?: 'button' | 'submit';
  disabled?: boolean;
}> = ({ children, onClick, variant = 'primary', className = "", type = 'button', disabled }) => {
  const variants = {
    primary: 'bg-indigo-600 text-white hover:bg-indigo-700',
    secondary: 'bg-white text-indigo-600 border border-indigo-200 hover:bg-indigo-50',
    danger: 'bg-red-500 text-white hover:bg-red-600',
    ghost: 'bg-transparent text-gray-600 hover:bg-gray-100'
  };
  return (
    <button 
      type={type}
      onClick={onClick} 
      disabled={disabled}
      className={`px-4 py-2 rounded-lg font-medium transition-all active:scale-95 disabled:opacity-50 disabled:active:scale-100 ${variants[variant]} ${className}`}
    >
      {children}
    </button>
  );
};

import React, { useState } from 'react';
import { useApp } from '../store/AppContext';
import { Card, Button, Modal } from '../components/Shared';
import { Plus, Search, Calendar, User, Package, AlertCircle, CheckCircle } from 'lucide-react';
import { formatCurrency, getStatusColor, calculateRentalTotal, calculateLateFee } from '../utils/helpers';
import { RentalStatus, PaymentStatus } from '../types';

const Rentals: React.FC = () => {
  const { rentals, products, customers, addRental, returnRental } = useApp();
  const [isNewRentalModalOpen, setIsNewRentalModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const handleCreateRental = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const productId = formData.get('productId') as string;
    const qty = Number(formData.get('quantity'));
    const start = formData.get('startDate') as string;
    const end = formData.get('expectedReturnDate') as string;
    const product = products.find(p => p.id === productId);

    if (product) {
      const total = calculateRentalTotal(start, end, product.rentalPrice, qty);
      addRental({
        customerId: formData.get('customerId') as string,
        productId,
        quantity: qty,
        startDate: start,
        expectedReturnDate: end,
        dailyRate: product.rentalPrice,
        securityDeposit: Number(formData.get('securityDeposit')),
        totalRentAmount: total,
        paidAmount: Number(formData.get('paidAmount')),
        paymentStatus: Number(formData.get('paidAmount')) >= total ? PaymentStatus.PAID : PaymentStatus.PARTIAL,
      });
      setIsNewRentalModalOpen(false);
    }
  };

  const handleReturn = (id: string) => {
    const rental = rentals.find(r => r.id === id);
    if (rental) {
      const lateFee = calculateLateFee(rental.expectedReturnDate, undefined, rental.dailyRate, rental.quantity);
      if (confirm(`Process return for this rental? Late fees calculated: ${formatCurrency(lateFee)}`)) {
        returnRental(id, lateFee);
      }
    }
  };

  const filteredRentals = rentals.filter(r => {
    const cust = customers.find(c => c.id === r.customerId);
    const prod = products.find(p => p.id === r.productId);
    return (
      cust?.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      prod?.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      r.invoiceNumber.toLowerCase().includes(searchTerm.toLowerCase())
    );
  });

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Rental Tracking</h1>
          <p className="text-sm text-gray-500">Manage active leases and equipment returns</p>
        </div>
        <Button onClick={() => setIsNewRentalModalOpen(true)} className="flex items-center gap-2">
          <Plus size={20} /> Create New Rental
        </Button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <Card className="p-4 bg-blue-50 border-blue-100 flex items-center space-x-4">
          <div className="p-3 bg-white rounded-xl shadow-sm text-blue-600"><Calendar /></div>
          <div>
            <p className="text-sm text-blue-700 font-medium">Active Rentals</p>
            <h3 className="text-xl font-bold text-blue-900">{rentals.filter(r => r.status === 'ACTIVE').length}</h3>
          </div>
        </Card>
        <Card className="p-4 bg-red-50 border-red-100 flex items-center space-x-4">
          <div className="p-3 bg-white rounded-xl shadow-sm text-red-600"><AlertCircle /></div>
          <div>
            <p className="text-sm text-red-700 font-medium">Overdue Returns</p>
            <h3 className="text-xl font-bold text-red-900">{rentals.filter(r => r.status === 'ACTIVE' && new Date(r.expectedReturnDate) < new Date()).length}</h3>
          </div>
        </Card>
        <Card className="p-4 bg-green-50 border-green-100 flex items-center space-x-4">
          <div className="p-3 bg-white rounded-xl shadow-sm text-green-600"><CheckCircle /></div>
          <div>
            <p className="text-sm text-green-700 font-medium">Completed Today</p>
            <h3 className="text-xl font-bold text-green-900">0</h3>
          </div>
        </Card>
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
        <input 
          type="text" 
          placeholder="Search rentals by customer, product or invoice..." 
          className="w-full pl-10 pr-4 py-2 bg-white border border-gray-200 rounded-xl outline-none"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <Card>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead>
              <tr className="bg-gray-50 border-b text-gray-400">
                <th className="px-6 py-4 font-semibold">ID & Customer</th>
                <th className="px-6 py-4 font-semibold">Product</th>
                <th className="px-6 py-4 font-semibold">Duration</th>
                <th className="px-6 py-4 font-semibold">Amount</th>
                <th className="px-6 py-4 font-semibold">Status</th>
                <th className="px-6 py-4 font-semibold text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y">
              {filteredRentals.map(rental => {
                const customer = customers.find(c => c.id === rental.customerId);
                const product = products.find(p => p.id === rental.productId);
                return (
                  <tr key={rental.id} className="hover:bg-gray-50">
                    <td className="px-6 py-4">
                      <div className="font-bold text-gray-900">{rental.invoiceNumber}</div>
                      <div className="text-xs text-gray-500">{customer?.name}</div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="font-medium text-gray-800">{product?.name}</div>
                      <div className="text-xs text-gray-400">Qty: {rental.quantity}</div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="text-xs">Start: {new Date(rental.startDate).toLocaleDateString()}</div>
                      <div className="text-xs font-bold text-red-600">End: {new Date(rental.expectedReturnDate).toLocaleDateString()}</div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="font-bold text-indigo-600">{formatCurrency(rental.totalRentAmount)}</div>
                      <div className="text-[10px] text-gray-400">Deposit: {formatCurrency(rental.securityDeposit)}</div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`px-2 py-1 rounded-full text-xs font-bold ${getStatusColor(rental.status)}`}>
                        {rental.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      {rental.status === 'ACTIVE' && (
                        <Button variant="secondary" onClick={() => handleReturn(rental.id)} className="text-xs">
                          Return Item
                        </Button>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          {filteredRentals.length === 0 && (
            <div className="py-20 text-center text-gray-500 italic">No rental records found.</div>
          )}
        </div>
      </Card>

      <Modal isOpen={isNewRentalModalOpen} onClose={() => setIsNewRentalModalOpen(false)} title="Create New Rental Agreement">
        <form onSubmit={handleCreateRental} className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-500">Customer</label>
            <select name="customerId" required className="w-full px-4 py-2 border rounded-xl">
              {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-500">Product</label>
            <select name="productId" required className="w-full px-4 py-2 border rounded-xl">
              {products.map(p => <option key={p.id} value={p.id}>{p.name} ({formatCurrency(p.rentalPrice)}/day)</option>)}
            </select>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-500">Quantity</label>
            <input name="quantity" type="number" defaultValue="1" required className="w-full px-4 py-2 border rounded-xl" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-500">Security Deposit</label>
            <input name="securityDeposit" type="number" required className="w-full px-4 py-2 border rounded-xl" placeholder="Refundable amount" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-500">Start Date</label>
            <input name="startDate" type="date" required className="w-full px-4 py-2 border rounded-xl" defaultValue={new Date().toISOString().split('T')[0]} />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-500">Expected Return</label>
            <input name="expectedReturnDate" type="date" required className="w-full px-4 py-2 border rounded-xl" />
          </div>
          <div className="col-span-2 space-y-1">
            <label className="text-xs font-bold uppercase text-gray-500">Payment Received</label>
            <input name="paidAmount" type="number" required className="w-full px-4 py-2 border rounded-xl" placeholder="Total payment received" />
          </div>
          <div className="col-span-2 flex gap-3 pt-4">
            <Button variant="ghost" onClick={() => setIsNewRentalModalOpen(false)} className="flex-1">Cancel</Button>
            <Button type="submit" className="flex-1">Issue Rental Invoice</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Rentals;

import React, { useState } from 'react';
import { AppProvider } from './store/AppContext';
import { NAVIGATION_ITEMS } from './constants';
import Dashboard from './pages/Dashboard';
import Inventory from './pages/Inventory';
import Rentals from './pages/Rentals';
import { 
  Bell, 
  Menu, 
  Search, 
  User, 
  LogOut, 
  Settings 
} from 'lucide-react';

