import React, { useState, useMemo } from 'react';
import { useApp } from '../store/AppContext';
import { Card, Button, Modal } from '../components/Shared';
import { 
  Search, 
  Plus, 
  Phone, 
  Mail, 
  MapPin, 
  ArrowLeft, 
  FileText, 
  RefreshCcw, 
  ShoppingBag,
  TrendingUp,
  Calendar
} from 'lucide-react';
import { formatCurrency, getStatusColor } from '../utils/helpers';
import { Sale, Rental, Customer } from '../types';

const Customers: React.FC = () => {
  const { customers, addCustomer, sales, rentals, products } = useApp();
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [transactionFilter, setTransactionFilter] = useState<'ALL' | 'SALE' | 'RENTAL'>('ALL');

  // Derived state for the selected customer's ledger
  const selectedCustomer = useMemo(() => 
    customers.find(c => c.id === selectedCustomerId), 
  [customers, selectedCustomerId]);

  const customerHistory = useMemo(() => {
    if (!selectedCustomerId) return { transactions: [], stats: { totalSpent: 0, activeRentals: 0, totalOrders: 0 } };

    const customerSales = sales.filter(s => s.customerId === selectedCustomerId).map(s => ({
      ...s,
      type: 'SALE' as const,
      sortDate: new Date(s.date)
    }));

    const customerRentals = rentals.filter(r => r.customerId === selectedCustomerId).map(r => ({
      ...r,
      type: 'RENTAL' as const,
      sortDate: new Date(r.date)
    }));

    // Merge and sort by date descending
    const allTransactions = [...customerSales, ...customerRentals].sort((a, b) => 
      b.sortDate.getTime() - a.sortDate.getTime()
    );

    const totalSpent = allTransactions.reduce((acc, t) => {
      if (t.type === 'SALE') return acc + (t as Sale).totalAmount;
      if (t.type === 'RENTAL') return acc + (t as Rental).totalRentAmount;
      return acc;
    }, 0);

    const activeRentals = customerRentals.filter(r => r.status === 'ACTIVE').length;

    // Apply Filter
    const visibleTransactions = allTransactions.filter(t => {
      if (transactionFilter === 'ALL') return true;
      return t.type === transactionFilter;
    });

    return {
      transactions: visibleTransactions,
      stats: {
        totalSpent,
        activeRentals,
        totalOrders: allTransactions.length // Lifetime total orders
      }
    };
  }, [sales, rentals, selectedCustomerId, transactionFilter]);

  const handleAddCustomer = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    addCustomer({
      name: formData.get('name') as string,
      phone: formData.get('phone') as string,
      email: formData.get('email') as string,
      address: formData.get('address') as string,
      gstin: formData.get('gstin') as string,
    });
    setIsAddModalOpen(false);
  };

  const filteredCustomers = customers.filter(c => 
    c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    c.phone.includes(searchTerm)
  );

  // -- RENDER: Customer Ledger (Detail View) --
  if (selectedCustomer) {
    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
        <div className="flex items-center gap-4">
          <button 
            onClick={() => setSelectedCustomerId(null)}
            className="p-2 hover:bg-white rounded-full transition-colors border border-transparent hover:border-gray-200"
          >
            <ArrowLeft size={24} className="text-gray-600" />
          </button>
          <div>
            <h1 className="text-2xl font-bold text-gray-800">{selectedCustomer.name}</h1>
            <p className="text-sm text-gray-500">Customer Ledger & History</p>
          </div>
        </div>

        {/* Customer Profile Card */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <Card className="p-6 col-span-1">
            <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider mb-4">Contact Details</h3>
            <div className="space-y-4">
              <div className="flex items-center gap-3">
                <div className="w-8 h-8 rounded-full bg-indigo-50 flex items-center justify-center text-indigo-600">
                  <Phone size={16} />
                </div>
                <div className="text-sm font-medium text-gray-700">{selectedCustomer.phone}</div>
              </div>
              <div className="flex items-center gap-3">
                <div className="w-8 h-8 rounded-full bg-indigo-50 flex items-center justify-center text-indigo-600">
                  <Mail size={16} />
                </div>
                <div className="text-sm font-medium text-gray-700">{selectedCustomer.email}</div>
              </div>
              <div className="flex items-center gap-3">
                <div className="w-8 h-8 rounded-full bg-indigo-50 flex items-center justify-center text-indigo-600">
                  <MapPin size={16} />
                </div>
                <div className="text-sm font-medium text-gray-700">{selectedCustomer.address}</div>
              </div>
              {selectedCustomer.gstin && (
                <div className="pt-4 border-t border-gray-100">
                   <p className="text-xs text-gray-400 uppercase">GSTIN / Tax ID</p>
                   <p className="font-mono text-sm text-gray-700">{selectedCustomer.gstin}</p>
                </div>
              )}
            </div>
          </Card>

          <Card className="p-6 col-span-1 lg:col-span-2">
            <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider mb-4">Performance Overview</h3>
            <div className="grid grid-cols-3 gap-6">
              <div className="p-4 bg-emerald-50 rounded-xl border border-emerald-100">
                <div className="flex items-center gap-2 mb-2 text-emerald-700">
                  <TrendingUp size={18} />
                  <span className="text-xs font-bold uppercase">Lifetime Value</span>
                </div>
                <p className="text-2xl font-bold text-gray-900">{formatCurrency(customerHistory.stats.totalSpent)}</p>
              </div>
              <div className="p-4 bg-blue-50 rounded-xl border border-blue-100">
                <div className="flex items-center gap-2 mb-2 text-blue-700">
                  <RefreshCcw size={18} />
                  <span className="text-xs font-bold uppercase">Active Rentals</span>
                </div>
                <p className="text-2xl font-bold text-gray-900">{customerHistory.stats.activeRentals}</p>
              </div>
              <div className="p-4 bg-purple-50 rounded-xl border border-purple-100">
                <div className="flex items-center gap-2 mb-2 text-purple-700">
                  <ShoppingBag size={18} />
                  <span className="text-xs font-bold uppercase">Total Transactions</span>
                </div>
                <p className="text-2xl font-bold text-gray-900">{customerHistory.stats.totalOrders}</p>
              </div>
            </div>
          </Card>
        </div>

        {/* Transaction History Table */}
        <Card className="overflow-hidden">
          <div className="p-6 border-b border-gray-100 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
             <div className="flex items-center gap-4">
               <h3 className="font-bold text-gray-800">Transaction History</h3>
               <div className="flex bg-gray-100 p-1 rounded-lg">
                  <button 
                    onClick={() => setTransactionFilter('ALL')} 
                    className={`px-3 py-1 text-xs font-medium rounded-md transition-all ${transactionFilter === 'ALL' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                  >
                    All
                  </button>
                  <button 
                    onClick={() => setTransactionFilter('SALE')} 
                    className={`px-3 py-1 text-xs font-medium rounded-md transition-all ${transactionFilter === 'SALE' ? 'bg-white text-emerald-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                  >
                    Sales
                  </button>
                  <button 
                    onClick={() => setTransactionFilter('RENTAL')} 
                    className={`px-3 py-1 text-xs font-medium rounded-md transition-all ${transactionFilter === 'RENTAL' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                  >
                    Rentals
                  </button>
               </div>
             </div>

             <div className="flex gap-2">
               {(transactionFilter === 'ALL' || transactionFilter === 'SALE') && (
                 <span className="flex items-center text-xs text-gray-500 gap-1"><span className="w-2 h-2 rounded-full bg-emerald-500"></span> Sale</span>
               )}
               {(transactionFilter === 'ALL' || transactionFilter === 'RENTAL') && (
                 <span className="flex items-center text-xs text-gray-500 gap-1"><span className="w-2 h-2 rounded-full bg-blue-500"></span> Rental</span>
               )}
             </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead className="bg-gray-50 text-gray-500">
                <tr>
                  <th className="px-6 py-4 font-semibold">Date</th>
                  <th className="px-6 py-4 font-semibold">Type</th>
                  <th className="px-6 py-4 font-semibold">Details</th>
                  <th className="px-6 py-4 font-semibold text-right">Amount</th>
                  <th className="px-6 py-4 font-semibold text-center">Status</th>
                </tr>
              </thead>
              <tbody className="divide-y">
                {customerHistory.transactions.map((t: any) => {
                  const isSale = t.type === 'SALE';
                  const productName = isSale 
                    ? `${t.items.length} Items` 
                    : products.find(p => p.id === t.productId)?.name || 'Unknown Product';

                  return (
                    <tr key={t.id} className="hover:bg-gray-50">
                      <td className="px-6 py-4">
                        <div className="font-medium text-gray-900">{new Date(t.date).toLocaleDateString()}</div>
                        <div className="text-xs text-gray-400 font-mono">{t.invoiceNumber}</div>
                      </td>
                      <td className="px-6 py-4">
                         {isSale ? (
                           <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium bg-emerald-100 text-emerald-800">
                             <ShoppingBag size={12} /> Sale
                           </span>
                         ) : (
                           <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
                             <RefreshCcw size={12} /> Rental
                           </span>
                         )}
                      </td>
                      <td className="px-6 py-4">
                        <div className="text-gray-900 font-medium">{productName}</div>
                        {!isSale && (
                          <div className="text-xs text-gray-500 mt-1 flex items-center gap-1">
                             <Calendar size={10} />
                             Due: {new Date(t.expectedReturnDate).toLocaleDateString()}
                          </div>
                        )}
                      </td>
                      <td className="px-6 py-4 text-right font-bold text-gray-700">
                        {formatCurrency(isSale ? t.totalAmount : t.totalRentAmount)}
                      </td>
                      <td className="px-6 py-4 text-center">
                         <span className={`px-2 py-1 rounded-full text-xs font-bold ${isSale ? 'bg-gray-100 text-gray-600' : getStatusColor(t.status)}`}>
                            {isSale ? t.paymentStatus : t.status}
                         </span>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            {customerHistory.transactions.length === 0 && (
              <div className="py-12 text-center text-gray-500 italic">No {transactionFilter !== 'ALL' ? transactionFilter.toLowerCase() : ''} transactions found.</div>
            )}
          </div>
        </Card>
      </div>
    );
  }

  // -- RENDER: Customer Directory (List View) --
  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Customers</h1>
          <p className="text-sm text-gray-500">Manage client relationships and view ledgers</p>
        </div>
        <Button onClick={() => setIsAddModalOpen(true)} className="flex items-center gap-2">
          <Plus size={20} /> Add New Customer
        </Button>
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
        <input 
          type="text" 
          placeholder="Search customers by name or phone..." 
          className="w-full pl-10 pr-4 py-2 bg-white border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500/20 transition-all"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <Card className="overflow-hidden">
        <table className="w-full text-left text-sm">
          <thead>
            <tr className="bg-gray-50 border-b text-gray-500">
              <th className="px-6 py-4 font-semibold uppercase">Customer Name</th>
              <th className="px-6 py-4 font-semibold uppercase">Contact Info</th>
              <th className="px-6 py-4 font-semibold uppercase text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y">
            {filteredCustomers.map(customer => (
              <tr key={customer.id} className="hover:bg-gray-50 group transition-colors">
                <td className="px-6 py-4">
                  <div className="flex items-center space-x-3">
                    <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-600 text-white rounded-full flex items-center justify-center font-bold text-lg">
                      {customer.name.charAt(0)}
                    </div>
                    <div>
                      <div className="font-bold text-gray-900">{customer.name}</div>
                      <div className="text-xs text-gray-400">ID: {customer.id}</div>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <div className="space-y-1">
                    <div className="flex items-center text-gray-600 gap-2">
                      <Phone size={14} /> {customer.phone}
                    </div>
                    <div className="flex items-center text-gray-500 text-xs gap-2">
                      <Mail size={14} /> {customer.email}
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4 text-right">
                  <Button variant="secondary" onClick={() => setSelectedCustomerId(customer.id)} className="text-xs">
                    <FileText size={14} className="mr-2 inline" /> View Ledger
                  </Button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {filteredCustomers.length === 0 && (
          <div className="py-20 text-center text-gray-500 italic">No customers found. Add one to get started.</div>
        )}
      </Card>

      <Modal isOpen={isAddModalOpen} onClose={() => setIsAddModalOpen(false)} title="Add New Customer">
        <form onSubmit={handleAddCustomer} className="grid grid-cols-1 gap-4">
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-500">Full Name</label>
            <input name="name" required className="w-full px-4 py-2 border rounded-xl" placeholder="John Doe" />
          </div>
