import React, { useState, useMemo } from 'react';
import { useApp } from '../store/AppContext';
import { Card, Button, Modal } from '../components/Shared';
import { 
  Search, 
  Plus, 
  Phone, 
  Mail, 
  MapPin, 
  ArrowLeft, 
  FileText, 
  RefreshCcw, 
  ShoppingBag,
  TrendingUp,
  Calendar
} from 'lucide-react';
import { formatCurrency, getStatusColor } from '../utils/helpers';
import { Sale, Rental, Customer } from '../types';

const Customers: React.FC = () => {
  const { customers, addCustomer, sales, rentals, products } = useApp();
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [transactionFilter, setTransactionFilter] = useState<'ALL' | 'SALE' | 'RENTAL'>('ALL');

  // Derived state for the selected customer's ledger
  const selectedCustomer = useMemo(() => 
    customers.find(c => c.id === selectedCustomerId), 
  [customers, selectedCustomerId]);

  const customerHistory = useMemo(() => {
    if (!selectedCustomerId) return { transactions: [], stats: { totalSpent: 0, activeRentals: 0, totalOrders: 0 } };

    const customerSales = sales.filter(s => s.customerId === selectedCustomerId).map(s => ({
      ...s,
      type: 'SALE' as const,
      sortDate: new Date(s.date)
    }));

    const customerRentals = rentals.filter(r => r.customerId === selectedCustomerId).map(r => ({
      ...r,
      type: 'RENTAL' as const,
      sortDate: new Date(r.date)
    }));

    // Merge and sort by date descending
    const allTransactions = [...customerSales, ...customerRentals].sort((a, b) => 
      b.sortDate.getTime() - a.sortDate.getTime()
    );

    const totalSpent = allTransactions.reduce((acc, t) => {
      if (t.type === 'SALE') return acc + (t as Sale).totalAmount;
      if (t.type === 'RENTAL') return acc + (t as Rental).totalRentAmount;
      return acc;
    }, 0);

    const activeRentals = customerRentals.filter(r => r.status === 'ACTIVE').length;

    // Apply Filter
    const visibleTransactions = allTransactions.filter(t => {
      if (transactionFilter === 'ALL') return true;
      return t.type === transactionFilter;
    });

    return {
      transactions: visibleTransactions,
      stats: {
        totalSpent,
        activeRentals,
        totalOrders: allTransactions.length // Lifetime total orders
      }
    };
  }, [sales, rentals, selectedCustomerId, transactionFilter]);

  const handleAddCustomer = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    addCustomer({
      name: formData.get('name') as string,
      phone: formData.get('phone') as string,
      email: formData.get('email') as string,
      address: formData.get('address') as string,
      gstin: formData.get('gstin') as string,
    });
    setIsAddModalOpen(false);
  };

  const filteredCustomers = customers.filter(c => 
    c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    c.phone.includes(searchTerm)
  );

  // -- RENDER: Customer Ledger (Detail View) --
  if (selectedCustomer) {
    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
        <div className="flex items-center gap-4">
          <button 
            onClick={() => setSelectedCustomerId(null)}
            className="p-2 hover:bg-white rounded-full transition-colors border border-transparent hover:border-gray-200 text-gray-500"
          >
            <ArrowLeft size={24} />
          </button>
          <div>
            <h1 className="text-2xl font-bold text-gray-800">{selectedCustomer.name}</h1>
            <p className="text-sm text-gray-400">Customer Ledger & History</p>
          </div>
        </div>

        {/* Customer Profile Card */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <Card className="p-6 col-span-1 border-0 shadow-sm">
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-6">Contact Details</h3>
            <div className="space-y-6">
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 rounded-xl bg-sky-50 flex items-center justify-center text-sky-500">
                  <Phone size={18} />
                </div>
                <div className="text-sm font-medium text-gray-700">{selectedCustomer.phone}</div>
              </div>
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 rounded-xl bg-sky-50 flex items-center justify-center text-sky-500">
                  <Mail size={18} />
                </div>
                <div className="text-sm font-medium text-gray-700">{selectedCustomer.email}</div>
              </div>
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 rounded-xl bg-sky-50 flex items-center justify-center text-sky-500">
                  <MapPin size={18} />
                </div>
                <div className="text-sm font-medium text-gray-700">{selectedCustomer.address}</div>
              </div>
              {selectedCustomer.gstin && (
                <div className="pt-4 border-t border-gray-100">
                   <p className="text-[10px] text-gray-400 uppercase font-bold tracking-wider">GSTIN / Tax ID</p>
                   <p className="font-mono text-sm text-gray-700 mt-1">{selectedCustomer.gstin}</p>
                </div>
              )}
            </div>
          </Card>

          <Card className="p-6 col-span-1 lg:col-span-2 border-0 shadow-sm">
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-6">Overview</h3>
            <div className="grid grid-cols-3 gap-6">
              <div className="p-5 bg-yellow-50 rounded-2xl border border-yellow-100">
                <div className="flex items-center gap-2 mb-2 text-yellow-600">
                  <TrendingUp size={18} />
                  <span className="text-[10px] font-black uppercase tracking-wider">LTV</span>
                </div>
                <p className="text-2xl font-black text-gray-800">{formatCurrency(customerHistory.stats.totalSpent)}</p>
              </div>
              <div className="p-5 bg-sky-50 rounded-2xl border border-sky-100">
                <div className="flex items-center gap-2 mb-2 text-sky-600">
                  <RefreshCcw size={18} />
                  <span className="text-[10px] font-black uppercase tracking-wider">Active Rentals</span>
                </div>
                <p className="text-2xl font-black text-gray-800">{customerHistory.stats.activeRentals}</p>
              </div>
              <div className="p-5 bg-pink-50 rounded-2xl border border-pink-100">
                <div className="flex items-center gap-2 mb-2 text-pink-600">
                  <ShoppingBag size={18} />
                  <span className="text-[10px] font-black uppercase tracking-wider">Transactions</span>
                </div>
                <p className="text-2xl font-black text-gray-800">{customerHistory.stats.totalOrders}</p>
              </div>
            </div>
          </Card>
        </div>

        {/* Transaction History Table */}
        <Card className="overflow-hidden border-0 shadow-sm">
          <div className="p-6 border-b border-gray-50 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
             <div className="flex items-center gap-4">
