import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { AppState, Product, Customer, Supplier, Sale, Rental, StockLog, RentalStatus, PaymentStatus } from '../types';
import { generateID } from '../utils/helpers';

interface AppContextType extends AppState {
  addProduct: (product: Omit<Product, 'id' | 'createdAt'>) => void;
  updateProduct: (id: string, product: Partial<Product>) => void;
  deleteProduct: (id: string) => void;
  addCustomer: (customer: Omit<Customer, 'id' | 'createdAt'>) => void;
  addSupplier: (supplier: Omit<Supplier, 'id' | 'createdAt'>) => void;
  addSale: (sale: Omit<Sale, 'id' | 'invoiceNumber' | 'date'>) => void;
  addPaymentToSale: (saleId: string, amount: number) => void;
  addRental: (rental: Omit<Rental, 'id' | 'invoiceNumber' | 'date' | 'status' | 'lateFee' | 'actualReturnDate'>) => void;
  returnRental: (rentalId: string, lateFee: number) => void;
  updateStock: (productId: string, quantity: number, type: 'IN' | 'OUT', reason: string) => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

const INITIAL_DATA: AppState = {
  products: [
    { id: 'P1', name: 'Princess Gown - Pink (4-5Y)', sku: 'DRS-001', barcode: '123456', category: 'Party Wear', purchasePrice: 1500, sellingPrice: 3500, rentalPrice: 500, taxPercent: 12, stockQuantity: 5, minStockAlert: 2, supplierId: 'S1', description: 'Sequined pink party gown with bow.', createdAt: new Date().toISOString() },
    { id: 'P2', name: 'Tuxedo Suit Set (Black)', sku: 'SUIT-002', barcode: '654321', category: 'Boys Wear', purchasePrice: 2000, sellingPrice: 4500, rentalPrice: 800, taxPercent: 12, stockQuantity: 8, minStockAlert: 3, supplierId: 'S1', description: '5-piece tuxedo suit set for boys.', createdAt: new Date().toISOString() },
    { id: 'P3', name: 'Superhero Costume (Spiderman)', sku: 'COS-003', barcode: '789012', category: 'Costumes', purchasePrice: 800, sellingPrice: 1800, rentalPrice: 300, taxPercent: 12, stockQuantity: 12, minStockAlert: 4, supplierId: 'S1', description: 'Full body superhero costume.', createdAt: new Date().toISOString() }
  ],
  customers: [
    { id: 'C1', name: 'Sarah Jenkins', phone: '9876543210', email: 'sarah@example.com', address: '123 Main St, Springfield', createdAt: new Date().toISOString() }
  ],
  suppliers: [
    { id: 'S1', name: 'Tiny Tots Wholesalers', contactPerson: 'Mike Brown', phone: '1122334455', email: 'orders@tinytots.com', address: 'Garment District, City', createdAt: new Date().toISOString() }
  ],
  sales: [],
  rentals: [],
  stockLogs: []
};

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('inventory_pro_data');
    return saved ? JSON.parse(saved) : INITIAL_DATA;
  });

  useEffect(() => {
    localStorage.setItem('inventory_pro_data', JSON.stringify(state));
  }, [state]);

  const addProduct = (p: Omit<Product, 'id' | 'createdAt'>) => {
    const newProduct: Product = { ...p, id: generateID(), createdAt: new Date().toISOString() };
    setState(prev => ({ ...prev, products: [...prev.products, newProduct] }));
  };

  const updateProduct = (id: string, updates: Partial<Product>) => {
    setState(prev => ({
      ...prev,
      products: prev.products.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const deleteProduct = (id: string) => {
    setState(prev => ({ ...prev, products: prev.products.filter(p => p.id !== id) }));
  };

  const addCustomer = (c: Omit<Customer, 'id' | 'createdAt'>) => {
    const newCustomer: Customer = { ...c, id: generateID(), createdAt: new Date().toISOString() };
    setState(prev => ({ ...prev, customers: [...prev.customers, newCustomer] }));
  };

  const addSupplier = (s: Omit<Supplier, 'id' | 'createdAt'>) => {
    const newSupplier: Supplier = { ...s, id: generateID(), createdAt: new Date().toISOString() };
    setState(prev => ({ ...prev, suppliers: [...prev.suppliers, newSupplier] }));
  };

  const addSale = (s: Omit<Sale, 'id' | 'invoiceNumber' | 'date'>) => {
    const newSale: Sale = {
      ...s,
      id: generateID(),
      invoiceNumber: `INV-${state.sales.length + 1001}`,
      date: new Date().toISOString()
    };

    // Update stock for all items
    s.items.forEach(item => {
      updateStock(item.productId, item.quantity, 'OUT', `Sale ${newSale.invoiceNumber}`);
    });

    setState(prev => ({ ...prev, sales: [...prev.sales, newSale] }));
  };

  const addPaymentToSale = (saleId: string, amount: number) => {
    setState(prev => ({
      ...prev,
      sales: prev.sales.map(s => {
        if (s.id === saleId) {
          const newPaidAmount = s.paidAmount + amount;
          return {
            ...s,
            paidAmount: newPaidAmount,
            paymentStatus: newPaidAmount >= s.totalAmount ? PaymentStatus.PAID : PaymentStatus.PARTIAL
          };
        }
        return s;
      })
    }));
  };

  const addRental = (r: Omit<Rental, 'id' | 'invoiceNumber' | 'date' | 'status' | 'lateFee' | 'actualReturnDate'>) => {
    const newRental: Rental = {
      ...r,
      id: generateID(),
      invoiceNumber: `RNT-${state.rentals.length + 1001}`,
      date: new Date().toISOString(),
      status: RentalStatus.ACTIVE,
      lateFee: 0
    };

    updateStock(r.productId, r.quantity, 'OUT', `Rental ${newRental.invoiceNumber}`);
    setState(prev => ({ ...prev, rentals: [...prev.rentals, newRental] }));
  };

  const returnRental = (id: string, lateFee: number) => {
    const rental = state.rentals.find(r => r.id === id);
    if (!rental) return;

    updateStock(rental.productId, rental.quantity, 'IN', `Return ${rental.invoiceNumber}`);

    setState(prev => ({
      ...prev,
      rentals: prev.rentals.map(r => r.id === id ? {
        ...r,
        status: RentalStatus.RETURNED,
        actualReturnDate: new Date().toISOString(),
        lateFee: lateFee,
        totalRentAmount: r.totalRentAmount + lateFee
      } : r)
    }));
  };

  const updateStock = (productId: string, quantity: number, type: 'IN' | 'OUT', reason: string) => {
    const log: StockLog = {
      id: generateID(),
      productId,
      type,
      quantity,
      reason,
      date: new Date().toISOString()
    };

    setState(prev => ({
      ...prev,
      products: prev.products.map(p => 
        p.id === productId 
          ? { ...p, stockQuantity: type === 'IN' ? p.stockQuantity + quantity : p.stockQuantity - quantity }
          : p
      ),
      stockLogs: [...prev.stockLogs, log]
    }));
  };

  return (
    <AppContext.Provider value={{ 
      ...state, 
      addProduct, 
      updateProduct, 
      deleteProduct, 
      addCustomer, 
      addSupplier, 
      addSale, 
      addPaymentToSale,
      addRental, 
      returnRental,
      updateStock 
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useApp must be used within AppProvider');
  return context;
};

import React, { useState, useMemo } from 'react';
import { useApp } from '../store/AppContext';
import { Card, Button, Modal } from '../components/Shared';
import { 
  Search, 
  Plus, 
  Phone, 
  Mail, 
  MapPin, 
  ArrowLeft, 
  FileText, 
  RefreshCcw, 
  ShoppingBag,
  TrendingUp,
  Calendar,
  Banknote,
  IndianRupee
} from 'lucide-react';
import { formatCurrency, getStatusColor } from '../utils/helpers';
