                <p className="text-2xl font-black text-gray-800">{customerHistory.stats.totalOrders}</p>
              </div>
            </div>
          </Card>
        </div>

        {/* Transaction History Table */}
        <Card className="overflow-hidden border-0 shadow-sm">
          <div className="p-6 border-b border-gray-50 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
             <div className="flex items-center gap-4">
               <h3 className="font-bold text-gray-800">History</h3>
               <div className="flex bg-gray-50 p-1 rounded-xl">
                  <button 
                    onClick={() => setTransactionFilter('ALL')} 
                    className={`px-4 py-1.5 text-xs font-bold rounded-lg transition-all ${transactionFilter === 'ALL' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                  >
                    All
                  </button>
                  <button 
                    onClick={() => setTransactionFilter('SALE')} 
                    className={`px-4 py-1.5 text-xs font-bold rounded-lg transition-all ${transactionFilter === 'SALE' ? 'bg-white text-emerald-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                  >
                    Sales
                  </button>
                  <button 
                    onClick={() => setTransactionFilter('RENTAL')} 
                    className={`px-4 py-1.5 text-xs font-bold rounded-lg transition-all ${transactionFilter === 'RENTAL' ? 'bg-white text-sky-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                  >
                    Rentals
                  </button>
               </div>
             </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead className="bg-gray-50/50 text-gray-400">
                <tr>
                  <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Date</th>
                  <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Type</th>
                  <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Details</th>
                  <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Payment</th>
                  <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-center">Status</th>
                  <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {customerHistory.transactions.map((t: any) => {
                  const isSale = t.type === 'SALE';
                  const productName = isSale 
                    ? `${t.items.length} Items` 
                    : products.find(p => p.id === t.productId)?.name || 'Unknown Product';

                  // Calculate balances
                  const total = isSale ? t.totalAmount : t.totalRentAmount;
                  const paid = t.paidAmount || 0;
                  const balance = total - paid;

                  return (
                    <tr key={t.id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-6 py-4">
                        <div className="font-bold text-gray-800">{new Date(t.date).toLocaleDateString()}</div>
                        <div className="text-xs text-gray-400 font-mono">{t.invoiceNumber}</div>
                      </td>
                      <td className="px-6 py-4">
                         {isSale ? (
                           <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold bg-emerald-50 text-emerald-600">
                             <ShoppingBag size={12} /> SALE
                           </span>
                         ) : (
                           <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold bg-sky-50 text-sky-600">
                             <RefreshCcw size={12} /> RENTAL
                           </span>
                         )}
                      </td>
                      <td className="px-6 py-4">
                        <div className="text-gray-800 font-medium">{productName}</div>
                        {!isSale && (
                          <div className="text-xs text-pink-500 mt-1 flex items-center gap-1 font-medium">
                             <Calendar size={10} />
                             Due: {new Date(t.expectedReturnDate).toLocaleDateString()}
                          </div>
                        )}
                      </td>
                      <td className="px-6 py-4 text-right">
                         <div className="font-bold text-gray-700">{formatCurrency(total)}</div>
                         {isSale && balance > 0 && (
                            <div className="text-[10px] font-bold text-pink-500 mt-0.5">
                               Bal: {formatCurrency(balance)}
                            </div>
                         )}
                         {isSale && balance <= 0 && (
                            <div className="text-[10px] font-bold text-emerald-500 mt-0.5">
                               Fully Paid
                            </div>
                         )}
                      </td>
                      <td className="px-6 py-4 text-center">
                         <span className={`px-2 py-1 rounded-full text-[10px] font-bold uppercase tracking-wide ${isSale ? 'bg-gray-100 text-gray-500' : getStatusColor(t.status)}`}>
                            {isSale ? t.paymentStatus : t.status}
                         </span>
                      </td>
                      <td className="px-6 py-4 text-right">
                         {isSale && t.paymentStatus !== PaymentStatus.PAID && (
                            <button 
                              onClick={() => openPaymentModal(t.id)}
                              className="text-xs font-bold text-sky-500 hover:text-sky-600 bg-sky-50 hover:bg-sky-100 px-3 py-1.5 rounded-lg transition-colors inline-flex items-center gap-1"
                            >
                               <Banknote size={14} /> Pay
                            </button>
                         )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            {customerHistory.transactions.length === 0 && (
              <div className="py-12 text-center text-gray-400 italic">No {transactionFilter !== 'ALL' ? transactionFilter.toLowerCase() : ''} transactions found.</div>
            )}
          </div>
        </Card>

        {/* Payment Modal */}
        <Modal 
           isOpen={isPaymentModalOpen} 
           onClose={() => { setIsPaymentModalOpen(false); setSelectedSaleForPayment(null); }} 
           title={`Record Payment: ${activePaymentSale?.invoiceNumber}`}
        >
           <form onSubmit={handleRecordPayment} className="space-y-4">
              <div className="p-4 bg-gray-50 rounded-xl space-y-2 border border-gray-100">
                 <div className="flex justify-between text-sm">
                    <span className="text-gray-500">Total Invoice Amount:</span>
                    <span className="font-bold text-gray-800">{formatCurrency(activePaymentSale?.totalAmount || 0)}</span>
                 </div>
                 <div className="flex justify-between text-sm">
                    <span className="text-gray-500">Already Paid:</span>
                    <span className="font-bold text-emerald-600">{formatCurrency(activePaymentSale?.paidAmount || 0)}</span>
                 </div>
                 <div className="flex justify-between text-sm pt-2 border-t border-gray-200">
                    <span className="font-bold text-gray-700">Balance Due:</span>
                    <span className="font-bold text-pink-500">{formatCurrency(activePaymentBalance)}</span>
                 </div>
              </div>

              <div className="space-y-1">
                 <label className="text-xs font-bold uppercase text-gray-400">Payment Amount</label>
                 <div className="relative">
                    <IndianRupee className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                    <input 
                      name="amount" 
                      type="number" 
                      max={activePaymentBalance}
                      min={1}
                      required 
                      autoFocus
                      className="w-full pl-10 pr-4 py-3 bg-white border border-gray-200 focus:border-sky-200 rounded-xl outline-none transition-all font-medium" 
                      placeholder="Enter amount" 
                    />
                 </div>
                 <p className="text-[10px] text-gray-400">Enter value less than or equal to balance.</p>
              </div>

              <div className="flex gap-3 pt-4">
                 <Button variant="ghost" onClick={() => setIsPaymentModalOpen(false)} className="flex-1">Cancel</Button>
                 <Button type="submit" className="flex-1">Save Payment</Button>
              </div>
           </form>
        </Modal>
      </div>
    );
  }

  // -- RENDER: Customer Directory (List View) --
  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-800 tracking-tight">Customers</h1>
          <p className="text-sm font-medium text-gray-400">Manage client relationships</p>
        </div>
        <Button onClick={() => setIsAddModalOpen(true)} className="flex items-center gap-2">
          <Plus size={20} /> Add Customer
        </Button>
      </div>

      <div className="relative">
        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
