          type="text" 
          placeholder="Search customers..." 
          className="w-full pl-11 pr-4 py-3 bg-white border border-gray-100 rounded-2xl outline-none focus:ring-2 focus:ring-sky-100 transition-all font-medium text-gray-600"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <Card className="overflow-hidden border-0 shadow-sm">
        <table className="w-full text-left text-sm">
          <thead>
            <tr className="bg-gray-50/50 border-b border-gray-100 text-gray-400">
              <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Customer Name</th>
              <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Contact Info</th>
              <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50">
            {filteredCustomers.map(customer => (
              <tr key={customer.id} className="hover:bg-gray-50 group transition-colors">
                <td className="px-6 py-4">
                  <div className="flex items-center space-x-4">
