                      {customer.name.charAt(0)}
                    </div>
                    <div>
                      <div className="font-bold text-gray-800">{customer.name}</div>
                      <div className="text-xs text-gray-400 font-medium">ID: {customer.id}</div>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <div className="space-y-1">
                    <div className="flex items-center text-gray-600 gap-2">
                      <Phone size={14} className="text-sky-400" /> {customer.phone}
                    </div>
                    <div className="flex items-center text-gray-400 text-xs gap-2 font-medium">
                      <Mail size={14} /> {customer.email}
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4 text-right">
                  <Button variant="secondary" onClick={() => setSelectedCustomerId(customer.id)} className="text-xs">
                    <FileText size={14} className="mr-2 inline" /> View Ledger
                  </Button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {filteredCustomers.length === 0 && (
          <div className="py-20 text-center text-gray-400 italic">No customers found. Add one to get started.</div>
        )}
      </Card>

      <Modal isOpen={isAddModalOpen} onClose={() => setIsAddModalOpen(false)} title="Add New Customer">
        <form onSubmit={handleAddCustomer} className="grid grid-cols-1 gap-4">
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Full Name</label>
            <input name="name" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="John Doe" />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-xs font-bold uppercase text-gray-400">Phone</label>
              <input name="phone" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="9876543210" />
            </div>
            <div className="space-y-1">
              <label className="text-xs font-bold uppercase text-gray-400">Email</label>
              <input name="email" type="email" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="john@example.com" />
            </div>
          </div>
