export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('inventory_pro_data');
    return saved ? JSON.parse(saved) : INITIAL_DATA;
  });

  useEffect(() => {
    localStorage.setItem('inventory_pro_data', JSON.stringify(state));
  }, [state]);

  const addProduct = (p: Omit<Product, 'id' | 'createdAt'>) => {
    const newProduct: Product = { ...p, id: generateID(), createdAt: new Date().toISOString() };
    setState(prev => ({ ...prev, products: [...prev.products, newProduct] }));
  };

  const updateProduct = (id: string, updates: Partial<Product>) => {
    setState(prev => ({
      ...prev,
      products: prev.products.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const deleteProduct = (id: string) => {
    setState(prev => ({ ...prev, products: prev.products.filter(p => p.id !== id) }));
  };

  const addCustomer = (c: Omit<Customer, 'id' | 'createdAt'>) => {
    const newCustomer: Customer = { ...c, id: generateID(), createdAt: new Date().toISOString() };
    setState(prev => ({ ...prev, customers: [...prev.customers, newCustomer] }));
  };

  const addSupplier = (s: Omit<Supplier, 'id' | 'createdAt'>) => {
    const newSupplier: Supplier = { ...s, id: generateID(), createdAt: new Date().toISOString() };
    setState(prev => ({ ...prev, suppliers: [...prev.suppliers, newSupplier] }));
  };

  const addSale = (s: Omit<Sale, 'id' | 'invoiceNumber' | 'date' | 'netPayout'>) => {
    const newSale: Sale = {
      ...s,
      id: generateID(),
      invoiceNumber: `INV-${state.sales.length + 1001}`,
      netPayout: s.totalAmount - s.marketplaceFees,
      date: new Date().toISOString()
    };

    // Update stock for all items
    s.items.forEach(item => {
      updateStock(item.productId, item.quantity, 'OUT', `Sale ${newSale.invoiceNumber} (${s.channel})`);
    });

    setState(prev => ({ ...prev, sales: [...prev.sales, newSale] }));
  };

  const updateOrderStatus = (saleId: string, status: OrderStatus) => {
     setState(prev => ({
        ...prev,
        sales: prev.sales.map(s => s.id === saleId ? { ...s, orderStatus: status } : s)
     }));
  };

  const addPaymentToSale = (saleId: string, amount: number) => {
    setState(prev => ({
      ...prev,
      sales: prev.sales.map(s => {
        if (s.id === saleId) {
          const newPaidAmount = s.paidAmount + amount;
          return {
            ...s,
            paidAmount: newPaidAmount,
            paymentStatus: newPaidAmount >= (s.channel === SalesChannel.IN_STORE ? s.totalAmount : s.netPayout) ? PaymentStatus.PAID : PaymentStatus.PARTIAL
          };
        }
        return s;
      })
    }));
  };

  const addRental = (r: Omit<Rental, 'id' | 'invoiceNumber' | 'date' | 'status' | 'lateFee' | 'actualReturnDate'>) => {
    const newRental: Rental = {
      ...r,
      id: generateID(),
      invoiceNumber: `RNT-${state.rentals.length + 1001}`,
      date: new Date().toISOString(),
      status: RentalStatus.ACTIVE,
      lateFee: 0
    };

    updateStock(r.productId, r.quantity, 'OUT', `Rental ${newRental.invoiceNumber}`);
    setState(prev => ({ ...prev, rentals: [...prev.rentals, newRental] }));
  };

  const returnRental = (id: string, lateFee: number) => {
    const rental = state.rentals.find(r => r.id === id);
    if (!rental) return;

    updateStock(rental.productId, rental.quantity, 'IN', `Return ${rental.invoiceNumber}`);

    setState(prev => ({
      ...prev,
      rentals: prev.rentals.map(r => r.id === id ? {
        ...r,
        status: RentalStatus.RETURNED,
        actualReturnDate: new Date().toISOString(),
        lateFee: lateFee,
        totalRentAmount: r.totalRentAmount + lateFee
      } : r)
    }));
  };

  const updateStock = (productId: string, quantity: number, type: 'IN' | 'OUT', reason: string) => {
    const log: StockLog = {
      id: generateID(),
      productId,
      type,
      quantity,
      reason,
      date: new Date().toISOString()
    };

    setState(prev => ({
      ...prev,
      products: prev.products.map(p => 
        p.id === productId 
          ? { ...p, stockQuantity: type === 'IN' ? p.stockQuantity + quantity : p.stockQuantity - quantity }
          : p
      ),
      stockLogs: [...prev.stockLogs, log]
    }));
  };

  return (
    <AppContext.Provider value={{ 
      ...state, 
      addProduct, 
      updateProduct, 
      deleteProduct, 
      addCustomer, 
      addSupplier, 
      addSale, 
      updateOrderStatus,
      addPaymentToSale,
      addRental, 
      returnRental,
      updateStock 
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useApp must be used within AppProvider');
  return context;
};

