const Sales: React.FC = () => {
  const { sales, products, customers, addSale, updateOrderStatus } = useApp();
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [channelFilter, setChannelFilter] = useState<'ALL' | SalesChannel>('ALL');

  const filteredSales = sales.filter(s => {
    const matchesSearch = s.invoiceNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          s.externalOrderId?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesChannel = channelFilter === 'ALL' || s.channel === channelFilter;
    return matchesSearch && matchesChannel;
  });

  // Calculate Metrics
  const totalRevenue = filteredSales.reduce((acc, s) => acc + s.totalAmount, 0);
  const totalFees = filteredSales.reduce((acc, s) => acc + s.marketplaceFees, 0);
  const netPayout = filteredSales.reduce((acc, s) => acc + s.netPayout, 0);
  const pendingOrders = filteredSales.filter(s => s.orderStatus === OrderStatus.PENDING || s.orderStatus === OrderStatus.READY_TO_SHIP).length;

  const handleCreateSale = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const productId = formData.get('productId') as string;
    const qty = Number(formData.get('quantity'));
    const product = products.find(p => p.id === productId);
    const channel = formData.get('channel') as SalesChannel;

    // Auto-select dummy customers for marketplaces if not in store
    let customerId = formData.get('customerId') as string;
    if (channel === SalesChannel.AMAZON) customerId = 'C_AMZ';
    if (channel === SalesChannel.FLIPKART) customerId = 'C_FK';
    if (channel === SalesChannel.MEESHO) customerId = 'C_MEE';

    if (product) {
      const unitPrice = Number(formData.get('unitPrice')) || product.sellingPrice;
      const total = unitPrice * qty;
      const fees = Number(formData.get('marketplaceFees')) || 0;

      addSale({
        channel: channel,
        externalOrderId: formData.get('externalOrderId') as string,
        customerId: customerId,
        items: [{
          productId: product.id,
          name: product.name,
          quantity: qty,
          unitPrice: unitPrice,
          taxAmount: 0,
          total: total
        }],
        totalAmount: total,
        marketplaceFees: fees,
        taxTotal: 0,
        discount: 0,
        paidAmount: channel === SalesChannel.IN_STORE ? total : 0, // In store is paid immediately usually
        paymentStatus: channel === SalesChannel.IN_STORE ? PaymentStatus.PAID : PaymentStatus.UNPAID,
        paymentMethod: formData.get('paymentMethod') as PaymentMethod,
        orderStatus: channel === SalesChannel.IN_STORE ? OrderStatus.COMPLETED : OrderStatus.PENDING,
      });
      setIsAddModalOpen(false);
    }
  };

  const getChannelIcon = (channel: SalesChannel) => {
    switch (channel) {
      case SalesChannel.AMAZON: return <ShoppingBag className="text-orange-500" size={16} />;
      case SalesChannel.FLIPKART: return <ShoppingBag className="text-blue-500" size={16} />;
      case SalesChannel.MEESHO: return <Smartphone className="text-pink-600" size={16} />;
      case SalesChannel.WEBSITE: return <Globe className="text-purple-500" size={16} />;
      default: return <Store className="text-sky-500" size={16} />;
    }
  };

  const getChannelStyle = (channel: SalesChannel) => {
    switch (channel) {
      case SalesChannel.AMAZON: return 'bg-orange-50 text-orange-700 border-orange-100';
      case SalesChannel.FLIPKART: return 'bg-blue-50 text-blue-700 border-blue-100';
      case SalesChannel.MEESHO: return 'bg-pink-50 text-pink-700 border-pink-100';
      default: return 'bg-gray-50 text-gray-700 border-gray-100';
    }
  };

  const getStatusBadge = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.COMPLETED: 
      case OrderStatus.DELIVERED:
        return <span className="inline-flex items-center gap-1 px-2 py-1 rounded-lg bg-green-50 text-green-700 text-[10px] font-bold uppercase"><CheckCircle size={10} /> {status}</span>;
      case OrderStatus.PENDING: 
      case OrderStatus.READY_TO_SHIP:
        return <span className="inline-flex items-center gap-1 px-2 py-1 rounded-lg bg-yellow-50 text-yellow-700 text-[10px] font-bold uppercase"><Clock size={10} /> {status.replace(/_/g, ' ')}</span>;
      case OrderStatus.SHIPPED:
        return <span className="inline-flex items-center gap-1 px-2 py-1 rounded-lg bg-blue-50 text-blue-700 text-[10px] font-bold uppercase"><Truck size={10} /> {status}</span>;
      case OrderStatus.RETURNED:
        return <span className="inline-flex items-center gap-1 px-2 py-1 rounded-lg bg-red-50 text-red-700 text-[10px] font-bold uppercase"><XCircle size={10} /> {status}</span>;
      default: return null;
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-800 tracking-tight">Sales & Orders</h1>
          <p className="text-sm font-medium text-gray-400">Track omnichannel orders and payouts</p>
        </div>
        <Button onClick={() => setIsAddModalOpen(true)} className="flex items-center gap-2">
          <Plus size={20} /> Record Sale
        </Button>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
         <Card className="p-5 border-0 shadow-sm flex flex-col justify-between">
            <p className="text-xs font-bold uppercase text-gray-400 tracking-wider">Gross Revenue</p>
            <div className="flex items-end justify-between mt-2">
               <h3 className="text-2xl font-black text-gray-800">{formatCurrency(totalRevenue)}</h3>
               <ArrowUpRight className="text-green-500 mb-1" size={18} />
            </div>
         </Card>
         <Card className="p-5 border-0 shadow-sm flex flex-col justify-between">
            <p className="text-xs font-bold uppercase text-pink-400 tracking-wider">Platform Fees</p>
            <div className="flex items-end justify-between mt-2">
               <h3 className="text-2xl font-black text-pink-600">{formatCurrency(totalFees)}</h3>
            </div>
            <p className="text-[10px] text-gray-400 mt-2">Commissions & Shipping</p>
         </Card>
         <Card className="p-5 border-0 shadow-sm flex flex-col justify-between bg-emerald-50 border-emerald-100">
            <p className="text-xs font-bold uppercase text-emerald-600 tracking-wider">Net Payout</p>
            <div className="flex items-end justify-between mt-2">
               <h3 className="text-2xl font-black text-emerald-800">{formatCurrency(netPayout)}</h3>
               <IndianRupee className="text-emerald-600 mb-1" size={18} />
            </div>
            <p className="text-[10px] text-emerald-600/70 mt-2">Realized Profit</p>
         </Card>
         <Card className="p-5 border-0 shadow-sm flex flex-col justify-between">
            <p className="text-xs font-bold uppercase text-orange-400 tracking-wider">Pending Orders</p>
            <div className="flex items-end justify-between mt-2">
               <h3 className="text-2xl font-black text-orange-600">{pendingOrders}</h3>
               <Package className="text-orange-400 mb-1" size={18} />
            </div>
            <p className="text-[10px] text-gray-400 mt-2">Needs Shipping</p>
         </Card>
      </div>

      <div className="flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Search invoice or order ID..." 
            className="w-full pl-11 pr-4 py-3 bg-white border border-gray-100 rounded-2xl outline-none focus:ring-2 focus:ring-sky-100 transition-all font-medium text-gray-600"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex bg-white rounded-xl border border-gray-100 p-1">
           {[
             { id: 'ALL', label: 'All', icon: null },
             { id: SalesChannel.IN_STORE, label: 'Store', icon: <Store size={14} /> },
             { id: SalesChannel.AMAZON, label: 'Amazon', icon: <ShoppingBag size={14} /> },
             { id: SalesChannel.FLIPKART, label: 'Flipkart', icon: <ShoppingBag size={14} /> },
             { id: SalesChannel.MEESHO, label: 'Meesho', icon: <Smartphone size={14} /> },
           ].map(tab => (
             <button
                key={tab.id}
                onClick={() => setChannelFilter(tab.id as any)}
                className={`px-3 py-2 rounded-lg text-xs font-bold flex items-center gap-2 transition-all ${channelFilter === tab.id ? 'bg-gray-800 text-white shadow-md' : 'text-gray-500 hover:bg-gray-50'}`}
             >
                {tab.icon} {tab.label}
             </button>
           ))}
        </div>
      </div>

      <Card className="overflow-hidden border-0 shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead>
              <tr className="bg-gray-50/50 border-b border-gray-100 text-gray-400">
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Source</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Order Details</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Amount</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Fees/Net</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Status</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filteredSales.map(sale => (
                <tr key={sale.id} className="hover:bg-gray-50 transition-colors">
                  <td className="px-6 py-4">
                    <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-xl border text-xs font-bold ${getChannelStyle(sale.channel)}`}>
                        {getChannelIcon(sale.channel)}
                        {sale.channel}
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="font-bold text-gray-800">{sale.invoiceNumber}</div>
                    {sale.externalOrderId && (
                        <div className="text-xs font-mono text-gray-400 mt-1">Ref: {sale.externalOrderId}</div>
                    )}
                    <div className="text-xs text-gray-500 mt-1">{sale.items.length} item(s) • {new Date(sale.date).toLocaleDateString()}</div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="font-bold text-gray-800">{formatCurrency(sale.totalAmount)}</div>
                    <div className="text-[10px] text-gray-400">{sale.paymentMethod}</div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="font-bold text-emerald-600">{formatCurrency(sale.netPayout)}</div>
                    {sale.marketplaceFees > 0 && (
                        <div className="text-[10px] text-pink-500 font-medium">-{formatCurrency(sale.marketplaceFees)} Fees</div>
                    )}
                  </td>
                  <td className="px-6 py-4">
                    {getStatusBadge(sale.orderStatus)}
                  </td>
                  <td className="px-6 py-4 text-right">
                    <select 
                        className="text-xs border border-gray-200 rounded-lg p-1 bg-white outline-none focus:border-sky-300"
                        value={sale.orderStatus}
                        onChange={(e) => updateOrderStatus(sale.id, e.target.value as OrderStatus)}
                        disabled={sale.orderStatus === OrderStatus.COMPLETED || sale.orderStatus === OrderStatus.CANCELLED}
                    >
                        {Object.values(OrderStatus).map(status => (
                            <option key={status} value={status}>{status.replace(/_/g, ' ')}</option>
                        ))}
                    </select>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {filteredSales.length === 0 && (
            <div className="py-20 text-center text-gray-400 italic">No sales found.</div>
          )}
        </div>
      </Card>

      {/* Record Sale Modal */}
      <Modal isOpen={isAddModalOpen} onClose={() => setIsAddModalOpen(false)} title="Record New Sale">
        <form onSubmit={handleCreateSale} className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="col-span-2 p-3 bg-yellow-50 text-yellow-800 text-xs rounded-xl flex items-start gap-2">
             <Filter size={14} className="mt-0.5" />
             Select the Sales Channel to automatically categorize the order and adjust stock. For Marketplaces, add the Order ID and Fee amount.
          </div>

          <div className="space-y-1">
             <label className="text-xs font-bold uppercase text-gray-400">Sales Channel</label>
             <select name="channel" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium">
                {Object.values(SalesChannel).map(c => <option key={c} value={c}>{c}</option>)}
             </select>
          </div>

          <div className="space-y-1">
             <label className="text-xs font-bold uppercase text-gray-400">External Order ID</label>
             <input name="externalOrderId" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="Optional (e.g. Amazon ID)" />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Product</label>
            <select name="productId" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium">
              {products.map(p => <option key={p.id} value={p.id}>{p.name} (Stock: {p.stockQuantity})</option>)}
            </select>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Quantity</label>
            <input name="quantity" type="number" min="1" defaultValue="1" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Selling Price (Unit)</label>
            <input name="unitPrice" type="number" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="Leave empty for default" />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Marketplace/Ship Fees</label>
            <input name="marketplaceFees" type="number" defaultValue="0" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="Total deductions" />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Customer (Offline Only)</label>
            <select name="customerId" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium">
              <option value="">Select for In-Store...</option>
              {customers.filter(c => !c.id.startsWith('C_')).map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
          </div>

          <div className="space-y-1">
             <label className="text-xs font-bold uppercase text-gray-400">Payment Method</label>
             <select name="paymentMethod" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium">
                {Object.values(PaymentMethod).map(m => <option key={m} value={m}>{m}</option>)}
             </select>
          </div>

          <div className="col-span-1 md:col-span-2 flex gap-3 pt-4">
            <Button variant="ghost" onClick={() => setIsAddModalOpen(false)} className="flex-1">Cancel</Button>
            <Button type="submit" className="flex-1">Record Sale</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Sales;

