                    <div className="w-12 h-12 bg-orange-100 text-orange-600 rounded-full flex items-center justify-center mb-4">
                      <Upload size={24} />
                    </div>
                    <h4 className="font-bold text-gray-800">Restore Data</h4>
                    <p className="text-sm text-gray-500 mt-2 mb-4">Upload a previously exported backup file to restore your data.</p>
                    <input 
                      type="file" 
                      ref={fileInputRef} 
                      className="hidden" 
                      accept=".json" 
                      onChange={handleFileChange}
                    />
                    <Button variant="secondary" onClick={handleImportClick} className="w-full">Upload Backup File</Button>
                  </div>
                </div>
               </Card>

               <Card className="p-8 border-0 shadow-sm border-l-4 border-l-red-500">
                 <div className="flex items-start justify-between">
                    <div>
                      <h3 className="text-lg font-bold text-red-600">Danger Zone</h3>
                      <p className="text-sm text-gray-500 mt-1">This action cannot be undone. This will verify that you want to delete all local data.</p>
                    </div>
                    <Button variant="danger" onClick={handleReset} className="flex items-center gap-2">
                       <Trash2 size={18} /> Factory Reset
                    </Button>
                 </div>
               </Card>
            </div>
          )}

        </div>
      </div>
    </div>
  );
};

