import React, { useState, useMemo } from 'react';
import { useApp } from '../store/AppContext';
import { Card, Button } from '../components/Shared';
import { formatCurrency } from '../utils/helpers';
import { 
  BarChart3, 
  TrendingUp, 
  CreditCard, 
  Calendar,
  Download
} from 'lucide-react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  Cell, PieChart, Pie, Legend
} from 'recharts';
import { subDays, isAfter, format, parseISO } from 'date-fns';

const Reports: React.FC = () => {
  const { sales, rentals, products } = useApp();
  const [timeRange, setTimeRange] = useState<'7D' | '30D' | 'ALL'>('30D');

  // Filter Data based on Time Range
  const filteredData = useMemo(() => {
    const now = new Date();
    let startDate = new Date(0); // Beginning of time

    if (timeRange === '7D') startDate = subDays(now, 7);
    if (timeRange === '30D') startDate = subDays(now, 30);

    const filteredSales = sales.filter(s => isAfter(parseISO(s.date), startDate));
    const filteredRentals = rentals.filter(r => isAfter(parseISO(r.date), startDate));

    return { sales: filteredSales, rentals: filteredRentals };
  }, [sales, rentals, timeRange]);

  // Calculations for Summary Cards
  const summary = useMemo(() => {
    const salesRevenue = filteredData.sales.reduce((acc, s) => acc + s.totalAmount, 0);
    const rentalRevenue = filteredData.rentals.reduce((acc, r) => acc + r.totalRentAmount, 0);
    const totalRevenue = salesRevenue + rentalRevenue;

    // Net Payout (Sales Net + Rental Revenue)
    const netPayout = filteredData.sales.reduce((acc, s) => acc + s.netPayout, 0) + rentalRevenue;

    const totalOrders = filteredData.sales.length + filteredData.rentals.length;
    const avgOrderValue = totalOrders > 0 ? totalRevenue / totalOrders : 0;

    return { totalRevenue, netPayout, totalOrders, avgOrderValue, salesRevenue, rentalRevenue };
  }, [filteredData]);

  // Chart Data: Revenue Trend (Daily)
  const trendData = useMemo(() => {
    const map = new Map<string, { date: string, sales: number, rentals: number, timestamp: number }>();

    [...filteredData.sales, ...filteredData.rentals].forEach(item => {
        const d = parseISO(item.date);
        const key = format(d, 'yyyy-MM-dd');
        const displayDate = format(d, 'MMM dd');

        if (!map.has(key)) {
            map.set(key, { date: displayDate, sales: 0, rentals: 0, timestamp: d.getTime() });
        }
        const entry = map.get(key)!;
        if ('totalAmount' in item) {
             entry.sales += (item as any).totalAmount;
        } else {
             entry.rentals += (item as any).totalRentAmount;
        }
    });

    return Array.from(map.values()).sort((a, b) => a.timestamp - b.timestamp);
  }, [filteredData]);

  // Chart Data: Sales by Channel
  const channelData = useMemo(() => {
    const counts: Record<string, number> = {};
    filteredData.sales.forEach(s => {
      counts[s.channel] = (counts[s.channel] || 0) + s.totalAmount;
    });

    return Object.entries(counts).map(([name, value]) => ({ name, value }));
  }, [filteredData]);

  // Top Products
  const topProducts = useMemo(() => {
      const productSales: Record<string, { name: string, quantity: number, revenue: number }> = {};

      filteredData.sales.forEach(s => {
          s.items.forEach(item => {
              if (!productSales[item.productId]) {
                  productSales[item.productId] = { name: item.name, quantity: 0, revenue: 0 };
              }
              productSales[item.productId].quantity += item.quantity;
              productSales[item.productId].revenue += item.total;
          });
      });

      return Object.values(productSales).sort((a, b) => b.revenue - a.revenue).slice(0, 5);
  }, [filteredData]);

  const COLORS = ['#0ea5e9', '#f43f5e', '#10b981', '#f59e0b', '#8b5cf6'];

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-800 tracking-tight">Reports & Analytics</h1>
          <p className="text-sm font-medium text-gray-400">Insights into your business performance</p>
        </div>
        <div className="flex bg-white rounded-xl border border-gray-100 p-1 shadow-sm">
           {['7D', '30D', 'ALL'].map((range) => (
             <button
                key={range}
                onClick={() => setTimeRange(range as any)}
                className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${timeRange === range ? 'bg-gray-800 text-white shadow-md' : 'text-gray-500 hover:bg-gray-50'}`}
             >
                {range === 'ALL' ? 'All Time' : `Last ${range.replace('D', ' Days')}`}
             </button>
           ))}
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="p-5 border-0 shadow-sm bg-gradient-to-br from-sky-500 to-sky-600 text-white">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-sky-100 text-xs font-bold uppercase tracking-wider">Total Revenue</p>
                    <h3 className="text-2xl font-black mt-1">{formatCurrency(summary.totalRevenue)}</h3>
                </div>
                <div className="p-2 bg-white/20 rounded-lg backdrop-blur-sm">
                    <TrendingUp size={20} className="text-white" />
                </div>
            </div>
            <div className="mt-4 pt-4 border-t border-white/20 flex gap-4 text-xs font-medium text-sky-100">
                <span>Sales: {formatCurrency(summary.salesRevenue)}</span>
                <span>Rentals: {formatCurrency(summary.rentalRevenue)}</span>
            </div>
        </Card>

        <Card className="p-5 border-0 shadow-sm">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-emerald-500 text-xs font-bold uppercase tracking-wider">Net Profit (Payout)</p>
                    <h3 className="text-2xl font-black text-gray-800 mt-1">{formatCurrency(summary.netPayout)}</h3>
                </div>
                <div className="p-2 bg-emerald-50 rounded-lg text-emerald-600">
                    <CreditCard size={20} />
                </div>
            </div>
            <p className="text-xs text-gray-400 mt-4">After marketplace fees & deductions</p>
        </Card>

        <Card className="p-5 border-0 shadow-sm">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-purple-500 text-xs font-bold uppercase tracking-wider">Total Orders</p>
                    <h3 className="text-2xl font-black text-gray-800 mt-1">{summary.totalOrders}</h3>
                </div>
                <div className="p-2 bg-purple-50 rounded-lg text-purple-600">
                    <BarChart3 size={20} />
                </div>
            </div>
             <p className="text-xs text-gray-400 mt-4">Across all channels</p>
        </Card>

        <Card className="p-5 border-0 shadow-sm">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-orange-500 text-xs font-bold uppercase tracking-wider">Avg. Order Value</p>
                    <h3 className="text-2xl font-black text-gray-800 mt-1">{formatCurrency(summary.avgOrderValue)}</h3>
                </div>
                <div className="p-2 bg-orange-50 rounded-lg text-orange-600">
                    <Calendar size={20} />
                </div>
            </div>
             <p className="text-xs text-gray-400 mt-4">Revenue per transaction</p>
        </Card>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Revenue Trend Chart */}
        <Card className="lg:col-span-2 p-6 border-0 shadow-sm">
            <h3 className="text-lg font-bold text-gray-800 mb-6">Revenue Trend</h3>
            <div className="h-[300px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={trendData}>
                        <defs>
                            <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#0ea5e9" stopOpacity={0.1}/>
                                <stop offset="95%" stopColor="#0ea5e9" stopOpacity={0}/>
                            </linearGradient>
                            <linearGradient id="colorRentals" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#facc15" stopOpacity={0.1}/>
                                <stop offset="95%" stopColor="#facc15" stopOpacity={0}/>
                            </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f3f4f6" />
                        <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fill: '#9ca3af', fontSize: 12}} />
                        <YAxis axisLine={false} tickLine={false} tick={{fill: '#9ca3af', fontSize: 12}} />
                        <Tooltip 
                            contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}
                        />
                        <Area type="monotone" dataKey="sales" name="Sales" stroke="#0ea5e9" fillOpacity={1} fill="url(#colorSales)" strokeWidth={3} />
                        <Area type="monotone" dataKey="rentals" name="Rentals" stroke="#facc15" fillOpacity={1} fill="url(#colorRentals)" strokeWidth={3} />
                        <Legend iconType="circle" />
                    </AreaChart>
                </ResponsiveContainer>
            </div>
        </Card>

        {/* Channel Distribution */}
        <Card className="p-6 border-0 shadow-sm">
            <h3 className="text-lg font-bold text-gray-800 mb-6">Sales by Channel</h3>
            <div className="h-[300px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                        <Pie
                            data={channelData}
                            cx="50%"
                            cy="50%"
                            innerRadius={60}
                            outerRadius={100}
                            fill="#8884d8"
                            paddingAngle={5}
                            dataKey="value"
                        >
                            {channelData.map((entry, index) => (
                                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                            ))}
                        </Pie>
                        <Tooltip />
                        <Legend layout="horizontal" verticalAlign="bottom" align="center" />
                    </PieChart>
                </ResponsiveContainer>
            </div>
        </Card>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Top Products */}
          <Card className="p-6 border-0 shadow-sm">
              <h3 className="text-lg font-bold text-gray-800 mb-4">Top Performing Products</h3>
              <div className="overflow-x-auto">
                  <table className="w-full text-left text-sm">
                      <thead className="text-gray-400 border-b border-gray-100">
                          <tr>
                              <th className="pb-3 font-bold uppercase text-xs">Product</th>
                              <th className="pb-3 font-bold uppercase text-xs text-right">Qty</th>
                              <th className="pb-3 font-bold uppercase text-xs text-right">Revenue</th>
                          </tr>
                      </thead>
                      <tbody className="divide-y divide-gray-50">
                          {topProducts.map((p, i) => (
                              <tr key={i} className="hover:bg-gray-50">
                                  <td className="py-3 font-medium text-gray-800 truncate max-w-[200px]">{p.name}</td>
                                  <td className="py-3 text-right text-gray-600">{p.quantity}</td>
                                  <td className="py-3 text-right font-bold text-gray-800">{formatCurrency(p.revenue)}</td>
                              </tr>
                          ))}
                          {topProducts.length === 0 && <tr><td colSpan={3} className="py-8 text-center text-gray-400">No data available</td></tr>}
                      </tbody>
                  </table>
              </div>
          </Card>

          {/* Inventory Value */}
          <Card className="p-6 border-0 shadow-sm flex flex-col justify-center">
              <div className="text-center mb-8">
                  <h3 className="text-lg font-bold text-gray-800 mb-1">Inventory Valuation</h3>
                  <p className="text-xs text-gray-400">Current stock value based on prices</p>
              </div>
              <div className="grid grid-cols-2 gap-8">
                  <div className="text-center p-6 bg-gray-50 rounded-2xl">
                      <p className="text-xs font-bold uppercase text-gray-400 mb-2">Cost Value</p>
                      <h3 className="text-2xl font-black text-gray-800">
                          {formatCurrency(products.reduce((acc, p) => acc + (p.purchasePrice * p.stockQuantity), 0))}
                      </h3>
                      <p className="text-[10px] text-gray-400 mt-1">Total Purchase Price</p>
                  </div>
                  <div className="text-center p-6 bg-sky-50 rounded-2xl">
                      <p className="text-xs font-bold uppercase text-sky-500 mb-2">Retail Value</p>
                      <h3 className="text-2xl font-black text-sky-600">
                          {formatCurrency(products.reduce((acc, p) => acc + (p.sellingPrice * p.stockQuantity), 0))}
                      </h3>
                      <p className="text-[10px] text-sky-400 mt-1">Total Selling Price</p>
                  </div>
              </div>
              <div className="mt-8">
                  <Button variant="secondary" className="w-full flex items-center justify-center gap-2" onClick={() => {}}>
                      <Download size={18} /> Download Inventory Report
                  </Button>
              </div>
          </Card>
      </div>
    </div>
  );
};

