import React, { useMemo } from 'react';
import { useApp } from '../store/AppContext';
import { Card } from '../components/Shared';
import { formatCurrency } from '../utils/helpers';
import { 
  TrendingUp, 
  Users, 
  Package, 
  AlertTriangle, 
  Clock, 
  ArrowUpRight, 
  ShoppingBag, 
  Activity,
  CreditCard,
  RefreshCcw,
  Store,
  ArrowRight
} from 'lucide-react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, Legend
} from 'recharts';
import { format, subDays, isSameDay, parseISO } from 'date-fns';

const Dashboard: React.FC = () => {
  const { sales, rentals, products, customers } = useApp();

  // 1. Key Metrics Calculation
  const totalRevenue = sales.reduce((sum, s) => sum + s.totalAmount, 0) + 
                       rentals.reduce((sum, r) => sum + r.totalRentAmount, 0);

  const netProfit = sales.reduce((sum, s) => sum + s.netPayout, 0) + 
                    rentals.reduce((sum, r) => sum + r.totalRentAmount, 0);

  const activeRentals = rentals.filter(r => r.status === 'ACTIVE').length;
  const lowStockItems = products.filter(p => p.stockQuantity <= p.minStockAlert);
  const totalCustomers = customers.length;

  // 2. Chart Data (Last 7 Days)
  const chartData = useMemo(() => {
    const data = [];
    const today = new Date();
    for (let i = 6; i >= 0; i--) {
      const date = subDays(today, i);
      // Mocking some data distribution if empty for visualization in this demo
      // In production, remove the || 0 logic if strict accuracy is needed without mock fallback
      const daySales = sales.filter(s => isSameDay(parseISO(s.date), date))
                            .reduce((sum, s) => sum + s.totalAmount, 0);
      const dayRentals = rentals.filter(r => isSameDay(parseISO(r.date), date))
                              .reduce((sum, r) => sum + r.totalRentAmount, 0);
      data.push({
        name: format(date, 'EEE'),
        fullDate: format(date, 'dd MMM'),
        sales: daySales,
        rentals: dayRentals
      });
    }
    return data;
  }, [sales, rentals]);

  // 3. Channel Distribution Data
  const channelData = useMemo(() => {
    const counts: Record<string, number> = {};
    sales.forEach(s => {
      counts[s.channel] = (counts[s.channel] || 0) + s.totalAmount;
    });
    // Ensure we have at least one entry for the chart to render something if empty
    if (Object.keys(counts).length === 0) return [{ name: 'No Sales', value: 1 }];
    return Object.keys(counts).map(key => ({ name: key, value: counts[key] }));
  }, [sales]);

  // 4. Recent Activity Feed
  const recentActivity = useMemo(() => {
     const _sales = sales.map(s => ({ 
       id: s.id, 
       type: 'SALE', 
       amount: s.totalAmount, 
       date: s.date,
       details: `${s.items.length} items`,
       status: s.orderStatus,
       ref: s.invoiceNumber
     }));
     const _rentals = rentals.map(r => ({ 
       id: r.id, 
       type: 'RENTAL', 
       amount: r.totalRentAmount, 
       date: r.date,
       details: 'Rental Duration',
       status: r.status,
       ref: r.invoiceNumber
     }));
     return [..._sales, ..._rentals]
        .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
        .slice(0, 5);
  }, [sales, rentals]);

  const COLORS = ['#0ea5e9', '#f43f5e', '#10b981', '#f59e0b', '#8b5cf6'];

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-800 tracking-tight">Dashboard</h1>
          <p className="text-sm font-medium text-gray-400">Welcome back, here's what's happening today.</p>
        </div>
        <div className="text-right hidden md:block">
          <p className="text-xs font-bold text-gray-400 uppercase">Today's Date</p>
          <p className="text-lg font-bold text-gray-700">{format(new Date(), 'EEEE, dd MMMM yyyy')}</p>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="p-5 border-0 shadow-sm relative overflow-hidden">
          <div className="flex justify-between items-start z-10 relative">
            <div>
              <p className="text-xs font-bold uppercase text-gray-400 tracking-wider">Total Revenue</p>
              <h3 className="text-2xl font-black text-gray-800 mt-1">{formatCurrency(totalRevenue)}</h3>
              <div className="flex items-center gap-1 mt-2 text-xs font-bold text-emerald-600 bg-emerald-50 w-fit px-2 py-1 rounded-full">
                <ArrowUpRight size={12} /> +12.5%
              </div>
            </div>
            <div className="p-3 bg-indigo-50 text-indigo-600 rounded-xl">
              <TrendingUp size={20} />
            </div>
          </div>
          {/* Decorative bg blob */}
          <div className="absolute -right-6 -bottom-6 w-24 h-24 bg-indigo-50 rounded-full opacity-50 z-0"></div>
        </Card>

        <Card className="p-5 border-0 shadow-sm relative overflow-hidden">
          <div className="flex justify-between items-start z-10 relative">
            <div>
              <p className="text-xs font-bold uppercase text-gray-400 tracking-wider">Net Profit</p>
              <h3 className="text-2xl font-black text-gray-800 mt-1">{formatCurrency(netProfit)}</h3>
              <p className="text-[10px] text-gray-400 mt-2">After marketplace fees</p>
            </div>
            <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl">
              <CreditCard size={20} />
            </div>
          </div>
        </Card>

        <Card className="p-5 border-0 shadow-sm relative overflow-hidden">
           <div className="flex justify-between items-start z-10 relative">
            <div>
              <p className="text-xs font-bold uppercase text-gray-400 tracking-wider">Active Rentals</p>
              <h3 className="text-2xl font-black text-gray-800 mt-1">{activeRentals}</h3>
              <div className="flex items-center gap-1 mt-2 text-xs font-bold text-sky-600 bg-sky-50 w-fit px-2 py-1 rounded-full">
                <Clock size={12} /> Ongoing
              </div>
            </div>
            <div className="p-3 bg-sky-50 text-sky-600 rounded-xl">
              <RefreshCcw size={20} />
            </div>
          </div>
        </Card>

        <Card className="p-5 border-0 shadow-sm relative overflow-hidden">
           <div className="flex justify-between items-start z-10 relative">
            <div>
              <p className="text-xs font-bold uppercase text-gray-400 tracking-wider">Customers</p>
              <h3 className="text-2xl font-black text-gray-800 mt-1">{totalCustomers}</h3>
              <p className="text-[10px] text-gray-400 mt-2">Total registered</p>
            </div>
            <div className="p-3 bg-pink-50 text-pink-500 rounded-xl">
              <Users size={20} />
            </div>
          </div>
        </Card>
      </div>

      {/* Main Content Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Left Column: Charts */}
        <div className="lg:col-span-2 space-y-6">
          {/* Revenue Chart */}
          <Card className="p-6 border-0 shadow-sm">
            <div className="flex items-center justify-between mb-6">
              <h3 className="font-bold text-gray-800 flex items-center gap-2">
                <Activity size={18} className="text-sky-500" /> Revenue Analytics
              </h3>
              <div className="flex gap-4">
                 <div className="flex items-center gap-1 text-xs font-bold text-gray-500">
                    <span className="w-2 h-2 rounded-full bg-sky-500"></span> Sales
                 </div>
                 <div className="flex items-center gap-1 text-xs font-bold text-gray-500">
                    <span className="w-2 h-2 rounded-full bg-yellow-400"></span> Rentals
                 </div>
              </div>
            </div>
            <div className="h-[280px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={chartData}>
                  <defs>
                    <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#0ea5e9" stopOpacity={0.1}/>
                      <stop offset="95%" stopColor="#0ea5e9" stopOpacity={0}/>
                    </linearGradient>
                    <linearGradient id="colorRentals" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#facc15" stopOpacity={0.1}/>
                      <stop offset="95%" stopColor="#facc15" stopOpacity={0}/>
