import React, { useState } from 'react';
import { useApp } from '../store/AppContext';
import { Card, Button, Modal } from '../components/Shared';
import { 
  Plus, 
  Search, 
  Calendar, 
  AlertCircle, 
  CheckCircle, 
  Clock, 
  User,
  Box,
  ArrowRight
} from 'lucide-react';
import { formatCurrency, getStatusColor, calculateRentalTotal, calculateLateFee } from '../utils/helpers';
import { PaymentStatus, RentalStatus } from '../types';
import { differenceInDays, parseISO } from 'date-fns';

const Rentals: React.FC = () => {
  const { rentals, products, customers, addRental, returnRental } = useApp();
  const [isNewRentalModalOpen, setIsNewRentalModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeTab, setActiveTab] = useState<'ACTIVE' | 'OVERDUE' | 'RETURNED'>('ACTIVE');

  const handleCreateRental = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const productId = formData.get('productId') as string;
    const qty = Number(formData.get('quantity'));
    const start = formData.get('startDate') as string;
    const end = formData.get('expectedReturnDate') as string;
    const product = products.find(p => p.id === productId);

    if (product) {
      const total = calculateRentalTotal(start, end, product.rentalPrice, qty);
      addRental({
        customerId: formData.get('customerId') as string,
        productId,
        quantity: qty,
        startDate: start,
        expectedReturnDate: end,
        dailyRate: product.rentalPrice,
        securityDeposit: Number(formData.get('securityDeposit')),
        totalRentAmount: total,
        paidAmount: Number(formData.get('paidAmount')),
        paymentStatus: Number(formData.get('paidAmount')) >= total ? PaymentStatus.PAID : PaymentStatus.PARTIAL,
      });
      setIsNewRentalModalOpen(false);
    }
  };

  const handleReturn = (id: string) => {
    const rental = rentals.find(r => r.id === id);
    if (rental) {
      const lateFee = calculateLateFee(rental.expectedReturnDate, undefined, rental.dailyRate, rental.quantity);
      if (confirm(`Process return for this rental? Late fees calculated: ${formatCurrency(lateFee)}`)) {
        returnRental(id, lateFee);
      }
    }
  };

  const filteredRentals = rentals.filter(r => {
    const cust = customers.find(c => c.id === r.customerId);
    const prod = products.find(p => p.id === r.productId);
    const matchesSearch = (
      cust?.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      prod?.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      r.invoiceNumber.toLowerCase().includes(searchTerm.toLowerCase())
    );

    if (activeTab === 'ACTIVE') return matchesSearch && r.status === 'ACTIVE' && new Date(r.expectedReturnDate) >= new Date();
    if (activeTab === 'OVERDUE') return matchesSearch && r.status === 'ACTIVE' && new Date(r.expectedReturnDate) < new Date();
    if (activeTab === 'RETURNED') return matchesSearch && r.status === 'RETURNED';
    return matchesSearch;
  });

  const getProgress = (start: string, end: string) => {
    const startDate = parseISO(start).getTime();
    const endDate = parseISO(end).getTime();
    const now = new Date().getTime();
    const totalDuration = endDate - startDate;
    const elapsed = now - startDate;
    const percentage = Math.max(0, Math.min(100, (elapsed / totalDuration) * 100));
    return percentage;
  };

  const activeCount = rentals.filter(r => r.status === 'ACTIVE').length;
  const overdueCount = rentals.filter(r => r.status === 'ACTIVE' && new Date(r.expectedReturnDate) < new Date()).length;
  const totalRevenue = rentals.reduce((acc, r) => acc + r.totalRentAmount, 0);

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-800 tracking-tight">Rentals</h1>
          <p className="text-sm font-medium text-gray-400">Track bookings, returns & deposits</p>
        </div>
        <Button onClick={() => setIsNewRentalModalOpen(true)} className="flex items-center gap-2 shadow-sky-200">
          <Plus size={20} /> Create Rental
        </Button>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <Card className="p-5 border-0 shadow-sm bg-white flex items-center justify-between">
          <div>
            <p className="text-xs font-bold uppercase text-gray-400 tracking-wider">Active Rentals</p>
            <h3 className="text-3xl font-black text-sky-600 mt-1">{activeCount}</h3>
          </div>
          <div className="p-4 bg-sky-50 text-sky-500 rounded-2xl">
              <Calendar size={24} />
          </div>
        </Card>

        <Card className={`p-5 border-0 shadow-sm flex items-center justify-between ${overdueCount > 0 ? 'bg-pink-50 border-pink-100' : 'bg-white'}`}>
          <div>
            <p className={`text-xs font-bold uppercase tracking-wider ${overdueCount > 0 ? 'text-pink-600' : 'text-gray-400'}`}>Overdue</p>
            <h3 className={`text-3xl font-black mt-1 ${overdueCount > 0 ? 'text-pink-600' : 'text-gray-800'}`}>{overdueCount}</h3>
          </div>
          <div className={`p-4 rounded-2xl ${overdueCount > 0 ? 'bg-white text-pink-500' : 'bg-gray-50 text-gray-400'}`}>
              <AlertCircle size={24} />
          </div>
        </Card>

        <Card className="p-5 border-0 shadow-sm bg-white flex items-center justify-between">
          <div>
            <p className="text-xs font-bold uppercase text-gray-400 tracking-wider">Total Revenue</p>
            <h3 className="text-3xl font-black text-emerald-600 mt-1">{formatCurrency(totalRevenue)}</h3>
          </div>
          <div className="p-4 bg-emerald-50 text-emerald-500 rounded-2xl">
              <CheckCircle size={24} />
          </div>
        </Card>
      </div>

      <div className="flex flex-col gap-4">
        {/* Navigation Tabs */}
        <div className="flex items-center justify-between">
             <div className="flex bg-gray-100/50 p-1 rounded-xl">
               {(['ACTIVE', 'OVERDUE', 'RETURNED'] as const).map(tab => (
                 <button
                    key={tab}
                    onClick={() => setActiveTab(tab)}
                    className={`px-5 py-2.5 rounded-lg text-xs font-bold transition-all ${activeTab === tab ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                 >
                    {tab.charAt(0) + tab.slice(1).toLowerCase()}
                 </button>
               ))}
            </div>
             <div className="relative hidden md:block w-72">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
