                {filteredRentals.map(rental => {
                    const customer = customers.find(c => c.id === rental.customerId);
                    const product = products.find(p => p.id === rental.productId);
                    const progress = getProgress(rental.startDate, rental.expectedReturnDate);

                    return (
                    <tr key={rental.id} className="hover:bg-gray-50 transition-colors">
                        <td className="px-6 py-4">
                            <div className="font-bold text-gray-800">{rental.invoiceNumber}</div>
                            <div className="flex items-center gap-1.5 mt-1">
                                <User size={12} className="text-gray-400" />
                                <span className="text-xs text-gray-500 font-medium">{customer?.name}</span>
                            </div>
                        </td>
                        <td className="px-6 py-4">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-indigo-50 text-indigo-500 rounded-lg flex items-center justify-center">
                                    <Box size={18} />
                                </div>
                                <div>
                                    <div className="font-bold text-gray-800">{product?.name}</div>
                                    <div className="text-xs text-gray-400">Qty: {rental.quantity}</div>
                                </div>
                            </div>
                        </td>
                        <td className="px-6 py-4 min-w-[200px]">
                            <div className="flex justify-between text-xs text-gray-500 mb-1.5 font-medium">
                                <span>{new Date(rental.startDate).toLocaleDateString(undefined, {month:'short', day:'numeric'})}</span>
                                <span className={activeTab === 'OVERDUE' ? 'text-pink-600 font-bold' : ''}>
                                    {new Date(rental.expectedReturnDate).toLocaleDateString(undefined, {month:'short', day:'numeric'})}
                                </span>
                            </div>
                            <div className="w-full h-1.5 bg-gray-100 rounded-full overflow-hidden">
                                <div 
                                    className={`h-full rounded-full ${
                                        rental.status === 'RETURNED' ? 'bg-green-400' :
                                        activeTab === 'OVERDUE' ? 'bg-pink-500' : 'bg-sky-400'
                                    }`} 
                                    style={{ width: rental.status === 'RETURNED' ? '100%' : `${progress}%` }}
                                ></div>
                            </div>
                            {rental.status === 'ACTIVE' && (
                                <p className="text-[10px] text-gray-400 mt-1 text-center">
                                    {activeTab === 'OVERDUE' ? 'Late Return' : 'In Progress'}
                                </p>
                            )}
                        </td>
                        <td className="px-6 py-4">
                            <div className="font-bold text-gray-800">{formatCurrency(rental.totalRentAmount)}</div>
                            <div className={`text-[10px] font-bold uppercase mt-1 ${rental.paymentStatus === 'PAID' ? 'text-green-600' : 'text-orange-500'}`}>
                                {rental.paymentStatus}
                            </div>
                        </td>
                        <td className="px-6 py-4 text-right">
                        {rental.status === 'ACTIVE' && (
                            <Button variant="secondary" onClick={() => handleReturn(rental.id)} className="text-xs h-8 px-3">
                                Check In
                            </Button>
                        )}
                        {rental.status === 'RETURNED' && (
                            <span className="text-xs font-bold text-gray-300">Closed</span>
                        )}
                        </td>
                    </tr>
                    );
                })}
                </tbody>
            </table>
            {filteredRentals.length === 0 && (
                <div className="py-20 text-center text-gray-400 italic">No {activeTab.toLowerCase()} rentals found.</div>
            )}
            </div>
        </Card>
      </div>

      <Modal isOpen={isNewRentalModalOpen} onClose={() => setIsNewRentalModalOpen(false)} title="Create New Rental">
        <form onSubmit={handleCreateRental} className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Customer</label>
            <select name="customerId" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium">
              {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Product</label>
            <select name="productId" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium">
              {products.map(p => <option key={p.id} value={p.id}>{p.name} ({formatCurrency(p.rentalPrice)}/day)</option>)}
            </select>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Quantity</label>
            <input name="quantity" type="number" defaultValue="1" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Security Deposit</label>
            <input name="securityDeposit" type="number" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="Refundable amount" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Start Date</label>
            <input name="startDate" type="date" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" defaultValue={new Date().toISOString().split('T')[0]} />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Expected Return</label>
            <input name="expectedReturnDate" type="date" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" />
          </div>
          <div className="col-span-2 space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Payment Received</label>
            <input name="paidAmount" type="number" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="Total payment received" />
          </div>
          <div className="col-span-2 flex gap-3 pt-4">
            <Button variant="ghost" onClick={() => setIsNewRentalModalOpen(false)} className="flex-1">Cancel</Button>
            <Button type="submit" className="flex-1">Issue Invoice</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Rentals;

import React, { useState, useMemo } from 'react';
import { useApp } from '../store/AppContext';
import { Card, Button, Modal } from '../components/Shared';
import { 
  Search, 
  Plus, 
  Phone, 
  Mail, 
  MapPin, 
  ArrowLeft, 
  FileText, 
  RefreshCcw, 
  ShoppingBag,
  TrendingUp,
  Calendar,
  Banknote,
  IndianRupee,
  User,
  Star
} from 'lucide-react';
import { formatCurrency, getStatusColor } from '../utils/helpers';
import { Sale, Rental, Customer, PaymentStatus } from '../types';

const Customers: React.FC = () => {
  const { customers, addCustomer, sales, rentals, products, addPaymentToSale } = useApp();
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);
  const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null);
  const [selectedSaleForPayment, setSelectedSaleForPayment] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [transactionFilter, setTransactionFilter] = useState<'ALL' | 'SALE' | 'RENTAL'>('ALL');

  // Derived state for the selected customer's ledger
  const selectedCustomer = useMemo(() => 
    customers.find(c => c.id === selectedCustomerId), 
  [customers, selectedCustomerId]);

  const customerHistory = useMemo(() => {
    if (!selectedCustomerId) return { transactions: [], stats: { totalSpent: 0, activeRentals: 0, totalOrders: 0 } };

    const customerSales = sales.filter(s => s.customerId === selectedCustomerId).map(s => ({
      ...s,
      type: 'SALE' as const,
      sortDate: new Date(s.date)
    }));

    const customerRentals = rentals.filter(r => r.customerId === selectedCustomerId).map(r => ({
      ...r,
      type: 'RENTAL' as const,
      sortDate: new Date(r.date)
    }));

    // Merge and sort by date descending
    const allTransactions = [...customerSales, ...customerRentals].sort((a, b) => 
      b.sortDate.getTime() - a.sortDate.getTime()
    );

    const totalSpent = allTransactions.reduce((acc, t) => {
      if (t.type === 'SALE') return acc + (t as Sale).totalAmount;
      if (t.type === 'RENTAL') return acc + (t as Rental).totalRentAmount;
      return acc;
    }, 0);

    const activeRentals = customerRentals.filter(r => r.status === 'ACTIVE').length;

    // Apply Filter
    const visibleTransactions = allTransactions.filter(t => {
      if (transactionFilter === 'ALL') return true;
      return t.type === transactionFilter;
    });

    return {
      transactions: visibleTransactions,
      stats: {
        totalSpent,
        activeRentals,
        totalOrders: allTransactions.length // Lifetime total orders
      }
    };
  }, [sales, rentals, selectedCustomerId, transactionFilter]);

  const handleAddCustomer = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    addCustomer({
      name: formData.get('name') as string,
      phone: formData.get('phone') as string,
      email: formData.get('email') as string,
      address: formData.get('address') as string,
      gstin: formData.get('gstin') as string,
    });
    setIsAddModalOpen(false);
  };

  const handleRecordPayment = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const amount = Number(formData.get('amount'));
    if (selectedSaleForPayment && amount > 0) {
      addPaymentToSale(selectedSaleForPayment, amount);
      setIsPaymentModalOpen(false);
      setSelectedSaleForPayment(null);
    }
  };

  const openPaymentModal = (saleId: string) => {
    setSelectedSaleForPayment(saleId);
    setIsPaymentModalOpen(true);
  };

  // Helper to find selected sale for the modal
  const activePaymentSale = sales.find(s => s.id === selectedSaleForPayment);
  const activePaymentBalance = activePaymentSale ? activePaymentSale.totalAmount - activePaymentSale.paidAmount : 0;

  // Filtered customers with computed stats for the list view
  const filteredCustomers = useMemo(() => {
     return customers.filter(c => 
        c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        c.phone.includes(searchTerm)
      ).map(c => {
        // Compute stats on the fly for the list
        const cSales = sales.filter(s => s.customerId === c.id);
        const cRentals = rentals.filter(r => r.customerId === c.id);

        const totalSpent = cSales.reduce((acc, s) => acc + s.totalAmount, 0) + 
                           cRentals.reduce((acc, r) => acc + r.totalRentAmount, 0);

        const balance = cSales.reduce((acc, s) => acc + (s.totalAmount - s.paidAmount), 0) +
                        cRentals.reduce((acc, r) => acc + (r.totalRentAmount - r.paidAmount), 0);

        // Find last activity
        const lastSale = cSales[cSales.length - 1]?.date;
        const lastRental = cRentals[cRentals.length - 1]?.date;
        const lastActive = [lastSale, lastRental].filter(Boolean).sort().pop();

        return { ...c, totalSpent, balance, lastActive };
      }).sort((a, b) => b.totalSpent - a.totalSpent); // Sort by highest spender
  }, [customers, sales, rentals, searchTerm]);

  // -- RENDER: Customer Ledger (Detail View) --
  if (selectedCustomer) {
    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
