        <div>
          <h1 className="text-3xl font-bold text-gray-800 tracking-tight">Customers</h1>
          <p className="text-sm font-medium text-gray-400">Manage client relationships</p>
        </div>
        <Button onClick={() => setIsAddModalOpen(true)} className="flex items-center gap-2 shadow-sky-200">
          <Plus size={20} /> Add Customer
        </Button>
      </div>

