          className="w-full pl-11 pr-4 py-3 bg-white border border-gray-100 rounded-2xl outline-none focus:ring-2 focus:ring-sky-100 transition-all font-medium text-gray-600"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <Card className="overflow-hidden border-0 shadow-sm">
        <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
            <thead>
                <tr className="bg-gray-50/50 border-b border-gray-100 text-gray-400">
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Customer Name</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Contact Info</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Last Order</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Total Spent</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Outstanding</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Actions</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
                {filteredCustomers.map(customer => (
                    <tr key={customer.id} className="hover:bg-gray-50 group transition-colors">
                    <td className="px-6 py-4">
                        <div className="flex items-center space-x-4">
                        <div className="w-12 h-12 bg-gradient-to-br from-gray-100 to-gray-200 text-gray-600 rounded-full flex items-center justify-center font-black text-lg shadow-inner">
                            {customer.name.charAt(0)}
                        </div>
                        <div>
                            <div className="font-bold text-gray-800">{customer.name}</div>
                            <div className="text-xs text-gray-400 font-medium">ID: {customer.id}</div>
                        </div>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                        <div className="space-y-1">
                        <div className="flex items-center text-gray-600 gap-2 font-medium">
                            <Phone size={14} className="text-gray-400" /> {customer.phone}
                        </div>
                        <div className="flex items-center text-gray-500 text-xs gap-2">
                            <Mail size={14} className="text-gray-300" /> {customer.email}
                        </div>
                        </div>
                    </td>
                    <td className="px-6 py-4 text-right">
                        <span className="text-gray-600 font-medium">
                            {customer.lastActive ? new Date(customer.lastActive).toLocaleDateString() : '-'}
                        </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                        <div className="font-bold text-gray-800">{formatCurrency(customer.totalSpent)}</div>
                    </td>
                    <td className="px-6 py-4 text-right">
                        <div className={`font-bold ${customer.balance > 0 ? 'text-pink-500' : 'text-emerald-500'}`}>
                            {formatCurrency(customer.balance)}
                        </div>
                        {customer.balance > 0 && <div className="text-[10px] text-gray-400 font-medium">Due Amount</div>}
                    </td>
                    <td className="px-6 py-4 text-right">
                        <Button variant="secondary" onClick={() => setSelectedCustomerId(customer.id)} className="text-xs px-4">
                            View Ledger <ArrowRight size={14} className="ml-1 inline" />
                        </Button>
                    </td>
                    </tr>
                ))}
            </tbody>
            </table>
        </div>
        {filteredCustomers.length === 0 && (
          <div className="py-20 text-center text-gray-400 italic">No customers found. Add one to get started.</div>
        )}
      </Card>

      <Modal isOpen={isAddModalOpen} onClose={() => setIsAddModalOpen(false)} title="Add New Customer">
        <form onSubmit={handleAddCustomer} className="grid grid-cols-1 gap-4">
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Full Name</label>
            <input name="name" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="John Doe" />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-xs font-bold uppercase text-gray-400">Phone</label>
              <input name="phone" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="9876543210" />
            </div>
            <div className="space-y-1">
              <label className="text-xs font-bold uppercase text-gray-400">Email</label>
              <input name="email" type="email" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="john@example.com" />
            </div>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Address</label>
            <textarea name="address" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium h-24" placeholder="Full billing address"></textarea>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">GSTIN (Optional)</label>
            <input name="gstin" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="Tax Identification Number" />
          </div>
          <div className="flex gap-3 pt-4">
            <Button variant="ghost" onClick={() => setIsAddModalOpen(false)} className="flex-1">Cancel</Button>
            <Button type="submit" className="flex-1">Save Customer</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Customers;

import React, { useState, useMemo } from 'react';
import { useApp } from '../store/AppContext';
import { Card, Button, Modal } from '../components/Shared';
import { 
  Search, 
  Plus, 
  Phone, 
  Mail, 
  MapPin, 
  ArrowLeft, 
  ArrowRight,
  FileText, 
  RefreshCcw, 
  ShoppingBag,
  TrendingUp,
  Calendar,
  Banknote,
  IndianRupee,
  User,
  Star
} from 'lucide-react';
import { formatCurrency, getStatusColor } from '../utils/helpers';
import { Sale, Rental, Customer, PaymentStatus } from '../types';

const Customers: React.FC = () => {
  const { customers, addCustomer, sales, rentals, products, addPaymentToSale } = useApp();
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);
  const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null);
  const [selectedSaleForPayment, setSelectedSaleForPayment] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [transactionFilter, setTransactionFilter] = useState<'ALL' | 'SALE' | 'RENTAL'>('ALL');

  // Derived state for the selected customer's ledger
  const selectedCustomer = useMemo(() => 
    customers.find(c => c.id === selectedCustomerId), 
  [customers, selectedCustomerId]);

  const customerHistory = useMemo(() => {
    if (!selectedCustomerId) return { transactions: [], stats: { totalSpent: 0, activeRentals: 0, totalOrders: 0 } };

    const customerSales = sales.filter(s => s.customerId === selectedCustomerId).map(s => ({
      ...s,
      type: 'SALE' as const,
      sortDate: new Date(s.date)
    }));

    const customerRentals = rentals.filter(r => r.customerId === selectedCustomerId).map(r => ({
      ...r,
      type: 'RENTAL' as const,
      sortDate: new Date(r.date)
    }));

    // Merge and sort by date descending
    const allTransactions = [...customerSales, ...customerRentals].sort((a, b) => 
      b.sortDate.getTime() - a.sortDate.getTime()
    );

    const totalSpent = allTransactions.reduce((acc, t) => {
      if (t.type === 'SALE') return acc + (t as Sale).totalAmount;
      if (t.type === 'RENTAL') return acc + (t as Rental).totalRentAmount;
      return acc;
    }, 0);

    const activeRentals = customerRentals.filter(r => r.status === 'ACTIVE').length;

    // Apply Filter
    const visibleTransactions = allTransactions.filter(t => {
      if (transactionFilter === 'ALL') return true;
      return t.type === transactionFilter;
    });

    return {
      transactions: visibleTransactions,
      stats: {
        totalSpent,
        activeRentals,
        totalOrders: allTransactions.length // Lifetime total orders
      }
    };
  }, [sales, rentals, selectedCustomerId, transactionFilter]);

  const handleAddCustomer = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    addCustomer({
      name: formData.get('name') as string,
      phone: formData.get('phone') as string,
      email: formData.get('email') as string,
      address: formData.get('address') as string,
      gstin: formData.get('gstin') as string,
    });
    setIsAddModalOpen(false);
  };

  const handleRecordPayment = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const amount = Number(formData.get('amount'));
    if (selectedSaleForPayment && amount > 0) {
      addPaymentToSale(selectedSaleForPayment, amount);
      setIsPaymentModalOpen(false);
      setSelectedSaleForPayment(null);
    }
  };

  const openPaymentModal = (saleId: string) => {
    setSelectedSaleForPayment(saleId);
    setIsPaymentModalOpen(true);
  };

  // Helper to find selected sale for the modal
  const activePaymentSale = sales.find(s => s.id === selectedSaleForPayment);
  const activePaymentBalance = activePaymentSale ? activePaymentSale.totalAmount - activePaymentSale.paidAmount : 0;

  // Filtered customers with computed stats for the list view
  const filteredCustomers = useMemo(() => {
     return customers.filter(c => 
        c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        c.phone.includes(searchTerm)
      ).map(c => {
        // Compute stats on the fly for the list
        const cSales = sales.filter(s => s.customerId === c.id);
        const cRentals = rentals.filter(r => r.customerId === c.id);

        const totalSpent = cSales.reduce((acc, s) => acc + s.totalAmount, 0) + 
                           cRentals.reduce((acc, r) => acc + r.totalRentAmount, 0);

        const balance = cSales.reduce((acc, s) => acc + (s.totalAmount - s.paidAmount), 0) +
                        cRentals.reduce((acc, r) => acc + (r.totalRentAmount - r.paidAmount), 0);

        // Find last activity
        const lastSale = cSales[cSales.length - 1]?.date;
        const lastRental = cRentals[cRentals.length - 1]?.date;
        const lastActive = [lastSale, lastRental].filter(Boolean).sort().pop();

        return { ...c, totalSpent, balance, lastActive };
      }).sort((a, b) => b.totalSpent - a.totalSpent); // Sort by highest spender
  }, [customers, sales, rentals, searchTerm]);

  // -- RENDER: Customer Ledger (Detail View) --
  if (selectedCustomer) {
    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
        <div className="flex items-center gap-4">
          <button 
            onClick={() => setSelectedCustomerId(null)}
            className="p-2 hover:bg-white rounded-full transition-colors border border-transparent hover:border-gray-200 text-gray-500"
          >
            <ArrowLeft size={24} />
          </button>
          <div>
            <h1 className="text-2xl font-bold text-gray-800">{selectedCustomer.name}</h1>
            <p className="text-sm text-gray-400">Customer Ledger & History</p>
          </div>
        </div>

        {/* Customer Profile Card */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <Card className="p-6 col-span-1 border-0 shadow-sm">
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-6">Contact Details</h3>
            <div className="space-y-6">
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 rounded-xl bg-sky-50 flex items-center justify-center text-sky-500">
                  <Phone size={18} />
                </div>
                <div className="text-sm font-medium text-gray-700">{selectedCustomer.phone}</div>
              </div>
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 rounded-xl bg-sky-50 flex items-center justify-center text-sky-500">
                  <Mail size={18} />
                </div>
                <div className="text-sm font-medium text-gray-700">{selectedCustomer.email}</div>
              </div>
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 rounded-xl bg-sky-50 flex items-center justify-center text-sky-500">
                  <MapPin size={18} />
                </div>
                <div className="text-sm font-medium text-gray-700">{selectedCustomer.address}</div>
              </div>
              {selectedCustomer.gstin && (
                <div className="pt-4 border-t border-gray-100">
                   <p className="text-[10px] text-gray-400 uppercase font-bold tracking-wider">GSTIN / Tax ID</p>
                   <p className="font-mono text-sm text-gray-700 mt-1">{selectedCustomer.gstin}</p>
                </div>
              )}
            </div>
          </Card>

          <Card className="p-6 col-span-1 lg:col-span-2 border-0 shadow-sm">
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-6">Overview</h3>
            <div className="grid grid-cols-3 gap-6">
              <div className="p-5 bg-yellow-50 rounded-2xl border border-yellow-100">
                <div className="flex items-center gap-2 mb-2 text-yellow-600">
                  <TrendingUp size={18} />
                  <span className="text-[10px] font-black uppercase tracking-wider">LTV</span>
                </div>
                <p className="text-2xl font-black text-gray-800">{formatCurrency(customerHistory.stats.totalSpent)}</p>
              </div>
              <div className="p-5 bg-sky-50 rounded-2xl border border-sky-100">
                <div className="flex items-center gap-2 mb-2 text-sky-600">
                  <RefreshCcw size={18} />
                  <span className="text-[10px] font-black uppercase tracking-wider">Active Rentals</span>
                </div>
                <p className="text-2xl font-black text-gray-800">{customerHistory.stats.activeRentals}</p>
              </div>
              <div className="p-5 bg-pink-50 rounded-2xl border border-pink-100">
                <div className="flex items-center gap-2 mb-2 text-pink-600">
                  <ShoppingBag size={18} />
                  <span className="text-[10px] font-black uppercase tracking-wider">Transactions</span>
                </div>
                <p className="text-2xl font-black text-gray-800">{customerHistory.stats.totalOrders}</p>
              </div>
            </div>
          </Card>
        </div>

        {/* Transaction History Table */}
        <Card className="overflow-hidden border-0 shadow-sm">
          <div className="p-6 border-b border-gray-50 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
             <div className="flex items-center gap-4">
               <h3 className="font-bold text-gray-800">History</h3>
               <div className="flex bg-gray-50 p-1 rounded-xl">
                  <button 
                    onClick={() => setTransactionFilter('ALL')} 
                    className={`px-4 py-1.5 text-xs font-bold rounded-lg transition-all ${transactionFilter === 'ALL' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                  >
                    All
                  </button>
                  <button 
                    onClick={() => setTransactionFilter('SALE')} 
                    className={`px-4 py-1.5 text-xs font-bold rounded-lg transition-all ${transactionFilter === 'SALE' ? 'bg-white text-emerald-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                  >
                    Sales
                  </button>
                  <button 
                    onClick={() => setTransactionFilter('RENTAL')} 
                    className={`px-4 py-1.5 text-xs font-bold rounded-lg transition-all ${transactionFilter === 'RENTAL' ? 'bg-white text-sky-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                  >
                    Rentals
                  </button>
               </div>
             </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead className="bg-gray-50/50 text-gray-400">
                <tr>
                  <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Date</th>
                  <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Type</th>
                  <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Details</th>
                  <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Payment</th>
                  <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-center">Status</th>
                  <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {customerHistory.transactions.map((t: any) => {
                  const isSale = t.type === 'SALE';
                  const productName = isSale 
                    ? `${t.items.length} Items` 
                    : products.find(p => p.id === t.productId)?.name || 'Unknown Product';

                  // Calculate balances
                  const total = isSale ? t.totalAmount : t.totalRentAmount;
                  const paid = t.paidAmount || 0;
                  const balance = total - paid;

                  return (
                    <tr key={t.id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-6 py-4">
                        <div className="font-bold text-gray-800">{new Date(t.date).toLocaleDateString()}</div>
                        <div className="text-xs text-gray-400 font-mono">{t.invoiceNumber}</div>
                      </td>
                      <td className="px-6 py-4">
                         {isSale ? (
                           <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold bg-emerald-50 text-emerald-600">
                             <ShoppingBag size={12} /> SALE
                           </span>
                         ) : (
                           <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold bg-sky-50 text-sky-600">
                             <RefreshCcw size={12} /> RENTAL
                           </span>
                         )}
                      </td>
                      <td className="px-6 py-4">
                        <div className="text-gray-800 font-medium">{productName}</div>
                        {!isSale && (
                          <div className="text-xs text-pink-500 mt-1 flex items-center gap-1 font-medium">
                             <Calendar size={10} />
                             Due: {new Date(t.expectedReturnDate).toLocaleDateString()}
                          </div>
                        )}
                      </td>
                      <td className="px-6 py-4 text-right">
                         <div className="font-bold text-gray-700">{formatCurrency(total)}</div>
                         {isSale && balance > 0 && (
                            <div className="text-[10px] font-bold text-pink-500 mt-0.5">
                               Bal: {formatCurrency(balance)}
                            </div>
                         )}
                         {isSale && balance <= 0 && (
                            <div className="text-[10px] font-bold text-emerald-500 mt-0.5">
                               Fully Paid
                            </div>
                         )}
                      </td>
                      <td className="px-6 py-4 text-center">
                         <span className={`px-2 py-1 rounded-full text-[10px] font-bold uppercase tracking-wide ${isSale ? 'bg-gray-100 text-gray-500' : getStatusColor(t.status)}`}>
                            {isSale ? t.paymentStatus : t.status}
                         </span>
                      </td>
                      <td className="px-6 py-4 text-right">
                         {isSale && t.paymentStatus !== PaymentStatus.PAID && (
                            <button 
                              onClick={() => openPaymentModal(t.id)}
                              className="text-xs font-bold text-sky-500 hover:text-sky-600 bg-sky-50 hover:bg-sky-100 px-3 py-1.5 rounded-lg transition-colors inline-flex items-center gap-1"
                            >
                               <Banknote size={14} /> Pay
                            </button>
                         )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            {customerHistory.transactions.length === 0 && (
              <div className="py-12 text-center text-gray-400 italic">No {transactionFilter !== 'ALL' ? transactionFilter.toLowerCase() : ''} transactions found.</div>
            )}
          </div>
        </Card>

        {/* Payment Modal */}
        <Modal 
           isOpen={isPaymentModalOpen} 
           onClose={() => { setIsPaymentModalOpen(false); setSelectedSaleForPayment(null); }} 
           title={`Record Payment: ${activePaymentSale?.invoiceNumber}`}
        >
           <form onSubmit={handleRecordPayment} className="space-y-4">
              <div className="p-4 bg-gray-50 rounded-xl space-y-2 border border-gray-100">
                 <div className="flex justify-between text-sm">
                    <span className="text-gray-500">Total Invoice Amount:</span>
                    <span className="font-bold text-gray-800">{formatCurrency(activePaymentSale?.totalAmount || 0)}</span>
                 </div>
                 <div className="flex justify-between text-sm">
                    <span className="text-gray-500">Already Paid:</span>
                    <span className="font-bold text-emerald-600">{formatCurrency(activePaymentSale?.paidAmount || 0)}</span>
                 </div>
                 <div className="flex justify-between text-sm pt-2 border-t border-gray-200">
                    <span className="font-bold text-gray-700">Balance Due:</span>
                    <span className="font-bold text-pink-500">{formatCurrency(activePaymentBalance)}</span>
                 </div>
              </div>

              <div className="space-y-1">
                 <label className="text-xs font-bold uppercase text-gray-400">Payment Amount</label>
                 <div className="relative">
                    <IndianRupee className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                    <input 
                      name="amount" 
                      type="number" 
                      max={activePaymentBalance}
                      min={1}
                      required 
                      autoFocus
                      className="w-full pl-10 pr-4 py-3 bg-white border border-gray-200 focus:border-sky-200 rounded-xl outline-none transition-all font-medium" 
                      placeholder="Enter amount" 
                    />
                 </div>
                 <p className="text-[10px] text-gray-400">Enter value less than or equal to balance.</p>
              </div>

              <div className="flex gap-3 pt-4">
                 <Button variant="ghost" onClick={() => setIsPaymentModalOpen(false)} className="flex-1">Cancel</Button>
                 <Button type="submit" className="flex-1">Save Payment</Button>
              </div>
           </form>
        </Modal>
      </div>
    );
  }

  // -- RENDER: Customer Directory (List View) --
  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-800 tracking-tight">Customers</h1>
          <p className="text-sm font-medium text-gray-400">Manage client relationships</p>
        </div>
        <Button onClick={() => setIsAddModalOpen(true)} className="flex items-center gap-2 shadow-sky-200">
          <Plus size={20} /> Add Customer
        </Button>
      </div>

      <div className="relative">
        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
        <input 
          type="text" 
          placeholder="Search customers..." 
          className="w-full pl-11 pr-4 py-3 bg-white border border-gray-100 rounded-2xl outline-none focus:ring-2 focus:ring-sky-100 transition-all font-medium text-gray-600"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <Card className="overflow-hidden border-0 shadow-sm">
        <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
            <thead>
                <tr className="bg-gray-50/50 border-b border-gray-100 text-gray-400">
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Customer Name</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Contact Info</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Last Order</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Total Spent</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Outstanding</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Actions</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
                {filteredCustomers.map(customer => (
                    <tr key={customer.id} className="hover:bg-gray-50 group transition-colors">
                    <td className="px-6 py-4">
                        <div className="flex items-center space-x-4">
                        <div className="w-12 h-12 bg-gradient-to-br from-gray-100 to-gray-200 text-gray-600 rounded-full flex items-center justify-center font-black text-lg shadow-inner">
                            {customer.name.charAt(0)}
                        </div>
                        <div>
                            <div className="font-bold text-gray-800">{customer.name}</div>
                            <div className="text-xs text-gray-400 font-medium">ID: {customer.id}</div>
                        </div>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                        <div className="space-y-1">
                        <div className="flex items-center text-gray-600 gap-2 font-medium">
                            <Phone size={14} className="text-gray-400" /> {customer.phone}
                        </div>
                        <div className="flex items-center text-gray-500 text-xs gap-2">
                            <Mail size={14} className="text-gray-300" /> {customer.email}
                        </div>
                        </div>
                    </td>
                    <td className="px-6 py-4 text-right">
                        <span className="text-gray-600 font-medium">
                            {customer.lastActive ? new Date(customer.lastActive).toLocaleDateString() : '-'}
                        </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                        <div className="font-bold text-gray-800">{formatCurrency(customer.totalSpent)}</div>
                    </td>
                    <td className="px-6 py-4 text-right">
                        <div className={`font-bold ${customer.balance > 0 ? 'text-pink-500' : 'text-emerald-500'}`}>
                            {formatCurrency(customer.balance)}
                        </div>
                        {customer.balance > 0 && <div className="text-[10px] text-gray-400 font-medium">Due Amount</div>}
                    </td>
                    <td className="px-6 py-4 text-right">
                        <Button variant="secondary" onClick={() => setSelectedCustomerId(customer.id)} className="text-xs px-4">
                            View Ledger <ArrowRight size={14} className="ml-1 inline" />
                        </Button>
                    </td>
                    </tr>
                ))}
            </tbody>
            </table>
        </div>
        {filteredCustomers.length === 0 && (
          <div className="py-20 text-center text-gray-400 italic">No customers found. Add one to get started.</div>
        )}
      </Card>

      <Modal isOpen={isAddModalOpen} onClose={() => setIsAddModalOpen(false)} title="Add New Customer">
        <form onSubmit={handleAddCustomer} className="grid grid-cols-1 gap-4">
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Full Name</label>
            <input name="name" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="John Doe" />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-xs font-bold uppercase text-gray-400">Phone</label>
              <input name="phone" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="9876543210" />
            </div>
            <div className="space-y-1">
              <label className="text-xs font-bold uppercase text-gray-400">Email</label>
              <input name="email" type="email" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="john@example.com" />
            </div>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Address</label>
            <textarea name="address" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium h-24" placeholder="Full billing address"></textarea>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">GSTIN (Optional)</label>
            <input name="gstin" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="Tax Identification Number" />
          </div>
          <div className="flex gap-3 pt-4">
            <Button variant="ghost" onClick={() => setIsAddModalOpen(false)} className="flex-1">Cancel</Button>
            <Button type="submit" className="flex-1">Save Customer</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Customers;

import React, { useState } from 'react';
import { useApp } from '../store/AppContext';
import { Card, Button, Modal } from '../components/Shared';
import { 
  Plus, 
  Search, 
  ShoppingBag, 
  Truck, 
  Smartphone, 
  Store, 
  Globe, 
  ArrowUpRight,
  Filter,
  IndianRupee,
  Package,
  CheckCircle,
  XCircle,
  Clock,
  User,
  Calendar,
  FileText,
  AlertCircle
} from 'lucide-react';
import { formatCurrency } from '../utils/helpers';
import { SalesChannel, PaymentMethod, PaymentStatus, OrderStatus } from '../types';

const Sales: React.FC = () => {
  const { sales, products, customers, addSale, updateOrderStatus } = useApp();
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [channelFilter, setChannelFilter] = useState<'ALL' | SalesChannel>('ALL');

  const filteredSales = sales.filter(s => {
    const matchesSearch = s.invoiceNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          s.externalOrderId?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesChannel = channelFilter === 'ALL' || s.channel === channelFilter;
    return matchesSearch && matchesChannel;
  });

  // Calculate Metrics
  const totalRevenue = filteredSales.reduce((acc, s) => acc + s.totalAmount, 0);
  const totalFees = filteredSales.reduce((acc, s) => acc + s.marketplaceFees, 0);
  const netPayout = filteredSales.reduce((acc, s) => acc + s.netPayout, 0);
  const pendingOrders = filteredSales.filter(s => s.orderStatus === OrderStatus.PENDING || s.orderStatus === OrderStatus.READY_TO_SHIP).length;

  const handleCreateSale = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const productId = formData.get('productId') as string;
    const qty = Number(formData.get('quantity'));
    const product = products.find(p => p.id === productId);
    const channel = formData.get('channel') as SalesChannel;

    // Auto-select dummy customers for marketplaces if not in store
    let customerId = formData.get('customerId') as string;
    if (channel === SalesChannel.AMAZON) customerId = 'C_AMZ';
    if (channel === SalesChannel.FLIPKART) customerId = 'C_FK';
    if (channel === SalesChannel.MEESHO) customerId = 'C_MEE';

    if (product) {
      const unitPrice = Number(formData.get('unitPrice')) || product.sellingPrice;
      const total = unitPrice * qty;
      const fees = Number(formData.get('marketplaceFees')) || 0;

      addSale({
        channel: channel,
        externalOrderId: formData.get('externalOrderId') as string,
        customerId: customerId,
        items: [{
          productId: product.id,
          name: product.name,
          quantity: qty,
          unitPrice: unitPrice,
          taxAmount: 0,
          total: total
        }],
        totalAmount: total,
        marketplaceFees: fees,
        taxTotal: 0,
        discount: 0,
        paidAmount: channel === SalesChannel.IN_STORE ? total : 0, // In store is paid immediately usually
        paymentStatus: channel === SalesChannel.IN_STORE ? PaymentStatus.PAID : PaymentStatus.UNPAID,
        paymentMethod: formData.get('paymentMethod') as PaymentMethod,
        orderStatus: channel === SalesChannel.IN_STORE ? OrderStatus.COMPLETED : OrderStatus.PENDING,
      });
      setIsAddModalOpen(false);
    }
  };

  const getChannelIcon = (channel: SalesChannel) => {
    switch (channel) {
      case SalesChannel.AMAZON: return <ShoppingBag size={14} />;
      case SalesChannel.FLIPKART: return <ShoppingBag size={14} />;
      case SalesChannel.MEESHO: return <Smartphone size={14} />;
      case SalesChannel.WEBSITE: return <Globe size={14} />;
      default: return <Store size={14} />;
    }
  };

  const getChannelStyle = (channel: SalesChannel) => {
    switch (channel) {
      case SalesChannel.AMAZON: return 'bg-orange-50 text-orange-700 border-orange-100';
      case SalesChannel.FLIPKART: return 'bg-blue-50 text-blue-700 border-blue-100';
      case SalesChannel.MEESHO: return 'bg-pink-50 text-pink-700 border-pink-100';
      default: return 'bg-gray-50 text-gray-700 border-gray-100';
    }
  };

  const getStatusBadge = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.COMPLETED: 
      case OrderStatus.DELIVERED:
        return <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-green-50 text-green-700 text-[10px] font-bold uppercase tracking-wide"><CheckCircle size={12} /> {status}</span>;
      case OrderStatus.PENDING: 
      case OrderStatus.READY_TO_SHIP:
        return <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-yellow-50 text-yellow-700 text-[10px] font-bold uppercase tracking-wide"><Clock size={12} /> {status.replace(/_/g, ' ')}</span>;
      case OrderStatus.SHIPPED:
        return <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-blue-50 text-blue-700 text-[10px] font-bold uppercase tracking-wide"><Truck size={12} /> {status}</span>;
      case OrderStatus.RETURNED:
      case OrderStatus.CANCELLED:
        return <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-red-50 text-red-700 text-[10px] font-bold uppercase tracking-wide"><XCircle size={12} /> {status}</span>;
      default: return null;
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-800 tracking-tight">Sales & Orders</h1>
          <p className="text-sm font-medium text-gray-400">Track omnichannel orders and payouts</p>
        </div>
        <Button onClick={() => setIsAddModalOpen(true)} className="flex items-center gap-2 shadow-sky-200">
          <Plus size={20} /> Record Sale
        </Button>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
         <Card className="p-5 border-0 shadow-sm bg-white">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-xs font-bold uppercase text-gray-400">Gross Revenue</p>
                    <h3 className="text-2xl font-black text-gray-800 mt-1">{formatCurrency(totalRevenue)}</h3>
                </div>
                <div className="p-2 bg-emerald-50 text-emerald-600 rounded-lg">
                    <IndianRupee size={20} />
                </div>
            </div>
            <div className="flex items-center gap-1 mt-2 text-[10px] font-medium text-emerald-600">
                <ArrowUpRight size={12} /> Total sales volume
            </div>
         </Card>

         <Card className="p-5 border-0 shadow-sm bg-white">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-xs font-bold uppercase text-gray-400">Platform Fees</p>
                    <h3 className="text-2xl font-black text-pink-600 mt-1">{formatCurrency(totalFees)}</h3>
                </div>
                <div className="p-2 bg-pink-50 text-pink-600 rounded-lg">
                    <FileText size={20} />
                </div>
            </div>
            <p className="text-[10px] text-gray-400 mt-2">Commissions & Shipping</p>
         </Card>

         <Card className="p-5 border-0 shadow-sm bg-white">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-xs font-bold uppercase text-gray-400">Net Payout</p>
                    <h3 className="text-2xl font-black text-emerald-600 mt-1">{formatCurrency(netPayout)}</h3>
                </div>
                <div className="p-2 bg-emerald-50 text-emerald-600 rounded-lg">
                    <CheckCircle size={20} />
                </div>
            </div>
            <p className="text-[10px] text-gray-400 mt-2">Realized profit after fees</p>
         </Card>

         <Card className="p-5 border-0 shadow-sm bg-white">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-xs font-bold uppercase text-gray-400">Pending Orders</p>
                    <h3 className="text-2xl font-black text-orange-500 mt-1">{pendingOrders}</h3>
                </div>
                <div className="p-2 bg-orange-50 text-orange-600 rounded-lg">
                    <Package size={20} />
                </div>
            </div>
            <p className="text-[10px] text-gray-400 mt-2">Needs shipping/fulfillment</p>
         </Card>
      </div>

      <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
        <div className="relative w-full md:w-96">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Search invoice, order ID..." 
            className="w-full pl-11 pr-4 py-2.5 bg-white border border-gray-100 rounded-2xl outline-none focus:ring-2 focus:ring-sky-100 transition-all font-medium text-gray-600"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex bg-gray-100/50 p-1 rounded-xl w-full md:w-auto overflow-x-auto">
           {[
             { id: 'ALL', label: 'All', icon: null },
             { id: SalesChannel.IN_STORE, label: 'Store', icon: <Store size={14} /> },
             { id: SalesChannel.AMAZON, label: 'Amazon', icon: <ShoppingBag size={14} /> },
             { id: SalesChannel.FLIPKART, label: 'Flipkart', icon: <ShoppingBag size={14} /> },
             { id: SalesChannel.MEESHO, label: 'Meesho', icon: <Smartphone size={14} /> },
           ].map(tab => (
             <button
                key={tab.id}
                onClick={() => setChannelFilter(tab.id as any)}
                className={`px-4 py-2 rounded-lg text-xs font-bold flex items-center gap-2 transition-all whitespace-nowrap ${channelFilter === tab.id ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
             >
                {tab.icon} {tab.label}
             </button>
           ))}
        </div>
      </div>

      <Card className="overflow-hidden border-0 shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead>
              <tr className="bg-gray-50/50 border-b border-gray-100 text-gray-400">
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Source</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Order Details</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Customer</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Financials</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Status</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filteredSales.map(sale => {
                  const customer = customers.find(c => c.id === sale.customerId);
                  return (
                    <tr key={sale.id} className="hover:bg-gray-50 transition-colors group">
                    <td className="px-6 py-4">
                        <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-xl border text-[10px] font-bold uppercase tracking-wider ${getChannelStyle(sale.channel)}`}>
                            {getChannelIcon(sale.channel)}
                            {sale.channel}
                        </div>
                    </td>
                    <td className="px-6 py-4">
                        <div className="font-bold text-gray-800">{sale.invoiceNumber}</div>
                        {sale.externalOrderId && (
                            <div className="text-xs font-mono text-gray-400 mt-1 flex items-center gap-1">
                                <FileText size={10} /> Ref: {sale.externalOrderId}
                            </div>
                        )}
                        <div className="text-xs text-gray-500 mt-1 flex items-center gap-1">
                             <Calendar size={10} />
                             {new Date(sale.date).toLocaleDateString()}
                        </div>
                    </td>
                    <td className="px-6 py-4">
                         <div className="flex items-center gap-2">
                            <div className="w-8 h-8 rounded-full bg-gray-100 flex items-center justify-center text-gray-500">
                                <User size={14} />
                            </div>
                            <div>
                                <div className="font-bold text-gray-700 text-xs">{customer?.name || 'Unknown'}</div>
                                <div className="text-[10px] text-gray-400">{sale.items.length} Item(s)</div>
                            </div>
                         </div>
                    </td>
                    <td className="px-6 py-4">
                        <div className="flex flex-col">
                            <span className="font-black text-gray-800">{formatCurrency(sale.totalAmount)}</span>
                            {sale.marketplaceFees > 0 ? (
                                <span className="text-[10px] text-emerald-600 font-bold mt-0.5">
                                    Net: {formatCurrency(sale.netPayout)}
                                </span>
                            ) : (
                                <span className="text-[10px] text-gray-400 mt-0.5">Gross Sales</span>
                            )}
                        </div>
                    </td>
                    <td className="px-6 py-4">
                        {getStatusBadge(sale.orderStatus)}
                    </td>
                    <td className="px-6 py-4 text-right">
                        <select 
                            className="text-xs font-medium text-gray-600 border border-gray-200 rounded-lg p-1.5 bg-white outline-none focus:border-sky-300 focus:ring-2 focus:ring-sky-50 transition-all cursor-pointer hover:border-gray-300"
                            value={sale.orderStatus}
                            onChange={(e) => updateOrderStatus(sale.id, e.target.value as OrderStatus)}
                            disabled={sale.orderStatus === OrderStatus.COMPLETED || sale.orderStatus === OrderStatus.CANCELLED}
                        >
                            {Object.values(OrderStatus).map(status => (
                                <option key={status} value={status}>{status.replace(/_/g, ' ')}</option>
                            ))}
                        </select>
                    </td>
                    </tr>
                  );
              })}
            </tbody>
          </table>
          {filteredSales.length === 0 && (
            <div className="py-20 text-center text-gray-400 italic">No sales found matching your criteria.</div>
          )}
        </div>
      </Card>

      {/* Record Sale Modal */}
      <Modal isOpen={isAddModalOpen} onClose={() => setIsAddModalOpen(false)} title="Record New Sale">
        <form onSubmit={handleCreateSale} className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="col-span-2 p-4 bg-sky-50 text-sky-800 text-xs rounded-2xl flex items-start gap-3 border border-sky-100">
             <AlertCircle size={16} className="mt-0.5 shrink-0" />
             <div>
                 <p className="font-bold mb-1">Channel Selection</p>
                 <p>Select the Sales Channel to automatically categorize the order. For Marketplaces (Amazon, Flipkart), add the Order ID and Fee amount for accurate net profit tracking.</p>
             </div>
          </div>

          <div className="space-y-1">
             <label className="text-xs font-bold uppercase text-gray-400">Sales Channel</label>
             <select name="channel" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium">
                {Object.values(SalesChannel).map(c => <option key={c} value={c}>{c}</option>)}
             </select>
          </div>

          <div className="space-y-1">
             <label className="text-xs font-bold uppercase text-gray-400">External Order ID</label>
             <input name="externalOrderId" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="Optional (e.g. Amazon ID)" />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Product</label>
            <select name="productId" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium">
              {products.map(p => <option key={p.id} value={p.id}>{p.name} (Stock: {p.stockQuantity})</option>)}
            </select>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Quantity</label>
            <input name="quantity" type="number" min="1" defaultValue="1" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Selling Price (Unit)</label>
            <input name="unitPrice" type="number" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="Leave empty for default" />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Marketplace/Ship Fees</label>
            <input name="marketplaceFees" type="number" defaultValue="0" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="Total deductions" />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Customer (Offline Only)</label>
            <select name="customerId" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium">
              <option value="">Select for In-Store...</option>
              {customers.filter(c => !c.id.startsWith('C_')).map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
          </div>

          <div className="space-y-1">
             <label className="text-xs font-bold uppercase text-gray-400">Payment Method</label>
             <select name="paymentMethod" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium">
                {Object.values(PaymentMethod).map(m => <option key={m} value={m}>{m}</option>)}
             </select>
          </div>

          <div className="col-span-1 md:col-span-2 flex gap-3 pt-4">
            <Button variant="ghost" onClick={() => setIsAddModalOpen(false)} className="flex-1">Cancel</Button>
            <Button type="submit" className="flex-1">Record Sale</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Sales;

export enum RentalStatus {
  ACTIVE = 'ACTIVE',
  RETURNED = 'RETURNED',
  OVERDUE = 'OVERDUE'
}

export enum PaymentStatus {
  PAID = 'PAID',
  PARTIAL = 'PARTIAL',
  UNPAID = 'UNPAID'
}

export enum PaymentMethod {
  CASH = 'CASH',
  UPI = 'UPI',
  CARD = 'CARD',
  BANK_TRANSFER = 'BANK_TRANSFER'
}

export enum SalesChannel {
  IN_STORE = 'IN_STORE',
  AMAZON = 'AMAZON',
  FLIPKART = 'FLIPKART',
  MEESHO = 'MEESHO',
  WEBSITE = 'WEBSITE'
}

export enum OrderStatus {
  COMPLETED = 'COMPLETED',       // Instant for offline
  PENDING = 'PENDING',           // New online order
  READY_TO_SHIP = 'READY_TO_SHIP',
  SHIPPED = 'SHIPPED',
  DELIVERED = 'DELIVERED',
  RETURNED = 'RETURNED',
  CANCELLED = 'CANCELLED'
}

export interface Product {
  id: string;
  name: string;
  sku: string;
  barcode: string;
  category: string;
  purchasePrice: number;
  sellingPrice: number;
  rentalPrice: number; // Daily rate
  taxPercent: number;
  stockQuantity: number;
  minStockAlert: number;
  supplierId: string;
  description: string;
  imageUrl?: string;
  createdAt: string;
}

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email: string;
  address: string;
  gstin?: string;
  createdAt: string;
}

export interface Supplier {
  id: string;
  name: string;
  contactPerson: string;
  phone: string;
  email: string;
  address: string;
  createdAt: string;
}

export interface InvoiceItem {
  productId: string;
  name: string;
  quantity: number;
  unitPrice: number;
  taxAmount: number;
  total: number;
}

export interface Sale {
  id: string;
  invoiceNumber: string; // Internal Invoice ID
  externalOrderId?: string; // e.g., Amazon Order ID
  channel: SalesChannel;
  customerId: string; // For marketplaces, this might be a generic "Amazon Customer"
  items: InvoiceItem[];
  totalAmount: number; // Gross Sale Amount
  marketplaceFees: number; // Commission + Shipping + Fixed Fees
  netPayout: number; // Total - Fees
  taxTotal: number;
  discount: number;
  paidAmount: number;
  paymentStatus: PaymentStatus;
  paymentMethod: PaymentMethod;
  orderStatus: OrderStatus;
  date: string;
}

export interface Rental {
  id: string;
  invoiceNumber: string;
  customerId: string;
  productId: string;
  quantity: number;
