          {/* User Menu (Mobile/Tablet) */}
          <div className="relative ml-2">
             <button 
               onClick={() => setIsUserMenuOpen(!isUserMenuOpen)}
               className="flex items-center gap-2 hover:bg-gray-50 p-1.5 pr-3 rounded-full transition-all border border-transparent hover:border-gray-100"
             >
                <div className="w-8 h-8 rounded-full bg-gradient-to-tr from-sky-400 to-indigo-500 text-white flex items-center justify-center shadow-md">
                   <User size={16} />
                </div>
                <ChevronDown size={14} className="text-gray-400 hidden md:block" />
             </button>

             {isUserMenuOpen && (
               <div className="absolute right-0 top-full mt-3 w-48 bg-white shadow-xl rounded-xl border border-gray-100 overflow-hidden animate-in fade-in slide-in-from-top-2 origin-top-right">
                  <div className="p-3 border-b border-gray-50">
                     <p className="text-xs font-bold text-gray-800">Store Admin</p>
                     <p className="text-[10px] text-gray-400 truncate">admin@kiddies.store</p>
                  </div>
                  <button onClick={() => { onTabChange('settings'); setIsUserMenuOpen(false); }} className="w-full text-left px-4 py-2.5 text-xs font-medium text-gray-600 hover:bg-gray-50 hover:text-sky-600 flex items-center gap-2">
                     <SettingsIcon size={14} /> Settings
                  </button>
                  <button className="w-full text-left px-4 py-2.5 text-xs font-medium text-red-500 hover:bg-red-50 flex items-center gap-2">
                     <LogOut size={14} /> Logout
