import React, { useState } from 'react';
import { useApp } from '../store/AppContext';
import { Card, Button, Modal } from '../components/Shared';
import { 
  Plus, 
  Search, 
  ShieldCheck, 
  User as UserIcon, 
  Mail, 
  Trash2, 
  Lock,
  Edit2
} from 'lucide-react';
import { UserRole } from '../types';

const Users: React.FC = () => {
  const { users, currentUser, addUser, updateUser, deleteUser } = useApp();
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingUserId, setEditingUserId] = useState<string | null>(null);

  const filteredUsers = users.filter(u => 
    u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    u.email.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const userData = {
      name: formData.get('name') as string,
      email: formData.get('email') as string,
      password: formData.get('password') as string,
      role: formData.get('role') as UserRole,
    };

    if (editingUserId) {
      updateUser(editingUserId, userData);
      setEditingUserId(null);
    } else {
      addUser(userData);
    }
    setIsAddModalOpen(false);
  };

  const openEdit = (user: any) => {
    setEditingUserId(user.id);
    setIsAddModalOpen(true);
  };

  const openAdd = () => {
    setEditingUserId(null);
    setIsAddModalOpen(true);
  };

  const handleDelete = (id: string) => {
    if (confirm('Are you sure you want to remove this user?')) {
      deleteUser(id);
    }
  };

  // Pre-fill data if editing
  const editingUser = editingUserId ? users.find(u => u.id === editingUserId) : null;

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-800 tracking-tight">User Management</h1>
          <p className="text-sm font-medium text-gray-400">Control system access and roles</p>
        </div>
        <Button onClick={openAdd} className="flex items-center gap-2 shadow-sky-200">
          <Plus size={20} /> Add User
        </Button>
      </div>

      <div className="relative max-w-md">
        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
        <input 
          type="text" 
          placeholder="Search users..." 
          className="w-full pl-11 pr-4 py-3 bg-white border border-gray-100 rounded-2xl outline-none focus:ring-2 focus:ring-sky-100 transition-all font-medium text-gray-600"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <Card className="overflow-hidden border-0 shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead>
              <tr className="bg-gray-50/50 border-b border-gray-100 text-gray-400">
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">User Profile</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Role</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Join Date</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filteredUsers.map(user => (
                <tr key={user.id} className="hover:bg-gray-50 transition-colors">
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-3">
                      <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white font-bold shadow-sm ${user.role === 'ADMIN' ? 'bg-indigo-500' : 'bg-emerald-500'}`}>
                         {user.name.charAt(0)}
                      </div>
                      <div>
                        <div className="font-bold text-gray-800 flex items-center gap-2">
                           {user.name} 
                           {user.id === currentUser?.id && <span className="bg-gray-100 text-gray-500 text-[10px] px-1.5 py-0.5 rounded">You</span>}
                        </div>
                        <div className="text-xs text-gray-400 flex items-center gap-1 mt-0.5">
                           <Mail size={10} /> {user.email}
                        </div>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold uppercase tracking-wide ${
                      user.role === UserRole.ADMIN ? 'bg-indigo-50 text-indigo-700' : 'bg-emerald-50 text-emerald-700'
                    }`}>
                      {user.role === UserRole.ADMIN ? <ShieldCheck size={12} /> : <UserIcon size={12} />}
                      {user.role}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                     <span className="text-gray-500">{new Date(user.createdAt).toLocaleDateString()}</span>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex items-center justify-end gap-2">
                       <button onClick={() => openEdit(user)} className="p-2 text-gray-400 hover:text-sky-600 hover:bg-sky-50 rounded-lg transition-colors">
                         <Edit2 size={16} />
                       </button>
                       {user.id !== currentUser?.id && (
                          <button onClick={() => handleDelete(user.id)} className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors">
                            <Trash2 size={16} />
                          </button>
                       )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Card>

      <Modal 
        isOpen={isAddModalOpen} 
        onClose={() => setIsAddModalOpen(false)} 
        title={editingUserId ? "Edit User" : "Add New User"}
      >
        <form onSubmit={handleSubmit} className="grid grid-cols-1 gap-4">
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Full Name</label>
            <input name="name" defaultValue={editingUser?.name} required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Email Address</label>
            <input name="email" type="email" defaultValue={editingUser?.email} required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Password</label>
            <div className="relative">
              <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
              <input name="password" type="password" defaultValue={editingUser?.password} required className="w-full pl-10 pr-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="••••••••" />
            </div>
            {editingUserId && <p className="text-[10px] text-orange-400 mt-1">Warning: Changing this will update their login password immediately.</p>}
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Role</label>
            <select name="role" defaultValue={editingUser?.role || UserRole.STAFF} className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium">
               <option value={UserRole.ADMIN}>Admin (Full Access)</option>
               <option value={UserRole.STAFF}>Staff (Restricted)</option>
            </select>
          </div>

          <div className="flex gap-3 pt-4">
            <Button variant="ghost" onClick={() => setIsAddModalOpen(false)} className="flex-1">Cancel</Button>
            <Button type="submit" className="flex-1">Save User</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Users;

import React, { useState, useRef, useEffect } from 'react';
import { AppProvider, useApp } from './store/AppContext';
import { NAVIGATION_ITEMS } from './constants';
import Dashboard from './pages/Dashboard';
import Inventory from './pages/Inventory';
import Rentals from './pages/Rentals';
import Customers from './pages/Customers';
import Suppliers from './pages/Suppliers';
import Sales from './pages/Sales';
import Settings from './pages/Settings';
import Reports from './pages/Reports';
import Users from './pages/Users';
import Login from './pages/Login';
import { 
  Bell, 
  Menu, 
  Search, 
  LogOut, 
  Settings as SettingsIcon,
  AlertTriangle,
  Clock,
  ChevronDown,
  User,
  X,
  ShieldCheck
} from 'lucide-react';
