          <span className="text-yellow-400">d</span>
          <span className="text-pink-400">ies</span>
        </h1>
      </div>
      <p className="text-[10px] font-bold text-gray-400 tracking-widest uppercase mt-2 ml-1">Kids Wear Admin</p>
