      <div className="flex-1 md:ml-64 min-w-0 transition-all duration-300">
        <TopBar activeTab={activeTab} onTabChange={setActiveTab} />
        <main className="p-4 md:p-8 max-w-7xl mx-auto">
          <MainContent activeTab={activeTab} />
        </main>
      </div>
    </div>
  );
};

