                    <div className={`inline-flex flex-col px-3 py-1.5 rounded-lg border ${
                      user.role === UserRole.ADMIN ? 'bg-indigo-50 border-indigo-100' : 'bg-emerald-50 border-emerald-100'
                    }`}>
                      <span className={`text-[10px] font-black uppercase tracking-wide flex items-center gap-1.5 ${
