                       : 'bg-white border-gray-100 hover:bg-gray-50'
                    }`}
                 >
                    <div className={`w-5 h-5 rounded-md border flex items-center justify-center transition-colors ${
                       tempPermissions.includes(item.id) ? 'bg-sky-500 border-sky-500' : 'border-gray-300 bg-white'
                    }`}>
                       {tempPermissions.includes(item.id) && <CheckCircle2 size={14} className="text-white" />}
                    </div>
                    <input 
                       type="checkbox" 
                       className="hidden" 
                       checked={tempPermissions.includes(item.id)}
                       onChange={() => togglePermission(item.id)}
                    />
                    <div className="flex items-center gap-2 text-sm font-bold text-gray-700">
                       <span className="text-gray-400">{item.icon}</span>
                       {item.label}
                    </div>
                 </label>
              ))}
           </div>

           <div className="flex gap-3 pt-4 border-t border-gray-50">
             <Button variant="ghost" onClick={() => setIsAccessModalOpen(false)} className="flex-1">Cancel</Button>
             <Button onClick={handleAccessSubmit} className="flex-1">Save Permissions</Button>
           </div>
        </div>
      </Modal>
    </div>
  );
};

