const MainContent: React.FC<{ activeTab: string }> = ({ activeTab }) => {
  const { currentUser, settings } = useApp();
  const userPermissions = settings.rolePermissions[currentUser?.role || ''] || [];

  if (!userPermissions.includes(activeTab)) {
     return (
        <div className="flex flex-col items-center justify-center py-32 text-center">
           <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mb-6 text-gray-300">
             <Lock size={32} />
           </div>
           <h3 className="text-xl font-bold text-gray-700">Access Denied</h3>
           <p className="text-sm mt-2 text-gray-400">You do not have permission to view this module.</p>
        </div>
     );
  }

  switch (activeTab) {
    case 'dashboard': return <Dashboard />;
    case 'inventory': return <Inventory />;
    case 'rentals': return <Rentals />;
    case 'customers': return <Customers />;
    case 'suppliers': return <Suppliers />;
    case 'sales': return <Sales />;
    case 'settings': return <Settings />;
    case 'reports': return <Reports />;
    case 'users': return <Users />;
    default: return (
      <div className="flex flex-col items-center justify-center py-32 text-gray-400 bg-white rounded-3xl border border-dashed border-gray-200 m-4">
