          <SettingsIcon size={32} />
        </div>
        <h3 className="text-xl font-bold text-gray-700">Module Coming Soon</h3>
        <p className="text-sm mt-2 text-gray-400">We are currently building this section.</p>
      </div>
    );
  }
};

const ProtectedApp: React.FC = () => {
  const { currentUser } = useApp();
