import React, { useState, useRef, useEffect } from 'react';
import { AppProvider, useApp } from './store/AppContext';
import { NAVIGATION_ITEMS } from './constants';
import Dashboard from './pages/Dashboard';
import Inventory from './pages/Inventory';
import Rentals from './pages/Rentals';
import Customers from './pages/Customers';
import Suppliers from './pages/Suppliers';
import Sales from './pages/Sales';
import Settings from './pages/Settings';
import Reports from './pages/Reports';
import Users from './pages/Users';
import Login from './pages/Login';
import { 
  Bell, 
  Menu, 
  Search, 
  LogOut, 
  Settings as SettingsIcon,
  AlertTriangle,
  Clock,
  ChevronDown,
  User,
  X,
  ShieldCheck,
  Lock,
  ShoppingBag,
  RefreshCcw
} from 'lucide-react';
import { UserRole } from './types';

// Helper to check permissions
const canAccess = (user: any, moduleId: string) => {
  if (!user) return false;
  if (user.role === UserRole.ADMIN) return true; // Admins access everything
  return user.permissions?.includes(moduleId) || false;
};

const Sidebar: React.FC<{ activeTab: string; onTabChange: (id: string) => void }> = ({ activeTab, onTabChange }) => {
  const { currentUser } = useApp();

  return (
  <aside className="w-64 bg-white text-gray-600 flex flex-col h-screen fixed left-0 top-0 z-40 border-r border-gray-100 hidden md:flex">
    {/* Branding Area */}
    <div className="p-8 pb-4">
      <div className="flex items-center gap-2 cursor-pointer" onClick={() => onTabChange('dashboard')}>
        <h1 className="text-3xl font-black tracking-tight leading-none">
          <span className="text-sky-500">Kid</span>
          <span className="text-yellow-400">d</span>
          <span className="text-pink-400">ies</span>
        </h1>
      </div>
      <p className="text-[10px] font-bold text-gray-400 tracking-widest uppercase mt-2 ml-1">Kids Wear Admin</p>
    </div>

    {/* Navigation */}
    <nav className="flex-1 px-4 space-y-1 overflow-y-auto custom-scrollbar mt-4 mb-4">
      {NAVIGATION_ITEMS.filter(item => {
        if (item.id === 'settings') return false; // Handled in header
        return canAccess(currentUser, item.id);
      }).map((item) => {
        const isActive = activeTab === item.id;
        return (
          <button
            key={item.id}
            onClick={() => onTabChange(item.id)}
            className={`
              relative w-full flex items-center gap-3.5 px-4 py-3 rounded-2xl text-sm font-bold transition-all duration-200
              ${isActive 
                ? 'bg-sky-50 text-sky-500 shadow-sm' 
                : 'text-gray-400 hover:text-gray-600 hover:bg-gray-50'
              }
            `}
          >
            <span className={`
              ${isActive ? 'text-sky-500' : 'text-gray-300'} 
              transition-colors duration-200
            `}>
              {React.isValidElement(item.icon) 
                ? React.cloneElement(item.icon as React.ReactElement<any>, { 
                    size: 20, 
                    strokeWidth: 2.5 
                  })
                : item.icon
              }
            </span>

            <span className="tracking-wide">{item.label}</span>

            {/* Notification Badge example for Inventory */}
            {item.id === 'inventory' && (
               <span className={`
                 ml-auto text-[10px] px-2 py-0.5 rounded-full font-bold transition-colors opacity-0 group-hover:opacity-100
                 ${isActive ? 'opacity-100 bg-pink-400 text-white' : ''}
               `}></span>
            )}
          </button>
        );
      })}
    </nav>
  </aside>
  );
};

const TopBar: React.FC<{ activeTab: string; onTabChange: (id: string) => void }> = ({ activeTab, onTabChange }) => {
  const { products, rentals, sales, currentUser, logout } = useApp();
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const tabLabel = NAVIGATION_ITEMS.find(i => i.id === activeTab)?.label;
  const canAccessSettings = canAccess(currentUser, 'settings');

  // Compute Notifications
  const lowStockItems = products.filter(p => p.stockQuantity <= p.minStockAlert);
  const overdueRentals = rentals.filter(r => r.status === 'ACTIVE' && new Date(r.expectedReturnDate) < new Date());

  // Recent Activity (Last 5 items mixed)
  const recentActivities = [...sales, ...rentals]
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
      .slice(0, 5)
      .map(item => {
          const isSale = 'items' in item;
          return {
              id: item.id,
              type: isSale ? 'SALE' : 'RENTAL',
              title: isSale ? 'New Sale Recorded' : 'New Rental Booking',
              message: `${isSale ? (item as any).invoiceNumber : (item as any).invoiceNumber} • ${new Date(item.date).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}`,
              action: () => onTabChange(isSale ? 'sales' : 'rentals'),
              urgent: false
          };
      });

  const notifications = [
    // Priority Alerts
    ...lowStockItems.map(p => ({
       id: `stock-${p.id}`,
       type: 'STOCK',
       title: 'Low Stock Alert',
       message: `${p.name} is running low (${p.stockQuantity} remaining).`,
       action: () => onTabChange('inventory'),
       urgent: true
    })),
    ...overdueRentals.map(r => ({
       id: `rental-${r.id}`,
       type: 'RENTAL_OVERDUE',
       title: 'Overdue Rental',
       message: `Rental #${r.invoiceNumber} is overdue since ${new Date(r.expectedReturnDate).toLocaleDateString()}.`,
       action: () => onTabChange('rentals'),
       urgent: true
    })),
    // Recent Activity Feed
    ...recentActivities
  ];

  const unreadCount = notifications.length;

  const getNotificationIcon = (type: string) => {
    switch (type) {
        case 'STOCK': return <AlertTriangle size={14} />;
        case 'RENTAL_OVERDUE': return <Clock size={14} />;
        case 'SALE': return <ShoppingBag size={14} />;
        case 'RENTAL': return <RefreshCcw size={14} />;
        default: return <Bell size={14} />;
    }
  };

  const getNotificationStyles = (note: any) => {
      if (note.urgent) return 'bg-red-50 text-red-500';
      if (note.type === 'SALE') return 'bg-emerald-50 text-emerald-500';
      if (note.type === 'RENTAL') return 'bg-sky-50 text-sky-500';
      return 'bg-gray-50 text-gray-500';
  };

  // Close dropdowns on outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsNotificationsOpen(false);
        setIsUserMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <header className="h-20 bg-white/90 backdrop-blur-md border-b border-gray-100 flex items-center justify-between px-6 md:px-8 sticky top-0 z-30 shadow-sm transition-all">
      <div className="flex items-center space-x-4">
        <button className="md:hidden p-2 text-gray-500 hover:bg-gray-100 rounded-lg">
           <Menu size={24} />
        </button>
        <div>
          <h2 className="text-xl font-black text-gray-800 tracking-tight">{tabLabel}</h2>
        </div>
      </div>

      <div className="flex items-center gap-2 md:gap-6" ref={dropdownRef}>
        {/* Search - Hidden on mobile */}
        <div className="hidden md:flex items-center bg-gray-100/50 rounded-2xl px-4 py-2.5 w-64 lg:w-80 focus-within:ring-2 focus-within:ring-sky-100 focus-within:bg-white transition-all border border-transparent focus-within:border-sky-100">
          <Search size={18} className="text-gray-400 mr-3 shrink-0" />
          <input 
            type="text" 
            placeholder="Quick search..." 
            className="bg-transparent text-sm outline-none w-full placeholder:text-gray-400 text-gray-700 font-medium"
          />
        </div>

        <div className="flex items-center gap-2">
          {/* Notifications */}
          <div className="relative">
            <button 
              onClick={() => setIsNotificationsOpen(!isNotificationsOpen)}
              className={`relative p-2.5 rounded-xl transition-all ${isNotificationsOpen ? 'bg-sky-50 text-sky-600' : 'text-gray-400 hover:bg-gray-100 hover:text-gray-600'}`}
            >
              <Bell size={20} strokeWidth={2.5} />
              {unreadCount > 0 && (
                <span className="absolute top-2 right-2.5 w-2.5 h-2.5 bg-pink-500 rounded-full border-2 border-white animate-pulse"></span>
              )}
            </button>

            {isNotificationsOpen && (
              <div className="absolute right-0 top-full mt-3 w-80 md:w-96 bg-white shadow-2xl rounded-2xl border border-gray-100 overflow-hidden animate-in fade-in slide-in-from-top-2 origin-top-right">
                <div className="p-4 border-b border-gray-50 flex justify-between items-center bg-gray-50/50">
                   <h3 className="font-bold text-gray-800 text-sm">Activity & Alerts</h3>
                   {unreadCount > 0 && <span className="bg-sky-100 text-sky-600 text-[10px] font-bold px-2 py-0.5 rounded-full">{unreadCount} New</span>}
                </div>
                <div className="max-h-[300px] overflow-y-auto custom-scrollbar">
                   {notifications.length > 0 ? (
                     notifications.map((note, i) => (
                       <div 
                         key={i} 
                         onClick={() => { note.action(); setIsNotificationsOpen(false); }}
                         className="p-4 hover:bg-gray-50 border-b border-gray-50 last:border-0 cursor-pointer transition-colors flex gap-3 items-start group"
                       >
                          <div className={`mt-0.5 p-2 rounded-full shrink-0 ${getNotificationStyles(note)}`}>
                             {getNotificationIcon(note.type)}
                          </div>
                          <div>
                             <p className="text-xs font-bold text-gray-800 group-hover:text-sky-600 transition-colors">{note.title}</p>
                             <p className="text-xs text-gray-500 mt-0.5 leading-relaxed">{note.message}</p>
                          </div>
                       </div>
                     ))
                   ) : (
                     <div className="p-8 text-center text-gray-400 flex flex-col items-center">
                        <Bell size={32} className="text-gray-200 mb-2" />
                        <p className="text-sm font-medium">No recent activity</p>
                        <p className="text-xs">You're all caught up!</p>
                     </div>
                   )}
                </div>
                {notifications.length > 0 && (
                   <div className="p-2 bg-gray-50 text-center">
                      <button 
                        onClick={() => setIsNotificationsOpen(false)} 
                        className="text-xs font-bold text-gray-500 hover:text-gray-800 transition-colors"
                      >
                        Dismiss All
                      </button>
                   </div>
                )}
              </div>
            )}
          </div>

          {/* Settings Button */}
          {canAccessSettings && (
            <button 
              onClick={() => onTabChange('settings')}
              className="hidden md:block p-2.5 text-gray-400 hover:bg-gray-100 hover:text-gray-600 rounded-xl transition-all"
              title="Settings"
            >
              <SettingsIcon size={20} strokeWidth={2.5} />
            </button>
          )}

          {/* User Menu (Mobile/Tablet) */}
          <div className="relative ml-2">
             <button 
               onClick={() => setIsUserMenuOpen(!isUserMenuOpen)}
               className="flex items-center gap-2 hover:bg-gray-50 p-1.5 pr-3 rounded-full transition-all border border-transparent hover:border-gray-100"
             >
                <div className={`w-8 h-8 rounded-full bg-gradient-to-tr ${currentUser?.role === UserRole.ADMIN ? 'from-indigo-400 to-indigo-600' : 'from-sky-400 to-sky-600'} text-white flex items-center justify-center shadow-md font-bold text-xs`}>
                   {currentUser?.name.charAt(0)}
                </div>
                <ChevronDown size={14} className="text-gray-400 hidden md:block" />
             </button>

             {isUserMenuOpen && (
               <div className="absolute right-0 top-full mt-3 w-48 bg-white shadow-xl rounded-xl border border-gray-100 overflow-hidden animate-in fade-in slide-in-from-top-2 origin-top-right">
                  <div className="p-3 border-b border-gray-50 bg-gray-50/50">
                     <p className="text-xs font-bold text-gray-800">{currentUser?.name}</p>
                     <div className="flex items-center gap-1 mt-0.5">
                       {currentUser?.role === UserRole.ADMIN ? <ShieldCheck size={10} className="text-indigo-500"/> : <User size={10} className="text-sky-500"/>}
                       <p className="text-[10px] text-gray-500 capitalize">{currentUser?.role.toLowerCase()}</p>
                     </div>
                  </div>
                  {canAccessSettings && (
                    <button onClick={() => { onTabChange('settings'); setIsUserMenuOpen(false); }} className="w-full text-left px-4 py-2.5 text-xs font-medium text-gray-600 hover:bg-gray-50 hover:text-sky-600 flex items-center gap-2">
                      <SettingsIcon size={14} /> Settings
                    </button>
                  )}
                  <button onClick={() => logout()} className="w-full text-left px-4 py-2.5 text-xs font-medium text-red-500 hover:bg-red-50 flex items-center gap-2">
                     <LogOut size={14} /> Logout
                  </button>
               </div>
             )}
          </div>
        </div>
      </div>
    </header>
  );
};

const MainContent: React.FC<{ activeTab: string }> = ({ activeTab }) => {
  const { currentUser } = useApp();

  if (!canAccess(currentUser, activeTab)) {
     return (
        <div className="flex flex-col items-center justify-center py-32 text-center animate-in fade-in zoom-in">
           <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mb-6 text-gray-300">
             <Lock size={32} />
           </div>
           <h3 className="text-xl font-bold text-gray-700">Access Denied</h3>
           <p className="text-sm mt-2 text-gray-400">You do not have permission to view this module.</p>
        </div>
     );
  }

  switch (activeTab) {
    case 'dashboard': return <Dashboard />;
    case 'inventory': return <Inventory />;
    case 'rentals': return <Rentals />;
    case 'customers': return <Customers />;
    case 'suppliers': return <Suppliers />;
    case 'sales': return <Sales />;
    case 'settings': return <Settings />;
    case 'reports': return <Reports />;
    case 'users': return <Users />;
    default: return (
      <div className="flex flex-col items-center justify-center py-32 text-gray-400 bg-white rounded-3xl border border-dashed border-gray-200 m-4">
        <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mb-6 text-gray-300">
          <SettingsIcon size={32} />
        </div>
        <h3 className="text-xl font-bold text-gray-700">Module Coming Soon</h3>
        <p className="text-sm mt-2 text-gray-400">We are currently building this section.</p>
      </div>
    );
  }
};

const ProtectedApp: React.FC = () => {
  const { currentUser } = useApp();
  const [activeTab, setActiveTab] = useState('dashboard');

  if (!currentUser) {
    return <Login />;
  }

  return (
    <div className="flex min-h-screen bg-gray-50/50">
      <Sidebar activeTab={activeTab} onTabChange={setActiveTab} />
      {/* Left margin matches sidebar width (w-64) for desktop */}
      <div className="flex-1 md:ml-64 min-w-0 transition-all duration-300">
        <TopBar activeTab={activeTab} onTabChange={setActiveTab} />
        <main className="p-4 md:p-8 max-w-7xl mx-auto">
          <MainContent activeTab={activeTab} />
        </main>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  return (
    <AppProvider>
      <ProtectedApp />
    </AppProvider>
  );
};

