        <form onSubmit={handleCreateSale} className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="col-span-2 p-4 bg-sky-50 text-sky-800 text-xs rounded-2xl flex items-start gap-3 border border-sky-100">
             <AlertCircle size={16} className="mt-0.5 shrink-0" />
             <div>
                 <p className="font-bold mb-1">Channel Selection</p>
                 <p>Select the Sales Channel to automatically categorize the order. This will deduct from the <strong>Sales Stock</strong> pool.</p>
