const TopBar: React.FC<{ activeTab: string; onTabChange: (id: string) => void }> = ({ activeTab, onTabChange }) => {
  const { products, rentals, sales, currentUser, logout } = useApp();
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const tabLabel = NAVIGATION_ITEMS.find(i => i.id === activeTab)?.label;
  const canAccessSettings = canAccess(currentUser, 'settings');

  // Compute Notifications
  // Check SALE stock for alerts
  const lowStockItems = products.filter(p => p.saleStock <= p.minStockAlert);
  const overdueRentals = rentals.filter(r => r.status === 'ACTIVE' && new Date(r.expectedReturnDate) < new Date());

  // Recent Activity (Last 5 items mixed)
  const recentActivities = [...sales, ...rentals]
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
      .slice(0, 5)
      .map(item => {
          const isSale = 'items' in item;
          return {
              id: item.id,
              type: isSale ? 'SALE' : 'RENTAL',
              title: isSale ? 'New Sale Recorded' : 'New Rental Booking',
              message: `${isSale ? (item as any).invoiceNumber : (item as any).invoiceNumber} • ${new Date(item.date).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}`,
              action: () => onTabChange(isSale ? 'sales' : 'rentals'),
              urgent: false
          };
      });

  const notifications = [
    // Priority Alerts
    ...lowStockItems.map(p => ({
       id: `stock-${p.id}`,
       type: 'STOCK',
       title: 'Low Stock Alert',
       message: `${p.name} is running low (${p.saleStock} remaining).`,
       action: () => onTabChange('inventory'),
       urgent: true
