    ...overdueRentals.map(r => ({
       id: `rental-${r.id}`,
       type: 'RENTAL_OVERDUE',
       title: 'Overdue Rental',
       message: `Rental #${r.invoiceNumber} is overdue since ${new Date(r.expectedReturnDate).toLocaleDateString()}.`,
       action: () => onTabChange('rentals'),
