import React, { useState, useMemo } from 'react';
import { useApp } from '../store/AppContext';
import { Card, Button, Modal } from '../components/Shared';
import { 
  Plus, 
  Search, 
  ShoppingBag, 
  Truck, 
  Smartphone, 
  Store, 
  Globe, 
  ArrowUpRight,
  Filter,
  IndianRupee,
  Package,
  CheckCircle,
  XCircle,
  Clock,
  User,
  Calendar,
  FileText,
  AlertCircle,
  Calculator
} from 'lucide-react';
import { formatCurrency } from '../utils/helpers';
import { SalesChannel, PaymentMethod, PaymentStatus, OrderStatus } from '../types';

const Sales: React.FC = () => {
  const { sales, products, customers, addSale, updateOrderStatus } = useApp();
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [channelFilter, setChannelFilter] = useState<'ALL' | SalesChannel>('ALL');

  // Form State
  const [selectedChannel, setSelectedChannel] = useState<SalesChannel>(SalesChannel.IN_STORE);
  const [selectedProductPrice, setSelectedProductPrice] = useState<number>(0);
  const [quantity, setQuantity] = useState<number>(1);
  const [fees, setFees] = useState<number>(0);

  const filteredSales = sales.filter(s => {
    const matchesSearch = s.invoiceNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          s.externalOrderId?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesChannel = channelFilter === 'ALL' || s.channel === channelFilter;
    return matchesSearch && matchesChannel;
  });

  // Calculate Metrics
  const totalRevenue = filteredSales.reduce((acc, s) => acc + s.totalAmount, 0);
  const totalFees = filteredSales.reduce((acc, s) => acc + s.marketplaceFees, 0);
  const netPayout = filteredSales.reduce((acc, s) => acc + s.netPayout, 0);
  const pendingOrders = filteredSales.filter(s => s.orderStatus === OrderStatus.PENDING || s.orderStatus === OrderStatus.READY_TO_SHIP).length;

  // Live Calculation for Modal
  const estimatedTotal = selectedProductPrice * quantity;
  const estimatedNet = estimatedTotal - fees;

  const handleCreateSale = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const productId = formData.get('productId') as string;
    const qty = Number(formData.get('quantity'));
    const product = products.find(p => p.id === productId);
    const channel = selectedChannel; // Use state

    // Auto-select dummy customers for marketplaces if not in store
    let customerId = formData.get('customerId') as string;
    if (channel === SalesChannel.AMAZON) customerId = 'C_AMZ';
    if (channel === SalesChannel.FLIPKART) customerId = 'C_FK';
    if (channel === SalesChannel.MEESHO) customerId = 'C_MEE';
    if (channel === SalesChannel.WEBSITE) customerId = 'C_AMZ'; // Fallback for website if no specific cust

    if (product) {
      const unitPrice = Number(formData.get('unitPrice')) || product.sellingPrice;
      const total = unitPrice * qty;
      const marketplaceFees = Number(formData.get('marketplaceFees')) || 0;

      addSale({
        channel: channel,
        externalOrderId: formData.get('externalOrderId') as string,
        customerId: customerId,
        items: [{
          productId: product.id,
          name: product.name,
          quantity: qty,
          unitPrice: unitPrice,
          taxAmount: 0,
          total: total
        }],
        totalAmount: total,
        marketplaceFees: marketplaceFees,
        netPayout: total - marketplaceFees,
        taxTotal: 0,
        discount: 0,
        paidAmount: channel === SalesChannel.IN_STORE ? total : 0, // In store is paid immediately usually
        paymentStatus: channel === SalesChannel.IN_STORE ? PaymentStatus.PAID : PaymentStatus.UNPAID,
        paymentMethod: formData.get('paymentMethod') as PaymentMethod,
        orderStatus: channel === SalesChannel.IN_STORE ? OrderStatus.COMPLETED : OrderStatus.PENDING,
      });
      setIsAddModalOpen(false);
      // Reset form state
      setSelectedChannel(SalesChannel.IN_STORE);
      setFees(0);
      setQuantity(1);
      setSelectedProductPrice(0);
    }
  };

  const openAddModal = () => {
    setSelectedChannel(SalesChannel.IN_STORE);
    setFees(0);
    setQuantity(1);
    setSelectedProductPrice(0);
    setIsAddModalOpen(true);
  }

  const getChannelIcon = (channel: SalesChannel) => {
    switch (channel) {
      case SalesChannel.AMAZON: return <ShoppingBag size={14} />;
      case SalesChannel.FLIPKART: return <ShoppingBag size={14} />;
      case SalesChannel.MEESHO: return <Smartphone size={14} />;
      case SalesChannel.WEBSITE: return <Globe size={14} />;
      default: return <Store size={14} />;
    }
  };

  const getChannelStyle = (channel: SalesChannel) => {
    switch (channel) {
      case SalesChannel.AMAZON: return 'bg-orange-50 text-orange-700 border-orange-100';
      case SalesChannel.FLIPKART: return 'bg-blue-50 text-blue-700 border-blue-100';
      case SalesChannel.MEESHO: return 'bg-pink-50 text-pink-700 border-pink-100';
      default: return 'bg-gray-50 text-gray-700 border-gray-100';
    }
  };

  const getStatusBadge = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.COMPLETED: 
      case OrderStatus.DELIVERED:
        return <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-green-50 text-green-700 text-[10px] font-bold uppercase tracking-wide"><CheckCircle size={12} /> {status}</span>;
      case OrderStatus.PENDING: 
      case OrderStatus.READY_TO_SHIP:
        return <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-yellow-50 text-yellow-700 text-[10px] font-bold uppercase tracking-wide"><Clock size={12} /> {status.replace(/_/g, ' ')}</span>;
      case OrderStatus.SHIPPED:
        return <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-blue-50 text-blue-700 text-[10px] font-bold uppercase tracking-wide"><Truck size={12} /> {status}</span>;
      case OrderStatus.RETURNED:
      case OrderStatus.CANCELLED:
        return <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-red-50 text-red-700 text-[10px] font-bold uppercase tracking-wide"><XCircle size={12} /> {status}</span>;
      default: return null;
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-800 tracking-tight">Sales & Orders</h1>
          <p className="text-sm font-medium text-gray-400">Track omnichannel orders and payouts</p>
        </div>
        <Button onClick={openAddModal} className="flex items-center gap-2 shadow-sky-200">
          <Plus size={20} /> Record Sale
        </Button>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
         <Card className="p-5 border-0 shadow-sm bg-white">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-xs font-bold uppercase text-gray-400">Gross Revenue</p>
                    <h3 className="text-2xl font-black text-gray-800 mt-1">{formatCurrency(totalRevenue)}</h3>
                </div>
                <div className="p-2 bg-emerald-50 text-emerald-600 rounded-lg">
                    <IndianRupee size={20} />
                </div>
            </div>
            <div className="flex items-center gap-1 mt-2 text-[10px] font-medium text-emerald-600">
                <ArrowUpRight size={12} /> Total sales volume
            </div>
         </Card>

         <Card className="p-5 border-0 shadow-sm bg-white">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-xs font-bold uppercase text-gray-400">Platform Fees</p>
                    <h3 className="text-2xl font-black text-pink-600 mt-1">{formatCurrency(totalFees)}</h3>
                </div>
                <div className="p-2 bg-pink-50 text-pink-600 rounded-lg">
                    <FileText size={20} />
                </div>
            </div>
            <p className="text-[10px] text-gray-400 mt-2">Commissions & Shipping</p>
         </Card>

         <Card className="p-5 border-0 shadow-sm bg-white">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-xs font-bold uppercase text-gray-400">Net Payout</p>
                    <h3 className="text-2xl font-black text-emerald-600 mt-1">{formatCurrency(netPayout)}</h3>
                </div>
                <div className="p-2 bg-emerald-50 text-emerald-600 rounded-lg">
                    <CheckCircle size={20} />
                </div>
            </div>
            <p className="text-[10px] text-gray-400 mt-2">Realized profit after fees</p>
         </Card>

         <Card className="p-5 border-0 shadow-sm bg-white">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-xs font-bold uppercase text-gray-400">Pending Orders</p>
                    <h3 className="text-2xl font-black text-orange-500 mt-1">{pendingOrders}</h3>
                </div>
                <div className="p-2 bg-orange-50 text-orange-600 rounded-lg">
                    <Package size={20} />
                </div>
            </div>
            <p className="text-[10px] text-gray-400 mt-2">Needs shipping/fulfillment</p>
         </Card>
      </div>

      <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
        <div className="relative w-full md:w-96">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Search invoice, order ID..." 
            className="w-full pl-11 pr-4 py-2.5 bg-white border border-gray-100 rounded-2xl outline-none focus:ring-2 focus:ring-sky-100 transition-all font-medium text-gray-600"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex bg-gray-100/50 p-1 rounded-xl w-full md:w-auto overflow-x-auto">
           {[
             { id: 'ALL', label: 'All', icon: null },
             { id: SalesChannel.IN_STORE, label: 'Store', icon: <Store size={14} /> },
             { id: SalesChannel.AMAZON, label: 'Amazon', icon: <ShoppingBag size={14} /> },
             { id: SalesChannel.FLIPKART, label: 'Flipkart', icon: <ShoppingBag size={14} /> },
             { id: SalesChannel.MEESHO, label: 'Meesho', icon: <Smartphone size={14} /> },
           ].map(tab => (
             <button
                key={tab.id}
                onClick={() => setChannelFilter(tab.id as any)}
                className={`px-4 py-2 rounded-lg text-xs font-bold flex items-center gap-2 transition-all whitespace-nowrap ${channelFilter === tab.id ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
             >
                {tab.icon} {tab.label}
             </button>
           ))}
        </div>
      </div>

      <Card className="overflow-hidden border-0 shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead>
              <tr className="bg-gray-50/50 border-b border-gray-100 text-gray-400">
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Source</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Order Details</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Customer</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Financials</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Status</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filteredSales.map(sale => {
                  const customer = customers.find(c => c.id === sale.customerId);
                  return (
                    <tr key={sale.id} className="hover:bg-gray-50 transition-colors group">
                    <td className="px-6 py-4">
                        <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-xl border text-[10px] font-bold uppercase tracking-wider ${getChannelStyle(sale.channel)}`}>
                            {getChannelIcon(sale.channel)}
                            {sale.channel}
                        </div>
                    </td>
                    <td className="px-6 py-4">
                        <div className="font-bold text-gray-800">{sale.invoiceNumber}</div>
                        {sale.externalOrderId && (
                            <div className="text-xs font-mono text-gray-400 mt-1 flex items-center gap-1">
                                <FileText size={10} /> Ref: {sale.externalOrderId}
                            </div>
                        )}
                        <div className="text-xs text-gray-500 mt-1 flex items-center gap-1">
                             <Calendar size={10} />
                             {new Date(sale.date).toLocaleDateString()}
                        </div>
                    </td>
                    <td className="px-6 py-4">
                         <div className="flex items-center gap-2">
                            <div className="w-8 h-8 rounded-full bg-gray-100 flex items-center justify-center text-gray-500">
                                <User size={14} />
                            </div>
                            <div>
                                <div className="font-bold text-gray-700 text-xs">{customer?.name || 'Unknown'}</div>
                                <div className="text-[10px] text-gray-400">{sale.items.length} Item(s)</div>
                            </div>
                         </div>
                    </td>
                    <td className="px-6 py-4">
                        <div className="flex flex-col">
                            <span className="font-black text-gray-800">{formatCurrency(sale.totalAmount)}</span>
                            {sale.marketplaceFees > 0 ? (
                                <span className="text-[10px] text-emerald-600 font-bold mt-0.5">
                                    Net: {formatCurrency(sale.netPayout)}
                                </span>
                            ) : (
                                <span className="text-[10px] text-gray-400 mt-0.5">Gross Sales</span>
                            )}
                        </div>
                    </td>
                    <td className="px-6 py-4">
                        {getStatusBadge(sale.orderStatus)}
                    </td>
                    <td className="px-6 py-4 text-right">
                        <select 
                            className="text-xs font-medium text-gray-600 border border-gray-200 rounded-lg p-1.5 bg-white outline-none focus:border-sky-300 focus:ring-2 focus:ring-sky-50 transition-all cursor-pointer hover:border-gray-300"
                            value={sale.orderStatus}
                            onChange={(e) => updateOrderStatus(sale.id, e.target.value as OrderStatus)}
                            disabled={sale.orderStatus === OrderStatus.COMPLETED || sale.orderStatus === OrderStatus.CANCELLED}
                        >
                            {Object.values(OrderStatus).map(status => (
                                <option key={status} value={status}>{status.replace(/_/g, ' ')}</option>
                            ))}
                        </select>
                    </td>
                    </tr>
                  );
              })}
            </tbody>
          </table>
          {filteredSales.length === 0 && (
            <div className="py-20 text-center text-gray-400 italic">No sales found matching your criteria.</div>
          )}
        </div>
      </Card>

      {/* Record Sale Modal */}
      <Modal isOpen={isAddModalOpen} onClose={() => setIsAddModalOpen(false)} title="Record New Sale">
        <form onSubmit={handleCreateSale} className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className={`col-span-2 p-4 text-xs rounded-2xl flex items-start gap-3 border transition-colors ${selectedChannel === SalesChannel.IN_STORE ? 'bg-gray-50 border-gray-100 text-gray-600' : 'bg-sky-50 border-sky-100 text-sky-800'}`}>
             <AlertCircle size={16} className="mt-0.5 shrink-0" />
             <div>
                 <p className="font-bold mb-1">
                    {selectedChannel === SalesChannel.IN_STORE ? 'In-Store Transaction' : 'Marketplace Order'}
                 </p>
                 <p>
                    {selectedChannel === SalesChannel.IN_STORE 
                      ? 'Stock is deducted immediately. Payment is marked as collected.' 
                      : 'Stock is deducted. Fees are recorded for Net Payout calculation. Payment status is pending payout.'}
                 </p>
             </div>
          </div>

          <div className="space-y-1">
             <label className="text-xs font-bold uppercase text-gray-400">Sales Channel</label>
             <select 
                name="channel" 
                className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium"
                value={selectedChannel}
                onChange={(e) => setSelectedChannel(e.target.value as SalesChannel)}
             >
                {Object.values(SalesChannel).map(c => <option key={c} value={c}>{c}</option>)}
             </select>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Product</label>
            <select 
                name="productId" 
                required 
                className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium"
                onChange={(e) => {
                    const product = products.find(p => p.id === e.target.value);
                    if (product) setSelectedProductPrice(product.sellingPrice);
                }}
            >
              <option value="">Select Item...</option>
              {products.map(p => <option key={p.id} value={p.id} disabled={p.saleStock === 0}>{p.name} (Qty: {p.saleStock})</option>)}
            </select>
          </div>

          {selectedChannel !== SalesChannel.IN_STORE && (
            <div className="space-y-1">
                <label className="text-xs font-bold uppercase text-gray-400">External Order ID</label>
                <input name="externalOrderId" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="e.g. #404-1234567" />
            </div>
          )}

          {selectedChannel === SalesChannel.IN_STORE && (
            <div className="space-y-1">
                <label className="text-xs font-bold uppercase text-gray-400">Customer</label>
                <select name="customerId" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium">
                <option value="">Guest (Walk-in)</option>
                {customers.filter(c => !c.id.startsWith('C_')).map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
            </div>
          )}

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Quantity</label>
            <input 
                name="quantity" 
                type="number" 
                min="1" 
                value={quantity}
                onChange={(e) => setQuantity(Number(e.target.value))}
                required 
                className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" 
            />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Unit Price</label>
            <input 
                name="unitPrice" 
                type="number" 
                value={selectedProductPrice}
                onChange={(e) => setSelectedProductPrice(Number(e.target.value))}
                className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" 
            />
          </div>

          {selectedChannel !== SalesChannel.IN_STORE && (
            <div className="space-y-1">
                <label className="text-xs font-bold uppercase text-gray-400">Marketplace Fees</label>
                <input 
                    name="marketplaceFees" 
                    type="number" 
                    value={fees}
                    onChange={(e) => setFees(Number(e.target.value))}
                    className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" 
                    placeholder="Commissions + Shipping" 
                />
            </div>
          )}

          <div className="space-y-1">
             <label className="text-xs font-bold uppercase text-gray-400">Payment Method</label>
             <select name="paymentMethod" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium">
                {Object.values(PaymentMethod).map(m => <option key={m} value={m}>{m}</option>)}
             </select>
          </div>

          {/* Financial Summary Preview */}
          <div className="col-span-1 md:col-span-2 bg-gray-50 rounded-2xl p-4 border border-gray-100 mt-2">
             <div className="flex justify-between items-center mb-2">
                <span className="text-sm font-medium text-gray-500">Total Sale Amount:</span>
                <span className="text-sm font-bold text-gray-800">{formatCurrency(estimatedTotal)}</span>
             </div>
             {selectedChannel !== SalesChannel.IN_STORE && (
                 <>
                    <div className="flex justify-between items-center mb-2 text-xs">
                        <span className="font-medium text-gray-400">Less: Marketplace Fees</span>
                        <span className="font-bold text-red-400">- {formatCurrency(fees)}</span>
                    </div>
                    <div className="flex justify-between items-center pt-2 border-t border-gray-200">
                        <span className="text-sm font-bold text-gray-700 flex items-center gap-2"><Calculator size={14}/> Est. Net Payout:</span>
                        <span className="text-base font-black text-emerald-600">{formatCurrency(estimatedNet)}</span>
                    </div>
                 </>
             )}
          </div>

          <div className="col-span-1 md:col-span-2 flex gap-3 pt-4">
            <Button variant="ghost" onClick={() => setIsAddModalOpen(false)} className="flex-1">Cancel</Button>
            <Button type="submit" className="flex-1">Record Sale</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Sales;

import React, { useState, useMemo } from 'react';
import { useApp } from '../store/AppContext';
import { Card, Button, Modal } from '../components/Shared';
import { 
  Plus, 
  Search, 
  ShoppingBag, 
  Truck, 
  Smartphone, 
  Store, 
  Globe, 
  ArrowUpRight,
  Filter,
  IndianRupee,
  Package,
  CheckCircle,
  XCircle,
  Clock,
  User,
  Calendar,
  FileText,
  AlertCircle,
  Calculator
} from 'lucide-react';
import { formatCurrency } from '../utils/helpers';
import { SalesChannel, PaymentMethod, PaymentStatus, OrderStatus } from '../types';

const Sales: React.FC = () => {
  const { sales, products, customers, addSale, updateOrderStatus } = useApp();
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [channelFilter, setChannelFilter] = useState<'ALL' | SalesChannel>('ALL');

  // Form State
  const [selectedChannel, setSelectedChannel] = useState<SalesChannel>(SalesChannel.IN_STORE);
  const [selectedProductPrice, setSelectedProductPrice] = useState<number>(0);
  const [quantity, setQuantity] = useState<number>(1);
  const [fees, setFees] = useState<number>(0);

  const filteredSales = sales.filter(s => {
    const matchesSearch = s.invoiceNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          s.externalOrderId?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesChannel = channelFilter === 'ALL' || s.channel === channelFilter;
    return matchesSearch && matchesChannel;
  });

  // Calculate Metrics
  const totalRevenue = filteredSales.reduce((acc, s) => acc + s.totalAmount, 0);
  const totalFees = filteredSales.reduce((acc, s) => acc + s.marketplaceFees, 0);
  const netPayout = filteredSales.reduce((acc, s) => acc + s.netPayout, 0);
  const pendingOrders = filteredSales.filter(s => s.orderStatus === OrderStatus.PENDING || s.orderStatus === OrderStatus.READY_TO_SHIP).length;

  // Live Calculation for Modal
  const estimatedTotal = selectedProductPrice * quantity;
  const estimatedNet = estimatedTotal - fees;

  const handleCreateSale = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const productId = formData.get('productId') as string;
    const qty = Number(formData.get('quantity'));
    const product = products.find(p => p.id === productId);
    const channel = selectedChannel; // Use state

    // Auto-select dummy customers for marketplaces if not in store
    let customerId = formData.get('customerId') as string;
    if (channel === SalesChannel.AMAZON) customerId = 'C_AMZ';
    if (channel === SalesChannel.FLIPKART) customerId = 'C_FK';
    if (channel === SalesChannel.MEESHO) customerId = 'C_MEE';
    if (channel === SalesChannel.WEBSITE) customerId = 'C_AMZ'; // Fallback for website if no specific cust

    if (product) {
      const unitPrice = Number(formData.get('unitPrice')) || product.sellingPrice;
      const total = unitPrice * qty;
      const marketplaceFees = Number(formData.get('marketplaceFees')) || 0;

      addSale({
        channel: channel,
        externalOrderId: formData.get('externalOrderId') as string,
        customerId: customerId,
        items: [{
          productId: product.id,
          name: product.name,
          quantity: qty,
          unitPrice: unitPrice,
          taxAmount: 0,
          total: total
        }],
        totalAmount: total,
        marketplaceFees: marketplaceFees,
        taxTotal: 0,
        discount: 0,
        paidAmount: channel === SalesChannel.IN_STORE ? total : 0, // In store is paid immediately usually
        paymentStatus: channel === SalesChannel.IN_STORE ? PaymentStatus.PAID : PaymentStatus.UNPAID,
        paymentMethod: formData.get('paymentMethod') as PaymentMethod,
        orderStatus: channel === SalesChannel.IN_STORE ? OrderStatus.COMPLETED : OrderStatus.PENDING,
      });
      setIsAddModalOpen(false);
      // Reset form state
      setSelectedChannel(SalesChannel.IN_STORE);
      setFees(0);
      setQuantity(1);
      setSelectedProductPrice(0);
    }
  };

  const openAddModal = () => {
    setSelectedChannel(SalesChannel.IN_STORE);
    setFees(0);
    setQuantity(1);
    setSelectedProductPrice(0);
    setIsAddModalOpen(true);
  }

  const getChannelIcon = (channel: SalesChannel) => {
    switch (channel) {
      case SalesChannel.AMAZON: return <ShoppingBag size={14} />;
      case SalesChannel.FLIPKART: return <ShoppingBag size={14} />;
      case SalesChannel.MEESHO: return <Smartphone size={14} />;
      case SalesChannel.WEBSITE: return <Globe size={14} />;
      default: return <Store size={14} />;
    }
  };

  const getChannelStyle = (channel: SalesChannel) => {
    switch (channel) {
      case SalesChannel.AMAZON: return 'bg-orange-50 text-orange-700 border-orange-100';
      case SalesChannel.FLIPKART: return 'bg-blue-50 text-blue-700 border-blue-100';
      case SalesChannel.MEESHO: return 'bg-pink-50 text-pink-700 border-pink-100';
      default: return 'bg-gray-50 text-gray-700 border-gray-100';
    }
  };

  const getStatusBadge = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.COMPLETED: 
      case OrderStatus.DELIVERED:
