        <div className="lg:col-span-2 space-y-6">
          {/* Revenue Chart */}
          <Card className="p-6 border-0 shadow-sm">
            <div className="flex items-center justify-between mb-6">
              <h3 className="font-bold text-gray-800 flex items-center gap-2">
                <Activity size={18} className="text-sky-500" /> Revenue Analytics
              </h3>
              <div className="flex gap-4">
                 <div className="flex items-center gap-1 text-xs font-bold text-gray-500">
                    <span className="w-2 h-2 rounded-full bg-sky-500"></span> Sales
                 </div>
                 <div className="flex items-center gap-1 text-xs font-bold text-gray-500">
                    <span className="w-2 h-2 rounded-full bg-yellow-400"></span> Rentals
                 </div>
              </div>
            </div>
            <div className="h-[280px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={chartData}>
                  <defs>
                    <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#0ea5e9" stopOpacity={0.1}/>
                      <stop offset="95%" stopColor="#0ea5e9" stopOpacity={0}/>
                    </linearGradient>
                    <linearGradient id="colorRentals" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#facc15" stopOpacity={0.1}/>
                      <stop offset="95%" stopColor="#facc15" stopOpacity={0}/>
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f3f4f6" />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#9ca3af', fontSize: 12}} dy={10} />
                  <YAxis axisLine={false} tickLine={false} tick={{fill: '#9ca3af', fontSize: 12}} />
                  <Tooltip 
                    contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}
                    labelStyle={{color: '#6b7280', marginBottom: '0.5rem'}}
                  />
                  <Area type="monotone" dataKey="sales" stroke="#0ea5e9" fillOpacity={1} fill="url(#colorSales)" strokeWidth={3} />
                  <Area type="monotone" dataKey="rentals" stroke="#facc15" fillOpacity={1} fill="url(#colorRentals)" strokeWidth={3} />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </Card>

          {/* Recent Activity */}
          <Card className="p-6 border-0 shadow-sm">
             <h3 className="font-bold text-gray-800 mb-4 flex items-center gap-2">
                <Clock size={18} className="text-gray-400" /> Recent Activity
             </h3>
             <div className="space-y-4">
                {recentActivity.map((item, index) => (
                  <div key={index} className="flex items-center justify-between p-3 hover:bg-gray-50 rounded-xl transition-colors border border-transparent hover:border-gray-100 group">
                    <div className="flex items-center gap-4">
                       <div className={`w-10 h-10 rounded-full flex items-center justify-center ${item.type === 'SALE' ? 'bg-emerald-50 text-emerald-600' : 'bg-sky-50 text-sky-600'}`}>
                          {item.type === 'SALE' ? <ShoppingBag size={18} /> : <RefreshCcw size={18} />}
                       </div>
                       <div>
                          <p className="text-sm font-bold text-gray-800">
                             {item.type === 'SALE' ? 'New Sale' : 'Rental Booking'}
                             <span className="text-gray-400 font-normal text-xs ml-2">#{item.ref}</span>
                          </p>
                          <p className="text-xs text-gray-500">{format(parseISO(item.date), 'dd MMM, hh:mm a')}</p>
                       </div>
                    </div>
                    <div className="text-right">
                       <p className="text-sm font-bold text-gray-800">{formatCurrency(item.amount)}</p>
                       <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold uppercase ${
                          item.status === 'COMPLETED' || item.status === 'DELIVERED' ? 'bg-green-100 text-green-700' : 
                          item.status === 'ACTIVE' ? 'bg-sky-100 text-sky-700' : 'bg-gray-100 text-gray-600'
                       }`}>
                          {item.status}
                       </span>
                    </div>
                  </div>
                ))}
                {recentActivity.length === 0 && (
                   <p className="text-center text-gray-400 text-sm py-4">No recent activity found.</p>
                )}
             </div>
          </Card>
        </div>

        {/* Right Column: Alerts & Distribution */}
        <div className="space-y-6">
           {/* Low Stock Alert */}
           <Card className={`p-6 border-0 shadow-sm ${lowStockItems.length > 0 ? 'bg-pink-50 border-pink-100' : 'bg-white'}`}>
              <div className="flex items-center justify-between mb-4">
                 <h3 className={`font-bold flex items-center gap-2 ${lowStockItems.length > 0 ? 'text-pink-700' : 'text-gray-800'}`}>
                    <AlertTriangle size={18} className={lowStockItems.length > 0 ? 'text-pink-600' : 'text-gray-400'} />
                    Sales Inventory
                 </h3>
                 {lowStockItems.length > 0 && <span className="bg-white text-pink-600 px-2 py-1 rounded-lg text-xs font-black shadow-sm">{lowStockItems.length} Alerts</span>}
              </div>

              {lowStockItems.length > 0 ? (
                <div className="space-y-3">
                   {lowStockItems.slice(0, 3).map(p => (
                      <div key={p.id} className="bg-white/60 p-3 rounded-xl flex items-center justify-between">
                         <div className="flex items-center gap-3">
                            <div className="w-8 h-8 rounded-lg bg-pink-100 text-pink-600 flex items-center justify-center font-bold text-xs">
                               {p.saleStock}
                            </div>
                            <div className="min-w-0">
                               <p className="text-xs font-bold text-gray-800 truncate w-24 sm:w-32">{p.name}</p>
                               <p className="text-[10px] text-pink-600">Below limit ({p.minStockAlert})</p>
                            </div>
                         </div>
                      </div>
                   ))}
                   {lowStockItems.length > 3 && (
                      <p className="text-center text-xs text-pink-600 font-bold mt-2">+ {lowStockItems.length - 3} more items</p>
                   )}
                </div>
              ) : (
                <div className="text-center py-6">
                   <div className="w-12 h-12 bg-green-50 text-green-500 rounded-full flex items-center justify-center mx-auto mb-2">
                      <Package size={20} />
                   </div>
                   <p className="text-sm font-bold text-gray-600">Stock Healthy</p>
                   <p className="text-xs text-gray-400">Sales items are above minimum levels.</p>
                </div>
              )}
           </Card>

           {/* Channel Distribution */}
           <Card className="p-6 border-0 shadow-sm flex flex-col h-[320px]">
              <h3 className="font-bold text-gray-800 mb-2 flex items-center gap-2">
                 <Store size={18} className="text-gray-400" /> Sales Channel
              </h3>
              <div className="flex-1 w-full relative">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={channelData}
                      cx="50%"
                      cy="50%"
                      innerRadius={50}
                      outerRadius={80}
                      paddingAngle={5}
                      dataKey="value"
                    >
                      {channelData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" height={36} iconType="circle" />
                  </PieChart>
                </ResponsiveContainer>
              </div>
           </Card>

           <div className="bg-gradient-to-br from-indigo-500 to-indigo-700 rounded-3xl p-6 text-white shadow-lg shadow-indigo-200">
              <h3 className="font-bold text-lg mb-1">Stock Tip</h3>
              <p className="text-indigo-100 text-sm mb-4">
                 Items can be moved between Sales and Rental pools via the "Update Stock" action in Inventory.
              </p>
              <button onClick={() => window.location.hash = 'inventory'} className="bg-white/20 hover:bg-white/30 transition-colors text-white text-xs font-bold px-4 py-2 rounded-xl flex items-center gap-2">
                 Manage Stock <ArrowRight size={14} />
              </button>
           </div>
        </div>

      </div>
    </div>
  );
};

