import React, { useState, useMemo } from 'react';
import { useApp } from '../store/AppContext';
import { Card, Button, Modal } from '../components/Shared';
import { 
  Plus, 
  Search, 
  Calendar, 
  AlertCircle, 
  CheckCircle, 
  Clock, 
  User,
  Box,
  ArrowRight
} from 'lucide-react';
import { formatCurrency, getStatusColor, calculateRentalTotal, calculateLateFee } from '../utils/helpers';
import { PaymentStatus, RentalStatus } from '../types';
import { differenceInDays, parseISO, isSameDay, isAfter, isBefore } from 'date-fns';

const Rentals: React.FC = () => {
  const { rentals, products, customers, addRental, returnRental } = useApp();
  const [isNewRentalModalOpen, setIsNewRentalModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeTab, setActiveTab] = useState<'ACTIVE' | 'OVERDUE' | 'RETURNED'>('ACTIVE');

  const handleCreateRental = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const productId = formData.get('productId') as string;
    const qty = Number(formData.get('quantity'));
    const start = formData.get('startDate') as string;
    const end = formData.get('expectedReturnDate') as string;
    const product = products.find(p => p.id === productId);

    if (product) {
      const total = calculateRentalTotal(start, end, product.rentalPrice, qty);
      addRental({
        customerId: formData.get('customerId') as string,
        productId,
        quantity: qty,
        startDate: start,
        expectedReturnDate: end,
        dailyRate: product.rentalPrice,
        securityDeposit: Number(formData.get('securityDeposit')),
        totalRentAmount: total,
        paidAmount: Number(formData.get('paidAmount')),
        paymentStatus: Number(formData.get('paidAmount')) >= total ? PaymentStatus.PAID : PaymentStatus.PARTIAL,
      });
      setIsNewRentalModalOpen(false);
    }
  };

  const handleReturn = (id: string) => {
    const rental = rentals.find(r => r.id === id);
    if (rental) {
      const lateFee = calculateLateFee(rental.expectedReturnDate, undefined, rental.dailyRate, rental.quantity);
      if (confirm(`Process return for this rental? Late fees calculated: ${formatCurrency(lateFee)}`)) {
        returnRental(id, lateFee);
      }
    }
  };

  const filteredRentals = rentals.filter(r => {
    const cust = customers.find(c => c.id === r.customerId);
    const prod = products.find(p => p.id === r.productId);
    const matchesSearch = (
      cust?.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      prod?.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      r.invoiceNumber.toLowerCase().includes(searchTerm.toLowerCase())
    );

    if (activeTab === 'ACTIVE') return matchesSearch && r.status === 'ACTIVE' && new Date(r.expectedReturnDate) >= new Date();
    if (activeTab === 'OVERDUE') return matchesSearch && r.status === 'ACTIVE' && new Date(r.expectedReturnDate) < new Date();
    if (activeTab === 'RETURNED') return matchesSearch && r.status === 'RETURNED';
    return matchesSearch;
  });

  const getProgress = (start: string, end: string) => {
    const startDate = parseISO(start).getTime();
    const endDate = parseISO(end).getTime();
    const now = new Date().getTime();
    const totalDuration = endDate - startDate;
    const elapsed = now - startDate;
    const percentage = Math.max(0, Math.min(100, (elapsed / totalDuration) * 100));
    return percentage;
  };

  const activeCount = rentals.filter(r => r.status === 'ACTIVE').length;
  const overdueCount = rentals.filter(r => r.status === 'ACTIVE' && new Date(r.expectedReturnDate) < new Date()).length;
  const returnsDueToday = rentals.filter(r => r.status === 'ACTIVE' && isSameDay(parseISO(r.expectedReturnDate), new Date())).length;
  const totalRevenue = rentals.reduce((acc, r) => acc + r.totalRentAmount, 0);

  return (
    <div className="space-y-6 animate-in fade-in duration-300 pb-10">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Rentals</h1>
          <p className="text-sm font-medium text-gray-400">Track bookings, returns & deposits</p>
        </div>
        <Button onClick={() => setIsNewRentalModalOpen(true)} className="flex items-center gap-2 shadow-sky-200">
          <Plus size={20} /> Create Rental
        </Button>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card className="p-5 border-0 shadow-sm bg-white flex items-center justify-between">
          <div>
            <p className="text-xs font-bold uppercase text-gray-400 tracking-wider">Active</p>
            <h3 className="text-3xl font-black text-sky-600 mt-1">{activeCount}</h3>
          </div>
          <div className="p-3 bg-sky-50 text-sky-500 rounded-xl">
              <Calendar size={20} />
          </div>
        </Card>

        <Card className={`p-5 border-0 shadow-sm flex items-center justify-between ${overdueCount > 0 ? 'bg-pink-50 border-pink-100' : 'bg-white'}`}>
          <div>
            <p className={`text-xs font-bold uppercase tracking-wider ${overdueCount > 0 ? 'text-pink-600' : 'text-gray-400'}`}>Overdue</p>
            <h3 className={`text-3xl font-black mt-1 ${overdueCount > 0 ? 'text-pink-600' : 'text-gray-800'}`}>{overdueCount}</h3>
          </div>
          <div className={`p-3 rounded-xl ${overdueCount > 0 ? 'bg-white text-pink-500' : 'bg-gray-50 text-gray-400'}`}>
              <AlertCircle size={20} />
          </div>
        </Card>

        <Card className={`p-5 border-0 shadow-sm flex items-center justify-between ${returnsDueToday > 0 ? 'bg-orange-50 border-orange-100' : 'bg-white'}`}>
          <div>
            <p className={`text-xs font-bold uppercase tracking-wider ${returnsDueToday > 0 ? 'text-orange-600' : 'text-gray-400'}`}>Due Today</p>
            <h3 className={`text-3xl font-black mt-1 ${returnsDueToday > 0 ? 'text-orange-600' : 'text-gray-800'}`}>{returnsDueToday}</h3>
          </div>
          <div className={`p-3 rounded-xl ${returnsDueToday > 0 ? 'bg-white text-orange-500' : 'bg-gray-50 text-gray-400'}`}>
              <Clock size={20} />
          </div>
        </Card>

        <Card className="p-5 border-0 shadow-sm bg-white flex items-center justify-between">
          <div>
            <p className="text-xs font-bold uppercase text-gray-400 tracking-wider">Revenue</p>
            <h3 className="text-2xl font-black text-emerald-600 mt-1">{formatCurrency(totalRevenue)}</h3>
          </div>
          <div className="p-3 bg-emerald-50 text-emerald-500 rounded-xl">
              <CheckCircle size={20} />
          </div>
        </Card>
      </div>

      <div className="flex flex-col gap-4">
        {/* Navigation Tabs */}
        <div className="flex items-center justify-between">
             <div className="flex bg-gray-100/50 p-1 rounded-xl">
               {(['ACTIVE', 'OVERDUE', 'RETURNED'] as const).map(tab => (
                 <button
                    key={tab}
                    onClick={() => setActiveTab(tab)}
                    className={`px-5 py-2.5 rounded-lg text-xs font-bold transition-all ${activeTab === tab ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                 >
                    {tab.charAt(0) + tab.slice(1).toLowerCase()}
                 </button>
               ))}
            </div>
             <div className="relative hidden md:block w-72">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                <input 
                  type="text" 
                  placeholder="Search invoice, customer..." 
                  className="w-full pl-10 pr-4 py-2 bg-white border border-gray-100 rounded-xl outline-none focus:ring-2 focus:ring-sky-100 transition-all font-medium text-sm text-gray-600"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
            </div>
        </div>

        <Card className="overflow-hidden border-0 shadow-sm">
            <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
                <thead>
                <tr className="bg-gray-50/50 border-b border-gray-100 text-gray-400">
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Order Info</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Product</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Timeline</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Payment</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Actions</th>
                </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                {filteredRentals.map(rental => {
                    const customer = customers.find(c => c.id === rental.customerId);
                    const product = products.find(p => p.id === rental.productId);
                    const progress = getProgress(rental.startDate, rental.expectedReturnDate);

                    return (
                    <tr key={rental.id} className="hover:bg-gray-50 transition-colors">
                        <td className="px-6 py-4">
                            <div className="font-bold text-gray-800">{rental.invoiceNumber}</div>
                            <div className="flex items-center gap-1.5 mt-1">
                                <User size={12} className="text-gray-400" />
                                <span className="text-xs text-gray-500 font-medium">{customer?.name}</span>
                            </div>
                        </td>
                        <td className="px-6 py-4">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-indigo-50 text-indigo-500 rounded-lg flex items-center justify-center">
                                    <Box size={18} />
                                </div>
                                <div>
                                    <div className="font-bold text-gray-800">{product?.name}</div>
                                    <div className="text-xs text-gray-400">Qty: {rental.quantity}</div>
                                </div>
                            </div>
                        </td>
                        <td className="px-6 py-4 min-w-[200px]">
                            <div className="flex justify-between text-xs text-gray-500 mb-1.5 font-medium">
                                <span>{new Date(rental.startDate).toLocaleDateString(undefined, {month:'short', day:'numeric'})}</span>
                                <span className={activeTab === 'OVERDUE' ? 'text-pink-600 font-bold' : ''}>
                                    {new Date(rental.expectedReturnDate).toLocaleDateString(undefined, {month:'short', day:'numeric'})}
                                </span>
                            </div>
                            <div className="w-full h-1.5 bg-gray-100 rounded-full overflow-hidden">
                                <div 
                                    className={`h-full rounded-full transition-all duration-500 ${
                                        rental.status === 'RETURNED' ? 'bg-green-400' :
                                        activeTab === 'OVERDUE' ? 'bg-pink-500' : 
                                        progress > 80 ? 'bg-orange-400' : 'bg-sky-400'
                                    }`} 
                                    style={{ width: rental.status === 'RETURNED' ? '100%' : `${progress}%` }}
                                ></div>
                            </div>
                            {rental.status === 'ACTIVE' && (
                                <div className="flex justify-between mt-1">
                                    <span className="text-[10px] text-gray-400">
                                        {activeTab === 'OVERDUE' ? 'Late Return' : `${Math.ceil((100 - progress)/100 * differenceInDays(parseISO(rental.expectedReturnDate), parseISO(rental.startDate)))} days left`}
                                    </span>
                                </div>
                            )}
                        </td>
                        <td className="px-6 py-4">
                            <div className="font-bold text-gray-800">{formatCurrency(rental.totalRentAmount)}</div>
                            <div className={`text-[10px] font-bold uppercase mt-1 inline-flex px-1.5 py-0.5 rounded ${rental.paymentStatus === 'PAID' ? 'bg-green-100 text-green-700' : 'bg-orange-100 text-orange-700'}`}>
                                {rental.paymentStatus}
                            </div>
                        </td>
                        <td className="px-6 py-4 text-right">
                        {rental.status === 'ACTIVE' && (
                            <Button variant="secondary" onClick={() => handleReturn(rental.id)} className="text-xs h-8 px-3">
                                Check In
                            </Button>
                        )}
                        {rental.status === 'RETURNED' && (
                            <span className="text-xs font-bold text-gray-300">Closed</span>
                        )}
                        </td>
                    </tr>
                    );
                })}
                </tbody>
            </table>
            {filteredRentals.length === 0 && (
                <div className="py-20 text-center text-gray-400 italic">No {activeTab.toLowerCase()} rentals found.</div>
            )}
            </div>
        </Card>
      </div>

      <Modal isOpen={isNewRentalModalOpen} onClose={() => setIsNewRentalModalOpen(false)} title="Create New Rental">
        <form onSubmit={handleCreateRental} className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="col-span-2 p-4 bg-sky-50 text-sky-800 text-xs rounded-2xl flex items-start gap-3 border border-sky-100">
             <AlertCircle size={16} className="mt-0.5 shrink-0" />
             <div>
                 <p className="font-bold mb-1">Rental Pool</p>
                 <p>Items will be deducted from the <strong>Rental Stock</strong>. Ensure items are available in the rental pool before booking.</p>
             </div>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Customer</label>
            <select name="customerId" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium">
              {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Product</label>
            <select name="productId" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium">
              {products.map(p => <option key={p.id} value={p.id} disabled={p.rentalStock === 0}>{p.name} ({formatCurrency(p.rentalPrice)}/day) - Avail: {p.rentalStock}</option>)}
            </select>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Quantity</label>
            <input name="quantity" type="number" defaultValue="1" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Security Deposit</label>
            <input name="securityDeposit" type="number" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="Refundable amount" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Start Date</label>
            <input name="startDate" type="date" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" defaultValue={new Date().toISOString().split('T')[0]} />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Expected Return</label>
            <input name="expectedReturnDate" type="date" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" />
          </div>
          <div className="col-span-2 space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Payment Received</label>
            <input name="paidAmount" type="number" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="Total payment received" />
          </div>
          <div className="col-span-2 flex gap-3 pt-4">
            <Button variant="ghost" onClick={() => setIsNewRentalModalOpen(false)} className="flex-1">Cancel</Button>
            <Button type="submit" className="flex-1">Issue Invoice</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Rentals;

import React, { useState, useMemo } from 'react';
import { useApp } from '../store/AppContext';
import { Card, Button, Modal } from '../components/Shared';
import { 
  Search, 
  Plus, 
  Phone, 
  Mail, 
  MapPin, 
  ArrowLeft, 
  ArrowRight,
  FileText, 
  RefreshCcw, 
  ShoppingBag,
  TrendingUp,
  Calendar,
  Banknote,
  IndianRupee,
  User,
  Star
} from 'lucide-react';
import { formatCurrency, getStatusColor } from '../utils/helpers';
import { Sale, Rental, Customer, PaymentStatus } from '../types';

const Customers: React.FC = () => {
  const { customers, addCustomer, sales, rentals, products, addPaymentToSale } = useApp();
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);
  const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null);
  const [selectedSaleForPayment, setSelectedSaleForPayment] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [transactionFilter, setTransactionFilter] = useState<'ALL' | 'SALE' | 'RENTAL'>('ALL');

  // Derived state for the selected customer's ledger
  const selectedCustomer = useMemo(() => 
    customers.find(c => c.id === selectedCustomerId), 
  [customers, selectedCustomerId]);

  const customerHistory = useMemo(() => {
    if (!selectedCustomerId) return { transactions: [], stats: { totalSpent: 0, activeRentals: 0, totalOrders: 0 } };

    const customerSales = sales.filter(s => s.customerId === selectedCustomerId).map(s => ({
      ...s,
      type: 'SALE' as const,
      sortDate: new Date(s.date)
    }));

    const customerRentals = rentals.filter(r => r.customerId === selectedCustomerId).map(r => ({
      ...r,
      type: 'RENTAL' as const,
      sortDate: new Date(r.date)
    }));

    // Merge and sort by date descending
    const allTransactions = [...customerSales, ...customerRentals].sort((a, b) => 
      b.sortDate.getTime() - a.sortDate.getTime()
    );

    const totalSpent = allTransactions.reduce((acc, t) => {
      if (t.type === 'SALE') return acc + (t as Sale).totalAmount;
      if (t.type === 'RENTAL') return acc + (t as Rental).totalRentAmount;
      return acc;
    }, 0);

    const activeRentals = customerRentals.filter(r => r.status === 'ACTIVE').length;

    // Apply Filter
    const visibleTransactions = allTransactions.filter(t => {
      if (transactionFilter === 'ALL') return true;
      return t.type === transactionFilter;
    });

    return {
      transactions: visibleTransactions,
      stats: {
        totalSpent,
        activeRentals,
        totalOrders: allTransactions.length // Lifetime total orders
      }
    };
  }, [sales, rentals, selectedCustomerId, transactionFilter]);

  const handleAddCustomer = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    addCustomer({
      name: formData.get('name') as string,
      phone: formData.get('phone') as string,
      email: formData.get('email') as string,
      address: formData.get('address') as string,
      gstin: formData.get('gstin') as string,
    });
    setIsAddModalOpen(false);
  };

  const handleRecordPayment = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const amount = Number(formData.get('amount'));
    if (selectedSaleForPayment && amount > 0) {
      addPaymentToSale(selectedSaleForPayment, amount);
      setIsPaymentModalOpen(false);
      setSelectedSaleForPayment(null);
    }
  };

  const openPaymentModal = (saleId: string) => {
    setSelectedSaleForPayment(saleId);
    setIsPaymentModalOpen(true);
  };

  // Helper to find selected sale for the modal
  const activePaymentSale = sales.find(s => s.id === selectedSaleForPayment);
  const activePaymentBalance = activePaymentSale ? activePaymentSale.totalAmount - activePaymentSale.paidAmount : 0;

  // Filtered customers with computed stats for the list view
  const filteredCustomers = useMemo(() => {
     return customers.filter(c => 
        c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        c.phone.includes(searchTerm)
      ).map(c => {
        // Compute stats on the fly for the list
        const cSales = sales.filter(s => s.customerId === c.id);
        const cRentals = rentals.filter(r => r.customerId === c.id);

        const totalSpent = cSales.reduce((acc, s) => acc + s.totalAmount, 0) + 
                           cRentals.reduce((acc, r) => acc + r.totalRentAmount, 0);

        const balance = cSales.reduce((acc, s) => acc + (s.totalAmount - s.paidAmount), 0) +
                        cRentals.reduce((acc, r) => acc + (r.totalRentAmount - r.paidAmount), 0);

        // Find last activity
        const lastSale = cSales[cSales.length - 1]?.date;
        const lastRental = cRentals[cRentals.length - 1]?.date;
        const lastActive = [lastSale, lastRental].filter(Boolean).sort().pop();

        return { ...c, totalSpent, balance, lastActive };
      }).sort((a, b) => b.totalSpent - a.totalSpent); // Sort by highest spender
  }, [customers, sales, rentals, searchTerm]);

  const getVipBadge = (spent: number) => {
      if (spent > 50000) return <span className="flex items-center gap-1 bg-yellow-100 text-yellow-700 text-[10px] font-black px-2 py-0.5 rounded-full border border-yellow-200"><Star size={10} fill="currentColor" /> VIP GOLD</span>;
      if (spent > 10000) return <span className="flex items-center gap-1 bg-gray-100 text-gray-600 text-[10px] font-black px-2 py-0.5 rounded-full border border-gray-200"><Star size={10} /> SILVER</span>;
      return null;
  }

  // -- RENDER: Customer Ledger (Detail View) --
  if (selectedCustomer) {
    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300 pb-10">
        <div className="flex items-center gap-4">
          <button 
            onClick={() => setSelectedCustomerId(null)}
            className="p-2 hover:bg-white rounded-full transition-colors border border-transparent hover:border-gray-200 text-gray-500"
          >
            <ArrowLeft size={24} />
          </button>
          <div>
            <h1 className="text-2xl font-black text-gray-800">{selectedCustomer.name}</h1>
            <p className="text-sm text-gray-400">Customer Ledger & History</p>
          </div>
        </div>

        {/* Customer Profile Card */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <Card className="p-6 col-span-1 border-0 shadow-sm">
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-6">Contact Details</h3>
            <div className="space-y-6">
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 rounded-xl bg-sky-50 flex items-center justify-center text-sky-500">
                  <Phone size={18} />
                </div>
                <div className="text-sm font-medium text-gray-700">{selectedCustomer.phone}</div>
              </div>
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 rounded-xl bg-sky-50 flex items-center justify-center text-sky-500">
                  <Mail size={18} />
                </div>
                <div className="text-sm font-medium text-gray-700">{selectedCustomer.email}</div>
              </div>
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 rounded-xl bg-sky-50 flex items-center justify-center text-sky-500">
                  <MapPin size={18} />
                </div>
                <div className="text-sm font-medium text-gray-700">{selectedCustomer.address}</div>
              </div>
              {selectedCustomer.gstin && (
                <div className="pt-4 border-t border-gray-100">
                   <p className="text-[10px] text-gray-400 uppercase font-bold tracking-wider">GSTIN / Tax ID</p>
                   <p className="font-mono text-sm text-gray-700 mt-1">{selectedCustomer.gstin}</p>
                </div>
              )}
            </div>
          </Card>

          <Card className="p-6 col-span-1 lg:col-span-2 border-0 shadow-sm">
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-6">Overview</h3>
            <div className="grid grid-cols-3 gap-6">
              <div className="p-5 bg-yellow-50 rounded-2xl border border-yellow-100 relative overflow-hidden">
                <div className="flex items-center gap-2 mb-2 text-yellow-600 relative z-10">
                  <TrendingUp size={18} />
                  <span className="text-[10px] font-black uppercase tracking-wider">Lifetime Value</span>
                </div>
                <p className="text-2xl font-black text-gray-800 relative z-10">{formatCurrency(customerHistory.stats.totalSpent)}</p>
                {/* Decorative blob */}
                <div className="absolute -right-4 -bottom-4 w-16 h-16 bg-yellow-100 rounded-full z-0"></div>
              </div>
              <div className="p-5 bg-sky-50 rounded-2xl border border-sky-100 relative overflow-hidden">
                <div className="flex items-center gap-2 mb-2 text-sky-600 relative z-10">
                  <RefreshCcw size={18} />
                  <span className="text-[10px] font-black uppercase tracking-wider">Active Rentals</span>
                </div>
                <p className="text-2xl font-black text-gray-800 relative z-10">{customerHistory.stats.activeRentals}</p>
              </div>
              <div className="p-5 bg-pink-50 rounded-2xl border border-pink-100 relative overflow-hidden">
                <div className="flex items-center gap-2 mb-2 text-pink-600 relative z-10">
                  <ShoppingBag size={18} />
                  <span className="text-[10px] font-black uppercase tracking-wider">Transactions</span>
                </div>
                <p className="text-2xl font-black text-gray-800 relative z-10">{customerHistory.stats.totalOrders}</p>
              </div>
            </div>
          </Card>
        </div>

        {/* Transaction History Table */}
        <Card className="overflow-hidden border-0 shadow-sm">
          <div className="p-6 border-b border-gray-50 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
             <div className="flex items-center gap-4">
               <h3 className="font-bold text-gray-800">History</h3>
               <div className="flex bg-gray-50 p-1 rounded-xl">
                  <button 
                    onClick={() => setTransactionFilter('ALL')} 
                    className={`px-4 py-1.5 text-xs font-bold rounded-lg transition-all ${transactionFilter === 'ALL' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                  >
                    All
                  </button>
                  <button 
                    onClick={() => setTransactionFilter('SALE')} 
                    className={`px-4 py-1.5 text-xs font-bold rounded-lg transition-all ${transactionFilter === 'SALE' ? 'bg-white text-emerald-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                  >
                    Sales
                  </button>
                  <button 
                    onClick={() => setTransactionFilter('RENTAL')} 
                    className={`px-4 py-1.5 text-xs font-bold rounded-lg transition-all ${transactionFilter === 'RENTAL' ? 'bg-white text-sky-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                  >
                    Rentals
                  </button>
               </div>
             </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead className="bg-gray-50/50 text-gray-400">
                <tr>
                  <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Date</th>
                  <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Type</th>
                  <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Details</th>
                  <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Payment</th>
                  <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-center">Status</th>
                  <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {customerHistory.transactions.map((t: any) => {
                  const isSale = t.type === 'SALE';
                  const productName = isSale 
                    ? `${t.items.length} Items` 
                    : products.find(p => p.id === t.productId)?.name || 'Unknown Product';

                  // Calculate balances
                  const total = isSale ? t.totalAmount : t.totalRentAmount;
                  const paid = t.paidAmount || 0;
                  const balance = total - paid;

                  return (
                    <tr key={t.id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-6 py-4">
                        <div className="font-bold text-gray-800">{new Date(t.date).toLocaleDateString()}</div>
                        <div className="text-xs text-gray-400 font-mono">{t.invoiceNumber}</div>
                      </td>
                      <td className="px-6 py-4">
                         {isSale ? (
                           <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold bg-emerald-50 text-emerald-600">
                             <ShoppingBag size={12} /> SALE
                           </span>
                         ) : (
                           <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold bg-sky-50 text-sky-600">
                             <RefreshCcw size={12} /> RENTAL
                           </span>
                         )}
                      </td>
                      <td className="px-6 py-4">
                        <div className="text-gray-800 font-medium">{productName}</div>
                        {!isSale && (
                          <div className="text-xs text-pink-500 mt-1 flex items-center gap-1 font-medium">
                             <Calendar size={10} />
                             Due: {new Date(t.expectedReturnDate).toLocaleDateString()}
                          </div>
                        )}
                      </td>
                      <td className="px-6 py-4 text-right">
                         <div className="font-bold text-gray-700">{formatCurrency(total)}</div>
                         {isSale && balance > 0 && (
                            <div className="text-[10px] font-bold text-pink-500 mt-0.5">
                               Bal: {formatCurrency(balance)}
                            </div>
                         )}
                         {isSale && balance <= 0 && (
                            <div className="text-[10px] font-bold text-emerald-500 mt-0.5">
                               Fully Paid
                            </div>
                         )}
                      </td>
                      <td className="px-6 py-4 text-center">
                         <span className={`px-2 py-1 rounded-full text-[10px] font-bold uppercase tracking-wide ${isSale ? 'bg-gray-100 text-gray-500' : getStatusColor(t.status)}`}>
                            {isSale ? t.paymentStatus : t.status}
                         </span>
                      </td>
                      <td className="px-6 py-4 text-right">
                         {isSale && t.paymentStatus !== PaymentStatus.PAID && (
                            <button 
                              onClick={() => openPaymentModal(t.id)}
                              className="text-xs font-bold text-sky-500 hover:text-sky-600 bg-sky-50 hover:bg-sky-100 px-3 py-1.5 rounded-lg transition-colors inline-flex items-center gap-1"
                            >
                               <Banknote size={14} /> Pay
                            </button>
                         )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            {customerHistory.transactions.length === 0 && (
              <div className="py-12 text-center text-gray-400 italic">No {transactionFilter !== 'ALL' ? transactionFilter.toLowerCase() : ''} transactions found.</div>
            )}
          </div>
        </Card>

        {/* Payment Modal */}
        <Modal 
           isOpen={isPaymentModalOpen} 
           onClose={() => { setIsPaymentModalOpen(false); setSelectedSaleForPayment(null); }} 
           title={`Record Payment: ${activePaymentSale?.invoiceNumber}`}
        >
           <form onSubmit={handleRecordPayment} className="space-y-4">
              <div className="p-4 bg-gray-50 rounded-xl space-y-2 border border-gray-100">
                 <div className="flex justify-between text-sm">
                    <span className="text-gray-500">Total Invoice Amount:</span>
                    <span className="font-bold text-gray-800">{formatCurrency(activePaymentSale?.totalAmount || 0)}</span>
                 </div>
                 <div className="flex justify-between text-sm">
                    <span className="text-gray-500">Already Paid:</span>
                    <span className="font-bold text-emerald-600">{formatCurrency(activePaymentSale?.paidAmount || 0)}</span>
                 </div>
                 <div className="flex justify-between text-sm pt-2 border-t border-gray-200">
                    <span className="font-bold text-gray-700">Balance Due:</span>
                    <span className="font-bold text-pink-500">{formatCurrency(activePaymentBalance)}</span>
                 </div>
              </div>

              <div className="space-y-1">
                 <label className="text-xs font-bold uppercase text-gray-400">Payment Amount</label>
                 <div className="relative">
                    <IndianRupee className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                    <input 
                      name="amount" 
                      type="number" 
                      max={activePaymentBalance}
                      min={1}
                      required 
                      autoFocus
                      className="w-full pl-10 pr-4 py-3 bg-white border border-gray-200 focus:border-sky-200 rounded-xl outline-none transition-all font-medium" 
                      placeholder="Enter amount" 
                    />
                 </div>
                 <p className="text-[10px] text-gray-400">Enter value less than or equal to balance.</p>
              </div>

              <div className="flex gap-3 pt-4">
                 <Button variant="ghost" onClick={() => setIsPaymentModalOpen(false)} className="flex-1">Cancel</Button>
                 <Button type="submit" className="flex-1">Save Payment</Button>
              </div>
           </form>
        </Modal>
      </div>
    );
  }

  // -- RENDER: Customer Directory (List View) --
  return (
    <div className="space-y-6 animate-in fade-in duration-300 pb-10">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Customers</h1>
          <p className="text-sm font-medium text-gray-400">Manage client relationships</p>
        </div>
        <Button onClick={() => setIsAddModalOpen(true)} className="flex items-center gap-2 shadow-sky-200">
          <Plus size={20} /> Add Customer
        </Button>
      </div>

      <div className="relative">
        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
        <input 
          type="text" 
          placeholder="Search customers..." 
          className="w-full pl-11 pr-4 py-3 bg-white border border-gray-100 rounded-2xl outline-none focus:ring-2 focus:ring-sky-100 transition-all font-medium text-gray-600"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <Card className="overflow-hidden border-0 shadow-sm">
        <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
            <thead>
                <tr className="bg-gray-50/50 border-b border-gray-100 text-gray-400">
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Customer Name</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Contact Info</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Last Order</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Total Spent</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Outstanding</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Actions</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
                {filteredCustomers.map(customer => (
                    <tr key={customer.id} className="hover:bg-gray-50 group transition-colors">
                    <td className="px-6 py-4">
                        <div className="flex items-center space-x-4">
                        <div className="w-12 h-12 bg-gradient-to-br from-gray-100 to-gray-200 text-gray-600 rounded-full flex items-center justify-center font-black text-lg shadow-inner relative">
                            {customer.name.charAt(0)}
                            {customer.totalSpent > 10000 && <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-yellow-400 rounded-full border-2 border-white flex items-center justify-center"><Star size={8} className="text-white" fill="currentColor"/></div>}
                        </div>
                        <div>
                            <div className="font-bold text-gray-800 flex items-center gap-2">
                                {customer.name}
                                {getVipBadge(customer.totalSpent)}
                            </div>
                            <div className="text-xs text-gray-400 font-medium mt-0.5">ID: {customer.id}</div>
                        </div>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                        <div className="space-y-1">
                        <div className="flex items-center text-gray-600 gap-2 font-medium">
                            <Phone size={14} className="text-gray-400" /> {customer.phone}
                        </div>
                        <div className="flex items-center text-gray-500 text-xs gap-2">
                            <Mail size={14} className="text-gray-300" /> {customer.email}
                        </div>
                        </div>
                    </td>
                    <td className="px-6 py-4 text-right">
                        <span className="text-gray-600 font-medium">
                            {customer.lastActive ? new Date(customer.lastActive).toLocaleDateString() : '-'}
                        </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                        <div className="font-bold text-gray-800">{formatCurrency(customer.totalSpent)}</div>
                    </td>
                    <td className="px-6 py-4 text-right">
                        <div className={`font-bold ${customer.balance > 0 ? 'text-pink-500' : 'text-emerald-500'}`}>
                            {formatCurrency(customer.balance)}
                        </div>
                        {customer.balance > 0 && <div className="text-[10px] text-gray-400 font-medium">Due Amount</div>}
                    </td>
                    <td className="px-6 py-4 text-right">
                        <Button variant="secondary" onClick={() => setSelectedCustomerId(customer.id)} className="text-xs px-4">
                            View Ledger <ArrowRight size={14} className="ml-1 inline" />
                        </Button>
                    </td>
                    </tr>
                ))}
            </tbody>
            </table>
        </div>
        {filteredCustomers.length === 0 && (
          <div className="py-20 text-center text-gray-400 italic">No customers found. Add one to get started.</div>
        )}
      </Card>

      <Modal isOpen={isAddModalOpen} onClose={() => setIsAddModalOpen(false)} title="Add New Customer">
        <form onSubmit={handleAddCustomer} className="grid grid-cols-1 gap-4">
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Full Name</label>
            <input name="name" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="John Doe" />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-xs font-bold uppercase text-gray-400">Phone</label>
              <input name="phone" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="9876543210" />
            </div>
            <div className="space-y-1">
              <label className="text-xs font-bold uppercase text-gray-400">Email</label>
              <input name="email" type="email" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="john@example.com" />
            </div>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Address</label>
            <textarea name="address" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium h-24" placeholder="Full billing address"></textarea>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">GSTIN (Optional)</label>
            <input name="gstin" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="Tax Identification Number" />
          </div>
          <div className="flex gap-3 pt-4">
            <Button variant="ghost" onClick={() => setIsAddModalOpen(false)} className="flex-1">Cancel</Button>
            <Button type="submit" className="flex-1">Save Customer</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Customers;

import React, { useState, useRef, useEffect } from 'react';
import { AppProvider, useApp } from './store/AppContext';
import { NAVIGATION_ITEMS } from './constants';
import Dashboard from './pages/Dashboard';
import Inventory from './pages/Inventory';
import Rentals from './pages/Rentals';
import Customers from './pages/Customers';
import Suppliers from './pages/Suppliers';
import Sales from './pages/Sales';
import Settings from './pages/Settings';
import Reports from './pages/Reports';
import Users from './pages/Users';
import Login from './pages/Login';
import { 
  Bell, 
  Menu, 
  Search, 
  LogOut, 
  Settings as SettingsIcon,
  AlertTriangle,
  Clock,
  ChevronDown,
  User,
  X,
  ShieldCheck,
  Lock,
  ShoppingBag,
  RefreshCcw
} from 'lucide-react';
import { UserRole } from './types';

// Helper to check permissions
const canAccess = (user: any, moduleId: string) => {
  if (!user) return false;
  if (user.role === UserRole.ADMIN) return true; // Admins access everything
  return user.permissions?.includes(moduleId) || false;
};

const Sidebar: React.FC<{ activeTab: string; onTabChange: (id: string) => void }> = ({ activeTab, onTabChange }) => {
