              }
            `}
          >
            <span className={`
              ${isActive ? 'text-sky-500' : 'text-gray-300'} 
              transition-colors duration-200
            `}>
              {React.isValidElement(item.icon) 
                ? React.cloneElement(item.icon as React.ReactElement<any>, { 
                    size: 20, 
                    strokeWidth: 2.5 
                  })
                : item.icon
              }
            </span>

            <span className="tracking-wide">{item.label}</span>

            {/* Notification Badge example for Inventory */}
            {item.id === 'inventory' && (
               <span className={`
                 ml-auto text-[10px] px-2 py-0.5 rounded-full font-bold transition-colors opacity-0 group-hover:opacity-100
                 ${isActive ? 'opacity-100 bg-pink-400 text-white' : ''}
               `}></span>
            )}
          </button>
        );
      })}
    </nav>
  </aside>
  );
};

const TopBar: React.FC<{ activeTab: string; onTabChange: (id: string) => void }> = ({ activeTab, onTabChange }) => {
  const { products, rentals, sales, currentUser, logout } = useApp();
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const tabLabel = NAVIGATION_ITEMS.find(i => i.id === activeTab)?.label;
  const canAccessSettings = canAccess(currentUser, 'settings');

  // Compute Notifications
  // Check SALE stock for alerts
  const lowStockItems = products.filter(p => p.saleStock <= p.minStockAlert);
  const overdueRentals = rentals.filter(r => r.status === 'ACTIVE' && new Date(r.expectedReturnDate) < new Date());

  // Recent Activity (Last 5 items mixed)
  const recentActivities = [...sales, ...rentals]
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
      .slice(0, 5)
      .map(item => {
          const isSale = 'items' in item;
          return {
              id: item.id,
              type: isSale ? 'SALE' : 'RENTAL',
              title: isSale ? 'New Sale Recorded' : 'New Rental Booking',
              message: `${isSale ? (item as any).invoiceNumber : (item as any).invoiceNumber} • ${new Date(item.date).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}`,
              action: () => onTabChange(isSale ? 'sales' : 'rentals'),
              urgent: false
          };
      });

  const notifications = [
    // Priority Alerts
    ...lowStockItems.map(p => ({
       id: `stock-${p.id}`,
       type: 'STOCK',
       title: 'Low Stock Alert',
       message: `${p.name} is running low (${p.saleStock} remaining).`,
       action: () => onTabChange('inventory'),
       urgent: true
    })),
    ...overdueRentals.map(r => ({
       id: `rental-${r.id}`,
       type: 'RENTAL_OVERDUE',
       title: 'Overdue Rental',
       message: `Rental #${r.invoiceNumber} is overdue since ${new Date(r.expectedReturnDate).toLocaleDateString()}.`,
       action: () => onTabChange('rentals'),
       urgent: true
    })),
    // Recent Activity Feed
    ...recentActivities
  ];

  const unreadCount = notifications.length;

  const getNotificationIcon = (type: string) => {
    switch (type) {
        case 'STOCK': return <AlertTriangle size={14} />;
        case 'RENTAL_OVERDUE': return <Clock size={14} />;
        case 'SALE': return <ShoppingBag size={14} />;
        case 'RENTAL': return <RefreshCcw size={14} />;
        default: return <Bell size={14} />;
    }
  };

  const getNotificationStyles = (note: any) => {
      if (note.urgent) return 'bg-red-50 text-red-500';
      if (note.type === 'SALE') return 'bg-emerald-50 text-emerald-500';
      if (note.type === 'RENTAL') return 'bg-sky-50 text-sky-500';
      return 'bg-gray-50 text-gray-500';
  };

  // Close dropdowns on outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsNotificationsOpen(false);
        setIsUserMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <header className="h-20 bg-white/90 backdrop-blur-md border-b border-gray-100 flex items-center justify-between px-6 md:px-8 sticky top-0 z-30 shadow-sm transition-all">
      <div className="flex items-center space-x-4">
        <button className="md:hidden p-2 text-gray-500 hover:bg-gray-100 rounded-lg">
           <Menu size={24} />
        </button>
        <div>
          <h2 className="text-xl font-black text-gray-800 tracking-tight">{tabLabel}</h2>
        </div>
      </div>

      <div className="flex items-center gap-2 md:gap-6" ref={dropdownRef}>
        {/* Search - Hidden on mobile */}
        <div className="hidden md:flex items-center bg-gray-100/50 rounded-2xl px-4 py-2.5 w-64 lg:w-80 focus-within:ring-2 focus-within:ring-sky-100 focus-within:bg-white transition-all border border-transparent focus-within:border-sky-100">
          <Search size={18} className="text-gray-400 mr-3 shrink-0" />
          <input 
            type="text" 
            placeholder="Quick search..." 
            className="bg-transparent text-sm outline-none w-full placeholder:text-gray-400 text-gray-700 font-medium"
          />
        </div>

        <div className="flex items-center gap-2">
          {/* Notifications */}
          <div className="relative">
            <button 
              onClick={() => setIsNotificationsOpen(!isNotificationsOpen)}
              className={`relative p-2.5 rounded-xl transition-all ${isNotificationsOpen ? 'bg-sky-50 text-sky-600' : 'text-gray-400 hover:bg-gray-100 hover:text-gray-600'}`}
            >
              <Bell size={20} strokeWidth={2.5} />
              {unreadCount > 0 && (
                <span className="absolute top-2 right-2.5 w-2.5 h-2.5 bg-pink-500 rounded-full border-2 border-white animate-pulse"></span>
              )}
            </button>

            {isNotificationsOpen && (
              <div className="absolute right-0 top-full mt-3 w-80 md:w-96 bg-white shadow-2xl rounded-2xl border border-gray-100 overflow-hidden animate-in fade-in slide-in-from-top-2 origin-top-right">
                <div className="p-4 border-b border-gray-50 flex justify-between items-center bg-gray-50/50">
                   <h3 className="font-bold text-gray-800 text-sm">Activity & Alerts</h3>
                   {unreadCount > 0 && <span className="bg-sky-100 text-sky-600 text-[10px] font-bold px-2 py-0.5 rounded-full">{unreadCount} New</span>}
                </div>
                <div className="max-h-[300px] overflow-y-auto custom-scrollbar">
                   {notifications.length > 0 ? (
                     notifications.map((note, i) => (
                       <div 
                         key={i} 
                         onClick={() => { note.action(); setIsNotificationsOpen(false); }}
                         className="p-4 hover:bg-gray-50 border-b border-gray-50 last:border-0 cursor-pointer transition-colors flex gap-3 items-start group"
                       >
                          <div className={`mt-0.5 p-2 rounded-full shrink-0 ${getNotificationStyles(note)}`}>
                             {getNotificationIcon(note.type)}
                          </div>
                          <div>
                             <p className="text-xs font-bold text-gray-800 group-hover:text-sky-600 transition-colors">{note.title}</p>
                             <p className="text-xs text-gray-500 mt-0.5 leading-relaxed">{note.message}</p>
                          </div>
                       </div>
                     ))
                   ) : (
                     <div className="p-8 text-center text-gray-400 flex flex-col items-center">
                        <Bell size={32} className="text-gray-200 mb-2" />
                        <p className="text-sm font-medium">No recent activity</p>
                        <p className="text-xs">You're all caught up!</p>
                     </div>
                   )}
                </div>
                {notifications.length > 0 && (
                   <div className="p-2 bg-gray-50 text-center">
                      <button 
                        onClick={() => setIsNotificationsOpen(false)} 
                        className="text-xs font-bold text-gray-500 hover:text-gray-800 transition-colors"
                      >
                        Dismiss All
                      </button>
                   </div>
                )}
              </div>
            )}
          </div>

          {/* Settings Button */}
          {canAccessSettings && (
            <button 
              onClick={() => onTabChange('settings')}
              className="hidden md:block p-2.5 text-gray-400 hover:bg-gray-100 hover:text-gray-600 rounded-xl transition-all"
              title="Settings"
            >
              <SettingsIcon size={20} strokeWidth={2.5} />
            </button>
          )}

          {/* User Menu (Mobile/Tablet) */}
          <div className="relative ml-2">
             <button 
               onClick={() => setIsUserMenuOpen(!isUserMenuOpen)}
               className="flex items-center gap-2 hover:bg-gray-50 p-1.5 pr-3 rounded-full transition-all border border-transparent hover:border-gray-100"
             >
                <div className={`w-8 h-8 rounded-full bg-gradient-to-tr ${currentUser?.role === UserRole.ADMIN ? 'from-indigo-400 to-indigo-600' : 'from-sky-400 to-sky-600'} text-white flex items-center justify-center shadow-md font-bold text-xs`}>
                   {currentUser?.name.charAt(0)}
                </div>
                <ChevronDown size={14} className="text-gray-400 hidden md:block" />
             </button>

             {isUserMenuOpen && (
               <div className="absolute right-0 top-full mt-3 w-48 bg-white shadow-xl rounded-xl border border-gray-100 overflow-hidden animate-in fade-in slide-in-from-top-2 origin-top-right">
                  <div className="p-3 border-b border-gray-50 bg-gray-50/50">
                     <p className="text-xs font-bold text-gray-800">{currentUser?.name}</p>
                     <div className="flex items-center gap-1 mt-0.5">
                       {currentUser?.role === UserRole.ADMIN ? <ShieldCheck size={10} className="text-indigo-500"/> : <User size={10} className="text-sky-500"/>}
                       <p className="text-[10px] text-gray-500 capitalize">{currentUser?.role.toLowerCase()}</p>
                     </div>
                  </div>
                  {canAccessSettings && (
                    <button onClick={() => { onTabChange('settings'); setIsUserMenuOpen(false); }} className="w-full text-left px-4 py-2.5 text-xs font-medium text-gray-600 hover:bg-gray-50 hover:text-sky-600 flex items-center gap-2">
                      <SettingsIcon size={14} /> Settings
                    </button>
                  )}
                  <button onClick={() => logout()} className="w-full text-left px-4 py-2.5 text-xs font-medium text-red-500 hover:bg-red-50 flex items-center gap-2">
                     <LogOut size={14} /> Logout
                  </button>
               </div>
             )}
          </div>
        </div>
      </div>
    </header>
  );
};

const AppContent: React.FC = () => {
  const { currentUser } = useApp();
  const [activeTab, setActiveTab] = useState('dashboard');

  if (!currentUser) {
    return <Login />;
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'inventory': return <Inventory />;
      case 'rentals': return <Rentals />;
      case 'customers': return <Customers />;
      case 'suppliers': return <Suppliers />;
      case 'sales': return <Sales />;
      case 'reports': return <Reports />;
      case 'users': return <Users />;
      case 'settings': return <Settings />;
      default: return <Dashboard />;
    }
  };

  return (
    <div className="flex h-screen bg-gray-50 font-sans text-gray-900">
      <Sidebar activeTab={activeTab} onTabChange={setActiveTab} />
      <div className="flex-1 flex flex-col h-screen overflow-hidden">
        <TopBar activeTab={activeTab} onTabChange={setActiveTab} />
        <main className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
          {renderContent()}
        </main>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  return (
    <AppProvider>
      <AppContent />
    </AppProvider>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { useApp } from '../store/AppContext';
import { Card, Button, Modal } from '../components/Shared';
import { 
  Plus, 
  Search, 
  Filter, 
  Edit2, 
  Trash2, 
  ArrowUpRight, 
  ArrowDownLeft,
  Package,
  AlertTriangle,
  Tags,
  DollarSign,
  Box,
  ShoppingBag,
  RefreshCcw,
  Check
} from 'lucide-react';
import { formatCurrency } from '../utils/helpers';
import { CATEGORIES } from '../constants';

const Inventory: React.FC = () => {
  const { products, addProduct, updateProduct, deleteProduct, updateStock, suppliers } = useApp();
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isStockModalOpen, setIsStockModalOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'ALL' | 'LOW' | 'OUT'>('ALL');

  // New State for Product Purpose Selection
  const [productType, setProductType] = useState<'SALE' | 'RENTAL' | 'BOTH'>('BOTH');

  // Stats Calculation
  const stats = useMemo(() => {
    const totalItems = products.reduce((acc, p) => acc + p.saleStock + p.rentalStock, 0);
    const totalValue = products.reduce((acc, p) => acc + (p.purchasePrice * (p.saleStock + p.rentalStock)), 0); // Asset value based on purchase price
    const lowStock = products.filter(p => p.saleStock > 0 && p.saleStock <= p.minStockAlert).length; // Only count if it's a sale item
    const outOfStock = products.filter(p => p.saleStock === 0 && p.rentalStock === 0).length;
    return { totalItems, totalValue, lowStock, outOfStock };
  }, [products]);

  const filteredProducts = products.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          p.sku.toLowerCase().includes(searchTerm.toLowerCase());

    if (statusFilter === 'LOW') return matchesSearch && p.saleStock > 0 && p.saleStock <= p.minStockAlert;
    if (statusFilter === 'OUT') return matchesSearch && p.saleStock === 0 && p.rentalStock === 0;

    return matchesSearch;
  });

  const handleAddProduct = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);

    // Determine values based on type selection
    const sellingPrice = (productType === 'SALE' || productType === 'BOTH') ? Number(formData.get('sellingPrice')) : 0;
    const saleStock = (productType === 'SALE' || productType === 'BOTH') ? Number(formData.get('saleStock')) : 0;

    const rentalPrice = (productType === 'RENTAL' || productType === 'BOTH') ? Number(formData.get('rentalPrice')) : 0;
    const rentalStock = (productType === 'RENTAL' || productType === 'BOTH') ? Number(formData.get('rentalStock')) : 0;

    addProduct({
      name: formData.get('name') as string,
      sku: formData.get('sku') as string,
      barcode: formData.get('barcode') as string,
      category: formData.get('category') as string,
      purchasePrice: Number(formData.get('purchasePrice')),
      sellingPrice,
      rentalPrice,
      taxPercent: Number(formData.get('taxPercent')),
      saleStock,
      rentalStock,
      minStockAlert: Number(formData.get('minStockAlert')),
      supplierId: formData.get('supplierId') as string,
      description: formData.get('description') as string,
    });
    setIsAddModalOpen(false);
    setProductType('BOTH'); // Reset
  };

  const handleStockUpdate = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    if (selectedProduct) {
      updateStock(
        selectedProduct,
        formData.get('pool') as 'SALE' | 'RENTAL',
        Number(formData.get('quantity')),
        formData.get('type') as 'IN' | 'OUT',
        formData.get('reason') as string
      );
    }
    setIsStockModalOpen(false);
  };

  const openAddModal = () => {
      setProductType('BOTH');
      setIsAddModalOpen(true);
  };

  // Helper to determine product type string for display
  const getProductTypeDisplay = (p: typeof products[0]) => {
      const isSale = p.sellingPrice > 0 || p.saleStock > 0;
      const isRent = p.rentalPrice > 0 || p.rentalStock > 0;
      if (isSale && isRent) return 'BOTH';
      if (isRent) return 'RENTAL';
      return 'SALE';
  }

  // Helper component for stock bar
  const StockBar = ({ current, max = 10, isLow, disabled }: { current: number, max?: number, isLow?: boolean, disabled?: boolean }) => {
      if (disabled) return <div className="h-1.5 w-16 mt-1 bg-gray-100 rounded-full opacity-50"></div>;

      const percentage = Math.min(100, (current / max) * 100);
      const color = current === 0 ? 'bg-gray-200' : isLow ? 'bg-orange-400' : 'bg-emerald-400';

      return (
          <div className="w-16 h-1.5 bg-gray-100 rounded-full overflow-hidden mt-1">
              <div className={`h-full rounded-full ${color}`} style={{ width: `${percentage}%` }}></div>
          </div>
      );
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-300 pb-10">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Inventory</h1>
          <p className="text-sm font-medium text-gray-400">Manage separate Sales & Rental pools</p>
        </div>
        <Button onClick={openAddModal} className="flex items-center gap-2 shadow-sky-200">
          <Plus size={20} /> Add Product
        </Button>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="p-5 border-0 shadow-sm bg-white">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-xs font-bold uppercase text-gray-400">Total Stock Value</p>
                    <h3 className="text-2xl font-black text-gray-800 mt-1">{formatCurrency(stats.totalValue)}</h3>
                </div>
                <div className="p-2 bg-emerald-50 text-emerald-600 rounded-lg">
                    <DollarSign size={20} />
                </div>
            </div>
            <p className="text-xs text-gray-400 mt-2">Combined retail & asset value</p>
        </Card>
        <Card className="p-5 border-0 shadow-sm bg-white">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-xs font-bold uppercase text-gray-400">Total Products</p>
                    <h3 className="text-2xl font-black text-gray-800 mt-1">{products.length}</h3>
                </div>
                <div className="p-2 bg-sky-50 text-sky-600 rounded-lg">
                    <Tags size={20} />
                </div>
            </div>
            <p className="text-xs text-gray-400 mt-2">{stats.totalItems} individual units</p>
        </Card>
        <Card className={`p-5 border-0 shadow-sm ${stats.lowStock > 0 ? 'bg-orange-50 border-orange-100' : 'bg-white'}`}>
            <div className="flex justify-between items-start">
                <div>
                    <p className={`text-xs font-bold uppercase ${stats.lowStock > 0 ? 'text-orange-600' : 'text-gray-400'}`}>Low Sales Stock</p>
                    <h3 className={`text-2xl font-black mt-1 ${stats.lowStock > 0 ? 'text-orange-700' : 'text-gray-800'}`}>{stats.lowStock}</h3>
                </div>
                <div className={`p-2 rounded-lg ${stats.lowStock > 0 ? 'bg-white text-orange-600' : 'bg-orange-50 text-orange-600'}`}>
                    <AlertTriangle size={20} />
                </div>
            </div>
            <p className={`text-xs mt-2 ${stats.lowStock > 0 ? 'text-orange-600' : 'text-gray-400'}`}>Items below alert threshold</p>
        </Card>
        <Card className={`p-5 border-0 shadow-sm ${stats.outOfStock > 0 ? 'bg-red-50 border-red-100' : 'bg-white'}`}>
            <div className="flex justify-between items-start">
                <div>
                    <p className={`text-xs font-bold uppercase ${stats.outOfStock > 0 ? 'text-red-600' : 'text-gray-400'}`}>Completely Out</p>
                    <h3 className={`text-2xl font-black mt-1 ${stats.outOfStock > 0 ? 'text-red-700' : 'text-gray-800'}`}>{stats.outOfStock}</h3>
                </div>
                <div className={`p-2 rounded-lg ${stats.outOfStock > 0 ? 'bg-white text-red-600' : 'bg-red-50 text-red-600'}`}>
                    <Box size={20} />
                </div>
            </div>
            <p className={`text-xs mt-2 ${stats.outOfStock > 0 ? 'text-red-600' : 'text-gray-400'}`}>Zero stock in both pools</p>
        </Card>
      </div>

      <div className="flex flex-col gap-4">
        {/* Search & Tabs */}
        <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
             <div className="relative w-full md:w-96">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                <input 
                    type="text" 
                    placeholder="Search by name, SKU..." 
                    className="w-full pl-11 pr-4 py-2.5 bg-white border border-gray-100 rounded-2xl outline-none focus:ring-2 focus:ring-sky-100 transition-all font-medium text-gray-600"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                />
            </div>

            <div className="flex bg-gray-100/50 p-1 rounded-xl">
               <button 
                 onClick={() => setStatusFilter('ALL')}
                 className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${statusFilter === 'ALL' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
               >
                 All Items
               </button>
               <button 
                 onClick={() => setStatusFilter('LOW')}
                 className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${statusFilter === 'LOW' ? 'bg-white text-orange-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
               >
                 Low Stock
               </button>
               <button 
                 onClick={() => setStatusFilter('OUT')}
                 className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${statusFilter === 'OUT' ? 'bg-white text-red-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
               >
                 Out of Stock
               </button>
            </div>
        </div>

        {/* Product Table */}
        <Card className="overflow-hidden border-0 shadow-sm">
            <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
                <thead>
                <tr className="bg-gray-50/50 border-b border-gray-100 text-gray-400">
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Product Info</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Category & SKU</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-center">Sale Stock</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-center">Rental Stock</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Actions</th>
                </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                {filteredProducts.map(product => {
                    const type = getProductTypeDisplay(product);
                    const isSaleEnabled = type === 'SALE' || type === 'BOTH';
                    const isRentalEnabled = type === 'RENTAL' || type === 'BOTH';

                    return (
                    <tr key={product.id} className="hover:bg-gray-50 transition-colors group">
                    <td className="px-6 py-4">
                        <div className="flex items-center space-x-4">
                        <div className={`w-12 h-12 rounded-xl flex items-center justify-center font-bold text-lg shadow-sm ${type === 'SALE' ? 'bg-emerald-50 text-emerald-500' : type === 'RENTAL' ? 'bg-sky-50 text-sky-500' : 'bg-indigo-50 text-indigo-500'}`}>
                            <Package size={20} />
                        </div>
                        <div>
                            <div className="font-bold text-gray-800">{product.name}</div>
                            <div className="flex items-center gap-2 mt-1">
                                {type === 'SALE' && <span className="text-[10px] font-bold bg-emerald-100 text-emerald-700 px-1.5 py-0.5 rounded">FOR SALE</span>}
                                {type === 'RENTAL' && <span className="text-[10px] font-bold bg-sky-100 text-sky-700 px-1.5 py-0.5 rounded">FOR RENT</span>}
                                {type === 'BOTH' && <span className="text-[10px] font-bold bg-indigo-100 text-indigo-700 px-1.5 py-0.5 rounded">HYBRID</span>}

                                {isSaleEnabled && product.saleStock <= product.minStockAlert && product.saleStock > 0 && (
                                    <span className="text-[10px] font-bold text-orange-600 bg-orange-50 px-2 py-0.5 rounded-full">Low Stock</span>
                                )}
                            </div>
                        </div>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                         <div className="text-gray-800 font-medium">{product.category}</div>
                         <div className="font-mono text-gray-400 text-xs mt-0.5">{product.sku}</div>
                    </td>
                    <td className="px-6 py-4 text-center">
                        {isSaleEnabled ? (
                            <div className="inline-flex flex-col items-center">
                                <span className={`font-bold text-lg ${product.saleStock === 0 ? 'text-gray-300' : 'text-gray-800'}`}>
                                    {product.saleStock}
                                </span>
                                <StockBar current={product.saleStock} max={product.minStockAlert * 3} isLow={product.saleStock <= product.minStockAlert} />
                            </div>
                        ) : (
                            <span className="text-gray-300 font-medium text-xs">—</span>
                        )}
                    </td>
                    <td className="px-6 py-4 text-center">
                        {isRentalEnabled ? (
                            <div className="inline-flex flex-col items-center">
                                <span className={`font-bold text-lg ${product.rentalStock === 0 ? 'text-gray-300' : 'text-sky-600'}`}>
                                    {product.rentalStock}
                                </span>
                                <StockBar current={product.rentalStock} max={5} />
                            </div>
                        ) : (
                             <span className="text-gray-300 font-medium text-xs">—</span>
                        )}
                    </td>
                    <td className="px-6 py-4 text-right">
                        <div className="flex items-center justify-end space-x-2">
                        <button 
                            onClick={() => { setSelectedProduct(product.id); setIsStockModalOpen(true); }}
                            className="p-2 text-sky-500 bg-sky-50 hover:bg-sky-100 rounded-lg transition-colors"
                            title="Update Stock"
                        >
                            <RefreshCcw size={16} />
                        </button>
                        <button 
                            onClick={() => deleteProduct(product.id)}
                            className="p-2 text-gray-300 hover:text-pink-500 hover:bg-pink-50 rounded-lg transition-colors"
                        >
                            <Trash2 size={16} />
                        </button>
                        </div>
                    </td>
                    </tr>
                    );
                })}
                </tbody>
            </table>
            {filteredProducts.length === 0 && (
                <div className="py-20 text-center text-gray-400 italic">No products found matching your search.</div>
            )}
            </div>
        </Card>
      </div>

      {/* Add Product Modal */}
      <Modal 
        isOpen={isAddModalOpen} 
        onClose={() => setIsAddModalOpen(false)} 
        title="Add New Product"
      >
        <form onSubmit={handleAddProduct} className="grid grid-cols-1 md:grid-cols-2 gap-4">

          <div className="col-span-1 md:col-span-2 space-y-2 mb-2">
             <label className="text-xs font-bold uppercase text-gray-400">Product Purpose</label>
             <div className="grid grid-cols-3 gap-3">
                 <button 
                    type="button"
                    onClick={() => setProductType('SALE')}
                    className={`flex items-center justify-center gap-2 p-3 rounded-xl border-2 font-bold text-sm transition-all ${productType === 'SALE' ? 'border-emerald-500 bg-emerald-50 text-emerald-700' : 'border-gray-100 text-gray-500 hover:border-gray-200'}`}
                 >
                    <ShoppingBag size={16} /> Sale Only
                 </button>
                 <button 
                    type="button"
                    onClick={() => setProductType('RENTAL')}
                    className={`flex items-center justify-center gap-2 p-3 rounded-xl border-2 font-bold text-sm transition-all ${productType === 'RENTAL' ? 'border-sky-500 bg-sky-50 text-sky-700' : 'border-gray-100 text-gray-500 hover:border-gray-200'}`}
                 >
                    <RefreshCcw size={16} /> Rent Only
                 </button>
                 <button 
                    type="button"
                    onClick={() => setProductType('BOTH')}
                    className={`flex items-center justify-center gap-2 p-3 rounded-xl border-2 font-bold text-sm transition-all ${productType === 'BOTH' ? 'border-indigo-500 bg-indigo-50 text-indigo-700' : 'border-gray-100 text-gray-500 hover:border-gray-200'}`}
                 >
                    <Package size={16} /> Hybrid
                 </button>
             </div>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Product Name</label>
            <input name="name" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="e.g. Princess Dress" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">SKU</label>
            <input name="sku" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="DRS-001" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Barcode</label>
            <input name="barcode" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="Scan or enter" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Category</label>
            <select name="category" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium">
              {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Purchase Cost</label>
            <input name="purchasePrice" type="number" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="0" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Supplier</label>
            <select name="supplierId" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium">
              {suppliers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
            </select>
          </div>

          {(productType === 'SALE' || productType === 'BOTH') && (
            <div className="col-span-2 grid grid-cols-2 gap-4 pt-4 pb-2 border-t border-gray-100 animate-in fade-in slide-in-from-top-2">
                 <div className="col-span-2 flex items-center gap-2 mb-1">
                    <span className="w-2 h-2 rounded-full bg-emerald-500"></span>
                    <h4 className="text-xs font-bold text-gray-800 uppercase tracking-wider">Sale Details</h4>
                 </div>
                 <div className="space-y-1">
                    <label className="text-xs font-bold uppercase text-emerald-600">Selling Price</label>
                    <input name="sellingPrice" type="number" required className="w-full px-4 py-3 bg-emerald-50 border-transparent focus:bg-white border focus:border-emerald-200 rounded-xl outline-none transition-all font-medium" placeholder="0" />
                 </div>
                 <div className="space-y-1">
                    <label className="text-xs font-bold uppercase text-emerald-600">Initial Sale Stock</label>
                    <input name="saleStock" type="number" required className="w-full px-4 py-3 bg-emerald-50 border-transparent focus:bg-white border focus:border-emerald-200 rounded-xl outline-none transition-all font-medium" placeholder="0" />
                 </div>
            </div>
          )}

          {(productType === 'RENTAL' || productType === 'BOTH') && (
            <div className="col-span-2 grid grid-cols-2 gap-4 pt-4 pb-2 border-t border-gray-100 animate-in fade-in slide-in-from-top-2">
                 <div className="col-span-2 flex items-center gap-2 mb-1">
                    <span className="w-2 h-2 rounded-full bg-sky-500"></span>
                    <h4 className="text-xs font-bold text-gray-800 uppercase tracking-wider">Rental Details</h4>
                 </div>
                 <div className="space-y-1">
                    <label className="text-xs font-bold uppercase text-sky-600">Rental Price / Day</label>
                    <input name="rentalPrice" type="number" required className="w-full px-4 py-3 bg-sky-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="0" />
                 </div>
                 <div className="space-y-1">
                    <label className="text-xs font-bold uppercase text-sky-600">Initial Rental Stock</label>
                    <input name="rentalStock" type="number" required className="w-full px-4 py-3 bg-sky-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="0" />
                 </div>
            </div>
          )}

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Min Alert Qty</label>
            <input name="minStockAlert" type="number" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" defaultValue="3" />
          </div>

          <div className="col-span-1 md:col-span-2 space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Description</label>
            <textarea name="description" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium h-24" placeholder="Product details..."></textarea>
          </div>
          <div className="col-span-1 md:col-span-2 flex gap-3 pt-4">
            <Button variant="ghost" onClick={() => setIsAddModalOpen(false)} className="flex-1">Cancel</Button>
            <Button type="submit" className="flex-1">Save Product</Button>
          </div>
        </form>
      </Modal>

      {/* Stock Update Modal */}
      <Modal 
        isOpen={isStockModalOpen} 
        onClose={() => setIsStockModalOpen(false)} 
        title="Update Stock Quantity"
      >
        <form onSubmit={handleStockUpdate} className="space-y-4">
          <div className="space-y-1">
             <label className="text-xs font-bold uppercase text-gray-400">Select Pool to Update</label>
             <div className="flex gap-4">
              <label className="flex-1 border rounded-xl p-3 flex items-center justify-center gap-2 cursor-pointer has-[:checked]:bg-emerald-50 has-[:checked]:border-emerald-500 has-[:checked]:text-emerald-700 transition-all">
                <input type="radio" name="pool" value="SALE" defaultChecked className="hidden" />
                <ShoppingBag size={18} /> Sales Stock
              </label>
              <label className="flex-1 border rounded-xl p-3 flex items-center justify-center gap-2 cursor-pointer has-[:checked]:bg-sky-50 has-[:checked]:border-sky-500 has-[:checked]:text-sky-700 transition-all">
                <input type="radio" name="pool" value="RENTAL" className="hidden" />
                <RefreshCcw size={18} /> Rental Pool
              </label>
            </div>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Adjustment Type</label>
            <div className="flex gap-4">
              <label className="flex-1 border rounded-xl p-3 flex items-center justify-center gap-2 cursor-pointer has-[:checked]:bg-green-50 has-[:checked]:border-green-500 has-[:checked]:text-green-700 transition-all">
                <input type="radio" name="type" value="IN" defaultChecked className="hidden" />
                <ArrowDownLeft size={18} /> Stock In
              </label>
              <label className="flex-1 border rounded-xl p-3 flex items-center justify-center gap-2 cursor-pointer has-[:checked]:bg-pink-50 has-[:checked]:border-pink-500 has-[:checked]:text-pink-700 transition-all">
                <input type="radio" name="type" value="OUT" className="hidden" />
                <ArrowUpRight size={18} /> Stock Out
              </label>
            </div>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Quantity</label>
            <input name="quantity" type="number" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="0" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Reason / Reference</label>
            <input name="reason" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="e.g. Bulk purchase, damage" />
          </div>
          <div className="flex gap-3 pt-4">
            <Button variant="ghost" onClick={() => setIsStockModalOpen(false)} className="flex-1">Cancel</Button>
            <Button type="submit" className="flex-1">Update Stock</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Inventory;

import React, { useState, useMemo } from 'react';
import { useApp } from '../store/AppContext';
import { Card, Button, Modal } from '../components/Shared';
import { 
  Plus, 
  Search, 
  Filter, 
  Edit2, 
  Trash2, 
  ArrowUpRight, 
  ArrowDownLeft,
  Package,
  AlertTriangle,
  Tags,
  DollarSign,
  Box,
  ShoppingBag,
  RefreshCcw,
  Check
} from 'lucide-react';
import { formatCurrency } from '../utils/helpers';
import { CATEGORIES } from '../constants';
import { Product } from '../types';

const Inventory: React.FC = () => {
  const { products, addProduct, updateProduct, deleteProduct, updateStock, suppliers } = useApp();
  const [isProductModalOpen, setIsProductModalOpen] = useState(false);
  const [isStockModalOpen, setIsStockModalOpen] = useState(false);

  const [selectedProduct, setSelectedProduct] = useState<string | null>(null); // For Stock Update Modal (ID only)
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);   // For Edit Modal (Full Object)

  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'ALL' | 'LOW' | 'OUT'>('ALL');

  // New State for Product Purpose Selection
  const [productType, setProductType] = useState<'SALE' | 'RENTAL' | 'BOTH'>('BOTH');

  // Stats Calculation
  const stats = useMemo(() => {
    const totalItems = products.reduce((acc, p) => acc + p.saleStock + p.rentalStock, 0);
    const totalValue = products.reduce((acc, p) => acc + (p.purchasePrice * (p.saleStock + p.rentalStock)), 0); // Asset value based on purchase price
    const lowStock = products.filter(p => p.saleStock > 0 && p.saleStock <= p.minStockAlert).length; // Only count if it's a sale item
    const outOfStock = products.filter(p => p.saleStock === 0 && p.rentalStock === 0).length;
    return { totalItems, totalValue, lowStock, outOfStock };
  }, [products]);

  const filteredProducts = products.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          p.sku.toLowerCase().includes(searchTerm.toLowerCase());

    if (statusFilter === 'LOW') return matchesSearch && p.saleStock > 0 && p.saleStock <= p.minStockAlert;
    if (statusFilter === 'OUT') return matchesSearch && p.saleStock === 0 && p.rentalStock === 0;

    return matchesSearch;
  });

  // Helper to determine product type string for display/edit
  const getProductTypeDisplay = (p: Product) => {
      const isSale = p.sellingPrice > 0 || p.saleStock > 0;
      const isRent = p.rentalPrice > 0 || p.rentalStock > 0;
      if (isSale && isRent) return 'BOTH';
      if (isRent) return 'RENTAL';
      return 'SALE';
  }

  const handleSaveProduct = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);

    // Determine values based on type selection
    const sellingPrice = (productType === 'SALE' || productType === 'BOTH') ? Number(formData.get('sellingPrice')) : 0;
    const saleStock = (productType === 'SALE' || productType === 'BOTH') ? Number(formData.get('saleStock')) : 0;

    const rentalPrice = (productType === 'RENTAL' || productType === 'BOTH') ? Number(formData.get('rentalPrice')) : 0;
    const rentalStock = (productType === 'RENTAL' || productType === 'BOTH') ? Number(formData.get('rentalStock')) : 0;

    const productData = {
      name: formData.get('name') as string,
      sku: formData.get('sku') as string,
      barcode: formData.get('barcode') as string,
      category: formData.get('category') as string,
      purchasePrice: Number(formData.get('purchasePrice')),
      sellingPrice,
      rentalPrice,
      taxPercent: Number(formData.get('taxPercent')) || 0,
      saleStock,
      rentalStock,
      minStockAlert: Number(formData.get('minStockAlert')),
      supplierId: formData.get('supplierId') as string,
      description: formData.get('description') as string,
    };

    if (productToEdit) {
        updateProduct(productToEdit.id, productData);
    } else {
        addProduct(productData);
    }

    setIsProductModalOpen(false);
    setProductToEdit(null);
    setProductType('BOTH'); // Reset
  };

  const handleStockUpdate = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    if (selectedProduct) {
      updateStock(
        selectedProduct,
        formData.get('pool') as 'SALE' | 'RENTAL',
        Number(formData.get('quantity')),
        formData.get('type') as 'IN' | 'OUT',
        formData.get('reason') as string
      );
    }
    setIsStockModalOpen(false);
  };

  const openAddModal = () => {
      setProductToEdit(null);
      setProductType('BOTH');
      setIsProductModalOpen(true);
  };

  const openEditModal = (product: Product) => {
      setProductToEdit(product);
      setProductType(getProductTypeDisplay(product));
      setIsProductModalOpen(true);
  };

  // Helper component for stock bar
  const StockBar = ({ current, max = 10, isLow, disabled }: { current: number, max?: number, isLow?: boolean, disabled?: boolean }) => {
      if (disabled) return <div className="h-1.5 w-16 mt-1 bg-gray-100 rounded-full opacity-50"></div>;

      const percentage = Math.min(100, (current / max) * 100);
      const color = current === 0 ? 'bg-gray-200' : isLow ? 'bg-orange-400' : 'bg-emerald-400';

      return (
          <div className="w-16 h-1.5 bg-gray-100 rounded-full overflow-hidden mt-1">
              <div className={`h-full rounded-full ${color}`} style={{ width: `${percentage}%` }}></div>
          </div>
      );
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-300 pb-10">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Inventory</h1>
          <p className="text-sm font-medium text-gray-400">Manage separate Sales & Rental pools</p>
        </div>
        <Button onClick={openAddModal} className="flex items-center gap-2 shadow-sky-200">
          <Plus size={20} /> Add Product
        </Button>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="p-5 border-0 shadow-sm bg-white">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-xs font-bold uppercase text-gray-400">Total Stock Value</p>
                    <h3 className="text-2xl font-black text-gray-800 mt-1">{formatCurrency(stats.totalValue)}</h3>
                </div>
                <div className="p-2 bg-emerald-50 text-emerald-600 rounded-lg">
                    <DollarSign size={20} />
                </div>
            </div>
            <p className="text-xs text-gray-400 mt-2">Combined retail & asset value</p>
        </Card>
        <Card className="p-5 border-0 shadow-sm bg-white">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-xs font-bold uppercase text-gray-400">Total Products</p>
                    <h3 className="text-2xl font-black text-gray-800 mt-1">{products.length}</h3>
                </div>
                <div className="p-2 bg-sky-50 text-sky-600 rounded-lg">
                    <Tags size={20} />
                </div>
            </div>
            <p className="text-xs text-gray-400 mt-2">{stats.totalItems} individual units</p>
        </Card>
        <Card className={`p-5 border-0 shadow-sm ${stats.lowStock > 0 ? 'bg-orange-50 border-orange-100' : 'bg-white'}`}>
            <div className="flex justify-between items-start">
                <div>
                    <p className={`text-xs font-bold uppercase ${stats.lowStock > 0 ? 'text-orange-600' : 'text-gray-400'}`}>Low Sales Stock</p>
                    <h3 className={`text-2xl font-black mt-1 ${stats.lowStock > 0 ? 'text-orange-700' : 'text-gray-800'}`}>{stats.lowStock}</h3>
                </div>
                <div className={`p-2 rounded-lg ${stats.lowStock > 0 ? 'bg-white text-orange-600' : 'bg-orange-50 text-orange-600'}`}>
                    <AlertTriangle size={20} />
                </div>
            </div>
            <p className={`text-xs mt-2 ${stats.lowStock > 0 ? 'text-orange-600' : 'text-gray-400'}`}>Items below alert threshold</p>
        </Card>
        <Card className={`p-5 border-0 shadow-sm ${stats.outOfStock > 0 ? 'bg-red-50 border-red-100' : 'bg-white'}`}>
            <div className="flex justify-between items-start">
                <div>
                    <p className={`text-xs font-bold uppercase ${stats.outOfStock > 0 ? 'text-red-600' : 'text-gray-400'}`}>Completely Out</p>
                    <h3 className={`text-2xl font-black mt-1 ${stats.outOfStock > 0 ? 'text-red-700' : 'text-gray-800'}`}>{stats.outOfStock}</h3>
                </div>
                <div className={`p-2 rounded-lg ${stats.outOfStock > 0 ? 'bg-white text-red-600' : 'bg-red-50 text-red-600'}`}>
                    <Box size={20} />
                </div>
            </div>
            <p className={`text-xs mt-2 ${stats.outOfStock > 0 ? 'text-red-600' : 'text-gray-400'}`}>Zero stock in both pools</p>
        </Card>
      </div>

      <div className="flex flex-col gap-4">
        {/* Search & Tabs */}
        <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
             <div className="relative w-full md:w-96">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                <input 
                    type="text" 
                    placeholder="Search by name, SKU..." 
                    className="w-full pl-11 pr-4 py-2.5 bg-white border border-gray-100 rounded-2xl outline-none focus:ring-2 focus:ring-sky-100 transition-all font-medium text-gray-600"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                />
            </div>

            <div className="flex bg-gray-100/50 p-1 rounded-xl">
               <button 
                 onClick={() => setStatusFilter('ALL')}
                 className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${statusFilter === 'ALL' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
               >
                 All Items
               </button>
               <button 
                 onClick={() => setStatusFilter('LOW')}
                 className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${statusFilter === 'LOW' ? 'bg-white text-orange-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
               >
                 Low Stock
               </button>
               <button 
                 onClick={() => setStatusFilter('OUT')}
                 className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${statusFilter === 'OUT' ? 'bg-white text-red-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
               >
                 Out of Stock
               </button>
            </div>
        </div>

        {/* Product Table */}
        <Card className="overflow-hidden border-0 shadow-sm">
            <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
                <thead>
                <tr className="bg-gray-50/50 border-b border-gray-100 text-gray-400">
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Product Info</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Category & SKU</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-center">Sale Stock</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-center">Rental Stock</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Actions</th>
                </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                {filteredProducts.map(product => {
                    const type = getProductTypeDisplay(product);
                    const isSaleEnabled = type === 'SALE' || type === 'BOTH';
                    const isRentalEnabled = type === 'RENTAL' || type === 'BOTH';

                    return (
                    <tr key={product.id} className="hover:bg-gray-50 transition-colors group">
                    <td className="px-6 py-4">
                        <div className="flex items-center space-x-4">
                        <div className={`w-12 h-12 rounded-xl flex items-center justify-center font-bold text-lg shadow-sm ${type === 'SALE' ? 'bg-emerald-50 text-emerald-500' : type === 'RENTAL' ? 'bg-sky-50 text-sky-500' : 'bg-indigo-50 text-indigo-500'}`}>
                            <Package size={20} />
                        </div>
                        <div>
                            <div className="font-bold text-gray-800">{product.name}</div>
                            <div className="flex items-center gap-2 mt-1">
                                {type === 'SALE' && <span className="text-[10px] font-bold bg-emerald-100 text-emerald-700 px-1.5 py-0.5 rounded">FOR SALE</span>}
                                {type === 'RENTAL' && <span className="text-[10px] font-bold bg-sky-100 text-sky-700 px-1.5 py-0.5 rounded">FOR RENT</span>}
                                {type === 'BOTH' && <span className="text-[10px] font-bold bg-indigo-100 text-indigo-700 px-1.5 py-0.5 rounded">HYBRID</span>}

                                {isSaleEnabled && product.saleStock <= product.minStockAlert && product.saleStock > 0 && (
                                    <span className="text-[10px] font-bold text-orange-600 bg-orange-50 px-2 py-0.5 rounded-full">Low Stock</span>
                                )}
                            </div>
                        </div>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                         <div className="text-gray-800 font-medium">{product.category}</div>
                         <div className="font-mono text-gray-400 text-xs mt-0.5">{product.sku}</div>
                    </td>
                    <td className="px-6 py-4 text-center">
                        {isSaleEnabled ? (
                            <div className="inline-flex flex-col items-center">
                                <span className={`font-bold text-lg ${product.saleStock === 0 ? 'text-gray-300' : 'text-gray-800'}`}>
                                    {product.saleStock}
                                </span>
                                <StockBar current={product.saleStock} max={product.minStockAlert * 3} isLow={product.saleStock <= product.minStockAlert} />
                            </div>
                        ) : (
                            <span className="text-gray-300 font-medium text-xs">—</span>
                        )}
                    </td>
                    <td className="px-6 py-4 text-center">
                        {isRentalEnabled ? (
                            <div className="inline-flex flex-col items-center">
                                <span className={`font-bold text-lg ${product.rentalStock === 0 ? 'text-gray-300' : 'text-sky-600'}`}>
                                    {product.rentalStock}
                                </span>
                                <StockBar current={product.rentalStock} max={5} />
                            </div>
                        ) : (
                             <span className="text-gray-300 font-medium text-xs">—</span>
                        )}
                    </td>
                    <td className="px-6 py-4 text-right">
                        <div className="flex items-center justify-end space-x-2">
                        <button 
                            onClick={() => openEditModal(product)}
                            className="p-2 text-indigo-500 bg-indigo-50 hover:bg-indigo-100 rounded-lg transition-colors"
                            title="Edit Product"
                        >
                            <Edit2 size={16} />
                        </button>
                        <button 
                            onClick={() => { setSelectedProduct(product.id); setIsStockModalOpen(true); }}
                            className="p-2 text-sky-500 bg-sky-50 hover:bg-sky-100 rounded-lg transition-colors"
                            title="Update Stock"
                        >
                            <RefreshCcw size={16} />
                        </button>
                        <button 
                            onClick={() => deleteProduct(product.id)}
                            className="p-2 text-gray-300 hover:text-pink-500 hover:bg-pink-50 rounded-lg transition-colors"
                        >
                            <Trash2 size={16} />
                        </button>
                        </div>
                    </td>
                    </tr>
                    );
                })}
                </tbody>
            </table>
            {filteredProducts.length === 0 && (
                <div className="py-20 text-center text-gray-400 italic">No products found matching your search.</div>
            )}
            </div>
        </Card>
      </div>

      {/* Add/Edit Product Modal */}
      <Modal 
        isOpen={isProductModalOpen} 
        onClose={() => setIsProductModalOpen(false)} 
        title={productToEdit ? "Edit Product" : "Add New Product"}
      >
        <form onSubmit={handleSaveProduct} className="grid grid-cols-1 md:grid-cols-2 gap-4">

          <div className="col-span-1 md:col-span-2 space-y-2 mb-2">
             <label className="text-xs font-bold uppercase text-gray-400">Product Purpose</label>
             <div className="grid grid-cols-3 gap-3">
                 <button 
                    type="button"
                    onClick={() => setProductType('SALE')}
                    className={`flex items-center justify-center gap-2 p-3 rounded-xl border-2 font-bold text-sm transition-all ${productType === 'SALE' ? 'border-emerald-500 bg-emerald-50 text-emerald-700' : 'border-gray-100 text-gray-500 hover:border-gray-200'}`}
                 >
                    <ShoppingBag size={16} /> Sale Only
                 </button>
                 <button 
                    type="button"
                    onClick={() => setProductType('RENTAL')}
                    className={`flex items-center justify-center gap-2 p-3 rounded-xl border-2 font-bold text-sm transition-all ${productType === 'RENTAL' ? 'border-sky-500 bg-sky-50 text-sky-700' : 'border-gray-100 text-gray-500 hover:border-gray-200'}`}
                 >
                    <RefreshCcw size={16} /> Rent Only
                 </button>
                 <button 
                    type="button"
                    onClick={() => setProductType('BOTH')}
                    className={`flex items-center justify-center gap-2 p-3 rounded-xl border-2 font-bold text-sm transition-all ${productType === 'BOTH' ? 'border-indigo-500 bg-indigo-50 text-indigo-700' : 'border-gray-100 text-gray-500 hover:border-gray-200'}`}
                 >
                    <Package size={16} /> Hybrid
                 </button>
             </div>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Product Name</label>
            <input name="name" defaultValue={productToEdit?.name} required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="e.g. Princess Dress" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">SKU</label>
            <input name="sku" defaultValue={productToEdit?.sku} required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="DRS-001" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Barcode</label>
            <input name="barcode" defaultValue={productToEdit?.barcode} className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="Scan or enter" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Category</label>
            <select name="category" defaultValue={productToEdit?.category} className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium">
              {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Purchase Cost</label>
            <input name="purchasePrice" type="number" defaultValue={productToEdit?.purchasePrice} required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="0" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Supplier</label>
            <select name="supplierId" defaultValue={productToEdit?.supplierId} className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium">
              {suppliers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
            </select>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Tax Rate (%)</label>
            <input name="taxPercent" type="number" defaultValue={productToEdit?.taxPercent || 12} className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" />
          </div>

          {(productType === 'SALE' || productType === 'BOTH') && (
            <div className="col-span-2 grid grid-cols-2 gap-4 pt-4 pb-2 border-t border-gray-100 animate-in fade-in slide-in-from-top-2">
                 <div className="col-span-2 flex items-center gap-2 mb-1">
                    <span className="w-2 h-2 rounded-full bg-emerald-500"></span>
                    <h4 className="text-xs font-bold text-gray-800 uppercase tracking-wider">Sale Details</h4>
                 </div>
                 <div className="space-y-1">
                    <label className="text-xs font-bold uppercase text-emerald-600">Selling Price</label>
                    <input name="sellingPrice" type="number" defaultValue={productToEdit?.sellingPrice} required className="w-full px-4 py-3 bg-emerald-50 border-transparent focus:bg-white border focus:border-emerald-200 rounded-xl outline-none transition-all font-medium" placeholder="0" />
                 </div>
                 <div className="space-y-1">
                    <label className="text-xs font-bold uppercase text-emerald-600">
                        {productToEdit ? 'Current Sale Stock' : 'Initial Sale Stock'}
                    </label>
                    <input name="saleStock" type="number" defaultValue={productToEdit?.saleStock} required className="w-full px-4 py-3 bg-emerald-50 border-transparent focus:bg-white border focus:border-emerald-200 rounded-xl outline-none transition-all font-medium" placeholder="0" />
                 </div>
            </div>
          )}

          {(productType === 'RENTAL' || productType === 'BOTH') && (
            <div className="col-span-2 grid grid-cols-2 gap-4 pt-4 pb-2 border-t border-gray-100 animate-in fade-in slide-in-from-top-2">
                 <div className="col-span-2 flex items-center gap-2 mb-1">
                    <span className="w-2 h-2 rounded-full bg-sky-500"></span>
                    <h4 className="text-xs font-bold text-gray-800 uppercase tracking-wider">Rental Details</h4>
                 </div>
                 <div className="space-y-1">
                    <label className="text-xs font-bold uppercase text-sky-600">Rental Price / Day</label>
                    <input name="rentalPrice" type="number" defaultValue={productToEdit?.rentalPrice} required className="w-full px-4 py-3 bg-sky-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="0" />
                 </div>
                 <div className="space-y-1">
                    <label className="text-xs font-bold uppercase text-sky-600">
                        {productToEdit ? 'Current Rental Stock' : 'Initial Rental Stock'}
                    </label>
                    <input name="rentalStock" type="number" defaultValue={productToEdit?.rentalStock} required className="w-full px-4 py-3 bg-sky-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="0" />
                 </div>
            </div>
          )}

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Min Alert Qty</label>
            <input name="minStockAlert" type="number" defaultValue={productToEdit?.minStockAlert || 3} required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" />
          </div>

          <div className="col-span-1 md:col-span-2 space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Description</label>
            <textarea name="description" defaultValue={productToEdit?.description} className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium h-24" placeholder="Product details..."></textarea>
          </div>
          <div className="col-span-1 md:col-span-2 flex gap-3 pt-4">
            <Button variant="ghost" onClick={() => setIsProductModalOpen(false)} className="flex-1">Cancel</Button>
            <Button type="submit" className="flex-1">{productToEdit ? 'Update Product' : 'Save Product'}</Button>
          </div>
        </form>
      </Modal>

      {/* Stock Update Modal */}
      <Modal 
        isOpen={isStockModalOpen} 
        onClose={() => setIsStockModalOpen(false)} 
        title="Update Stock Quantity"
      >
        <form onSubmit={handleStockUpdate} className="space-y-4">
          <div className="space-y-1">
             <label className="text-xs font-bold uppercase text-gray-400">Select Pool to Update</label>
             <div className="flex gap-4">
              <label className="flex-1 border rounded-xl p-3 flex items-center justify-center gap-2 cursor-pointer has-[:checked]:bg-emerald-50 has-[:checked]:border-emerald-500 has-[:checked]:text-emerald-700 transition-all">
                <input type="radio" name="pool" value="SALE" defaultChecked className="hidden" />
                <ShoppingBag size={18} /> Sales Stock
              </label>
              <label className="flex-1 border rounded-xl p-3 flex items-center justify-center gap-2 cursor-pointer has-[:checked]:bg-sky-50 has-[:checked]:border-sky-500 has-[:checked]:text-sky-700 transition-all">
                <input type="radio" name="pool" value="RENTAL" className="hidden" />
                <RefreshCcw size={18} /> Rental Pool
              </label>
            </div>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Adjustment Type</label>
            <div className="flex gap-4">
              <label className="flex-1 border rounded-xl p-3 flex items-center justify-center gap-2 cursor-pointer has-[:checked]:bg-green-50 has-[:checked]:border-green-500 has-[:checked]:text-green-700 transition-all">
                <input type="radio" name="type" value="IN" defaultChecked className="hidden" />
                <ArrowDownLeft size={18} /> Stock In
              </label>
              <label className="flex-1 border rounded-xl p-3 flex items-center justify-center gap-2 cursor-pointer has-[:checked]:bg-pink-50 has-[:checked]:border-pink-500 has-[:checked]:text-pink-700 transition-all">
                <input type="radio" name="type" value="OUT" className="hidden" />
                <ArrowUpRight size={18} /> Stock Out
              </label>
            </div>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Quantity</label>
            <input name="quantity" type="number" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="0" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Reason / Reference</label>
            <input name="reason" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-xl outline-none transition-all font-medium" placeholder="e.g. Bulk purchase, damage" />
          </div>
          <div className="flex gap-3 pt-4">
            <Button variant="ghost" onClick={() => setIsStockModalOpen(false)} className="flex-1">Cancel</Button>
            <Button type="submit" className="flex-1">Update Stock</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Inventory;

export enum RentalStatus {
  ACTIVE = 'ACTIVE',
  RETURNED = 'RETURNED',
  OVERDUE = 'OVERDUE'
}

export enum PaymentStatus {
  PAID = 'PAID',
  PARTIAL = 'PARTIAL',
  UNPAID = 'UNPAID'
}

export enum PaymentMethod {
  CASH = 'CASH',
  UPI = 'UPI',
  CARD = 'CARD',
  BANK_TRANSFER = 'BANK_TRANSFER'
}

export enum SalesChannel {
  IN_STORE = 'IN_STORE',
  AMAZON = 'AMAZON',
  FLIPKART = 'FLIPKART',
  MEESHO = 'MEESHO',
  WEBSITE = 'WEBSITE'
}

export enum OrderStatus {
  COMPLETED = 'COMPLETED',       // Instant for offline
  PENDING = 'PENDING',           // New online order
  READY_TO_SHIP = 'READY_TO_SHIP',
  SHIPPED = 'SHIPPED',
  DELIVERED = 'DELIVERED',
  RETURNED = 'RETURNED',
  CANCELLED = 'CANCELLED'
}

export enum UserRole {
  ADMIN = 'ADMIN',
  STAFF = 'STAFF'
}

export interface User {
  id: string;
  name: string;
  email: string;
  password: string; // In a real app, this should be hashed. Storing plain/base64 for this demo.
  role: UserRole;
  permissions: string[]; // List of specific module IDs this user can access
  avatar?: string;
  createdAt: string;
}

export interface Product {
  id: string;
  name: string;
  sku: string;
  barcode: string;
  category: string;
  purchasePrice: number;
  sellingPrice: number;
  rentalPrice: number; // Daily rate
  taxPercent: number;

  // Stock Split
  saleStock: number;   // Items available for purchase
  rentalStock: number; // Items available for rent

  minStockAlert: number;
  supplierId: string;
  description: string;
  imageUrl?: string;
  createdAt: string;
}

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email: string;
  address: string;
  gstin?: string;
  createdAt: string;
}

export interface Supplier {
  id: string;
  name: string;
  contactPerson: string;
  phone: string;
  email: string;
  address: string;
  createdAt: string;
}

export interface InvoiceItem {
  productId: string;
  name: string;
  quantity: number;
  unitPrice: number;
  taxAmount: number;
  total: number;
}

export interface Sale {
  id: string;
  invoiceNumber: string; // Internal Invoice ID
  externalOrderId?: string; // e.g., Amazon Order ID
  channel: SalesChannel;
  customerId: string; // For marketplaces, this might be a generic "Amazon Customer"
  items: InvoiceItem[];
  totalAmount: number; // Gross Sale Amount
  marketplaceFees: number; // Commission + Shipping + Fixed Fees
  netPayout: number; // Total - Fees
  taxTotal: number;
  discount: number;
  paidAmount: number;
  paymentStatus: PaymentStatus;
  paymentMethod: PaymentMethod;
  orderStatus: OrderStatus;
  date: string;
}

export interface Rental {
  id: string;
  invoiceNumber: string;
  customerId: string;
  productId: string;
  quantity: number;
  startDate: string;
  expectedReturnDate: string;
  actualReturnDate?: string;
  dailyRate: number;
  securityDeposit: number;
  totalRentAmount: number;
  lateFee: number;
  paidAmount: number;
  status: RentalStatus;
  paymentStatus: PaymentStatus;
  date: string;
}

export interface StockLog {
  id: string;
  productId: string;
  pool: 'SALE' | 'RENTAL';
  type: 'IN' | 'OUT';
  quantity: number;
  reason: string;
  date: string;
}

export interface StoreProfile {
  storeName: string;
  address: string;
  phone: string;
  email: string;
  gstin: string;
  website: string;
}

export interface AppSettings {
  defaultTaxRate: number;
  currency: string;
  enableLowStockAlerts: boolean;
  lowStockThreshold: number; // Default global threshold
  salesInvoicePrefix: string;
  rentalInvoicePrefix: string;
}

export interface AppNotification {
  id: string;
  type: 'INFO' | 'SUCCESS' | 'WARNING' | 'ERROR';
  category: 'SALE' | 'RENTAL' | 'INVENTORY' | 'SYSTEM' | 'CUSTOMER';
  title: string;
  message: string;
  timestamp: string;
  isRead: boolean;
  linkTo?: string; // Tab ID
}

export interface AppState {
  currentUser: User | null;
  users: User[];
  products: Product[];
  customers: Customer[];
  suppliers: Supplier[];
  sales: Sale[];
  rentals: Rental[];
  stockLogs: StockLog[];
  notifications: AppNotification[];
  storeProfile: StoreProfile;
  settings: AppSettings;
}

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { AppState, Product, Customer, Supplier, Sale, Rental, StockLog, RentalStatus, PaymentStatus, SalesChannel, OrderStatus, PaymentMethod, StoreProfile, AppSettings, User, UserRole, AppNotification } from '../types';
import { generateID } from '../utils/helpers';

interface AppContextType extends AppState {
  login: (email: string, pass: string) => boolean;
  logout: () => void;
  addUser: (user: Omit<User, 'id' | 'createdAt'>) => void;
  updateUser: (id: string, updates: Partial<User>) => void;
  deleteUser: (id: string) => void;
  addProduct: (product: Omit<Product, 'id' | 'createdAt'>) => void;
  updateProduct: (id: string, product: Partial<Product>) => void;
  deleteProduct: (id: string) => void;
  addCustomer: (customer: Omit<Customer, 'id' | 'createdAt'>) => void;
  addSupplier: (supplier: Omit<Supplier, 'id' | 'createdAt'>) => void;
  addSale: (sale: Omit<Sale, 'id' | 'invoiceNumber' | 'date' | 'netPayout'>) => void;
  updateOrderStatus: (saleId: string, status: OrderStatus) => void;
  addPaymentToSale: (saleId: string, amount: number) => void;
  addRental: (rental: Omit<Rental, 'id' | 'invoiceNumber' | 'date' | 'status' | 'lateFee' | 'actualReturnDate'>) => void;
  returnRental: (rentalId: string, lateFee: number) => void;
  updateStock: (productId: string, pool: 'SALE' | 'RENTAL', quantity: number, type: 'IN' | 'OUT', reason: string) => void;
  updateStoreProfile: (profile: Partial<StoreProfile>) => void;
  updateSettings: (settings: Partial<AppSettings>) => void;
  importData: (jsonData: string) => boolean;
  resetData: () => void;
  markNotificationsAsRead: () => void;
  clearNotifications: () => void;
}

