      {NAVIGATION_ITEMS.filter(item => {
        if (item.id === 'settings') return false; // Handled in header
        return canAccess(currentUser, item.id);
      }).map((item) => {
        const isActive = activeTab === item.id;
        return (
          <button
            key={item.id}
            onClick={() => onTabChange(item.id)}
            className={`
              relative w-full flex items-center gap-3.5 px-4 py-3 rounded-2xl text-sm font-bold transition-all duration-200
              ${isActive 
                ? 'bg-sky-50 text-sky-600 shadow-sm' 
                : 'text-gray-500 hover:text-gray-700 hover:bg-gray-50'
              }
            `}
          >
            <span className={`
              ${isActive ? 'text-sky-600' : 'text-gray-400'} 
              transition-colors duration-200
            `}>
              {React.isValidElement(item.icon) 
                ? React.cloneElement(item.icon as React.ReactElement<any>, { 
                    size: 20, 
                    strokeWidth: 2.5 
                  })
                : item.icon
              }
            </span>

            <span className="tracking-wide">{item.label}</span>

            {/* Notification Badge example for Inventory */}
            {item.id === 'inventory' && (
               <span className={`
                 ml-auto text-[10px] px-2 py-0.5 rounded-full font-bold transition-colors opacity-0 group-hover:opacity-100
                 ${isActive ? 'opacity-100 bg-pink-500 text-white' : ''}
               `}></span>
            )}
          </button>
        );
      })}
    </nav>
  </aside>
  );
};

const TopBar: React.FC<{ activeTab: string; onTabChange: (id: string) => void }> = ({ activeTab, onTabChange }) => {
  const { products, rentals, notifications, currentUser, logout, markNotificationsAsRead, clearNotifications } = useApp();
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const [activeNotifTab, setActiveNotifTab] = useState<'ALERTS' | 'ACTIVITY'>('ALERTS');
  const dropdownRef = useRef<HTMLDivElement>(null);

  const tabLabel = NAVIGATION_ITEMS.find(i => i.id === activeTab)?.label;
  const canAccessSettings = canAccess(currentUser, 'settings');

  // 1. Calculate System Alerts (Live Status)
  const lowStockItems = products.filter(p => p.saleStock <= p.minStockAlert);
  const overdueRentals = rentals.filter(r => r.status === 'ACTIVE' && new Date(r.expectedReturnDate) < new Date());

  const systemAlerts = [
    ...lowStockItems.map(p => ({
       id: `stock-${p.id}`,
       type: 'WARNING',
       title: 'Low Stock Alert',
       message: `${p.name} is running low (${p.saleStock} left).`,
       action: () => onTabChange('inventory'),
       icon: <AlertTriangle size={16} />
    })),
    ...overdueRentals.map(r => ({
       id: `rental-${r.id}`,
       type: 'ERROR',
       title: 'Overdue Rental',
       message: `Rental #${r.invoiceNumber} is overdue.`,
       action: () => onTabChange('rentals'),
       icon: <Clock size={16} />
    }))
  ];

  // 2. Activity Feed (From AppState)
  const activityFeed = notifications;
  const unreadActivityCount = notifications.filter(n => !n.isRead).length;

  const totalUnreadCount = systemAlerts.length + unreadActivityCount;

  // Close dropdowns on outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsNotificationsOpen(false);
        setIsUserMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const getNotifIcon = (type: string, category?: string) => {
      if (category === 'SALE') return <ShoppingBag size={16} />;
      if (category === 'RENTAL') return <RefreshCcw size={16} />;
      if (type === 'SUCCESS') return <CheckCircle2 size={16} />;
      if (type === 'ERROR') return <AlertTriangle size={16} />;
      if (type === 'INFO') return <Info size={16} />;
      return <Bell size={16} />;
  }

  const getNotifColor = (type: string) => {
      if (type === 'SUCCESS') return 'bg-emerald-50 text-emerald-600';
      if (type === 'ERROR') return 'bg-pink-50 text-pink-600';
      if (type === 'WARNING') return 'bg-orange-50 text-orange-600';
      return 'bg-sky-50 text-sky-600';
  }

  return (
    <header className="h-20 bg-white/90 backdrop-blur-md border-b border-gray-100 flex items-center justify-between px-6 md:px-8 sticky top-0 z-30 shadow-sm transition-all">
      <div className="flex items-center space-x-4">
        <button className="md:hidden p-2 text-gray-500 hover:bg-gray-100 rounded-lg">
           <Menu size={24} />
        </button>
        <div>
          <h2 className="text-xl font-black text-gray-800 tracking-tight">{tabLabel}</h2>
        </div>
      </div>

      <div className="flex items-center gap-2 md:gap-6" ref={dropdownRef}>
        {/* Search - Hidden on mobile */}
        <div className="hidden md:flex items-center bg-gray-100/50 rounded-2xl px-4 py-2.5 w-64 lg:w-80 focus-within:ring-2 focus-within:ring-sky-100 focus-within:bg-white transition-all border border-transparent focus-within:border-sky-100">
          <Search size={18} className="text-gray-400 mr-3 shrink-0" />
          <input 
            type="text" 
            placeholder="Quick search..." 
            className="bg-transparent text-sm outline-none w-full placeholder:text-gray-400 text-gray-700 font-medium"
          />
        </div>

        <div className="flex items-center gap-2">
          {/* Notifications */}
          <div className="relative">
            <button 
              onClick={() => setIsNotificationsOpen(!isNotificationsOpen)}
              className={`relative p-2.5 rounded-xl transition-all ${isNotificationsOpen ? 'bg-sky-50 text-sky-600' : 'text-gray-400 hover:bg-gray-100 hover:text-gray-600'}`}
            >
              <Bell size={20} strokeWidth={2.5} />
              {totalUnreadCount > 0 && (
                <span className="absolute top-2 right-2.5 w-2.5 h-2.5 bg-pink-500 rounded-full border-2 border-white animate-pulse"></span>
              )}
            </button>

            {isNotificationsOpen && (
              <div className="absolute right-0 top-full mt-3 w-80 md:w-96 bg-white shadow-2xl rounded-2xl border border-gray-100 overflow-hidden animate-in fade-in slide-in-from-top-2 origin-top-right">

                {/* Header with Tabs */}
                <div className="bg-gray-50 border-b border-gray-100">
                   <div className="flex p-2 gap-2">
                      <button 
                         onClick={() => setActiveNotifTab('ALERTS')}
                         className={`flex-1 py-2 text-xs font-bold rounded-xl transition-all flex items-center justify-center gap-2 ${activeNotifTab === 'ALERTS' ? 'bg-white shadow-sm text-gray-800' : 'text-gray-400 hover:text-gray-600'}`}
                      >
                         Alerts 
                         {systemAlerts.length > 0 && <span className="bg-pink-100 text-pink-600 px-1.5 rounded-md text-[10px]">{systemAlerts.length}</span>}
                      </button>
                      <button 
                         onClick={() => setActiveNotifTab('ACTIVITY')}
                         className={`flex-1 py-2 text-xs font-bold rounded-xl transition-all flex items-center justify-center gap-2 ${activeNotifTab === 'ACTIVITY' ? 'bg-white shadow-sm text-gray-800' : 'text-gray-400 hover:text-gray-600'}`}
                      >
                         Activity
                         {unreadActivityCount > 0 && <span className="bg-sky-100 text-sky-600 px-1.5 rounded-md text-[10px]">{unreadActivityCount}</span>}
                      </button>
                   </div>
                </div>

                <div className="max-h-[350px] overflow-y-auto custom-scrollbar bg-white">

                   {/* SYSTEM ALERTS TAB */}
                   {activeNotifTab === 'ALERTS' && (
                       <div>
                           {systemAlerts.length > 0 ? (
                               systemAlerts.map((alert, i) => (
                                   <div 
                                       key={i}
                                       onClick={() => { alert.action(); setIsNotificationsOpen(false); }}
                                       className="p-4 border-b border-gray-50 hover:bg-gray-50 cursor-pointer flex gap-3 group"
                                   >
                                       <div className={`mt-1 w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${alert.type === 'ERROR' ? 'bg-pink-50 text-pink-500' : 'bg-orange-50 text-orange-500'}`}>
                                           {alert.icon}
                                       </div>
                                       <div>
                                           <h4 className="text-xs font-bold text-gray-800 group-hover:text-sky-600 transition-colors">{alert.title}</h4>
                                           <p className="text-xs text-gray-500 mt-1 leading-relaxed">{alert.message}</p>
                                           <div className="flex gap-2 mt-2">
                                              <span className="text-[10px] font-bold bg-white border border-gray-200 px-2 py-0.5 rounded-md text-gray-500">Action Required</span>
                                           </div>
                                       </div>
                                   </div>
                               ))
                           ) : (
                               <div className="flex flex-col items-center justify-center py-12 text-center px-6">
                                   <div className="w-12 h-12 bg-emerald-50 text-emerald-500 rounded-full flex items-center justify-center mb-3">
                                       <CheckCircle2 size={24} />
                                   </div>
                                   <p className="text-sm font-bold text-gray-800">All Systems Normal</p>
                                   <p className="text-xs text-gray-400 mt-1">No low stock or overdue alerts.</p>
                               </div>
                           )}
                       </div>
                   )}

                   {/* ACTIVITY FEED TAB */}
                   {activeNotifTab === 'ACTIVITY' && (
                       <div>
                           {activityFeed.length > 0 ? (
                               activityFeed.map((note) => (
                                   <div 
                                       key={note.id}
                                       onClick={() => { if(note.linkTo) { onTabChange(note.linkTo); setIsNotificationsOpen(false); } }}
                                       className={`p-4 border-b border-gray-50 hover:bg-gray-50 cursor-pointer flex gap-3 group ${!note.isRead ? 'bg-sky-50/30' : ''}`}
                                   >
                                       <div className={`mt-1 w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${getNotifColor(note.type)}`}>
                                           {getNotifIcon(note.type, note.category)}
                                       </div>
                                       <div className="flex-1">
                                           <div className="flex justify-between items-start">
                                                <h4 className={`text-xs font-bold group-hover:text-sky-600 transition-colors ${!note.isRead ? 'text-gray-900' : 'text-gray-600'}`}>
                                                    {note.title}
                                                </h4>
                                                <span className="text-[10px] text-gray-400 whitespace-nowrap ml-2">
                                                    {formatDistanceToNow(parseISO(note.timestamp), { addSuffix: true }).replace('about ', '')}
                                                </span>
                                           </div>
                                           <p className="text-xs text-gray-500 mt-1 leading-relaxed">{note.message}</p>
                                       </div>
                                       {!note.isRead && (
                                           <div className="w-2 h-2 bg-sky-500 rounded-full shrink-0 mt-2"></div>
                                       )}
                                   </div>
                               ))
                           ) : (
                               <div className="flex flex-col items-center justify-center py-12 text-center px-6">
                                   <div className="w-12 h-12 bg-gray-50 text-gray-400 rounded-full flex items-center justify-center mb-3">
                                       <Bell size={24} />
                                   </div>
                                   <p className="text-sm font-bold text-gray-800">No recent activity</p>
                                   <p className="text-xs text-gray-400 mt-1">Transactions will appear here.</p>
                               </div>
                           )}
                       </div>
                   )}
                </div>

                {/* Footer Actions */}
                {activeNotifTab === 'ACTIVITY' && activityFeed.length > 0 && (
                   <div className="p-2 bg-gray-50 flex justify-between items-center border-t border-gray-100">
                      <button 
                        onClick={clearNotifications}
                        className="text-[10px] font-bold text-gray-400 hover:text-red-500 transition-colors px-2 py-1 flex items-center gap-1"
                      >
                        <Trash2 size={12} /> Clear History
                      </button>
                      <button 
                        onClick={markNotificationsAsRead}
                        className="text-[10px] font-bold text-sky-600 hover:text-sky-700 transition-colors px-2 py-1"
                      >
                        Mark all as read
                      </button>
                   </div>
                )}
              </div>
            )}
          </div>

          {/* Settings Button */}
          {canAccessSettings && (
            <button 
              onClick={() => onTabChange('settings')}
              className="hidden md:block p-2.5 text-gray-400 hover:bg-gray-100 hover:text-gray-600 rounded-xl transition-all"
              title="Settings"
            >
              <SettingsIcon size={20} strokeWidth={2.5} />
            </button>
          )}

          {/* User Menu (Mobile/Tablet) */}
          <div className="relative ml-2">
             <button 
               onClick={() => setIsUserMenuOpen(!isUserMenuOpen)}
               className="flex items-center gap-2 hover:bg-gray-50 p-1.5 pr-3 rounded-full transition-all border border-transparent hover:border-gray-100"
             >
                <div className={`w-8 h-8 rounded-full bg-gradient-to-tr ${currentUser?.role === UserRole.ADMIN ? 'from-indigo-400 to-indigo-600' : 'from-sky-400 to-sky-600'} text-white flex items-center justify-center shadow-md font-bold text-xs`}>
                   {currentUser?.name.charAt(0)}
                </div>
                <ChevronDown size={14} className="text-gray-400 hidden md:block" />
             </button>

             {isUserMenuOpen && (
               <div className="absolute right-0 top-full mt-3 w-48 bg-white shadow-xl rounded-xl border border-gray-100 overflow-hidden animate-in fade-in slide-in-from-top-2 origin-top-right">
                  <div className="p-3 border-b border-gray-50 bg-gray-50/50">
                     <p className="text-xs font-bold text-gray-800">{currentUser?.name}</p>
                     <div className="flex items-center gap-1 mt-0.5">
                       {currentUser?.role === UserRole.ADMIN ? <ShieldCheck size={10} className="text-indigo-500"/> : <User size={10} className="text-sky-500"/>}
                       <p className="text-[10px] text-gray-500 capitalize">{currentUser?.role.toLowerCase()}</p>
                     </div>
                  </div>
                  {canAccessSettings && (
                    <button onClick={() => { onTabChange('settings'); setIsUserMenuOpen(false); }} className="w-full text-left px-4 py-2.5 text-xs font-medium text-gray-600 hover:bg-gray-50 hover:text-sky-600 flex items-center gap-2">
                      <SettingsIcon size={14} /> Settings
                    </button>
                  )}
                  <button onClick={() => logout()} className="w-full text-left px-4 py-2.5 text-xs font-medium text-red-500 hover:bg-red-50 flex items-center gap-2">
                     <LogOut size={14} /> Logout
                  </button>
               </div>
             )}
          </div>
        </div>
      </div>
    </header>
  );
};

const AppContent: React.FC = () => {
  const { currentUser } = useApp();
  const [activeTab, setActiveTab] = useState('dashboard');

  if (!currentUser) {
    return <Login />;
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'inventory': return <Inventory />;
      case 'rentals': return <Rentals />;
      case 'customers': return <Customers />;
      case 'suppliers': return <Suppliers />;
      case 'sales': return <Sales />;
      case 'reports': return <Reports />;
      case 'users': return <Users />;
      case 'settings': return <Settings />;
      default: return <Dashboard />;
    }
  };

  return (
    <div className="flex h-screen bg-gray-50 font-sans text-gray-900">
      <Sidebar activeTab={activeTab} onTabChange={setActiveTab} />
      <div className="flex-1 flex flex-col h-screen overflow-hidden">
        <TopBar activeTab={activeTab} onTabChange={setActiveTab} />
        <main className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
          {renderContent()}
        </main>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  return (
    <AppProvider>
      <AppContent />
    </AppProvider>
  );
};

export default App;

