        <div className="flex items-center gap-2">
          {/* Notifications */}
          <div className="relative">
            <button 
              onClick={() => setIsNotificationsOpen(!isNotificationsOpen)}
              className={`relative p-2.5 rounded-md transition-all ${isNotificationsOpen ? 'bg-sky-50 text-sky-600' : 'text-gray-400 hover:bg-gray-100 hover:text-gray-600'}`}
            >
              <Bell size={20} strokeWidth={2.5} />
              {totalUnreadCount > 0 && (
                <span className="absolute top-2 right-2.5 w-2.5 h-2.5 bg-pink-500 rounded-full border-2 border-white animate-pulse"></span>
              )}
