            {isNotificationsOpen && (
              <div className="absolute right-0 top-full mt-3 w-80 md:w-96 bg-white shadow-2xl rounded-xl border border-gray-100 overflow-hidden animate-in fade-in slide-in-from-top-2 origin-top-right">

                {/* Header with Tabs */}
                <div className="bg-gray-50 border-b border-gray-100">
                   <div className="flex p-2 gap-2">
                      <button 
                         onClick={() => setActiveNotifTab('ALERTS')}
                         className={`flex-1 py-2 text-xs font-bold rounded-md transition-all flex items-center justify-center gap-2 ${activeNotifTab === 'ALERTS' ? 'bg-white shadow-sm text-gray-800' : 'text-gray-400 hover:text-gray-600'}`}
                      >
                         Alerts 
                         {systemAlerts.length > 0 && <span className="bg-pink-100 text-pink-600 px-1.5 rounded-md text-[10px]">{systemAlerts.length}</span>}
                      </button>
                      <button 
                         onClick={() => setActiveNotifTab('ACTIVITY')}
                         className={`flex-1 py-2 text-xs font-bold rounded-md transition-all flex items-center justify-center gap-2 ${activeNotifTab === 'ACTIVITY' ? 'bg-white shadow-sm text-gray-800' : 'text-gray-400 hover:text-gray-600'}`}
                      >
                         Activity
                         {unreadActivityCount > 0 && <span className="bg-sky-100 text-sky-600 px-1.5 rounded-md text-[10px]">{unreadActivityCount}</span>}
                      </button>
                   </div>
                </div>

                <div className="max-h-[350px] overflow-y-auto custom-scrollbar bg-white">

                   {/* SYSTEM ALERTS TAB */}
                   {activeNotifTab === 'ALERTS' && (
                       <div>
                           {systemAlerts.length > 0 ? (
                               systemAlerts.map((alert, i) => (
                                   <div 
                                       key={i}
                                       onClick={() => { alert.action(); setIsNotificationsOpen(false); }}
                                       className="p-4 border-b border-gray-50 hover:bg-gray-50 cursor-pointer flex gap-3 group"
                                   >
                                       <div className={`mt-1 w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${alert.type === 'ERROR' ? 'bg-pink-50 text-pink-500' : 'bg-orange-50 text-orange-500'}`}>
                                           {alert.icon}
                                       </div>
                                       <div>
                                           <h4 className="text-xs font-bold text-gray-800 group-hover:text-sky-600 transition-colors">{alert.title}</h4>
                                           <p className="text-xs text-gray-500 mt-1 leading-relaxed">{alert.message}</p>
                                           <div className="flex gap-2 mt-2">
                                              <span className="text-[10px] font-bold bg-white border border-gray-200 px-2 py-0.5 rounded text-gray-500">Action Required</span>
                                           </div>
                                       </div>
                                   </div>
                               ))
                           ) : (
                               <div className="flex flex-col items-center justify-center py-12 text-center px-6">
                                   <div className="w-12 h-12 bg-emerald-50 text-emerald-500 rounded-full flex items-center justify-center mb-3">
                                       <CheckCircle2 size={24} />
                                   </div>
                                   <p className="text-sm font-bold text-gray-800">All Systems Normal</p>
                                   <p className="text-xs text-gray-400 mt-1">No low stock or overdue alerts.</p>
                               </div>
                           )}
                       </div>
                   )}

                   {/* ACTIVITY FEED TAB */}
                   {activeNotifTab === 'ACTIVITY' && (
                       <div>
                           {activityFeed.length > 0 ? (
                               activityFeed.map((note) => (
                                   <div 
                                       key={note.id}
                                       onClick={() => { if(note.linkTo) { onTabChange(note.linkTo); setIsNotificationsOpen(false); } }}
                                       className={`p-4 border-b border-gray-50 hover:bg-gray-50 cursor-pointer flex gap-3 group ${!note.isRead ? 'bg-sky-50/30' : ''}`}
                                   >
                                       <div className={`mt-1 w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${getNotifColor(note.type)}`}>
                                           {getNotifIcon(note.type, note.category)}
                                       </div>
                                       <div className="flex-1">
                                           <div className="flex justify-between items-start">
                                                <h4 className={`text-xs font-bold group-hover:text-sky-600 transition-colors ${!note.isRead ? 'text-gray-900' : 'text-gray-600'}`}>
                                                    {note.title}
                                                </h4>
                                                <span className="text-[10px] text-gray-400 whitespace-nowrap ml-2">
                                                    {formatDistanceToNow(parseISO(note.timestamp), { addSuffix: true }).replace('about ', '')}
                                                </span>
                                           </div>
                                           <p className="text-xs text-gray-500 mt-1 leading-relaxed">{note.message}</p>
                                       </div>
                                       {!note.isRead && (
                                           <div className="w-2 h-2 bg-sky-500 rounded-full shrink-0 mt-2"></div>
                                       )}
                                   </div>
                               ))
                           ) : (
                               <div className="flex flex-col items-center justify-center py-12 text-center px-6">
                                   <div className="w-12 h-12 bg-gray-50 text-gray-400 rounded-full flex items-center justify-center mb-3">
                                       <Bell size={24} />
                                   </div>
                                   <p className="text-sm font-bold text-gray-800">No recent activity</p>
                                   <p className="text-xs text-gray-400 mt-1">Transactions will appear here.</p>
                               </div>
                           )}
                       </div>
                   )}
                </div>

                {/* Footer Actions */}
                {activeNotifTab === 'ACTIVITY' && activityFeed.length > 0 && (
                   <div className="p-2 bg-gray-50 flex justify-between items-center border-t border-gray-100">
                      <button 
                        onClick={clearNotifications}
                        className="text-[10px] font-bold text-gray-400 hover:text-red-500 transition-colors px-2 py-1 flex items-center gap-1"
                      >
                        <Trash2 size={12} /> Clear History
                      </button>
                      <button 
                        onClick={markNotificationsAsRead}
                        className="text-[10px] font-bold text-sky-600 hover:text-sky-700 transition-colors px-2 py-1"
                      >
                        Mark all as read
                      </button>
                   </div>
                )}
              </div>
            )}
          </div>

          {/* Settings Button */}
          {canAccessSettings && (
            <button 
              onClick={() => onTabChange('settings')}
              className="hidden md:block p-2.5 text-gray-400 hover:bg-gray-100 hover:text-gray-600 rounded-md transition-all"
              title="Settings"
            >
              <SettingsIcon size={20} strokeWidth={2.5} />
            </button>
          )}

          {/* User Menu (Mobile/Tablet) */}
          <div className="relative ml-2">
             <button 
               onClick={() => setIsUserMenuOpen(!isUserMenuOpen)}
               className="flex items-center gap-2 hover:bg-gray-50 p-1.5 pr-3 rounded-full transition-all border border-transparent hover:border-gray-100"
             >
                <div className={`w-8 h-8 rounded-full bg-gradient-to-tr ${currentUser?.role === UserRole.ADMIN ? 'from-indigo-400 to-indigo-600' : 'from-sky-400 to-sky-600'} text-white flex items-center justify-center shadow-md font-bold text-xs`}>
                   {currentUser?.name.charAt(0)}
                </div>
                <ChevronDown size={14} className="text-gray-400 hidden md:block" />
             </button>

             {isUserMenuOpen && (
               <div className="absolute right-0 top-full mt-3 w-48 bg-white shadow-xl rounded-lg border border-gray-100 overflow-hidden animate-in fade-in slide-in-from-top-2 origin-top-right">
                  <div className="p-3 border-b border-gray-50 bg-gray-50/50">
                     <p className="text-xs font-bold text-gray-800">{currentUser?.name}</p>
                     <div className="flex items-center gap-1 mt-0.5">
                       {currentUser?.role === UserRole.ADMIN ? <ShieldCheck size={10} className="text-indigo-500"/> : <User size={10} className="text-sky-500"/>}
                       <p className="text-[10px] text-gray-500 capitalize">{currentUser?.role.toLowerCase()}</p>
                     </div>
                  </div>
                  {canAccessSettings && (
                    <button onClick={() => { onTabChange('settings'); setIsUserMenuOpen(false); }} className="w-full text-left px-4 py-2.5 text-xs font-medium text-gray-600 hover:bg-gray-50 hover:text-sky-600 flex items-center gap-2">
                      <SettingsIcon size={14} /> Settings
                    </button>
                  )}
                  <button onClick={() => logout()} className="w-full text-left px-4 py-2.5 text-xs font-medium text-red-500 hover:bg-red-50 flex items-center gap-2">
                     <LogOut size={14} /> Logout
                  </button>
               </div>
             )}
          </div>
        </div>
      </div>
    </header>
  );
};

const AppContent: React.FC = () => {
  const { currentUser } = useApp();
  const [activeTab, setActiveTab] = useState('dashboard');

  if (!currentUser) {
    return <Login />;
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'inventory': return <Inventory />;
      case 'rentals': return <Rentals />;
      case 'customers': return <Customers />;
      case 'suppliers': return <Suppliers />;
      case 'sales': return <Sales />;
      case 'reports': return <Reports />;
      case 'users': return <Users />;
      case 'settings': return <Settings />;
      default: return <Dashboard />;
    }
  };

  return (
    <div className="flex h-screen bg-gray-50 font-sans text-gray-900">
      <Sidebar activeTab={activeTab} onTabChange={setActiveTab} />
      <div className="flex-1 flex flex-col h-screen overflow-hidden">
        <TopBar activeTab={activeTab} onTabChange={setActiveTab} />
        <main className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
          {renderContent()}
        </main>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  return (
    <AppProvider>
      <AppContent />
    </AppProvider>
  );
};

export default App;

import React, { useMemo } from 'react';
import { useApp } from '../store/AppContext';
import { Card } from '../components/Shared';
import { formatCurrency } from '../utils/helpers';
import { 
  TrendingUp, 
  Users, 
  Package, 
  AlertTriangle, 
  Clock, 
  ArrowUpRight, 
  ShoppingBag, 
  Activity,
  CreditCard,
  RefreshCcw,
  Store,
  ArrowRight,
  PlusCircle,
  UserPlus,
  Truck
} from 'lucide-react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, Legend
} from 'recharts';
import { format, subDays, isSameDay, parseISO } from 'date-fns';

const Dashboard: React.FC = () => {
  const { sales, rentals, products, customers } = useApp();

  // 1. Key Metrics Calculation
  const totalRevenue = sales.reduce((sum, s) => sum + s.totalAmount, 0) + 
                       rentals.reduce((sum, r) => sum + r.totalRentAmount, 0);

  const netProfit = sales.reduce((sum, s) => sum + s.netPayout, 0) + 
                    rentals.reduce((sum, r) => sum + r.totalRentAmount, 0);

  const activeRentals = rentals.filter(r => r.status === 'ACTIVE').length;
  const lowStockItems = products.filter(p => p.saleStock <= p.minStockAlert);
  const totalCustomers = customers.length;

  // 2. Chart Data (Last 7 Days)
  const chartData = useMemo(() => {
    const data = [];
    const today = new Date();
    for (let i = 6; i >= 0; i--) {
      const date = subDays(today, i);
      const daySales = sales.filter(s => isSameDay(parseISO(s.date), date))
                            .reduce((sum, s) => sum + s.totalAmount, 0);
      const dayRentals = rentals.filter(r => isSameDay(parseISO(r.date), date))
                              .reduce((sum, r) => sum + r.totalRentAmount, 0);
      data.push({
        name: format(date, 'EEE'),
        fullDate: format(date, 'dd MMM'),
        sales: daySales,
        rentals: dayRentals
      });
    }
    return data;
  }, [sales, rentals]);

  // 3. Channel Distribution Data
  const channelData = useMemo(() => {
    const counts: Record<string, number> = {};
    sales.forEach(s => {
      counts[s.channel] = (counts[s.channel] || 0) + s.totalAmount;
    });
    if (Object.keys(counts).length === 0) return [{ name: 'No Sales', value: 1 }];
    return Object.keys(counts).map(key => ({ name: key, value: counts[key] }));
  }, [sales]);

  // 4. Recent Activity Feed
  const recentActivity = useMemo(() => {
     const _sales = sales.map(s => ({ 
       id: s.id, 
       type: 'SALE', 
       amount: s.totalAmount, 
       date: s.date,
       details: `${s.items.length} items`,
       status: s.orderStatus,
       ref: s.invoiceNumber
     }));
     const _rentals = rentals.map(r => ({ 
       id: r.id, 
       type: 'RENTAL', 
       amount: r.totalRentAmount, 
       date: r.date,
       details: 'Rental Duration',
       status: r.status,
       ref: r.invoiceNumber
     }));
     return [..._sales, ..._rentals]
        .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
        .slice(0, 5);
  }, [sales, rentals]);

  const COLORS = ['#0ea5e9', '#f43f5e', '#10b981', '#f59e0b', '#8b5cf6'];

  const quickActions = [
    { label: 'New Sale', icon: <ShoppingBag size={20} />, color: 'bg-emerald-500', link: 'sales' },
    { label: 'New Rental', icon: <RefreshCcw size={20} />, color: 'bg-sky-500', link: 'rentals' },
    { label: 'Add Product', icon: <PlusCircle size={20} />, color: 'bg-indigo-500', link: 'inventory' },
    { label: 'Add Customer', icon: <UserPlus size={20} />, color: 'bg-pink-500', link: 'customers' },
  ];

  return (
    <div className="space-y-6 animate-in fade-in duration-300 pb-10">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Dashboard</h1>
          <p className="text-sm font-medium text-gray-400">Overview of your store's performance</p>
        </div>
        <div className="text-right hidden md:block">
          <p className="text-xs font-bold text-gray-400 uppercase tracking-wider">Today's Date</p>
          <p className="text-lg font-bold text-gray-700">{format(new Date(), 'EEEE, dd MMMM')}</p>
        </div>
      </div>

      {/* Quick Actions */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {quickActions.map((action, idx) => (
          <button 
            key={idx}
            onClick={() => window.location.hash = action.link}
            className="flex items-center gap-3 p-4 bg-white rounded-lg border border-gray-100 shadow-sm hover:shadow-md transition-all group"
          >
            <div className={`w-10 h-10 rounded-md ${action.color} text-white flex items-center justify-center shadow-md group-hover:scale-110 transition-transform`}>
              {action.icon}
            </div>
            <span className="font-bold text-gray-700 text-sm">{action.label}</span>
          </button>
        ))}
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="p-5 border-0 shadow-sm relative overflow-hidden bg-gradient-to-br from-white to-gray-50">
          <div className="flex justify-between items-start z-10 relative">
            <div>
              <p className="text-xs font-bold uppercase text-gray-400 tracking-wider">Total Revenue</p>
              <h3 className="text-2xl font-black text-gray-800 mt-1">{formatCurrency(totalRevenue)}</h3>
              <div className="flex items-center gap-1 mt-2 text-xs font-bold text-emerald-600 bg-emerald-50 w-fit px-2 py-1 rounded-full">
                <ArrowUpRight size={12} /> +12.5%
              </div>
            </div>
            <div className="p-3 bg-indigo-50 text-indigo-600 rounded-lg">
              <TrendingUp size={20} />
            </div>
          </div>
        </Card>

        <Card className="p-5 border-0 shadow-sm relative overflow-hidden">
          <div className="flex justify-between items-start z-10 relative">
            <div>
              <p className="text-xs font-bold uppercase text-gray-400 tracking-wider">Net Profit</p>
              <h3 className="text-2xl font-black text-gray-800 mt-1">{formatCurrency(netProfit)}</h3>
              <p className="text-[10px] text-gray-400 mt-2">After marketplace fees</p>
            </div>
            <div className="p-3 bg-emerald-50 text-emerald-600 rounded-lg">
              <CreditCard size={20} />
            </div>
          </div>
        </Card>

        <Card className="p-5 border-0 shadow-sm relative overflow-hidden">
           <div className="flex justify-between items-start z-10 relative">
            <div>
              <p className="text-xs font-bold uppercase text-gray-400 tracking-wider">Active Renting</p>
              <h3 className="text-2xl font-black text-gray-800 mt-1">{activeRentals}</h3>
              <div className="flex items-center gap-1 mt-2 text-xs font-bold text-sky-600 bg-sky-50 w-fit px-2 py-1 rounded-full">
                <Clock size={12} /> Items Out
