        <Card className="p-5 border-0 shadow-sm relative overflow-hidden">
           <div className="flex justify-between items-start z-10 relative">
            <div>
              <p className="text-xs font-bold uppercase text-gray-400 tracking-wider">Customers</p>
              <h3 className="text-2xl font-black text-gray-800 mt-1">{totalCustomers}</h3>
              <p className="text-[10px] text-gray-400 mt-2">Total registered</p>
            </div>
            <div className="p-3 bg-pink-50 text-pink-500 rounded-lg">
              <Users size={20} />
            </div>
          </div>
        </Card>
      </div>

      {/* Main Content Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Left Column: Charts */}
        <div className="lg:col-span-2 space-y-6">
          {/* Revenue Chart */}
          <Card className="p-6 border-0 shadow-sm">
            <div className="flex items-center justify-between mb-6">
              <h3 className="font-bold text-gray-800 flex items-center gap-2">
