                 <h3 className={`font-bold flex items-center gap-2 ${lowStockItems.length > 0 ? 'text-pink-700' : 'text-gray-800'}`}>
                    <AlertTriangle size={18} className={lowStockItems.length > 0 ? 'text-pink-600' : 'text-gray-400'} />
                    Sales Inventory
                 </h3>
                 {lowStockItems.length > 0 && <span className="bg-white text-pink-600 px-2 py-1 rounded-md text-xs font-black shadow-sm">{lowStockItems.length} Alerts</span>}
              </div>

              {lowStockItems.length > 0 ? (
                <div className="space-y-3">
                   {lowStockItems.slice(0, 3).map(p => (
                      <div key={p.id} className="bg-white/60 p-3 rounded-lg flex items-center justify-between">
                         <div className="flex items-center gap-3">
                            <div className="w-8 h-8 rounded-md bg-pink-100 text-pink-600 flex items-center justify-center font-bold text-xs">
                               {p.saleStock}
                            </div>
                            <div className="min-w-0">
                               <p className="text-xs font-bold text-gray-800 truncate w-24 sm:w-32">{p.name}</p>
                               <p className="text-[10px] text-pink-600">Below limit ({p.minStockAlert})</p>
                            </div>
                         </div>
                      </div>
                   ))}
                   {lowStockItems.length > 3 && (
                      <p className="text-center text-xs text-pink-600 font-bold mt-2">+ {lowStockItems.length - 3} more items</p>
                   )}
                </div>
              ) : (
                <div className="text-center py-6">
                   <div className="w-12 h-12 bg-green-50 text-green-500 rounded-full flex items-center justify-center mx-auto mb-2">
                      <Package size={20} />
                   </div>
                   <p className="text-sm font-bold text-gray-600">Stock Healthy</p>
                   <p className="text-xs text-gray-400">Sales items are above minimum levels.</p>
                </div>
              )}
           </Card>

           {/* Channel Distribution */}
           <Card className="p-6 border-0 shadow-sm flex flex-col h-[320px]">
              <h3 className="font-bold text-gray-800 mb-2 flex items-center gap-2">
                 <Store size={18} className="text-gray-400" /> Sales Channel
              </h3>
              <div className="flex-1 w-full relative">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={channelData}
                      cx="50%"
                      cy="50%"
                      innerRadius={50}
                      outerRadius={80}
                      paddingAngle={5}
                      dataKey="value"
                    >
                      {channelData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" height={36} iconType="circle" />
                  </PieChart>
                </ResponsiveContainer>
              </div>
           </Card>

           <div className="bg-gradient-to-br from-indigo-500 to-indigo-700 rounded-xl p-6 text-white shadow-lg shadow-indigo-200">
              <h3 className="font-bold text-lg mb-1">Stock Tip</h3>
              <p className="text-indigo-100 text-sm mb-4">
                 Items can be moved between Sales and Rental pools via the "Update Stock" action in Inventory.
              </p>
              <button onClick={() => window.location.hash = 'inventory'} className="bg-white/20 hover:bg-white/30 transition-colors text-white text-xs font-bold px-4 py-2 rounded-lg flex items-center gap-2">
                 Manage Stock <ArrowRight size={14} />
              </button>
           </div>
        </div>

      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { useApp } from '../store/AppContext';
import { Card, Button, Modal } from '../components/Shared';
import { 
  Plus, 
  Search, 
  Filter, 
  Edit2, 
  Trash2, 
  ArrowUpRight, 
  ArrowDownLeft,
  Package,
  AlertTriangle,
  Tags,
  DollarSign,
  Box,
  ShoppingBag,
  RefreshCcw,
  Check
} from 'lucide-react';
import { formatCurrency } from '../utils/helpers';
import { CATEGORIES } from '../constants';
import { Product } from '../types';

const Inventory: React.FC = () => {
  const { products, addProduct, updateProduct, deleteProduct, updateStock, suppliers } = useApp();
  const [isProductModalOpen, setIsProductModalOpen] = useState(false);
  const [isStockModalOpen, setIsStockModalOpen] = useState(false);

  const [selectedProduct, setSelectedProduct] = useState<string | null>(null); // For Stock Update Modal (ID only)
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);   // For Edit Modal (Full Object)

  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'ALL' | 'LOW' | 'OUT'>('ALL');

  // New State for Product Purpose Selection
  const [productType, setProductType] = useState<'SALE' | 'RENTAL' | 'BOTH'>('BOTH');

  // Stats Calculation
  const stats = useMemo(() => {
    const totalItems = products.reduce((acc, p) => acc + p.saleStock + p.rentalStock, 0);
    const totalValue = products.reduce((acc, p) => acc + (p.purchasePrice * (p.saleStock + p.rentalStock)), 0); // Asset value based on purchase price
    const lowStock = products.filter(p => p.saleStock > 0 && p.saleStock <= p.minStockAlert).length; // Only count if it's a sale item
    const outOfStock = products.filter(p => p.saleStock === 0 && p.rentalStock === 0).length;
    return { totalItems, totalValue, lowStock, outOfStock };
  }, [products]);

  const filteredProducts = products.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          p.sku.toLowerCase().includes(searchTerm.toLowerCase());

    if (statusFilter === 'LOW') return matchesSearch && p.saleStock > 0 && p.saleStock <= p.minStockAlert;
    if (statusFilter === 'OUT') return matchesSearch && p.saleStock === 0 && p.rentalStock === 0;

    return matchesSearch;
  });

  // Helper to determine product type string for display/edit
  const getProductTypeDisplay = (p: Product) => {
      const isSale = p.sellingPrice > 0 || p.saleStock > 0;
      const isRent = p.rentalPrice > 0 || p.rentalStock > 0;
      if (isSale && isRent) return 'BOTH';
      if (isRent) return 'RENTAL';
      return 'SALE';
  }

  const handleSaveProduct = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);

    // Determine values based on type selection
    const sellingPrice = (productType === 'SALE' || productType === 'BOTH') ? Number(formData.get('sellingPrice')) : 0;
    const saleStock = (productType === 'SALE' || productType === 'BOTH') ? Number(formData.get('saleStock')) : 0;

    const rentalPrice = (productType === 'RENTAL' || productType === 'BOTH') ? Number(formData.get('rentalPrice')) : 0;
    const rentalStock = (productType === 'RENTAL' || productType === 'BOTH') ? Number(formData.get('rentalStock')) : 0;

    const productData = {
      name: formData.get('name') as string,
      sku: formData.get('sku') as string,
      barcode: formData.get('barcode') as string,
      category: formData.get('category') as string,
      purchasePrice: Number(formData.get('purchasePrice')),
      sellingPrice,
      rentalPrice,
      taxPercent: Number(formData.get('taxPercent')) || 0,
      saleStock,
      rentalStock,
      minStockAlert: Number(formData.get('minStockAlert')),
      supplierId: formData.get('supplierId') as string,
      description: formData.get('description') as string,
    };

    if (productToEdit) {
        updateProduct(productToEdit.id, productData);
    } else {
        addProduct(productData);
    }

    setIsProductModalOpen(false);
    setProductToEdit(null);
    setProductType('BOTH'); // Reset
  };

  const handleStockUpdate = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    if (selectedProduct) {
      updateStock(
        selectedProduct,
        formData.get('pool') as 'SALE' | 'RENTAL',
        Number(formData.get('quantity')),
        formData.get('type') as 'IN' | 'OUT',
        formData.get('reason') as string
      );
    }
    setIsStockModalOpen(false);
  };

  const openAddModal = () => {
      setProductToEdit(null);
      setProductType('BOTH');
      setIsProductModalOpen(true);
  };

  const openEditModal = (product: Product) => {
      setProductToEdit(product);
      setProductType(getProductTypeDisplay(product));
      setIsProductModalOpen(true);
  };

  // Helper component for stock bar
  const StockBar = ({ current, max = 10, isLow, disabled }: { current: number, max?: number, isLow?: boolean, disabled?: boolean }) => {
      if (disabled) return <div className="h-1.5 w-16 mt-1 bg-gray-100 rounded-full opacity-50"></div>;

      const percentage = Math.min(100, (current / max) * 100);
      const color = current === 0 ? 'bg-gray-200' : isLow ? 'bg-orange-400' : 'bg-emerald-400';

      return (
          <div className="w-16 h-1.5 bg-gray-100 rounded-full overflow-hidden mt-1">
              <div className={`h-full rounded-full ${color}`} style={{ width: `${percentage}%` }}></div>
          </div>
      );
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-300 pb-10">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Inventory</h1>
          <p className="text-sm font-medium text-gray-400">Manage separate Sales & Rental pools</p>
        </div>
        <Button onClick={openAddModal} className="flex items-center gap-2 shadow-sky-200">
          <Plus size={20} /> Add Product
        </Button>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="p-5 border-0 shadow-sm bg-white">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-xs font-bold uppercase text-gray-400">Total Stock Value</p>
                    <h3 className="text-2xl font-black text-gray-800 mt-1">{formatCurrency(stats.totalValue)}</h3>
                </div>
                <div className="p-2 bg-emerald-50 text-emerald-600 rounded-md">
                    <DollarSign size={20} />
                </div>
            </div>
            <p className="text-xs text-gray-400 mt-2">Combined retail & asset value</p>
        </Card>
        <Card className="p-5 border-0 shadow-sm bg-white">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-xs font-bold uppercase text-gray-400">Total Products</p>
                    <h3 className="text-2xl font-black text-gray-800 mt-1">{products.length}</h3>
                </div>
                <div className="p-2 bg-sky-50 text-sky-600 rounded-md">
                    <Tags size={20} />
                </div>
            </div>
            <p className="text-xs text-gray-400 mt-2">{stats.totalItems} individual units</p>
        </Card>
        <Card className={`p-5 border-0 shadow-sm ${stats.lowStock > 0 ? 'bg-orange-50 border-orange-100' : 'bg-white'}`}>
            <div className="flex justify-between items-start">
                <div>
                    <p className={`text-xs font-bold uppercase ${stats.lowStock > 0 ? 'text-orange-600' : 'text-gray-400'}`}>Low Sales Stock</p>
                    <h3 className={`text-2xl font-black mt-1 ${stats.lowStock > 0 ? 'text-orange-700' : 'text-gray-800'}`}>{stats.lowStock}</h3>
                </div>
                <div className={`p-2 rounded-md ${stats.lowStock > 0 ? 'bg-white text-orange-600' : 'bg-orange-50 text-orange-600'}`}>
                    <AlertTriangle size={20} />
                </div>
            </div>
            <p className={`text-xs mt-2 ${stats.lowStock > 0 ? 'text-orange-600' : 'text-gray-400'}`}>Items below alert threshold</p>
        </Card>
        <Card className={`p-5 border-0 shadow-sm ${stats.outOfStock > 0 ? 'bg-red-50 border-red-100' : 'bg-white'}`}>
            <div className="flex justify-between items-start">
                <div>
                    <p className={`text-xs font-bold uppercase ${stats.outOfStock > 0 ? 'text-red-600' : 'text-gray-400'}`}>Completely Out</p>
                    <h3 className={`text-2xl font-black mt-1 ${stats.outOfStock > 0 ? 'text-red-700' : 'text-gray-800'}`}>{stats.outOfStock}</h3>
                </div>
                <div className={`p-2 rounded-md ${stats.outOfStock > 0 ? 'bg-white text-red-600' : 'bg-red-50 text-red-600'}`}>
                    <Box size={20} />
                </div>
            </div>
            <p className={`text-xs mt-2 ${stats.outOfStock > 0 ? 'text-red-600' : 'text-gray-400'}`}>Zero stock in both pools</p>
        </Card>
      </div>

      <div className="flex flex-col gap-4">
        {/* Search & Tabs */}
        <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
             <div className="relative w-full md:w-96">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                <input 
                    type="text" 
                    placeholder="Search by name, SKU..." 
                    className="w-full pl-11 pr-4 py-2.5 bg-white border border-gray-100 rounded-lg outline-none focus:ring-2 focus:ring-sky-100 transition-all font-medium text-gray-600"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                />
            </div>

            <div className="flex bg-gray-100/50 p-1 rounded-lg">
               <button 
                 onClick={() => setStatusFilter('ALL')}
                 className={`px-4 py-2 rounded-md text-xs font-bold transition-all ${statusFilter === 'ALL' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
               >
                 All Items
               </button>
               <button 
                 onClick={() => setStatusFilter('LOW')}
                 className={`px-4 py-2 rounded-md text-xs font-bold transition-all ${statusFilter === 'LOW' ? 'bg-white text-orange-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
               >
                 Low Stock
               </button>
               <button 
                 onClick={() => setStatusFilter('OUT')}
                 className={`px-4 py-2 rounded-md text-xs font-bold transition-all ${statusFilter === 'OUT' ? 'bg-white text-red-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
               >
                 Out of Stock
               </button>
            </div>
        </div>

        {/* Product Table */}
        <Card className="overflow-hidden border-0 shadow-sm">
            <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
                <thead>
                <tr className="bg-gray-50/50 border-b border-gray-100 text-gray-400">
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Product Info</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Category & SKU</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-center">Sale Stock</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-center">Rental Stock</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Actions</th>
                </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                {filteredProducts.map(product => {
                    const type = getProductTypeDisplay(product);
                    const isSaleEnabled = type === 'SALE' || type === 'BOTH';
                    const isRentalEnabled = type === 'RENTAL' || type === 'BOTH';

                    return (
                    <tr key={product.id} className="hover:bg-gray-50 transition-colors group">
                    <td className="px-6 py-4">
                        <div className="flex items-center space-x-4">
                        <div className={`w-12 h-12 rounded-lg flex items-center justify-center font-bold text-lg shadow-sm ${type === 'SALE' ? 'bg-emerald-50 text-emerald-500' : type === 'RENTAL' ? 'bg-sky-50 text-sky-500' : 'bg-indigo-50 text-indigo-500'}`}>
                            <Package size={20} />
                        </div>
                        <div>
                            <div className="font-bold text-gray-800">{product.name}</div>
                            <div className="flex items-center gap-2 mt-1">
                                {type === 'SALE' && <span className="text-[10px] font-bold bg-emerald-100 text-emerald-700 px-1.5 py-0.5 rounded">FOR SALE</span>}
                                {type === 'RENTAL' && <span className="text-[10px] font-bold bg-sky-100 text-sky-700 px-1.5 py-0.5 rounded">FOR RENT</span>}
                                {type === 'BOTH' && <span className="text-[10px] font-bold bg-indigo-100 text-indigo-700 px-1.5 py-0.5 rounded">HYBRID</span>}

                                {isSaleEnabled && product.saleStock <= product.minStockAlert && product.saleStock > 0 && (
                                    <span className="text-[10px] font-bold text-orange-600 bg-orange-50 px-2 py-0.5 rounded-full">Low Stock</span>
                                )}
                            </div>
                        </div>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                         <div className="text-gray-800 font-medium">{product.category}</div>
                         <div className="font-mono text-gray-400 text-xs mt-0.5">{product.sku}</div>
                    </td>
                    <td className="px-6 py-4 text-center">
                        {isSaleEnabled ? (
                            <div className="inline-flex flex-col items-center">
                                <span className={`font-bold text-lg ${product.saleStock === 0 ? 'text-gray-300' : 'text-gray-800'}`}>
                                    {product.saleStock}
                                </span>
                                <StockBar current={product.saleStock} max={product.minStockAlert * 3} isLow={product.saleStock <= product.minStockAlert} />
                            </div>
                        ) : (
                            <span className="text-gray-300 font-medium text-xs">—</span>
                        )}
                    </td>
                    <td className="px-6 py-4 text-center">
                        {isRentalEnabled ? (
                            <div className="inline-flex flex-col items-center">
                                <span className={`font-bold text-lg ${product.rentalStock === 0 ? 'text-gray-300' : 'text-sky-600'}`}>
                                    {product.rentalStock}
                                </span>
                                <StockBar current={product.rentalStock} max={5} />
                            </div>
                        ) : (
                             <span className="text-gray-300 font-medium text-xs">—</span>
                        )}
                    </td>
                    <td className="px-6 py-4 text-right">
                        <div className="flex items-center justify-end space-x-2">
                        <button 
                            onClick={() => openEditModal(product)}
                            className="p-2 text-indigo-500 bg-indigo-50 hover:bg-indigo-100 rounded-md transition-colors"
                            title="Edit Product"
                        >
                            <Edit2 size={16} />
                        </button>
                        <button 
                            onClick={() => { setSelectedProduct(product.id); setIsStockModalOpen(true); }}
                            className="p-2 text-sky-500 bg-sky-50 hover:bg-sky-100 rounded-md transition-colors"
                            title="Update Stock"
                        >
                            <RefreshCcw size={16} />
                        </button>
                        <button 
                            onClick={() => deleteProduct(product.id)}
                            className="p-2 text-gray-300 hover:text-pink-500 hover:bg-pink-50 rounded-md transition-colors"
                        >
                            <Trash2 size={16} />
                        </button>
                        </div>
                    </td>
                    </tr>
                    );
                })}
                </tbody>
            </table>
            {filteredProducts.length === 0 && (
                <div className="py-20 text-center text-gray-400 italic">No products found matching your search.</div>
            )}
            </div>
        </Card>
      </div>

      {/* Add/Edit Product Modal */}
      <Modal 
        isOpen={isProductModalOpen} 
        onClose={() => setIsProductModalOpen(false)} 
        title={productToEdit ? "Edit Product" : "Add New Product"}
      >
        <form onSubmit={handleSaveProduct} className="grid grid-cols-1 md:grid-cols-2 gap-4">

          <div className="col-span-1 md:col-span-2 space-y-2 mb-2">
             <label className="text-xs font-bold uppercase text-gray-400">Product Purpose</label>
             <div className="grid grid-cols-3 gap-3">
                 <button 
                    type="button"
                    onClick={() => setProductType('SALE')}
                    className={`flex items-center justify-center gap-2 p-3 rounded-lg border-2 font-bold text-sm transition-all ${productType === 'SALE' ? 'border-emerald-500 bg-emerald-50 text-emerald-700' : 'border-gray-100 text-gray-500 hover:border-gray-200'}`}
                 >
                    <ShoppingBag size={16} /> Sale Only
                 </button>
                 <button 
                    type="button"
                    onClick={() => setProductType('RENTAL')}
                    className={`flex items-center justify-center gap-2 p-3 rounded-lg border-2 font-bold text-sm transition-all ${productType === 'RENTAL' ? 'border-sky-500 bg-sky-50 text-sky-700' : 'border-gray-100 text-gray-500 hover:border-gray-200'}`}
                 >
                    <RefreshCcw size={16} /> Rent Only
                 </button>
                 <button 
                    type="button"
                    onClick={() => setProductType('BOTH')}
                    className={`flex items-center justify-center gap-2 p-3 rounded-lg border-2 font-bold text-sm transition-all ${productType === 'BOTH' ? 'border-indigo-500 bg-indigo-50 text-indigo-700' : 'border-gray-100 text-gray-500 hover:border-gray-200'}`}
                 >
                    <Package size={16} /> Hybrid
                 </button>
             </div>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Product Name</label>
            <input name="name" defaultValue={productToEdit?.name} required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium" placeholder="e.g. Princess Dress" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">SKU</label>
            <input name="sku" defaultValue={productToEdit?.sku} required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium" placeholder="DRS-001" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Barcode</label>
            <input name="barcode" defaultValue={productToEdit?.barcode} className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium" placeholder="Scan or enter" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Category</label>
            <select name="category" defaultValue={productToEdit?.category} className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium">
              {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Purchase Cost</label>
            <input name="purchasePrice" type="number" defaultValue={productToEdit?.purchasePrice} required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium" placeholder="0" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Supplier</label>
            <select name="supplierId" defaultValue={productToEdit?.supplierId} className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium">
              {suppliers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
            </select>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Tax Rate (%)</label>
            <input name="taxPercent" type="number" defaultValue={productToEdit?.taxPercent || 12} className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium" />
          </div>

          {(productType === 'SALE' || productType === 'BOTH') && (
            <div className="col-span-2 grid grid-cols-2 gap-4 pt-4 pb-2 border-t border-gray-100 animate-in fade-in slide-in-from-top-2">
                 <div className="col-span-2 flex items-center gap-2 mb-1">
                    <span className="w-2 h-2 rounded-full bg-emerald-500"></span>
                    <h4 className="text-xs font-bold text-gray-800 uppercase tracking-wider">Sale Details</h4>
                 </div>
                 <div className="space-y-1">
                    <label className="text-xs font-bold uppercase text-emerald-600">Selling Price</label>
                    <input name="sellingPrice" type="number" defaultValue={productToEdit?.sellingPrice} required className="w-full px-4 py-3 bg-emerald-50 border-transparent focus:bg-white border focus:border-emerald-200 rounded-lg outline-none transition-all font-medium" placeholder="0" />
                 </div>
