             { id: SalesChannel.AMAZON, label: 'Amazon', icon: <ShoppingBag size={14} /> },
             { id: SalesChannel.FLIPKART, label: 'Flipkart', icon: <ShoppingBag size={14} /> },
             { id: SalesChannel.MEESHO, label: 'Meesho', icon: <Smartphone size={14} /> },
           ].map(tab => (
             <button
                key={tab.id}
                onClick={() => setChannelFilter(tab.id as any)}
                className={`px-4 py-2 rounded-md text-xs font-bold flex items-center gap-2 transition-all whitespace-nowrap ${channelFilter === tab.id ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
             >
                {tab.icon} {tab.label}
             </button>
           ))}
