              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filteredSales.map(sale => {
                  const customer = customers.find(c => c.id === sale.customerId);
                  return (
                    <tr key={sale.id} className="hover:bg-gray-50 transition-colors group">
                    <td className="px-6 py-4">
                        <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-lg border text-[10px] font-bold uppercase tracking-wider ${getChannelStyle(sale.channel)}`}>
