                            value={sale.orderStatus}
                            onChange={(e) => updateOrderStatus(sale.id, e.target.value as OrderStatus)}
                            disabled={sale.orderStatus === OrderStatus.COMPLETED || sale.orderStatus === OrderStatus.CANCELLED}
                        >
                            {Object.values(OrderStatus).map(status => (
                                <option key={status} value={status}>{status.replace(/_/g, ' ')}</option>
                            ))}
                        </select>
                    </td>
                    </tr>
                  );
              })}
            </tbody>
          </table>
          {filteredSales.length === 0 && (
            <div className="py-20 text-center text-gray-400 italic">No sales found matching your criteria.</div>
          )}
        </div>
      </Card>

      {/* Record Sale Modal */}
      <Modal isOpen={isAddModalOpen} onClose={() => setIsAddModalOpen(false)} title="Record New Sale">
        <form onSubmit={handleCreateSale} className="grid grid-cols-1 md:grid-cols-2 gap-4">
