             <AlertCircle size={16} className="mt-0.5 shrink-0" />
             <div>
                 <p className="font-bold mb-1">
                    {selectedChannel === SalesChannel.IN_STORE ? 'In-Store Transaction' : 'Marketplace Order'}
                 </p>
                 <p>
                    {selectedChannel === SalesChannel.IN_STORE 
                      ? 'Stock is deducted immediately. Payment is marked as collected.' 
                      : 'Stock is deducted. Fees are recorded for Net Payout calculation. Payment status is pending payout.'}
                 </p>
             </div>
          </div>

          <div className="space-y-1">
             <label className="text-xs font-bold uppercase text-gray-400">Sales Channel</label>
             <select 
                name="channel" 
                className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium"
                value={selectedChannel}
                onChange={(e) => setSelectedChannel(e.target.value as SalesChannel)}
             >
                {Object.values(SalesChannel).map(c => <option key={c} value={c}>{c}</option>)}
             </select>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Product</label>
            <select 
                name="productId" 
                required 
                className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium"
                onChange={(e) => {
                    const product = products.find(p => p.id === e.target.value);
                    if (product) setSelectedProductPrice(product.sellingPrice);
                }}
            >
              <option value="">Select Item...</option>
              {products.map(p => <option key={p.id} value={p.id} disabled={p.saleStock === 0}>{p.name} (Qty: {p.saleStock})</option>)}
            </select>
          </div>

          {selectedChannel !== SalesChannel.IN_STORE && (
            <div className="space-y-1">
                <label className="text-xs font-bold uppercase text-gray-400">External Order ID</label>
                <input name="externalOrderId" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium" placeholder="e.g. #404-1234567" />
            </div>
          )}

          {selectedChannel === SalesChannel.IN_STORE && (
            <div className="space-y-1">
                <label className="text-xs font-bold uppercase text-gray-400">Customer</label>
                <select name="customerId" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium">
                <option value="">Guest (Walk-in)</option>
                {customers.filter(c => !c.id.startsWith('C_')).map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
            </div>
          )}

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Quantity</label>
            <input 
                name="quantity" 
                type="number" 
                min="1" 
                value={quantity}
                onChange={(e) => setQuantity(Number(e.target.value))}
                required 
                className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium" 
            />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Unit Price</label>
            <input 
                name="unitPrice" 
                type="number" 
                value={selectedProductPrice}
                onChange={(e) => setSelectedProductPrice(Number(e.target.value))}
                className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium" 
            />
          </div>

          {selectedChannel !== SalesChannel.IN_STORE && (
            <div className="space-y-1">
                <label className="text-xs font-bold uppercase text-gray-400">Marketplace Fees</label>
                <input 
                    name="marketplaceFees" 
                    type="number" 
                    value={fees}
                    onChange={(e) => setFees(Number(e.target.value))}
                    className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium" 
                    placeholder="Commissions + Shipping" 
                />
            </div>
          )}

          <div className="space-y-1">
             <label className="text-xs font-bold uppercase text-gray-400">Payment Method</label>
             <select name="paymentMethod" className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium">
                {Object.values(PaymentMethod).map(m => <option key={m} value={m}>{m}</option>)}
             </select>
          </div>

          {/* Financial Summary Preview */}
          <div className="col-span-1 md:col-span-2 bg-gray-50 rounded-lg p-4 border border-gray-100 mt-2">
             <div className="flex justify-between items-center mb-2">
                <span className="text-sm font-medium text-gray-500">Total Sale Amount:</span>
                <span className="text-sm font-bold text-gray-800">{formatCurrency(estimatedTotal)}</span>
             </div>
             {selectedChannel !== SalesChannel.IN_STORE && (
                 <>
                    <div className="flex justify-between items-center mb-2 text-xs">
                        <span className="font-medium text-gray-400">Less: Marketplace Fees</span>
                        <span className="font-bold text-red-400">- {formatCurrency(fees)}</span>
                    </div>
                    <div className="flex justify-between items-center pt-2 border-t border-gray-200">
                        <span className="text-sm font-bold text-gray-700 flex items-center gap-2"><Calculator size={14}/> Est. Net Payout:</span>
                        <span className="text-base font-black text-emerald-600">{formatCurrency(estimatedNet)}</span>
                    </div>
                 </>
             )}
          </div>

          <div className="col-span-1 md:col-span-2 flex gap-3 pt-4">
            <Button variant="ghost" onClick={() => setIsAddModalOpen(false)} className="flex-1">Cancel</Button>
            <Button type="submit" className="flex-1">Record Sale</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Sales;

import React, { useState } from 'react';
import { useApp } from '../store/AppContext';
import { Card, Button, Modal } from '../components/Shared';
import { NAVIGATION_ITEMS } from '../constants';
import { 
  Plus, 
  Search, 
  ShieldCheck, 
  User as UserIcon, 
  Mail, 
  Trash2, 
  Lock,
  Edit2,
  CheckCircle2,
  AlertOctagon,
  Unlock,
  KeyRound
} from 'lucide-react';
import { UserRole } from '../types';

const Users: React.FC = () => {
  const { users, currentUser, addUser, updateUser, deleteUser } = useApp();
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingUserId, setEditingUserId] = useState<string | null>(null);

  // Local state for form
  const [selectedRole, setSelectedRole] = useState<UserRole>(UserRole.STAFF);
  const [userPermissions, setUserPermissions] = useState<string[]>([]);

  // Security Guard: Only Admins can access this page
  if (currentUser?.role !== UserRole.ADMIN) {
    return (
      <div className="flex flex-col items-center justify-center h-[60vh] text-center animate-in fade-in zoom-in duration-300">
         <div className="bg-red-50 p-6 rounded-3xl text-red-500 mb-6 shadow-sm border border-red-100">
            <AlertOctagon size={48} />
         </div>
         <h2 className="text-3xl font-black text-gray-800 tracking-tight">Access Restricted</h2>
         <p className="text-gray-400 mt-3 font-medium max-w-md mx-auto leading-relaxed">
           You do not have permission to view the User Management module. 
           Please contact your system administrator.
         </p>
      </div>
    );
  }

  const filteredUsers = users.filter(u => 
    u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    u.email.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const userData = {
      name: formData.get('name') as string,
      email: formData.get('email') as string,
      password: formData.get('password') as string,
      role: selectedRole,
      permissions: selectedRole === UserRole.ADMIN ? [] : userPermissions,
    };

    if (editingUserId) {
      updateUser(editingUserId, userData);
      setEditingUserId(null);
    } else {
      addUser(userData);
    }
    setIsAddModalOpen(false);
  };

  const togglePermission = (id: string) => {
    setUserPermissions(prev => 
      prev.includes(id) 
        ? prev.filter(p => p !== id) 
        : [...prev, id]
    );
  };

  const openEdit = (user: any) => {
    setEditingUserId(user.id);
    setSelectedRole(user.role);
    setUserPermissions(user.permissions || []);
    setIsAddModalOpen(true);
  };

  const openAdd = () => {
    setEditingUserId(null);
    setSelectedRole(UserRole.STAFF);
    setUserPermissions(['dashboard', 'sales', 'inventory']); // Default for new staff
    setIsAddModalOpen(true);
  };

  const handleDelete = (id: string) => {
    if (confirm('Are you sure you want to remove this user? This action cannot be undone.')) {
      deleteUser(id);
    }
  };

  const editingUser = editingUserId ? users.find(u => u.id === editingUserId) : null;

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-800 tracking-tight">User Management</h1>
          <p className="text-sm font-medium text-gray-400">Create users and assign specific permissions</p>
        </div>
        <Button onClick={openAdd} className="flex items-center gap-2 shadow-sky-200">
          <Plus size={20} /> Add User
        </Button>
      </div>

      <div className="relative max-w-md">
        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
        <input 
          type="text" 
          placeholder="Search by name or email..." 
          className="w-full pl-11 pr-4 py-3 bg-white border border-gray-100 rounded-lg outline-none focus:ring-2 focus:ring-sky-100 transition-all font-medium text-gray-600"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <Card className="overflow-hidden border-0 shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead>
              <tr className="bg-gray-50/50 border-b border-gray-100 text-gray-400">
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">User</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Role</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Access Scope</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Joined</th>
                <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filteredUsers.map(user => (
                <tr key={user.id} className="hover:bg-gray-50 transition-colors">
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-3">
                      <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white font-bold shadow-sm ${user.role === 'ADMIN' ? 'bg-gradient-to-br from-indigo-500 to-purple-600' : 'bg-gradient-to-br from-emerald-400 to-teal-500'}`}>
                         {user.name.charAt(0)}
                      </div>
                      <div>
                        <div className="font-bold text-gray-800 flex items-center gap-2">
                           {user.name} 
                           {user.id === currentUser?.id && <span className="bg-gray-100 text-gray-500 text-[10px] px-1.5 py-0.5 rounded font-bold border border-gray-200">YOU</span>}
                        </div>
                        <div className="text-xs text-gray-400 flex items-center gap-1 mt-0.5 font-medium">
                           <Mail size={12} /> {user.email}
                        </div>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold uppercase tracking-wide ${
                       user.role === UserRole.ADMIN ? 'bg-indigo-50 text-indigo-700' : 'bg-emerald-50 text-emerald-700'
                    }`}>
                       {user.role === UserRole.ADMIN ? <ShieldCheck size={12} /> : <UserIcon size={12} />}
                       {user.role}
                    </div>
                  </td>
                  <td className="px-6 py-4">
                     {user.role === UserRole.ADMIN ? (
                       <span className="text-xs font-bold text-indigo-400">Full System Control</span>
                     ) : (
                       <div className="flex flex-wrap gap-1">
                          {user.permissions && user.permissions.length > 0 ? (
                            user.permissions.slice(0, 3).map(p => {
                               const item = NAVIGATION_ITEMS.find(i => i.id === p);
                               return (
                                 <span key={p} className="bg-gray-100 text-gray-500 text-[10px] px-2 py-0.5 rounded border border-gray-200 capitalize">
                                   {item?.label || p}
                                 </span>
                               )
                            })
                          ) : (
                             <span className="text-xs text-gray-400 italic">No access</span>
                          )}
                          {user.permissions && user.permissions.length > 3 && (
                             <span className="bg-gray-50 text-gray-400 text-[10px] px-1.5 py-0.5 rounded border border-gray-100">
                               +{user.permissions.length - 3}
                             </span>
                          )}
                       </div>
                     )}
                  </td>
                  <td className="px-6 py-4">
                     <span className="text-gray-500 font-medium text-xs">{new Date(user.createdAt).toLocaleDateString()}</span>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex items-center justify-end gap-2">
                       <button onClick={() => openEdit(user)} className="p-2 text-gray-400 hover:text-sky-600 hover:bg-sky-50 rounded-md transition-colors" title="Edit User">
                         <Edit2 size={16} />
                       </button>
                       {user.id !== currentUser?.id && (
                          <button onClick={() => handleDelete(user.id)} className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-md transition-colors" title="Delete User">
                            <Trash2 size={16} />
                          </button>
                       )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Card>

      {/* Add/Edit User Modal */}
      <Modal 
        isOpen={isAddModalOpen} 
        onClose={() => setIsAddModalOpen(false)} 
        title={editingUserId ? "Edit User & Access" : "Create New User"}
      >
        <form onSubmit={handleSubmit} className="grid grid-cols-1 gap-5">
          {/* User Details Section */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-1">
                <label className="text-xs font-bold uppercase text-gray-400">Full Name</label>
                <input name="name" defaultValue={editingUser?.name} required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium" placeholder="Jane Doe" />
            </div>
            <div className="space-y-1">
                <label className="text-xs font-bold uppercase text-gray-400">Email Address</label>
                <input name="email" type="email" defaultValue={editingUser?.email} required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium" placeholder="jane@kiddies.store" />
            </div>
