export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('inventory_pro_data');
    if (saved) {
      const parsed = JSON.parse(saved);
      // Migration: Map old stockQuantity to saleStock if saleStock is undefined
      const migratedProducts = (parsed.products || []).map((p: any) => ({
        ...p,
        saleStock: p.saleStock ?? p.stockQuantity ?? 0,
        rentalStock: p.rentalStock ?? 0
      }));

      const sessionUser = localStorage.getItem('inventory_pro_session');

      return {
        ...INITIAL_DATA,
        ...parsed,
        products: migratedProducts,
        notifications: parsed.notifications || INITIAL_DATA.notifications,
        currentUser: sessionUser ? JSON.parse(sessionUser) : null,
        users: parsed.users || INITIAL_DATA.users,
        storeProfile: { ...INITIAL_DATA.storeProfile, ...parsed.storeProfile },
        settings: { ...INITIAL_DATA.settings, ...parsed.settings }
      };
    }
    return INITIAL_DATA;
  });

  useEffect(() => {
    const { currentUser, ...persistentState } = state;
    localStorage.setItem('inventory_pro_data', JSON.stringify(persistentState));
  }, [state]);

  // -- HELPER: Internal Notification Generator --
  const createNotification = (
      type: 'INFO' | 'SUCCESS' | 'WARNING' | 'ERROR', 
      category: 'SALE' | 'RENTAL' | 'INVENTORY' | 'SYSTEM' | 'CUSTOMER',
      title: string, 
      message: string,
      linkTo?: string
  ): AppNotification => ({
    id: generateID(),
    type,
    category,
    title,
    message,
    timestamp: new Date().toISOString(),
    isRead: false,
    linkTo
  });

  // -- AUTH --
  const login = (email: string, pass: string) => {
    const user = state.users.find(u => u.email === email && u.password === pass);
    if (user) {
      setState(prev => ({ ...prev, currentUser: user }));
      localStorage.setItem('inventory_pro_session', JSON.stringify(user));
      return true;
    }
    return false;
  };

  const logout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    localStorage.removeItem('inventory_pro_session');
  };

  // -- USERS --
  const addUser = (u: Omit<User, 'id' | 'createdAt'>) => {
    const newUser: User = { 
      ...u, 
      id: generateID(), 
      createdAt: new Date().toISOString(),
      permissions: u.role === UserRole.ADMIN ? [] : (u.permissions || [])
    };
    setState(prev => ({ ...prev, users: [...prev.users, newUser] }));
  };

  const updateUser = (id: string, updates: Partial<User>) => {
    setState(prev => ({
      ...prev,
      users: prev.users.map(u => {
        if (u.id !== id) return u;
        const newRole = updates.role || u.role;
        const newPermissions = newRole === UserRole.ADMIN ? [] : (updates.permissions || u.permissions);
        return { ...u, ...updates, permissions: newPermissions };
      })
    }));
  };

  const deleteUser = (id: string) => {
    setState(prev => ({ ...prev, users: prev.users.filter(u => u.id !== id) }));
  };

  // -- OTHER ENTITIES --
  const addProduct = (p: Omit<Product, 'id' | 'createdAt'>) => {
    const newProduct: Product = { ...p, id: generateID(), createdAt: new Date().toISOString() };
    setState(prev => ({ 
      ...prev, 
      products: [...prev.products, newProduct],
      notifications: [
        createNotification('SUCCESS', 'INVENTORY', 'Product Added', `Added ${newProduct.name} to inventory`, 'inventory'),
        ...prev.notifications
      ]
    }));
  };

  const updateProduct = (id: string, updates: Partial<Product>) => {
    setState(prev => ({
      ...prev,
      products: prev.products.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const deleteProduct = (id: string) => {
    setState(prev => ({ ...prev, products: prev.products.filter(p => p.id !== id) }));
  };

  const addCustomer = (c: Omit<Customer, 'id' | 'createdAt'>) => {
    const newCustomer: Customer = { ...c, id: generateID(), createdAt: new Date().toISOString() };
    setState(prev => ({ 
      ...prev, 
      customers: [...prev.customers, newCustomer],
      notifications: [
        createNotification('INFO', 'CUSTOMER', 'New Customer', `${newCustomer.name} has been registered`, 'customers'),
        ...prev.notifications
      ]
    }));
  };

  const addSupplier = (s: Omit<Supplier, 'id' | 'createdAt'>) => {
    const newSupplier: Supplier = { ...s, id: generateID(), createdAt: new Date().toISOString() };
    setState(prev => ({ ...prev, suppliers: [...prev.suppliers, newSupplier] }));
  };

  const addSale = (s: Omit<Sale, 'id' | 'invoiceNumber' | 'date' | 'netPayout'>) => {
    const prefix = state.settings.salesInvoicePrefix || 'INV-';
    const newSale: Sale = {
      ...s,
      id: generateID(),
      invoiceNumber: `${prefix}${state.sales.length + 1001}`,
      netPayout: s.totalAmount - s.marketplaceFees,
      date: new Date().toISOString()
    };

    // SALES deduct from SALE STOCK
    s.items.forEach(item => {
      updateStock(item.productId, 'SALE', item.quantity, 'OUT', `Sale ${newSale.invoiceNumber} (${s.channel})`);
    });

    setState(prev => ({ 
      ...prev, 
      sales: [...prev.sales, newSale],
      notifications: [
        createNotification('SUCCESS', 'SALE', 'New Order', `Invoice ${newSale.invoiceNumber} created for ${s.channel}`, 'sales'),
        ...prev.notifications
      ]
    }));
  };

  const updateOrderStatus = (saleId: string, status: OrderStatus) => {
     setState(prev => ({
        ...prev,
        sales: prev.sales.map(s => s.id === saleId ? { ...s, orderStatus: status } : s)
     }));
  };

  const addPaymentToSale = (saleId: string, amount: number) => {
    setState(prev => ({
      ...prev,
      sales: prev.sales.map(s => {
        if (s.id === saleId) {
          const newPaidAmount = s.paidAmount + amount;
          return {
            ...s,
            paidAmount: newPaidAmount,
            paymentStatus: newPaidAmount >= (s.channel === SalesChannel.IN_STORE ? s.totalAmount : s.netPayout) ? PaymentStatus.PAID : PaymentStatus.PARTIAL
          };
        }
        return s;
      }),
      notifications: [
        createNotification('SUCCESS', 'SALE', 'Payment Received', `Recorded payment of ${amount} for sale`, 'sales'),
        ...prev.notifications
      ]
    }));
  };

  const addRental = (r: Omit<Rental, 'id' | 'invoiceNumber' | 'date' | 'status' | 'lateFee' | 'actualReturnDate'>) => {
    const prefix = state.settings.rentalInvoicePrefix || 'RNT-';
    const newRental: Rental = {
      ...r,
      id: generateID(),
      invoiceNumber: `${prefix}${state.rentals.length + 1001}`,
      date: new Date().toISOString(),
      status: RentalStatus.ACTIVE,
      lateFee: 0
    };

    // RENTALS deduct from RENTAL STOCK
    updateStock(r.productId, 'RENTAL', r.quantity, 'OUT', `Rental ${newRental.invoiceNumber}`);
    setState(prev => ({ 
      ...prev, 
      rentals: [...prev.rentals, newRental],
      notifications: [
        createNotification('SUCCESS', 'RENTAL', 'New Rental', `Rental ${newRental.invoiceNumber} booked`, 'rentals'),
        ...prev.notifications
      ]
    }));
  };

  const updateRental = (id: string, updates: Partial<Rental>) => {
    setState(prev => ({
      ...prev,
      rentals: prev.rentals.map(r => r.id === id ? { ...r, ...updates } : r)
    }));
  };

  const returnRental = (id: string, lateFee: number) => {
    const rental = state.rentals.find(r => r.id === id);
    if (!rental) return;

    // RETURNS add back to RENTAL STOCK
    updateStock(rental.productId, 'RENTAL', rental.quantity, 'IN', `Return ${rental.invoiceNumber}`);

    setState(prev => ({
      ...prev,
      rentals: prev.rentals.map(r => r.id === id ? {
        ...r,
        status: RentalStatus.RETURNED,
        actualReturnDate: new Date().toISOString(),
        lateFee: lateFee,
        totalRentAmount: r.totalRentAmount + lateFee
      } : r),
      notifications: [
        createNotification('INFO', 'RENTAL', 'Rental Returned', `Items checked in for ${rental.invoiceNumber}`, 'rentals'),
        ...prev.notifications
      ]
    }));
  };

  const updateStock = (productId: string, pool: 'SALE' | 'RENTAL', quantity: number, type: 'IN' | 'OUT', reason: string) => {
    const log: StockLog = {
      id: generateID(),
      productId,
      pool,
      type,
      quantity,
      reason,
      date: new Date().toISOString()
    };

    setState(prev => ({
      ...prev,
      products: prev.products.map(p => {
        if (p.id !== productId) return p;
        if (pool === 'SALE') {
           return { ...p, saleStock: type === 'IN' ? p.saleStock + quantity : p.saleStock - quantity };
        } else {
           return { ...p, rentalStock: type === 'IN' ? p.rentalStock + quantity : p.rentalStock - quantity };
        }
      }),
      stockLogs: [...prev.stockLogs, log]
    }));
  };

  const updateStoreProfile = (profile: Partial<StoreProfile>) => {
    setState(prev => ({ ...prev, storeProfile: { ...prev.storeProfile, ...profile } }));
  };

  const updateSettings = (settings: Partial<AppSettings>) => {
    setState(prev => ({ ...prev, settings: { ...prev.settings, ...settings } }));
  };

  const importData = (jsonData: string): boolean => {
    try {
      const parsedData = JSON.parse(jsonData);
      if (!parsedData.products || !parsedData.sales) {
        return false;
      }
      setState(prev => ({
        ...parsedData,
        currentUser: prev.currentUser
      }));
      return true;
    } catch (e) {
      return false;
    }
  };

  const resetData = () => {
    const current = state.currentUser;
    setState({ ...INITIAL_DATA, currentUser: current });
  };

  const markNotificationsAsRead = () => {
    setState(prev => ({
      ...prev,
      notifications: prev.notifications.map(n => ({ ...n, isRead: true }))
    }));
  };

  const clearNotifications = () => {
    setState(prev => ({ ...prev, notifications: [] }));
  };

  return (
    <AppContext.Provider value={{ 
      ...state, 
      login, logout, addUser, updateUser, deleteUser,
      addProduct, updateProduct, deleteProduct, 
      addCustomer, addSupplier, 
      addSale, updateOrderStatus, addPaymentToSale,
      addRental, updateRental, returnRental,
      updateStock, updateStoreProfile, updateSettings,
      importData, resetData,
      markNotificationsAsRead, clearNotifications
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useApp must be used within AppProvider');
  return context;
};

