        startDate: start,
        expectedReturnDate: end,
        dailyRate: product.rentalPrice,
        securityDeposit: Number(formData.get('securityDeposit')),
        totalRentAmount: total,
        paidAmount: Number(formData.get('paidAmount')),
        paymentStatus: Number(formData.get('paidAmount')) >= total ? PaymentStatus.PAID : PaymentStatus.PARTIAL,
      });
      setIsNewRentalModalOpen(false);
    }
  };

  const openCheckIn = (rental: Rental) => {
      setSelectedRental(rental);
      setDamageFee(0);
      setReturnNotes('');
      setIsCheckInModalOpen(true);
  }

  const handleConfirmReturn = () => {
    if (selectedRental) {
        // Late fee is calculated on the fly in the modal view, but we need to re-calc here to save it
        // Or we pass it from the modal state if we allowed overrides. 
        // For simplicity, we recalculate using standard logic.
        const lateFee = calculateLateFee(selectedRental.expectedReturnDate, undefined, selectedRental.dailyRate, selectedRental.quantity);
        // We might want to store damageFee essentially as a generic fee adjustment or add it to totalRentAmount
        // Since the interface has 'lateFee' but not 'damageFee', we will combine them for the record
        const totalExtraFees = lateFee + damageFee;

        returnRental(selectedRental.id, totalExtraFees);
        setIsCheckInModalOpen(false);
        setSelectedRental(null);
    }
  }

  const openExtend = (rental: Rental) => {
      setSelectedRental(rental);
      setExtendDays(1);
      setIsExtendModalOpen(true);
  }

  const handleConfirmExtend = () => {
      if (selectedRental) {
          const currentEnd = parseISO(selectedRental.expectedReturnDate);
          const newEnd = addDays(currentEnd, extendDays);
          const newEndDateStr = format(newEnd, 'yyyy-MM-dd');

          // Calculate additional rent cost
          const additionalCost = extendDays * selectedRental.dailyRate * selectedRental.quantity;

          updateRental(selectedRental.id, {
              expectedReturnDate: newEndDateStr,
              totalRentAmount: selectedRental.totalRentAmount + additionalCost,
              // If previously paid in full, now it might be partial? 
              // We'll leave status as is, user can record payment separately or we assume payment collected
          });

          setIsExtendModalOpen(false);
          setSelectedRental(null);
      }
  }

  // --- Calculations for Views ---

  const filteredRentals = rentals.filter(r => {
    const cust = customers.find(c => c.id === r.customerId);
    const prod = products.find(p => p.id === r.productId);
    const matchesSearch = (
      cust?.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      prod?.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      r.invoiceNumber.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const today = new Date();
    today.setHours(0,0,0,0);
    const returnDate = parseISO(r.expectedReturnDate);
    const isOverdue = isBefore(returnDate, today) && r.status === RentalStatus.ACTIVE;

    if (activeTab === 'ACTIVE') return matchesSearch && r.status === 'ACTIVE' && !isOverdue;
    if (activeTab === 'OVERDUE') return matchesSearch && r.status === 'ACTIVE' && isOverdue;
    if (activeTab === 'RETURNED') return matchesSearch && r.status === 'RETURNED';
    return matchesSearch;
  });

  const getProgress = (start: string, end: string) => {
    const startDate = parseISO(start).getTime();
    const endDate = parseISO(end).getTime();
    const now = new Date().getTime();
    const totalDuration = endDate - startDate;
    const elapsed = now - startDate;
    const percentage = Math.max(0, Math.min(100, (elapsed / totalDuration) * 100));
    return percentage;
  };

  // KPIs
  const activeCount = rentals.filter(r => r.status === 'ACTIVE').length;
  const overdueCount = rentals.filter(r => r.status === 'ACTIVE' && isBefore(parseISO(r.expectedReturnDate), new Date())).length;
  const returnsDueToday = rentals.filter(r => r.status === 'ACTIVE' && isSameDay(parseISO(r.expectedReturnDate), new Date())).length;
  const activeDeposits = rentals
    .filter(r => r.status === 'ACTIVE')
    .reduce((acc, r) => acc + r.securityDeposit, 0);

  // Return Modal Calculation Helper
  const getReturnSummary = () => {
      if (!selectedRental) return { lateFee: 0, totalDue: 0, settlement: 0 };

      const lateFee = calculateLateFee(selectedRental.expectedReturnDate, undefined, selectedRental.dailyRate, selectedRental.quantity);
      const outstandingRent = selectedRental.totalRentAmount - selectedRental.paidAmount;

      const totalCharges = outstandingRent + lateFee + damageFee;
      // Settlement = Deposit - Charges
      const settlement = selectedRental.securityDeposit - totalCharges;

      return { lateFee, totalDue: totalCharges, settlement };
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-300 pb-10">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Rentals</h1>
          <p className="text-sm font-medium text-gray-400">Track bookings, returns & deposits</p>
        </div>
        <Button onClick={() => setIsNewRentalModalOpen(true)} className="flex items-center gap-2 shadow-sky-200">
          <Plus size={20} /> Create Rental
        </Button>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card className="p-5 border-0 shadow-sm bg-white flex items-center justify-between">
          <div>
            <p className="text-xs font-bold uppercase text-gray-400 tracking-wider">Active</p>
            <h3 className="text-3xl font-black text-sky-600 mt-1">{activeCount}</h3>
          </div>
          <div className="p-3 bg-sky-50 text-sky-500 rounded-lg">
              <Calendar size={20} />
          </div>
        </Card>

        <Card className={`p-5 border-0 shadow-sm flex items-center justify-between ${overdueCount > 0 ? 'bg-pink-50 border-pink-100' : 'bg-white'}`}>
          <div>
            <p className={`text-xs font-bold uppercase tracking-wider ${overdueCount > 0 ? 'text-pink-600' : 'text-gray-400'}`}>Overdue</p>
            <h3 className={`text-3xl font-black mt-1 ${overdueCount > 0 ? 'text-pink-600' : 'text-gray-800'}`}>{overdueCount}</h3>
          </div>
          <div className={`p-3 rounded-lg ${overdueCount > 0 ? 'bg-white text-pink-500' : 'bg-gray-50 text-gray-400'}`}>
              <AlertCircle size={20} />
          </div>
        </Card>

        <Card className={`p-5 border-0 shadow-sm flex items-center justify-between ${returnsDueToday > 0 ? 'bg-orange-50 border-orange-100' : 'bg-white'}`}>
          <div>
            <p className={`text-xs font-bold uppercase tracking-wider ${returnsDueToday > 0 ? 'text-orange-600' : 'text-gray-400'}`}>Due Today</p>
            <h3 className={`text-3xl font-black mt-1 ${returnsDueToday > 0 ? 'text-orange-600' : 'text-gray-800'}`}>{returnsDueToday}</h3>
          </div>
          <div className={`p-3 rounded-lg ${returnsDueToday > 0 ? 'bg-white text-orange-500' : 'bg-gray-50 text-gray-400'}`}>
              <Clock size={20} />
          </div>
        </Card>

        <Card className="p-5 border-0 shadow-sm bg-white flex items-center justify-between">
          <div>
            <p className="text-xs font-bold uppercase text-gray-400 tracking-wider">Deposits Held</p>
            <h3 className="text-2xl font-black text-gray-800 mt-1">{formatCurrency(activeDeposits)}</h3>
          </div>
          <div className="p-3 bg-gray-100 text-gray-600 rounded-lg">
              <Receipt size={20} />
          </div>
        </Card>
      </div>

      <div className="flex flex-col gap-4">
        {/* Navigation Tabs */}
        <div className="flex items-center justify-between">
             <div className="flex bg-gray-100/50 p-1 rounded-lg">
               {(['ACTIVE', 'OVERDUE', 'RETURNED'] as const).map(tab => (
                 <button
                    key={tab}
                    onClick={() => setActiveTab(tab)}
                    className={`px-5 py-2.5 rounded-md text-xs font-bold transition-all ${activeTab === tab ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                 >
                    {tab.charAt(0) + tab.slice(1).toLowerCase()}
                 </button>
               ))}
            </div>
             <div className="relative hidden md:block w-72">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                <input 
                  type="text" 
                  placeholder="Search invoice, customer..." 
                  className="w-full pl-10 pr-4 py-2 bg-white border border-gray-100 rounded-lg outline-none focus:ring-2 focus:ring-sky-100 transition-all font-medium text-sm text-gray-600"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
            </div>
        </div>

        <Card className="overflow-hidden border-0 shadow-sm">
            <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
                <thead>
                <tr className="bg-gray-50/50 border-b border-gray-100 text-gray-400">
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Order Info</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Product</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Timeline</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Financials</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Actions</th>
                </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                {filteredRentals.map(rental => {
                    const customer = customers.find(c => c.id === rental.customerId);
                    const product = products.find(p => p.id === rental.productId);
                    const progress = getProgress(rental.startDate, rental.expectedReturnDate);
                    const isLate = activeTab === 'OVERDUE';
                    const estLateFee = calculateLateFee(rental.expectedReturnDate, undefined, rental.dailyRate, rental.quantity);

                    return (
                    <tr key={rental.id} className="hover:bg-gray-50 transition-colors">
                        <td className="px-6 py-4">
                            <div className="font-bold text-gray-800">{rental.invoiceNumber}</div>
                            <div className="flex items-center gap-2 mt-1.5">
                                {customer?.phone && (
                                    <a href={`tel:${customer.phone}`} className="w-6 h-6 rounded-full bg-gray-100 flex items-center justify-center text-gray-500 hover:bg-sky-50 hover:text-sky-600 transition-colors" title="Call Customer">
                                        <Phone size={12} />
                                    </a>
                                )}
                                <div className="text-xs text-gray-500 font-medium">{customer?.name}</div>
                            </div>
                        </td>
                        <td className="px-6 py-4">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-indigo-50 text-indigo-500 rounded-md flex items-center justify-center shrink-0">
                                    <Box size={18} />
                                </div>
                                <div>
                                    <div className="font-bold text-gray-800">{product?.name}</div>
                                    <div className="text-xs text-gray-400">Qty: {rental.quantity}</div>
                                </div>
                            </div>
                        </td>
                        <td className="px-6 py-4 min-w-[200px]">
                            <div className="flex justify-between text-xs text-gray-500 mb-1.5 font-medium">
                                <span>{new Date(rental.startDate).toLocaleDateString(undefined, {month:'short', day:'numeric'})}</span>
                                <span className={isLate ? 'text-pink-600 font-bold' : ''}>
                                    {new Date(rental.expectedReturnDate).toLocaleDateString(undefined, {month:'short', day:'numeric'})}
                                </span>
                            </div>
                            <div className="w-full h-1.5 bg-gray-100 rounded-full overflow-hidden">
                                <div 
                                    className={`h-full rounded-full transition-all duration-500 ${
                                        rental.status === 'RETURNED' ? 'bg-green-400' :
                                        isLate ? 'bg-pink-500' : 
                                        progress > 80 ? 'bg-orange-400' : 'bg-sky-400'
                                    }`} 
                                    style={{ width: rental.status === 'RETURNED' ? '100%' : `${progress}%` }}
                                ></div>
                            </div>
                            {rental.status === 'ACTIVE' && (
                                <div className="flex justify-between mt-1">
                                    <span className={`text-[10px] ${isLate ? 'text-pink-600 font-bold' : 'text-gray-400'}`}>
                                        {isLate 
                                            ? `Overdue by ${differenceInDays(new Date(), parseISO(rental.expectedReturnDate))} days` 
                                            : `${Math.ceil((100 - progress)/100 * differenceInDays(parseISO(rental.expectedReturnDate), parseISO(rental.startDate)))} days left`
                                        }
                                    </span>
                                </div>
                            )}
                        </td>
                        <td className="px-6 py-4">
                            <div className="flex flex-col gap-0.5">
                                <span className="font-bold text-gray-800">{formatCurrency(rental.totalRentAmount)}</span>
                                <span className="text-[10px] text-gray-400">Dep: {formatCurrency(rental.securityDeposit)}</span>
                                {isLate && (
                                    <span className="text-[10px] font-bold text-pink-600 bg-pink-50 px-1 rounded w-fit">
                                        + Late: {formatCurrency(estLateFee)}
                                    </span>
                                )}
                            </div>
                        </td>
                        <td className="px-6 py-4 text-right">
                        {rental.status === 'ACTIVE' ? (
                            <div className="flex justify-end gap-2">
                                <button 
                                    onClick={() => openExtend(rental)}
                                    className="p-1.5 text-gray-400 hover:text-sky-600 hover:bg-sky-50 rounded-md transition-colors"
                                    title="Extend Rental"
                                >
                                    <CalendarDays size={16} />
                                </button>
                                <Button 
                                    variant="secondary" 
                                    onClick={() => openCheckIn(rental)} 
                                    className="text-xs h-8 px-3 flex items-center gap-1 shadow-none border-gray-200"
                                >
                                    <Check size={14} /> Check In
                                </Button>
                            </div>
                        ) : (
                            <span className="inline-flex items-center gap-1 px-2 py-1 rounded-full bg-gray-100 text-gray-500 text-[10px] font-bold uppercase">
                                <CheckCircle size={10} /> Returned
                            </span>
                        )}
                        </td>
                    </tr>
                    );
                })}
                </tbody>
            </table>
            {filteredRentals.length === 0 && (
                <div className="py-20 text-center text-gray-400 italic">No {activeTab.toLowerCase()} rentals found.</div>
            )}
            </div>
        </Card>
      </div>

      {/* New Rental Modal */}
      <Modal isOpen={isNewRentalModalOpen} onClose={() => setIsNewRentalModalOpen(false)} title="Create New Rental">
        <form onSubmit={handleCreateRental} className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="col-span-2 p-4 bg-sky-50 text-sky-800 text-xs rounded-lg flex items-start gap-3 border border-sky-100">
             <AlertCircle size={16} className="mt-0.5 shrink-0" />
             <div>
                 <p className="font-bold mb-1">Rental Pool</p>
                 <p>Items will be deducted from the <strong>Rental Stock</strong>. Ensure items are available in the rental pool before booking.</p>
             </div>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Customer</label>
            <select name="customerId" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium">
              {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Product</label>
            <select name="productId" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium">
              {products.map(p => <option key={p.id} value={p.id} disabled={p.rentalStock === 0}>{p.name} ({formatCurrency(p.rentalPrice)}/day) - Avail: {p.rentalStock}</option>)}
            </select>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Quantity</label>
            <input name="quantity" type="number" defaultValue="1" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Security Deposit</label>
            <input name="securityDeposit" type="number" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium" placeholder="Refundable amount" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Start Date</label>
            <input name="startDate" type="date" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium" defaultValue={new Date().toISOString().split('T')[0]} />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Expected Return</label>
            <input name="expectedReturnDate" type="date" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium" />
          </div>
          <div className="col-span-2 space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Payment Received</label>
            <input name="paidAmount" type="number" required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium" placeholder="Total payment received" />
          </div>
          <div className="col-span-2 flex gap-3 pt-4">
            <Button variant="ghost" onClick={() => setIsNewRentalModalOpen(false)} className="flex-1">Cancel</Button>
            <Button type="submit" className="flex-1">Issue Invoice</Button>
          </div>
        </form>
      </Modal>

      {/* Check In / Return Modal */}
      <Modal isOpen={isCheckInModalOpen} onClose={() => setIsCheckInModalOpen(false)} title="Rental Check-In">
         {selectedRental && (() => {
             const summary = getReturnSummary();
             return (
                 <div className="space-y-6">
                     <div className="grid grid-cols-2 gap-4 text-sm bg-gray-50 p-4 rounded-lg border border-gray-100">
                         <div>
                             <p className="text-gray-400 text-xs uppercase font-bold">Customer</p>
                             <p className="font-bold text-gray-800">{customers.find(c => c.id === selectedRental.customerId)?.name}</p>
                         </div>
                         <div>
                             <p className="text-gray-400 text-xs uppercase font-bold">Deposit Held</p>
                             <p className="font-bold text-gray-800">{formatCurrency(selectedRental.securityDeposit)}</p>
                         </div>
                         <div>
                             <p className="text-gray-400 text-xs uppercase font-bold">Outstanding Rent</p>
                             <p className="font-bold text-gray-800">{formatCurrency(Math.max(0, selectedRental.totalRentAmount - selectedRental.paidAmount))}</p>
                         </div>
                         <div>
                             <p className="text-gray-400 text-xs uppercase font-bold">Late Fees (Auto)</p>
                             <p className="font-bold text-pink-600">{formatCurrency(summary.lateFee)}</p>
                         </div>
                     </div>

                     <div className="space-y-1">
                         <label className="text-xs font-bold uppercase text-gray-400">Damage / Cleaning Fee</label>
                         <div className="relative">
                             <IndianRupee className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                             <input 
                                type="number" 
                                value={damageFee} 
                                onChange={e => setDamageFee(Number(e.target.value))} 
                                className="w-full pl-10 pr-4 py-3 bg-white border border-gray-200 focus:border-sky-200 rounded-lg outline-none font-medium"
                                placeholder="0"
                             />
                         </div>
                     </div>

                     <div className={`p-4 rounded-lg flex justify-between items-center ${summary.settlement >= 0 ? 'bg-emerald-50 border border-emerald-100' : 'bg-red-50 border border-red-100'}`}>
                         <div>
                             <p className="text-xs font-bold uppercase opacity-70 mb-1">Final Settlement</p>
                             <p className={`text-lg font-black ${summary.settlement >= 0 ? 'text-emerald-700' : 'text-red-700'}`}>
                                 {summary.settlement >= 0 ? `Refund Customer: ${formatCurrency(summary.settlement)}` : `Collect Payment: ${formatCurrency(Math.abs(summary.settlement))}`}
                             </p>
                         </div>
                         <div className={`p-2 rounded-full ${summary.settlement >= 0 ? 'bg-emerald-200 text-emerald-800' : 'bg-red-200 text-red-800'}`}>
                             {summary.settlement >= 0 ? <ArrowRight size={24} className="rotate-45" /> : <IndianRupee size={24} />}
                         </div>
                     </div>

                     <div className="flex gap-3 pt-2">
                        <Button variant="ghost" onClick={() => setIsCheckInModalOpen(false)} className="flex-1">Cancel</Button>
                        <Button type="button" onClick={handleConfirmReturn} className="flex-1">Confirm Return</Button>
                     </div>
                 </div>
             );
         })()}
      </Modal>

      {/* Extend Rental Modal */}
      <Modal isOpen={isExtendModalOpen} onClose={() => setIsExtendModalOpen(false)} title="Extend Rental">
          {selectedRental && (
              <div className="space-y-6">
                  <div className="bg-sky-50 p-4 rounded-lg border border-sky-100 text-sm">
                      <p className="text-sky-800 font-bold mb-1">Current Due Date</p>
                      <p className="text-sky-600">{new Date(selectedRental.expectedReturnDate).toLocaleDateString()}</p>
                  </div>

                  <div className="space-y-1">
                      <label className="text-xs font-bold uppercase text-gray-400">Add Days</label>
                      <input 
                        type="number" 
                        min="1" 
                        value={extendDays} 
                        onChange={e => setExtendDays(Number(e.target.value))} 
                        className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none font-medium"
                      />
                  </div>

                  <div className="flex justify-between items-center px-2 py-1">
                      <span className="text-sm font-bold text-gray-500">New Due Date:</span>
                      <span className="text-sm font-bold text-gray-800">{format(addDays(parseISO(selectedRental.expectedReturnDate), extendDays), 'dd MMM yyyy')}</span>
                  </div>

                  <div className="flex justify-between items-center px-2 py-1 border-t border-gray-100 pt-3">
                      <span className="text-sm font-bold text-gray-500">Additional Cost:</span>
                      <span className="text-lg font-black text-sky-600">{formatCurrency(extendDays * selectedRental.dailyRate * selectedRental.quantity)}</span>
                  </div>

                  <div className="flex gap-3 pt-2">
                    <Button variant="ghost" onClick={() => setIsExtendModalOpen(false)} className="flex-1">Cancel</Button>
                    <Button type="button" onClick={handleConfirmExtend} className="flex-1">Save Extension</Button>
                  </div>
              </div>
          )}
      </Modal>
    </div>
  );
};

export default Rentals;

export enum RentalStatus {
  ACTIVE = 'ACTIVE',
  RETURNED = 'RETURNED',
  OVERDUE = 'OVERDUE'
}

export enum PaymentStatus {
  PAID = 'PAID',
  PARTIAL = 'PARTIAL',
  UNPAID = 'UNPAID'
}

export enum PaymentMethod {
  CASH = 'CASH',
  UPI = 'UPI',
  CARD = 'CARD',
  BANK_TRANSFER = 'BANK_TRANSFER'
}

export enum SalesChannel {
  IN_STORE = 'IN_STORE',
  AMAZON = 'AMAZON',
  FLIPKART = 'FLIPKART',
  MEESHO = 'MEESHO',
  WEBSITE = 'WEBSITE'
}

export enum OrderStatus {
  COMPLETED = 'COMPLETED',       // Instant for offline
  PENDING = 'PENDING',           // New online order
  READY_TO_SHIP = 'READY_TO_SHIP',
  SHIPPED = 'SHIPPED',
  DELIVERED = 'DELIVERED',
  RETURNED = 'RETURNED',
  CANCELLED = 'CANCELLED'
}

export enum UserRole {
  ADMIN = 'ADMIN',
  STAFF = 'STAFF'
}

export interface User {
  id: string;
  name: string;
  email: string;
  password: string; // In a real app, this should be hashed. Storing plain/base64 for this demo.
  role: UserRole;
  permissions: string[]; // List of specific module IDs this user can access
  avatar?: string;
  createdAt: string;
}

export interface Product {
  id: string;
  name: string;
  sku: string;
  barcode: string;
  category: string;
  purchasePrice: number;
  sellingPrice: number;
  rentalPrice: number; // Daily rate
  taxPercent: number;

  // Stock Split
  saleStock: number;   // Items available for purchase
  rentalStock: number; // Items available for rent

  minStockAlert: number;
  supplierId: string;
  description: string;
  imageUrl?: string;
  createdAt: string;
}

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email: string;
  address: string;
  gstin?: string;
  createdAt: string;
}

export interface Supplier {
  id: string;
  name: string;
  contactPerson: string;
  phone: string;
  email: string;
  address: string;
  createdAt: string;
}

export interface InvoiceItem {
  productId: string;
  name: string;
  quantity: number;
  unitPrice: number;
  taxAmount: number;
  total: number;
}

export interface Sale {
  id: string;
  invoiceNumber: string; // Internal Invoice ID
  externalOrderId?: string; // e.g., Amazon Order ID
  channel: SalesChannel;
  customerId: string; // For marketplaces, this might be a generic "Amazon Customer"
  items: InvoiceItem[];
  totalAmount: number; // Gross Sale Amount
  marketplaceFees: number; // Commission + Shipping + Fixed Fees
  netPayout: number; // Total - Fees
  taxTotal: number;
  discount: number;
  paidAmount: number;
  paymentStatus: PaymentStatus;
  paymentMethod: PaymentMethod;
  orderStatus: OrderStatus;
  date: string;
}

export interface Rental {
  id: string;
  invoiceNumber: string;
  customerId: string;
  productId: string;
  quantity: number;
  startDate: string;
  expectedReturnDate: string;
  actualReturnDate?: string;
  dailyRate: number;
  securityDeposit: number;
  totalRentAmount: number;
  lateFee: number;
  paidAmount: number;
  status: RentalStatus;
  paymentStatus: PaymentStatus;
  images?: string[]; // Array of base64 strings for condition photos/ID proofs
  date: string;
}

export interface StockLog {
  id: string;
  productId: string;
  pool: 'SALE' | 'RENTAL';
  type: 'IN' | 'OUT';
  quantity: number;
  reason: string;
  date: string;
}

export interface StoreProfile {
  storeName: string;
  address: string;
  phone: string;
  email: string;
  gstin: string;
  website: string;
}

export interface AppSettings {
  defaultTaxRate: number;
  currency: string;
  enableLowStockAlerts: boolean;
  lowStockThreshold: number; // Default global threshold
  salesInvoicePrefix: string;
  rentalInvoicePrefix: string;
}

export interface AppNotification {
  id: string;
  type: 'INFO' | 'SUCCESS' | 'WARNING' | 'ERROR';
  category: 'SALE' | 'RENTAL' | 'INVENTORY' | 'SYSTEM' | 'CUSTOMER';
  title: string;
  message: string;
  timestamp: string;
  isRead: boolean;
  linkTo?: string; // Tab ID
}

export interface AppState {
  currentUser: User | null;
  users: User[];
  products: Product[];
  customers: Customer[];
  suppliers: Supplier[];
  sales: Sale[];
  rentals: Rental[];
  stockLogs: StockLog[];
  notifications: AppNotification[];
  storeProfile: StoreProfile;
  settings: AppSettings;
}

import React, { useState, useMemo, useRef } from 'react';
import { useApp } from '../store/AppContext';
import { Card, Button, Modal } from '../components/Shared';
import { 
  Plus, 
  Search, 
  Edit2, 
  Trash2, 
  ArrowUpRight, 
  ArrowDownLeft,
  Package,
  AlertTriangle,
  Tags,
  DollarSign,
  Box,
  ShoppingBag,
  RefreshCcw,
  Image as ImageIcon,
  Upload,
  X
} from 'lucide-react';
import { formatCurrency } from '../utils/helpers';
import { CATEGORIES } from '../constants';
import { Product } from '../types';

const Inventory: React.FC = () => {
  const { products, addProduct, updateProduct, deleteProduct, updateStock, suppliers } = useApp();
  const [isProductModalOpen, setIsProductModalOpen] = useState(false);
  const [isStockModalOpen, setIsStockModalOpen] = useState(false);

  const [selectedProduct, setSelectedProduct] = useState<string | null>(null); // For Stock Update Modal (ID only)
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);   // For Edit Modal (Full Object)

  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'ALL' | 'LOW' | 'OUT'>('ALL');

  // New State for Product Purpose Selection
  const [productType, setProductType] = useState<'SALE' | 'RENTAL' | 'BOTH'>('BOTH');

  // Image Upload State
  const [previewImage, setPreviewImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Stats Calculation
  const stats = useMemo(() => {
    const totalItems = products.reduce((acc, p) => acc + p.saleStock + p.rentalStock, 0);
    const totalValue = products.reduce((acc, p) => acc + (p.purchasePrice * (p.saleStock + p.rentalStock)), 0); // Asset value based on purchase price
    const lowStock = products.filter(p => p.saleStock > 0 && p.saleStock <= p.minStockAlert).length; // Only count if it's a sale item
    const outOfStock = products.filter(p => p.saleStock === 0 && p.rentalStock === 0).length;
    return { totalItems, totalValue, lowStock, outOfStock };
  }, [products]);

  const filteredProducts = products.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          p.sku.toLowerCase().includes(searchTerm.toLowerCase());

    if (statusFilter === 'LOW') return matchesSearch && p.saleStock > 0 && p.saleStock <= p.minStockAlert;
    if (statusFilter === 'OUT') return matchesSearch && p.saleStock === 0 && p.rentalStock === 0;

    return matchesSearch;
  });

  // Helper to determine product type string for display/edit
  const getProductTypeDisplay = (p: Product) => {
      const isSale = p.sellingPrice > 0 || p.saleStock > 0;
      const isRent = p.rentalPrice > 0 || p.rentalStock > 0;
      if (isSale && isRent) return 'BOTH';
      if (isRent) return 'RENTAL';
      return 'SALE';
  }

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleRemoveImage = () => {
    setPreviewImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSaveProduct = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);

    // Determine values based on type selection
    const sellingPrice = (productType === 'SALE' || productType === 'BOTH') ? Number(formData.get('sellingPrice')) : 0;
    const saleStock = (productType === 'SALE' || productType === 'BOTH') ? Number(formData.get('saleStock')) : 0;

    const rentalPrice = (productType === 'RENTAL' || productType === 'BOTH') ? Number(formData.get('rentalPrice')) : 0;
    const rentalStock = (productType === 'RENTAL' || productType === 'BOTH') ? Number(formData.get('rentalStock')) : 0;

    const productData = {
      name: formData.get('name') as string,
      sku: formData.get('sku') as string,
      barcode: formData.get('barcode') as string,
      category: formData.get('category') as string,
      purchasePrice: Number(formData.get('purchasePrice')),
      sellingPrice,
      rentalPrice,
      taxPercent: Number(formData.get('taxPercent')) || 0,
      saleStock,
      rentalStock,
      minStockAlert: Number(formData.get('minStockAlert')),
      supplierId: formData.get('supplierId') as string,
      description: formData.get('description') as string,
      imageUrl: previewImage || undefined,
    };

    if (productToEdit) {
        updateProduct(productToEdit.id, productData);
    } else {
        addProduct(productData);
    }

    setIsProductModalOpen(false);
    setProductToEdit(null);
    setProductType('BOTH'); // Reset
    setPreviewImage(null);
  };

  const handleStockUpdate = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    if (selectedProduct) {
      updateStock(
        selectedProduct,
        formData.get('pool') as 'SALE' | 'RENTAL',
        Number(formData.get('quantity')),
        formData.get('type') as 'IN' | 'OUT',
        formData.get('reason') as string
      );
    }
    setIsStockModalOpen(false);
  };

  const openAddModal = () => {
      setProductToEdit(null);
      setPreviewImage(null);
      setProductType('BOTH');
      setIsProductModalOpen(true);
  };

  const openEditModal = (product: Product) => {
      setProductToEdit(product);
      setPreviewImage(product.imageUrl || null);
      setProductType(getProductTypeDisplay(product));
      setIsProductModalOpen(true);
  };

  // Helper component for stock bar
  const StockBar = ({ current, max = 10, isLow, disabled }: { current: number, max?: number, isLow?: boolean, disabled?: boolean }) => {
      if (disabled) return <div className="h-1.5 w-16 mt-1 bg-gray-100 rounded-full opacity-50"></div>;

      const percentage = Math.min(100, (current / max) * 100);
      const color = current === 0 ? 'bg-gray-200' : isLow ? 'bg-orange-400' : 'bg-emerald-400';

      return (
          <div className="w-16 h-1.5 bg-gray-100 rounded-full overflow-hidden mt-1">
              <div className={`h-full rounded-full ${color}`} style={{ width: `${percentage}%` }}></div>
          </div>
      );
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-300 pb-10">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Inventory</h1>
          <p className="text-sm font-medium text-gray-400">Manage separate Sales & Rental pools</p>
        </div>
        <Button onClick={openAddModal} className="flex items-center gap-2 shadow-sky-200">
          <Plus size={20} /> Add Product
        </Button>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="p-5 border-0 shadow-sm bg-white">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-xs font-bold uppercase text-gray-400">Total Stock Value</p>
                    <h3 className="text-2xl font-black text-gray-800 mt-1">{formatCurrency(stats.totalValue)}</h3>
                </div>
                <div className="p-2 bg-emerald-50 text-emerald-600 rounded-md">
                    <DollarSign size={20} />
                </div>
            </div>
            <p className="text-xs text-gray-400 mt-2">Combined retail & asset value</p>
        </Card>
        <Card className="p-5 border-0 shadow-sm bg-white">
            <div className="flex justify-between items-start">
                <div>
                    <p className="text-xs font-bold uppercase text-gray-400">Total Products</p>
                    <h3 className="text-2xl font-black text-gray-800 mt-1">{products.length}</h3>
                </div>
                <div className="p-2 bg-sky-50 text-sky-600 rounded-md">
                    <Tags size={20} />
                </div>
            </div>
            <p className="text-xs text-gray-400 mt-2">{stats.totalItems} individual units</p>
        </Card>
        <Card className={`p-5 border-0 shadow-sm ${stats.lowStock > 0 ? 'bg-orange-50 border-orange-100' : 'bg-white'}`}>
            <div className="flex justify-between items-start">
                <div>
                    <p className={`text-xs font-bold uppercase ${stats.lowStock > 0 ? 'text-orange-600' : 'text-gray-400'}`}>Low Sales Stock</p>
                    <h3 className={`text-2xl font-black mt-1 ${stats.lowStock > 0 ? 'text-orange-700' : 'text-gray-800'}`}>{stats.lowStock}</h3>
                </div>
                <div className={`p-2 rounded-md ${stats.lowStock > 0 ? 'bg-white text-orange-600' : 'bg-orange-50 text-orange-600'}`}>
                    <AlertTriangle size={20} />
                </div>
            </div>
            <p className={`text-xs mt-2 ${stats.lowStock > 0 ? 'text-orange-600' : 'text-gray-400'}`}>Items below alert threshold</p>
        </Card>
        <Card className={`p-5 border-0 shadow-sm ${stats.outOfStock > 0 ? 'bg-red-50 border-red-100' : 'bg-white'}`}>
            <div className="flex justify-between items-start">
                <div>
                    <p className={`text-xs font-bold uppercase ${stats.outOfStock > 0 ? 'text-red-600' : 'text-gray-400'}`}>Completely Out</p>
                    <h3 className={`text-2xl font-black mt-1 ${stats.outOfStock > 0 ? 'text-red-700' : 'text-gray-800'}`}>{stats.outOfStock}</h3>
                </div>
                <div className={`p-2 rounded-md ${stats.outOfStock > 0 ? 'bg-white text-red-600' : 'bg-red-50 text-red-600'}`}>
                    <Box size={20} />
                </div>
            </div>
            <p className={`text-xs mt-2 ${stats.outOfStock > 0 ? 'text-red-600' : 'text-gray-400'}`}>Zero stock in both pools</p>
        </Card>
      </div>

      <div className="flex flex-col gap-4">
        {/* Search & Tabs */}
        <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
             <div className="relative w-full md:w-96">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                <input 
                    type="text" 
                    placeholder="Search by name, SKU..." 
                    className="w-full pl-11 pr-4 py-2.5 bg-white border border-gray-100 rounded-lg outline-none focus:ring-2 focus:ring-sky-100 transition-all font-medium text-gray-600"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                />
            </div>

            <div className="flex bg-gray-100/50 p-1 rounded-lg">
               <button 
                 onClick={() => setStatusFilter('ALL')}
                 className={`px-4 py-2 rounded-md text-xs font-bold transition-all ${statusFilter === 'ALL' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
               >
                 All Items
               </button>
               <button 
                 onClick={() => setStatusFilter('LOW')}
                 className={`px-4 py-2 rounded-md text-xs font-bold transition-all ${statusFilter === 'LOW' ? 'bg-white text-orange-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
               >
                 Low Stock
               </button>
               <button 
                 onClick={() => setStatusFilter('OUT')}
                 className={`px-4 py-2 rounded-md text-xs font-bold transition-all ${statusFilter === 'OUT' ? 'bg-white text-red-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
               >
                 Out of Stock
               </button>
            </div>
        </div>

        {/* Product Table */}
        <Card className="overflow-hidden border-0 shadow-sm">
            <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
                <thead>
                <tr className="bg-gray-50/50 border-b border-gray-100 text-gray-400">
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Product Info</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider">Category & SKU</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-center">Sale Stock</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-center">Rental Stock</th>
                    <th className="px-6 py-4 font-bold uppercase text-xs tracking-wider text-right">Actions</th>
                </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                {filteredProducts.map(product => {
                    const type = getProductTypeDisplay(product);
                    const isSaleEnabled = type === 'SALE' || type === 'BOTH';
                    const isRentalEnabled = type === 'RENTAL' || type === 'BOTH';

                    return (
                    <tr key={product.id} className="hover:bg-gray-50 transition-colors group">
                    <td className="px-6 py-4">
                        <div className="flex items-center space-x-4">
                        {product.imageUrl ? (
                            <div className="w-12 h-12 rounded-lg overflow-hidden border border-gray-200 shrink-0">
                                <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                            </div>
                        ) : (
                            <div className={`w-12 h-12 rounded-lg flex items-center justify-center font-bold text-lg shadow-sm shrink-0 ${type === 'SALE' ? 'bg-emerald-50 text-emerald-500' : type === 'RENTAL' ? 'bg-sky-50 text-sky-500' : 'bg-indigo-50 text-indigo-500'}`}>
                                <Package size={20} />
                            </div>
                        )}
                        <div>
                            <div className="font-bold text-gray-800">{product.name}</div>
                            <div className="flex items-center gap-2 mt-1">
                                {type === 'SALE' && <span className="text-[10px] font-bold bg-emerald-100 text-emerald-700 px-1.5 py-0.5 rounded">FOR SALE</span>}
                                {type === 'RENTAL' && <span className="text-[10px] font-bold bg-sky-100 text-sky-700 px-1.5 py-0.5 rounded">FOR RENT</span>}
                                {type === 'BOTH' && <span className="text-[10px] font-bold bg-indigo-100 text-indigo-700 px-1.5 py-0.5 rounded">HYBRID</span>}

                                {isSaleEnabled && product.saleStock <= product.minStockAlert && product.saleStock > 0 && (
                                    <span className="text-[10px] font-bold text-orange-600 bg-orange-50 px-2 py-0.5 rounded-full">Low Stock</span>
                                )}
                            </div>
                        </div>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                         <div className="text-gray-800 font-medium">{product.category}</div>
                         <div className="font-mono text-gray-400 text-xs mt-0.5">{product.sku}</div>
                    </td>
                    <td className="px-6 py-4 text-center">
                        {isSaleEnabled ? (
                            <div className="inline-flex flex-col items-center">
                                <span className={`font-bold text-lg ${product.saleStock === 0 ? 'text-gray-300' : 'text-gray-800'}`}>
                                    {product.saleStock}
                                </span>
                                <StockBar current={product.saleStock} max={product.minStockAlert * 3} isLow={product.saleStock <= product.minStockAlert} />
                            </div>
                        ) : (
                            <span className="text-gray-300 font-medium text-xs">—</span>
                        )}
                    </td>
                    <td className="px-6 py-4 text-center">
                        {isRentalEnabled ? (
                            <div className="inline-flex flex-col items-center">
                                <span className={`font-bold text-lg ${product.rentalStock === 0 ? 'text-gray-300' : 'text-sky-600'}`}>
                                    {product.rentalStock}
                                </span>
                                <StockBar current={product.rentalStock} max={5} />
                            </div>
                        ) : (
                             <span className="text-gray-300 font-medium text-xs">—</span>
                        )}
                    </td>
                    <td className="px-6 py-4 text-right">
                        <div className="flex items-center justify-end space-x-2">
                        <button 
                            onClick={() => openEditModal(product)}
                            className="p-2 text-indigo-500 bg-indigo-50 hover:bg-indigo-100 rounded-md transition-colors"
                            title="Edit Product"
                        >
                            <Edit2 size={16} />
                        </button>
                        <button 
                            onClick={() => { setSelectedProduct(product.id); setIsStockModalOpen(true); }}
                            className="p-2 text-sky-500 bg-sky-50 hover:bg-sky-100 rounded-md transition-colors"
                            title="Update Stock"
                        >
                            <RefreshCcw size={16} />
                        </button>
                        <button 
                            onClick={() => deleteProduct(product.id)}
                            className="p-2 text-gray-300 hover:text-pink-500 hover:bg-pink-50 rounded-md transition-colors"
                        >
                            <Trash2 size={16} />
                        </button>
                        </div>
                    </td>
                    </tr>
                    );
                })}
                </tbody>
            </table>
            {filteredProducts.length === 0 && (
                <div className="py-20 text-center text-gray-400 italic">No products found matching your search.</div>
            )}
            </div>
        </Card>
      </div>

      {/* Add/Edit Product Modal */}
      <Modal 
        isOpen={isProductModalOpen} 
        onClose={() => setIsProductModalOpen(false)} 
        title={productToEdit ? "Edit Product" : "Add New Product"}
      >
        <form onSubmit={handleSaveProduct} className="grid grid-cols-1 md:grid-cols-2 gap-4">

          {/* Image Upload Section */}
          <div className="col-span-1 md:col-span-2 flex justify-center mb-4">
             <div className="relative group">
                <div className="w-32 h-32 rounded-xl bg-gray-50 border-2 border-dashed border-gray-300 flex items-center justify-center overflow-hidden cursor-pointer hover:border-sky-400 transition-colors" onClick={() => fileInputRef.current?.click()}>
                   {previewImage ? (
                      <img src={previewImage} alt="Preview" className="w-full h-full object-cover" />
                   ) : (
                      <div className="text-center text-gray-400">
                         <ImageIcon size={24} className="mx-auto mb-1" />
                         <span className="text-[10px] font-bold">Upload Image</span>
                      </div>
                   )}
                </div>
                {previewImage && (
                   <button 
                     type="button"
                     onClick={handleRemoveImage}
                     className="absolute -top-2 -right-2 bg-white text-red-500 p-1 rounded-full shadow-md border border-gray-200 hover:bg-red-50"
                   >
                      <X size={14} />
                   </button>
                )}
                <input 
                   type="file" 
                   ref={fileInputRef} 
                   onChange={handleImageChange} 
                   accept="image/*" 
                   className="hidden" 
                />
             </div>
          </div>

          <div className="col-span-1 md:col-span-2 space-y-2 mb-2">
             <label className="text-xs font-bold uppercase text-gray-400">Product Purpose</label>
             <div className="grid grid-cols-3 gap-3">
                 <button 
                    type="button"
                    onClick={() => setProductType('SALE')}
                    className={`flex items-center justify-center gap-2 p-3 rounded-lg border-2 font-bold text-sm transition-all ${productType === 'SALE' ? 'border-emerald-500 bg-emerald-50 text-emerald-700' : 'border-gray-100 text-gray-500 hover:border-gray-200'}`}
                 >
                    <ShoppingBag size={16} /> Sale Only
                 </button>
                 <button 
                    type="button"
                    onClick={() => setProductType('RENTAL')}
                    className={`flex items-center justify-center gap-2 p-3 rounded-lg border-2 font-bold text-sm transition-all ${productType === 'RENTAL' ? 'border-sky-500 bg-sky-50 text-sky-700' : 'border-gray-100 text-gray-500 hover:border-gray-200'}`}
                 >
                    <RefreshCcw size={16} /> Rent Only
                 </button>
                 <button 
                    type="button"
                    onClick={() => setProductType('BOTH')}
                    className={`flex items-center justify-center gap-2 p-3 rounded-lg border-2 font-bold text-sm transition-all ${productType === 'BOTH' ? 'border-indigo-500 bg-indigo-50 text-indigo-700' : 'border-gray-100 text-gray-500 hover:border-gray-200'}`}
                 >
                    <Package size={16} /> Hybrid
                 </button>
             </div>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Product Name</label>
            <input name="name" defaultValue={productToEdit?.name} required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium" placeholder="e.g. Princess Dress" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">SKU</label>
            <input name="sku" defaultValue={productToEdit?.sku} required className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium" placeholder="DRS-001" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Barcode</label>
            <input name="barcode" defaultValue={productToEdit?.barcode} className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium" placeholder="Scan or enter" />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Category</label>
            <select name="category" defaultValue={productToEdit?.category} className="w-full px-4 py-3 bg-gray-50 border-transparent focus:bg-white border focus:border-sky-200 rounded-lg outline-none transition-all font-medium">
              {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
