             <div className="flex gap-4">
              <label className="flex-1 border rounded-lg p-3 flex items-center justify-center gap-2 cursor-pointer has-[:checked]:bg-emerald-50 has-[:checked]:border-emerald-500 has-[:checked]:text-emerald-700 transition-all">
