          <div className="space-y-1">
            <label className="text-xs font-bold uppercase text-gray-400">Adjustment Type</label>
            <div className="flex gap-4">
              <label className="flex-1 border rounded-lg p-3 flex items-center justify-center gap-2 cursor-pointer has-[:checked]:bg-green-50 has-[:checked]:border-green-500 has-[:checked]:text-green-700 transition-all">
                <input type="radio" name="type" value="IN" defaultChecked className="hidden" />
                <ArrowDownLeft size={18} /> Stock In
              </label>
              <label className="flex-1 border rounded-lg p-3 flex items-center justify-center gap-2 cursor-pointer has-[:checked]:bg-pink-50 has-[:checked]:border-pink-500 has-[:checked]:text-pink-700 transition-all">
                <input type="radio" name="type" value="OUT" className="hidden" />
